insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ عَوْفِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ تَبُوكَ وَهُوَ فِي قُبَّةٍ مِنْ أَدَمٍ، فَقَالَ: "اعْدُدْ سِتًّا بَيْنَ يَدَيِ السَّاعَةِ: مَوْتِي، ثُمَّ فَتْحُ بَيْتِ الْمَقْدِسِ، ثُمَّ مُوْتَانٌ يَأْخُذُ فِيكُمْ كَقُعَاصِ الْغَنَمِ، ثُمَّ اسْتِفَاضَةُ الْمَالِ حَتَّى يُعْطَى الرَّجُلُ مِائَةَ دِينَارٍ فَيَظَلُّ سَاخِطًا، ثُمَّ فِتْنَةٌ لَا يَبْقَى بَيْتٌ مِنَ الْعَرَبِ إِلَّا دَخَلَتْهُ، ثُمَّ هُدْنَةٌ تَكُونُ بَيْنَكُمْ وَبَيْنَ بَنِي الْأَصْفَرِ، فَيَغْدِرُونَ فَيَأْتُونَكُمْ تَحْتَ ثَمَانِينَ غَايَةً، تَحْتَ كُلِّ غَايَةٍ اثْنَا عَشَرَ أَلْفًا". (خ)', 'ഔഫുബ്നു മാലിക്(റ): തബൂക് യുദ്ധഘട്ടത്തിൽ ഞാൻ നബി(സ)യുടെയടുക്കൽ ചെന്നു. അവിടന്ന് തോലുകൊണ്ടുള്ള ഒരു കൂടാരത്തിലായിരുന്നു. നബി(സ) പറഞ്ഞു: "അന്ത്യനാളിന്റെ മുമ്പായി സംഭവിക്കാൻ പോകുന്ന ആറ് കാര്യങ്ങളിതാ എണ്ണിക്കൊള്ളുക: എന്റെ മരണം, ബൈതുൽ മുഖദ്ദസിന്റെ വിജയം, ആടുകളെ ബാധിക്കാറുള്ള ഒരു വ്യാധി പോലെ നിങ്ങളെ ബാധിക്കുന്ന കൂട്ടമരണം, ധനത്തിന്റെ അമിതമായ വരവ്; അന്ന് ഒരാൾക്ക് 100 ദീനാർ തന്നെ (ദാനമായി) നൽകിയാലും അവന്റെ മുഖം വിവർണ്ണമായിരിക്കും. ശേഷം എല്ലാ അറബീ വീടുകളെയും ബാധിക്കുന്ന ഒരു വിപത്ത്. അതിനുശേഷം നിങ്ങൾക്കും റോമക്കാർക്കുമിടയിൽ ഉണ്ടാകുന്ന ഒരു സന്ധിയാണ്. അതിൽ അവർ നിങ്ങളെ വഞ്ചിക്കുകയും എൺപത് കൊടികൾക്ക് കീഴിലായി നിങ്ങൾക്കു നേരെ അവർ വരികയും ചെയ്യും. അതിൽ ഓരോ കൊടിക്ക് കീഴിലും പന്ത്രണ്ടായിരം പടയാളികളുണ്ടായിരിക്കും." (ബു)', 'عَوْفِ بْنِ مَالِكٍ', 'ഔഫുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 43, 43, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لِكُلِّ غَادِرٍ لِوَاءٌ يَوْمَ الْقِيَامَةِ يُرْفَعُ لَهُ بِقَدْرِ غَدْرِهِ، أَلَا وَلَا غَادِرَ أَعْظَمُ غَدْرًا مِنْ أَمِيرِ عَامَّةٍ". (م)', 'അബൂസഈദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഓരോ വഞ്ചകനും അന്ത്യനാളിൽ ഓരോ കൊടിയുണ്ടാവുകയും അവന്റെ വഞ്ചനയുടെ തോതനുസരിച്ച് അവനുവേണ്ടി അതുയർത്തപ്പെടുകയും ചെയ്യും. അറിയുക, ഒരു ജനനേതാവിനെക്കാളും വലിയ വഞ്ചന നടത്തുന്ന ഒരാളുമില്ല." (മു)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 43, 43, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الْغَادِرَ يُنْصَبُ لَهُ لِوَاءٌ يَوْمَ الْقِيَامَةِ، فَيُقَالُ: هَذِهِ غَدْرَةُ فُلَانِ بْنِ فُلَانٍ". (ق,د,ن,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം ഒരു വഞ്ചകന് അന്ത്യനാളിൽ ഒരു കൊടിനാട്ടപ്പെടും. എന്നിട്ട് ഇന്നയാളുടെ മകനായ ഇന്നയാളുടെ വഞ്ചനയാണിത് എന്ന് പറയപ്പെടും." (ബു,മു,ദ,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 43, 43, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ عَبْدالله وأَنَسٍ رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لِكُلِّ غَادِرٍ لِوَاءٌ يَوْمَ الْقِيَامَةِ، قَالَ أَحَدُهُمَا: يُنْصَبُ، وَقَالَ الْآخَرُ: يُرَى يَوْمَ الْقِيَامَةِ يُعْرَفُ بِهِ". (خ)', 'അബ്ദുല്ലാഹ്(റ), അനസ്(റ): നബി(സ) പറഞ്ഞു: "ഓരോ വഞ്ചകനും അന്ത്യനാളിൽ ഓരോ കൊടിയുണ്ടാകും." നിവേദകരിൽ ഒരാൾ പറയുന്നു: "അത് നാട്ടപ്പെടും." മറ്റൊരാൾ പറഞ്ഞു: "കൊടി കാണുമ്പോൾ അന്ത്യനാളിൽ അവനെ തിരിച്ചറിയും." (ബു)', 'عَبْدالله وأَنَسٍ', 'അബ്ദുല്ലാഹ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 43, 43, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ كَتَبَ إِلَى أَهْلِ الْبَصَرَةِ قَبْلَ مَوْتِهِ بِسَنَةٍ: فَرِّقُوا بَيْنَ كُلِّ ذِي مَحْرَمٍ مِنَ الْمَجُوسِ، وَلَمْ يَكُنْ عُمَرُ أَخَذَ الْجِزْيَةَ مِنَ الْمَجُوسِ حَتَّى شَهِدَ عَبْدُالرَّحْمَنِ بْنُ عَوْفٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَذَهَا مِنْ مَجُوسِ هَجَرَ. (خ)', 'ഉമറുബ്നുൽ ഖത്ത്വാബ്(റ): വിവാഹബന്ധം സ്ഥാപിക്കാൻ പാടില്ലാത്ത അടുത്ത കുടുംബക്കാർക്കിടയിൽ വിവാഹബന്ധം സ്ഥാപിച്ച മജൂസികളെ പരസ്പരം അകറ്റിനിർത്തണമെന്ന്, തന്റെ വിയോഗത്തിന് ഒരു വർഷം മുമ്പ്, ഉമർ(റ) ബസറക്കാരെ എഴുതി അറിയിക്കുകയുണ്ടായി. ഉമർ(റ) മജൂസികളിൽ നിന്ന് ജിസ്‌യ വാങ്ങിയിരുന്നില്ല. തിരുമേനി(സ) ഹജറിലെ മജൂസികളിൽ നിന്ന് ജിസ്‌യ വാങ്ങിയിരുന്നുവെന്ന് അബ്ദുർറഹ്മാനുബ്നുഔഫ്(റ) സാക്ഷി പറഞ്ഞപ്പോഴാണ് അവരിൽ നിന്ന് അദ്ദേഹം ജിസ്‌യ വാങ്ങിയത്. (ബു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്ത്വാബ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 44, 44, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ عَمْرِو بْنِ عَوْفٍ الْأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ وَهُوَ حَلِيفٌ لِبَنِي عَامِرِ بْنِ لُؤَيٍّ، وَكَانَ شَهِدَ بَدْرًا، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ أَبَا عُبَيْدَةَ بْنَ الْجَرَّاحِ إِلَى الْبَحْرَيْنِ يَأْتِي بِجِزْيَتِهَا، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هُوَ صَالَحَ أَهْلَ الْبَحْرَيْنِ وَأَمَّرَ عَلَيْهِمُ الْعَلَاءَ بْنَ الْحَضْرَمِيِّ، فَقَدِمَ أَبُو عُبَيْدَةَ بِمَالٍ مِنَ الْبَحْرَيْنِ، فَسَمِعَتِ الْأَنْصَارُ بِقُدُومِ أَبِي عُبَيْدَةَ، فَوَافَتْ صَلَاةَ الصُّبْحِ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا صَلَّى بِهِمُ الْفَجْرَ انْصَرَفَ، فَتَعَرَّضُوا لَهُ، فَتَبَسَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ رَآهُمْ وَقَالَ: "أَظُنُّكُمْ قَدْ سَمِعْتُمْ أَنَّ أَبَا عُبَيْدَةَ قَدْ جَاءَ بِشَيْءٍ؟" قَالُوا: أَجَلْ يَا رَسُولَ اللَّهِ، قَالَ: "فَأَبْشِرُوا وَأَمِّلُوا مَا يَسُرُّكُمْ، فَوَاللَّهِ لَا الْفَقْرَ أَخْشَى عَلَيْكُمْ، وَلَكِنْ أَخْشَى عَلَيْكُمْ أَنْ تُبْسَطَ عَلَيْكُمُ الدُّنْيَا كَمَا بُسِطَتْ عَلَى مَنْ كَانَ قَبْلَكُمْ، فَتَنَافَسُوهَا كَمَا تَنَافَسُوهَا، وَتُهْلِكَكُمْ كَمَا أَهْلَكَتْهُمْ". (خ)', 'അംറുബ്നു ഔഫിൽ അൻസാരി(റ) - ബനൂ ആമിറുബ്നു ലുഅയ്യ് ഗോത്രവുമായി സന്ധിയിലേർപ്പെട്ട ഇദ്ദേഹം ബദ്ർ യുദ്ധത്തിൽ പങ്കെടുത്തിട്ടുണ്ട് -: ബഹ്റൈനിലെ ജിസ്‌യ കൊണ്ടുവരാനായി അബൂഉബൈദ(റ)യെ നബി(സ) അയച്ചു. റസൂൽ(സ) ബഹ്റൈൻ നിവാസികളോട് സന്ധിചെയ്യുകയും അലാഉബ്നു ഹള്റമി(റ)വിനെ അവിടത്തെ നേതാവായി നിയമിക്കുകയും ചെയ്തിട്ടുണ്ടായിരുന്നു. അങ്ങനെ അബൂഉബൈദ(റ) ബഹ്റൈനിൽ നിന്ന് ധനവുമായി തിരിച്ചെത്തിയപ്പോൾ ആ വരവിനെക്കുറിച്ച് അൻസാരികൾ കേട്ടു. അവർ നബി(സ)യോടൊപ്പം സുബ്ഹി നിസ്കരിക്കാൻ വേണ്ടി വന്നു. നിസ്കാരം കഴിഞ്ഞയുടനെ നബി(സ) പിരിഞ്ഞ് പോകാൻ ഒരുങ്ങി. അവർ തിരുമേനി(സ)യുടെ മുന്നിൽ വന്ന് നിന്നു. അവരെ കണ്ടപ്പോൾ നബി(സ) പുഞ്ചിരിച്ചുകൊണ്ട് പറഞ്ഞു: "അബൂഉബൈദ കുറച്ച് ധനവുമായി എത്തിയ വിവരം നിങ്ങൾ കേട്ടിട്ടുണ്ടെന്ന് ഞാൻ കരുതുന്നു." അതെ അല്ലാഹുവിന്റെ ദൂതരേ, അവർ പ്രതിവചിച്ചു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ സന്തോഷിക്കുകയും സന്തോഷമുണ്ടാക്കിയത് എന്താണെന്ന് ആലോചിക്കുകയും ചെയ്യുക. അല്ലാഹുവിനെ തന്നെ സത്യം, ദാരിദ്ര്യമല്ല ഞാൻ നിങ്ങളുടെമേൽ ഭയക്കുന്നത്, ഞാൻ ഭയക്കുന്നത് നിങ്ങൾക്ക് മുമ്പുള്ളവർക്ക് ഇഹലോകം ഐശ്വര്യ പൂർണ്ണമായതുപോലെ നിങ്ങൾക്കും ഐശ്വര്യപൂർണ്ണമാകുന്നതിനെയാണ്. അവർ അവയ്ക്കുവേണ്ടി പരസ്പരം മൽസരിച്ചതുപോലെ നിങ്ങളും മത്സരിക്കുമോ എന്നും തന്മൂലം അവർ നശിച്ചതു പോലെ നിങ്ങളും നശിക്കുമോ എന്നുമാണ് ഞാൻ ഭയക്കുന്നത്." (ബു)', 'عَمْرِو بْنِ عَوْفٍ الْأَنْصَارِيِّ', 'അംറുബ്നു ഔഫിൽ അൻസാരി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 44, 44, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ بَعَثَ النَّاسَ فِي أَفْنَاءِ الْأَمْصَارِ يُقَاتِلُونَ الْمُشْرِكِينَ، فَأَسْلَمَ الْهُرْمُزَانُ. فَقَالَ: إِنِّي مُسْتَشِيرُكَ فِي مَغَازِيَّ هَذِهِ فَقَالَ: نَعَمْ، مَثَلُهَا وَمَثَلُ مَنْ فِيهَا مِنَ النَّاسِ مِنْ عَدُوِّ الْمُسْلِمِينَ مَثَلُ طَائِرٍ لَهُ رَأْسٌ وَلَهُ جَنَاحَانِ وَلَهُ رِجْلَانِ، فَإِنْ كُسِرَ أَحَدُ الْجَنَاحَيْنِ نَهَضَتِ الرِّجْلَانِ بِجَنَاحٍ وَالرَّأْسِ، فَإِنْ كُسِرَ الْجَنَاحُ الْآخَرُ نَهَضَتِ الرِّجْلَانِ وَالرَّأْسُ، وَإِنْ شُدِخَ الرَّأْسُ ذَهَبَتِ الرِّجْلَانِ وَالْجَنَاحَانِ وَالرَّأْسُ، فَالرَّأْسُ كِسْرَى وَالْجَنَاحُ قَيْصَرُ وَالْجَنَاحُ الْآخَرُ فَارِسُ، فَمُرِ الْمُسْلِمِينَ فَلْيَنْفِرُوا إِلَى كِسْرَى، فَنَدَبَنَا عُمَرُ وَاسْتَعْمَلَ عَلَيْنَا النُّعْمَانَ بْنَ مُقَرِّنٍ، حَتَّى إِذَا كُنَّا بِأَرْضِ الْعَدُوِّ وَخَرَجَ عَلَيْنَا عَامِلُ كِسْرَى فِي أَرْبَعِينَ أَلْفًا، فَقَامَ تُرْجُمَانٌ فَقَالَ: لِيُكَلِّمْنِي رَجُلٌ مِنْكُمْ، فَقَالَ الْمُغِيرَةُ: سَلْ عَمَّا شِئْتَ، فَقَالَ: مَا أَنْتُمْ؟ قَالَ: نَحْنُ أُنَاسٌ مِنَ الْعَرَبِ كُنَّا فِي شَقَاءٍ شَدِيدٍ وَبَلَاءٍ شَدِيدٍ، نَمَصُّ الْجِلْدَ وَالنَّوَى مِنَ الْجُوعِ وَنَلْبَسُ الْوَبَرَ وَالشَّعَرَ وَنَعْبُدُ الشَّجَرَ وَالْحَجَرَ، فَبَيْنَا نَحْنُ كَذَلِكَ، إِذْ بَعَثَ رَبُّ السَّمَوَاتِ وَرَبُّ الْأَرَضِينَ، تَعَالَى ذِكْرُهُ وَجَلَّتْ عَظَمَتُهُ، إِلَيْنَا نَبِيًّا مِنْ أَنْفُسِنَا نَعْرِفُ أَبَاهُ وَأُمَّهُ، فَأَمَرَنَا نَبِيُّنَا رَسُولُ رَبِّنَا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نُقَاتِلَكُمْ حَتَّى تَعْبُدُوا اللَّهَ وَحْدَهُ أَوْ تُؤَدُّوا الْجِزْيَةَ، وَأَخْبَرَنَا نَبِيُّنَا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ رِسَالَةِ رَبِّنَا: أَنَّهُ مَنْ قُتِلَ مِنَّا صَارَ إِلَى الْجَنَّةِ فِي نَعِيمٍ لَمْ يَرَ مِثْلَهَا قَطُّ، وَمَنْ بَقِيَ مِنَّا مَلَكَ رِقَابَكُمْ. فَقَالَ النُّعْمَانُ: رُبَّمَا أَشْهَدَكَ اللَّهُ مِثْلَهَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يُنَدِّمْكَ وَلَمْ يُخْزِكَ، وَلَكِنِّي شَهِدْتُ الْقِتَالَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، كَانَ إِذَا لَمْ يُقَاتِلْ فِي أَوَّلِ النَّهَارِ انْتَظَرَ حَتَّى تَهُبَّ الْأَرْوَاحُ وَتَحْضُرَ الصَّلَوَاتُ. (خ)', 'ഉമർ(റ): ബഹുദൈവ വിശ്വാസികളുമായി യുദ്ധം ചെയ്യാൻ വൻ നഗരങ്ങളിലേക്ക് അദ്ദേഹം സൈന്യങ്ങളെ അയച്ചു. അങ്ങനെ ''ഹുർമുസാൻ'' ഇസ്‌ലാം സ്വീകരിച്ചു. ഉമർ(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: എന്റെ ഈ യുദ്ധങ്ങളെക്കുറിച്ച് ഞാൻ നിങ്ങളോട് അഭിപ്രായം ചോദിക്കുകയാണ്. അദ്ദേഹം പറഞ്ഞു: അതെ, ആ നാടുകളുടെയും, മുസ്‌ലിംകളുടെ ശത്രുക്കളായ അവിടത്തെ ജനങ്ങളുടെയും ഉപമ ഒരു പക്ഷിയുടേത് പോലെയാണ്. അതിന് തലയും രണ്ട് ചിറകും രണ്ട് കാലുമുണ്ട്. ഇരുചിറകുകളിലൊന്ന് ഒടിഞ്ഞാൽ രണ്ട് കാലുകളും ഒരു ചിറകും തലയുമായി അത് സഞ്ചരിക്കും. മറ്റേ ചിറകു കൂടി ഒടിഞ്ഞുവെന്നിരിക്കട്ടെ, രണ്ട് കാലും തലയുമായി അത് സഞ്ചരിക്കും. തല മുറിഞ്ഞ് പോയാലോ അതോടൊപ്പം രണ്ട് കാലും രണ്ട് ചിറകും തലയും നഷ്ടപ്പെട്ടതു തന്നെ. ഇവിടെ തല കിസ്റയാണ്. ഒരു ചിറക് കൈസറും, മറ്റേ ചിറക് പേർഷ്യയും. അതുകൊണ്ട് കിസ്റയുമായി യുദ്ധത്തിന് പുറപ്പെടാൻ താങ്കൾ മുസ്‌ലിംകളോട് കൽപിക്കുക. അങ്ങനെ ഉമർ(റ) ഞങ്ങളെ യുദ്ധത്തിനായി നിയോഗിച്ചു. ഞങ്ങളുടെ നായകനായി നുഅ്മാനുബ്നു മുഖർരിൻ(റ)വിനെ നിയോഗിച്ചു. ഞങ്ങൾ ശത്രുരാജ്യത്ത് എത്തിയപ്പോൾ കിസ്റയുടെ സേനാനായകൻ നാൽപതിനായിരം പേരോടു കൂടി ഞങ്ങൾക്കെതിരിൽ പുറപ്പെട്ടു. എന്നിട്ട് ഒരു വിവർത്തകൻ വന്ന് മുസ്‌ലിംകളോട് പറഞ്ഞു: നിങ്ങളുടെ കൂട്ടത്തിലൊരാൾ വന്ന് എന്നോട് സംസാരിക്കുക. അപ്പോൾ മുഗീറ(റ) പറഞ്ഞു: നിങ്ങൾ എന്തുവേണമെങ്കിലും ചോദിച്ചുകൊള്ളുക. കിസ്റയുടെ പ്രതിനിധി ചോദിച്ചു: നിങ്ങൾ ആരാണ്? മുഗീറ(റ) പറഞ്ഞു: ഞങ്ങൾ അറബികളാണ്. വമ്പിച്ച നിർഭാഗ്യത്തിലും കഠിന ദാരിദ്ര്യത്തിലുമാണ് ഞങ്ങൾ കഴിഞ്ഞിരുന്നത്. പട്ടിണിമൂലം തുകലും ഈത്തപ്പഴക്കുരുവും കഴിച്ചാണ് ഞങ്ങൾ കഴിഞ്ഞിരുന്നത്. രോമത്തിന്റെ വസ്ത്രമാണ് ധരിച്ചിരുന്നത്. കല്ലിനെയും മരത്തെയുമാണ് അന്ന് ഞങ്ങൾ പൂജിച്ചിരുന്നത്. അതിനിടക്ക് ആകാശഭൂമികളുടെ നാഥൻ - അവന്റെ നാമം മേന്മയുള്ളതും അവന്റെ മഹത്വം അത്യുന്നതവുമാണ് - ഞങ്ങളുടെ കൂട്ടത്തിൽ നിന്ന് തന്നെ ഒരു പ്രവാചകനെ ഞങ്ങളുടെ അടുത്തേക്ക് അയച്ചു. അദ്ദേഹത്തിന്റെ മാതാപിതാക്കളെക്കുറിച്ച് ഞങ്ങൾക്ക് നന്നായറിയാം. അങ്ങനെ ഞങ്ങളുടെ പ്രവാചകൻ - ഞങ്ങളുടെ നാഥന്റെ ദൂതൻ - അല്ലാഹുവിന് മാത്രം ആരാധിക്കുകയോ ജിസ്‌യ നൽകുകയോ ചെയ്യുന്നത് വരെ നിങ്ങളോട് യുദ്ധം ചെയ്യാൻ ഞങ്ങളോട് കൽപിച്ചു. ഞങ്ങളുടെ നാഥനിൽ നിന്നുള്ള ദൗത്യമെന്ന നിലക്ക് പ്രവാചകൻ(സ) ഞങ്ങളെ അറിയിച്ചു: ഞങ്ങളുടെ കൂട്ടത്തിൽ വല്ലവരും വധിക്കപ്പെട്ടാൽ സുഖാഢംഭരങ്ങളുള്ള തുല്യത കാണപ്പെടാത്ത സ്വർഗ്ഗത്തിലേക്ക് അവൻ പോകും. ഞങ്ങളുടെ കൂട്ടത്തിൽ വല്ലവനും അവശേഷിച്ചാലോ, അവർ നിങ്ങളെ കീഴടക്കി ഭരിക്കും. നുഅ്മാൻ(റ) പറഞ്ഞു: ഇതുപോലെ ധാരാളം യുദ്ധങ്ങളിൽ തിരുമേനി(സ)യോടൊപ്പം താങ്കളെ അല്ലാഹു പങ്കെടുപ്പിച്ചിട്ടുണ്ടാവും. എന്നാൽ അത്തരം സന്ദർഭങ്ങളിൽ ഖേദത്തിനോ നിന്ദ്യതക്കോ താങ്കൾ പാത്രമായിട്ടുണ്ടായിരിക്കില്ല. പക്ഷേ, റസൂൽ(സ)യോട് കൂടെ ഞാൻ ചില യുദ്ധങ്ങളിൽ പങ്കെടുത്തിട്ടുണ്ട്. തിരുമേനി(സ)ക്ക് പകലിന്റെ ആദ്യഘട്ടത്തിൽ യുദ്ധം ആരംഭിക്കാൻ സൗകര്യപ്പെട്ടിട്ടില്ലെങ്കിൽ കാറ്റുവീശുകയും നമസ്കാര സമയം വന്നെത്തുകയും ചെയ്യുന്നതുവരെ അവിടുന്ന് കാത്തിരിക്കുമായിരുന്നു. (ബു)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 44, 46, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ خَالِدَ بْنَ الْوَلِيدِ إِلَى أُكَيْدِرِ دُومَةَ فَأُخِذَ، فَأَتَوْهُ بِهِ، فَحَقَنَ لَهُ دَمَهُ وَصَالَحَهُ عَلَى الْجِزْيَةِ. (د)', 'അനസുബ്നു മാലിക്(റ): നിശ്ചയം നബി(സ) ഖാലിദുബ്നു വലീദ്(റ)വിനെ ദൂമയിലെ ഉകൈദിർ രാജാവിനു നേരെ നിയോഗിക്കുകയും അയാൾ പിടിക്കപ്പെടുകയും ചെയ്തു. അങ്ങനെ അവർ (മുസ്‌ലിംകൾ) അയാളെ റസൂൽ(സ)യുടെ പക്കൽ കൊണ്ടുവരികയും, അവിടുന്ന് അയാളുടെ ജീവന് സംരക്ഷണം നൽകുകയും ജിസ്‌യയ്ക്കു പകരമായി സന്ധിയിലേർപ്പെടുകയും ചെയ്തു. (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 46, 46, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ مُعَاذٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا وَجَّهَهُ إِلَى الْيَمَنِ أَمَرَهُ أَنْ يَأْخُذَ مِنْ كُلِّ حَالِمٍ - يَعْنِي مُحْتَلِمًا - دِينَارًا، أَوْ عَدْلَهُ مِنَ الْمَعَافِرِ، ثِيَابٌ تَكُونُ بِالْيَمَنِ. (د,ت,ن,جه)', 'മുആദ്(റ): നിശ്ചയം നബി(സ) അദ്ദേഹത്തെ യമനിലേക്ക് പറഞ്ഞയച്ചപ്പോൾ, പ്രായപൂർത്തിയായ ഓരോരുത്തരിൽനിന്നും ഓരോ ദീനാറോ, അല്ലെങ്കിൽ: യമനിലെ പ്രത്യേക വസ്ത്രമായ മഗാഫിർ വസ്ത്രത്തിൽ നിന്ന് ഒരു ദീനാറിന് തുല്ല്യമായതോ സ്വീകരിക്കണമെന്ന് കൽപിച്ചു. (ദ,തു,ന,ജ)', 'مُعَاذٍ', 'മുആദ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 46, 46, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَئِنْ بَقِيتُ لِنَصَارَى بَنِي تَغْلِبَ لَأَقْتُلَنَّ الْمُقَاتِلَةَ وَلَأَسْبِيَنَّ الذُّرِّيَّةَ، فَإِنِّي كَتَبْتُ الْكِتَابَ بَيْنَهُمْ وَبَيْنَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى أَنْ لَا يُنَصِّرُوا أَبْنَاءَهُمْ. قَالَ أَبُو دَاوُدَ: هَذَا حَدِيثٌ مُنْكَرٌ. (د)', 'അലി(റ): ബനൂതഗ്ലിബിലെ ക്രസ്ത്യാനികളോട് പോരാടാൻ എനിക്കു ആയുസ്സ് ലഭിച്ചാൽ, നിശ്ചയം അവരിലെ യോദ്ധാക്കളെ വധിച്ചു കളയുകയും കുട്ടികളെ ബന്ധികളാക്കുകയും ചെയ്യും. അവരുടെ കുട്ടികളെ ക്രസ്ത്യാനികളാക്കരുതെന്നുള്ള, നബി(സ)ക്കും അവർക്കുമിടയിലുള്ള, കരാർപത്രം എഴുതിയത് ഞാനായിരുന്നു. അബൂദാവൂദ്(റ) പറഞ്ഞു: ഇത് മുൻകറായ ഹദീസാണ്. (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 46, 46, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: صَالَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَهْلَ نَجْرَانَ عَلَى أَلْفَيْ حُلَّةٍ، النِّصْفُ فِي صَفَرٍ وَالْبَقِيَّةُ فِي رَجَبٍ، يُؤَدُّونَهَا إِلَى الْمُسْلِمِينَ، وَعَارِيَّةِ ثَلَاثِينَ دِرْعًا وَثَلَاثِينَ فَرَسًا وَثَلَاثِينَ بَعِيرًا وَثَلَاثِينَ مِنْ كُلِّ صِنْفٍ مِنْ أَصْنَافِ السِّلَاحِ يَغْزُونَ بِهَا، وَالْمُسْلِمُونَ ضَامِنُونَ لَهَا حَتَّى يَرُدُّوهَا عَلَيْهِمْ، إِنْ كَانَ بِالْيَمَنِ كَيْدٌ أَوْ غَدْرَةٌ. عَلَى أَنْ لَا تُهْدَمَ لَهُمْ بِيعَةٌ، وَلَا يُخْرَجَ لَهُمْ قَسٌّ، وَلَا يُفْتَنُوا عَنْ دِينِهِمْ، مَا لَمْ يُحْدِثُوا حَدَثًا أَوْ يَأْكُلُوا الرِّبَا. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) നജ്റാൻ നിവാസികളോട്, രണ്ടായിരം വസ്ത്രങ്ങൾ (മുസ്‌ലിംകൾക്ക്) നൽകണമെന്ന വ്യവസ്ഥയിൽ, സന്ധിചെയ്തു. അതിൽ പകുതി ''സ്വഫർ'' മാസത്തിലും ശേഷിച്ചത് ''റജബ്'' മാസത്തിലും നൽകണം. അതോടൊപ്പം മുപ്പത് അങ്കികളും മുപ്പത് കുതിരകളും മുപ്പത് ഒട്ടകങ്ങളും, അവരുടെ യുദ്ധോപകരണങ്ങളുടെ ഓരോ ഇനത്തിൽനിന്നും മുപ്പത് എണ്ണവും വായ്പയായി നൽകണം. യമനിൽ യുദ്ധമോ കരാർ ലംഘനമോ ഉണ്ടാവുകയാണെങ്കിൽ അവ തിരിച്ചേൽപിക്കുന്നതിന് മുസ്‌ലിംകൾ ഉത്തരവാദികളായിരിക്കും. നജ്റാനുകാർ (ക്രസ്ത്യാനികൾ) വല്ല പ്രശ്നവും സൃഷ്ടിക്കുകയോ പലിശ ഭക്ഷിക്കുകയോ ചെയ്യാത്ത കാലത്തോളം, അവരുടെ ആരാധനാലയങ്ങൾ തകർക്കപ്പെടുകയോ, സന്യാസിമാർ നാടുകടത്തപ്പെടുകയോ, മത കാര്യത്തിൽ പ്രശ്നമുണ്ടാക്കപ്പെടുകയോ ചെയ്യുകയില്ല എന്നതിനു പകരമായിരുന്നു ഇത്. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 46, 46, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: إِنَّ أَهْلَ فَارِسَ لَمَّا مَاتَ نَبِيُّهُمْ كَتَبَ لَهُمْ إِبْلِيسُ الْمَجُوسِيَّةَ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): നിശ്ചയം പേർഷ്യക്കാരുടെ പ്രവാചകൻ വഫാതായപ്പോൾ ഇബ്ലീസ് മജൂസീ മതത്തെ അവർക്ക് എഴുതിയുണ്ടാക്കി നൽകി. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 47, 47, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ بَجَالَةَ بْنِ عَبْدَةَ قَالَ: كُنْتُ كَاتِبًا لِجَزْءِ بْنِ مُعَاوِيَةَ - عَمِّ الْأَحْنَفِ بْنِ قَيْسٍ - إِذْ جَاءَنَا كِتَابُ عُمَرَ رَضِيَ اللَّهُ عَنْهُ قَبْلَ مَوْتِهِ بِسَنَةٍ: اقْتُلُوا كُلَّ سَاحِرٍ، وَفَرِّقُوا بَيْنَ كُلِّ ذِي مَحْرَمٍ مِنَ الْمَجُوسِ، وَانْهَوْهُمْ عَنِ الزَّمْزَمَةِ. فَقَتَلْنَا فِي يَوْمٍ ثَلَاثَةَ سَوَاحِرَ، وَفَرَّقْنَا بَيْنَ كُلِّ رَجُلٍ مِنَ الْمَجُوسِ وَحَرِيمِهِ فِي كِتَابِ اللَّهِ. وَصَنَعَ طَعَامًا كَثِيرًا فَدَعَاهُمْ، فَعَرَضَ السَّيْفَ عَلَى فَخِذِهِ، فَأَكَلُوا وَلَمْ يُزَمْزِمُوا، وَأَلْقَوْا وِقْرَ بَغْلٍ أَوْ بَغْلَيْنِ مِنَ الْوَرِقِ، وَلَمْ يَكُنْ عُمَرُ أَخَذَ الْجِزْيَةَ مِنَ الْمَجُوسِ حَتَّى شَهِدَ عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَذَهَا مِنْ مَجُوسِ هَجَرَ. (ق,د,ت,ن)', 'ബജാലതുബ്നു അബ്ദ(റ): അഹ്നഫുബ്നു ഖൈസിന്റെ പിതൃവ്യനായ ജസ്ഉബ്നു മുആവിയയുടെ എഴുത്തുകാരനായിരുന്നു ഞാൻ. അങ്ങനെ ഉമർ(റ) വഫാതാകുന്നതിനു ഒരു വർഷം മുമ്പ് അദ്ദേഹത്തിന്റെ കത്ത് ഞങ്ങൾക്ക് ലഭിച്ചു (അതിൽ ഇപ്രകാരമാണുണ്ടായിരുന്നത്): എല്ലാ മാരണക്കാരെയും നിങ്ങൾ വധിച്ചു കളയുക, മജൂസികളിലെ (ഭാര്യാഭർത്താക്കളിൽ) രക്തബന്ധമുള്ളവരെ വേർപിരിക്കുക, സംസമ (ഭക്ഷണം കഴിക്കുമ്പോൾ മജൂസികൾ ചൊല്ലാറുള്ള പ്രത്യേക വചനം) യെത്തൊട്ട് അവരെ വിലക്കുക. അങ്ങനെ ഒറ്റ ദിവസം മൂന്ന് മാരണക്കാരെ ഞങ്ങൾ വധിച്ചു. മജൂസികളിലെ രക്തബന്ധമുള്ളവരെ (ഭാര്യാഭർത്താക്കൾ) ദൈവിക ഗ്രന്ഥത്തിലെ വിധിയനുസരിച്ച് ഞങ്ങൾ വേർപെടുത്തി. ജസ്ഉബ്നു മുആവിയ ധാരാളം ഭക്ഷണം ഉണ്ടാക്കുകയും മജൂസികളെ ക്ഷണിക്കുകയും ചെയ്തു. അദ്ദേഹം വാൾ തന്റെ തുടയുടെ മീതെ വെച്ചു. അപ്പോൾ ''സംസമ'' ചൊല്ലാതെത്തന്നെ അവർ ഭക്ഷണം കഴിച്ചു. മാത്രമല്ല, ഒന്നോ രണ്ടോ കോവർകഴുതക്ക് ചുമക്കാവുന്നയത്ര വെള്ളി അവർ കൊണ്ടുവരികയും ചെയ്തു. ഹജറിലെ മജൂസികളിൽനിന്ന് റസൂൽ(സ) ജിസ്‌യ സ്വീകിരിച്ചിട്ടുണ്ടെന്ന് അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ) സാക്ഷ്യപ്പെടുത്തുന്നതിനു മുമ്പ് ഉമർ(റ) മജൂസികളിൽനിന്ന് ജിസ്‌യ സ്വീകരിക്കാറുണ്ടായിരുന്നില്ല. (ബു,മു,ദ,തു,ന)', 'بَجَالَةَ بْنِ عَبْدَةَ قَالَ', 'ബജാലതുബ്നു അബ്ദ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 47, 47, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: جَاءَ رَجُلٌ مِنَ الْأَسْبَذِيِّينَ مِنْ أَهْلِ الْبَحْرَيْنِ - وَهُمْ مَجُوسُ أَهْلِ هَجَرَ - إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَمَكَثَ عِنْدَهُ ثُمَّ خَرَجَ، فَسَأَلْتُهُ: مَا قَضَى اللَّهُ وَرَسُولُهُ فِيكُمْ؟ قَالَ: شَرٌّ، قُلْتُ: مَهْ؟ قَالَ: الْإِسْلَامُ أَوِ الْقَتْلُ. قَالَ: وَقَالَ عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ: قَبِلَ مِنْهُمُ الْجِزْيَةَ. قَالَ ابْنُ عَبَّاسٍ: فَأَخَذَ النَّاسُ بِقَوْلِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ، وَتَرَكُوا مَا سَمِعْتُ أَنَا مِنَ الْأَسْبَذِيِّ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ബഹ്റൈനുകാരിൽപെട്ട അസ്ബദികളിലെ ഒരാൾ റസൂൽ(സ)യുടെ അടുത്ത് വന്നു - അസ്ബദികൾ ഹജറിലെ മജൂസികളാണ് - റസൂൽ(സ)യുടെ അടുത്ത് അൽപം തങ്ങിയ ശേഷം അയാൾ പുറപ്പെട്ടു. അപ്പോൾ ഞാൻ അയാളോട് ചോദിച്ചു: അല്ലാഹുവും അവന്റെ ദൂതരും നിങ്ങളുടെ കാര്യത്തിൽ എന്താണ് വിധിച്ചിരിക്കുന്നത്? അയാൾ പറഞ്ഞു: തിന്മയാണ്. ഞാൻ ചോദിച്ചു: എന്ത്? അയാൾ പറഞ്ഞു: ഒന്നുകിൽ ഇസ്‌ലാം സ്വീകരിക്കുക, അല്ലെങ്കിൽ യുദ്ധം. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: റസൂൽ(സ) അവരിൽനിന്ന് ജിസ്‌യ സ്വീകരിച്ചുവെന്നാണ് അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ) പറയുന്നത്. ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: അങ്ങനെ ജനങ്ങൾ അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ)വിന്റെ വാക്ക് സ്വീകരിക്കുകയും അസ്ബദിയിൽനിന്ന് ഞാൻ കേട്ടതിനെ ഒഴിവാക്കുകയും ചെയ്തു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 47, 47, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ بَجَالَةَ بْنِ عَبْدَةَ قَالَ: كُنْتُ كَاتِبًا لِجَزْءِ بْنِ مُعَاوِيَةَ عَلَى مُنَاذِرَ، فَجَاءَنَا كِتَابُ عُمَرَ رَضِيَ اللَّهُ عَنْهُ: انْظُرْ مَجُوسَ مَنْ قِبَلَكَ فَخُذْ مِنْهُمُ الْجِزْيَةَ، فَإِنَّ عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ رَضِيَ اللَّهُ عَنْهُ أَخْبَرَنِي: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَذَ الْجِزْيَةَ مِنْ مَجُوسِ هَجَرَ. وَفِي رِوَايَةٍ: أَنَّ عُمَرَ رَضِيَ اللَّهُ عَنْهُ كَانَ لَا يَأْخُذُ الْجِزْيَةَ مِنَ الْمَجُوسِ، حَتَّى أَخْبَرَهُ عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَذَ الْجِزْيَةَ مِنْ مَجُوسِ هَجَرَ. (خ,د,ت,ن)', 'ബജാലതുബ്നു അബ്ദ(റ): ഞാൻ ജസ്ഉബ്നു മുആവിയയുടെ മുനാദിറിലെ എഴുത്തുകാരനായിരുന്നു. അങ്ങനെ ഞങ്ങൾക്ക് ഉമർ(റ)വിന്റെ എഴുത്ത് കിട്ടി (അതിൽ ഇതാണുണ്ടായിരുന്നത്): നിന്റെ മുന്നിലുള്ള മജൂസികളെ നീ വീക്ഷിക്കുക. അവരിൽ നിന്ന് ജിസ്‌യ വാങ്ങിക്കൊള്ളുക. അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ) എന്നോട് പറഞ്ഞിരിക്കുന്നു. നിശ്ചയം റസൂൽ(സ) ഹജറിലെ മജൂസികളിൽ നിന്ന് ജിസ്‌യ വാങ്ങിയിരുന്നു. മറ്റൊരു നിവേദനത്തിൽ: നബി(സ) ഹജറിലെ മജൂസികളിൽ നിന്ന് ജിസ്‌യ സ്വീകരിച്ചിരുന്നെന്ന് അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ) പറയുന്നത് വരെ ഉമർ(റ) മജൂസികളിൽ നിന്ന് ജിസ്‌യ സ്വീകരിക്കാറുണ്ടായിരുന്നില്ല. (ബു,ദ,തു,ന)', 'بَجَالَةَ بْنِ عَبْدَةَ قَالَ', 'ബജാലതുബ്നു അബ്ദ(റ)', null, null, array['خ','د','ت','ن']::text[], array['ബു','ദ','തു','ന']::text[], null, null, 48, 48, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=15), 1, 'وَفِي رِوَايَةٍ: أَنَّ عُمَرَ رَضِيَ اللَّهُ عَنْهُ كَانَ لَا يَأْخُذُ الْجِزْيَةَ مِنَ الْمَجُوسِ، حَتَّى أَخْبَرَهُ عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَذَ الْجِزْيَةَ مِنْ مَجُوسِ هَجَرَ. (خ,د,ت,ن)', 'മറ്റൊരു നിവേദനത്തിൽ: നബി(സ) ഹജറിലെ മജൂസികളിൽ നിന്ന് ജിസ്‌യ സ്വീകരിച്ചിരുന്നെന്ന് അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ) പറയുന്നത് വരെ ഉമർ(റ) മജൂസികളിൽ നിന്ന് ജിസ്‌യ സ്വീകരിക്കാറുണ്ടായിരുന്നില്ല. (ബു,ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنِ السَّائِبِ بْنِ يَزِيدَ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْجِزْيَةَ مِنْ مَجُوسِ الْبَحْرَيْنِ، وَأَخَذَهَا عُمَرُ مِنْ فَارِسَ، وَأَخَذَهَا عُثْمَانُ مِنَ الْبَرْبَرِ. (ت)', 'സാഇബുബ്നു യസീദ്(റ): ബഹ്റൈനിലെ മജൂസികളിൽ നിന്ന് റസൂൽ(സ) ജിസ്‌യ സ്വീകരിച്ചിരുന്നു. പേർഷ്യയിൽ നിന്ന് ഉമർ(റ)വും ബർബരികളിൽ നിന്ന് ഉസ്മാൻ(റ)വും ജിസ്‌യ സ്വീകരിച്ചിരുന്നു. (തു)', 'السَّائِبِ بْنِ يَزِيدَ', 'സാഇബുബ്നു യസീദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 48, 48, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ هِشَامِ بْنِ حَكِيمِ بْنِ حِزَامٍ رَضِيَ اللَّهُ عَنْهُمَا: وَجَدَ رَجُلًا - وَهُوَ عَلَى حِمْصَ - يُشَمِّسُ نَاسًا مِنَ الْقِبْطِ فِي أَدَاءِ الْجِزْيَةِ، فَقَالَ: مَا هَذَا؟ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ اللَّهَ يُعَذِّبُ الَّذِينَ يُعَذِّبُونَ النَّاسَ فِي الدُّنْيَا". (م,د,ن)', 'ഹിശാമുബ്നു ഹകീമുബ്നു ഹിസാം(റ): ഹിംസ്വിലെ ഗവർണ്ണറായിരുന്ന ഒരാൾ, ഖിബ്ത്വികളിലെ ചിലയാളുകളെ, ജിസ്‌യ നൽകാത്തതിന്റെ പേരിൽ, വെയിലിൽ നിർത്തിയതായി അദ്ദേഹം കണ്ടു. അദ്ദേഹം ചോദിച്ചു: എന്താണിത്? റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "ഐഹിക ലോകത്തുവെച്ച് ജനങ്ങളെ ശിക്ഷിക്കുന്നവരെ നിശ്ചയം അല്ലാഹു ശിക്ഷിക്കുന്നതാണ്." (മു,ദ,ന)', 'هِشَامِ بْنِ حَكِيمِ بْنِ حِزَامٍ', 'ഹിശാമുബ്നു ഹകീമുബ്നു ഹിസാം(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 48, 48, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ حَرْبِ بْنِ عُبَيْدِ اللَّهِ بْنِ عُمَيْرٍ الثَّقَفِيِّ، عَنْ جَدِّهِ أَبِي أُمِّهِ، عَنْ أَبِيهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا الْعُشُورُ عَلَى الْيَهُودِ وَالنَّصَارَى، وَلَيْسَ عَلَى الْمُسْلِمِينَ عُشُورٌ". وَفِي رِوَايَةٍ: "خَرَاجٌ". (د)', 'ഹർബുബ്നു ഉബൈദില്ലാഹിബ്നു ഉമൈരിസ്സഖഫി, തന്റെ മാതാവ് വഴിക്കുള്ള പിതാമഹനിൽ നിന്നും, അദ്ദേഹം തന്റെ പിതാവിൽനിന്നും നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "പത്തിലൊന്ന് ജൂതർക്കും ക്രസ്ത്യാനികൾക്കും മാത്രമാണ് നിർബന്ധം, മുസ്‌ലിംകൾക്ക് പത്തിലൊന്ന് നിർബന്ധമില്ല." മറ്റൊരു നിവേദനത്തിൽ "നികുതി" എന്നാണുള്ളത്. (ദ)', 'حَرْبِ بْنِ عُبَيْدِ اللَّهِ بْنِ عُمَيْرٍ الثَّقَفِيِّ، عَنْ جَدِّهِ أَبِي أُمِّهِ، عَنْ أَبِيهِ، قَالَ', null, null, null, array['د']::text[], array['ദ']::text[], null, null, 48, 48, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=18), 1, 'وَفِي رِوَايَةٍ: "خَرَاجٌ". (د)', 'മറ്റൊരു നിവേദനത്തിൽ "നികുതി" എന്നാണുള്ളത്. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ عَطَاءِ بْنِ السَّائِبِ، عَنْ رَجُلٍ مِنْ بَكْرِ بْنِ وَائِلٍ، عَنْ خَالِهِ، قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، أُعَشِّرُ قَوْمِي؟ قَالَ: "إِنَّمَا الْعُشُورُ عَلَى الْيَهُودِ وَالنَّصَارَى". (د)', 'അത്വാഉബ്നു സാഇബ്, ബക്റുബ്നു വാഇലിൽപെട്ട ഒരാളിൽ നിന്നും, അദ്ദേഹം തന്റെ അമ്മാവനിൽ നിന്നും നിവേദനം: ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ സമൂഹത്തിൽ നിന്ന് ഞാൻ പത്തിലൊന്ന് (നികുതി) വാങ്ങട്ടെയോ? അവിടുന്ന് പറഞ്ഞു: "പത്തിലൊന്ന് ജൂതർക്കും ക്രൈസ്തവർക്കും മാത്രമാണ് നിർബന്ധമുള്ളത്." (ദ)', 'عَطَاءِ بْنِ السَّائِبِ، عَنْ رَجُلٍ مِنْ بَكْرِ بْنِ وَائِلٍ، عَنْ خَالِهِ، قَالَ', null, null, null, array['د']::text[], array['ദ']::text[], null, null, 49, 49, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ حَرْبِ بْنِ عُبَيْدِ اللَّهِ بْنِ عُمَيْرٍ الثَّقَفِيِّ، عَنْ جَدِّهِ - رَجُلٍ مِنْ بَنِي تَغْلِبَ - قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَسْلَمْتُ وَعَلَّمَنِي الْإِسْلَامَ، وَعَلَّمَنِي كَيْفَ آخُذُ الصَّدَقَةَ مِنْ قَوْمِي مِمَّنْ أَسْلَمَ، ثُمَّ رَجَعْتُ إِلَيْهِ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، كُلُّ مَا عَلَّمْتَنِي قَدْ حَفِظْتُهُ إِلَّا الصَّدَقَةَ، أَفَأُعَشِّرُهُمْ؟ قَالَ: "لَا، إِنَّمَا الْعُشُورُ عَلَى النَّصَارَى وَالْيَهُودِ". (د)', 'ഹർബുബ്നു ഉബൈദില്ലാഹിബ്നു ഉമൈരിസ്സഖഫി ബനൂതഗ്ലബിൽപെട്ട തന്റെ പിതാമഹനിൽ നിന്ന് നിവേദനം: അദ്ദേഹം പറഞ്ഞു: ഞാൻ നബി(സ)യുടെ സന്നിധിയിൽ ചെല്ലുകയും മുസ്‌ലിമാവുകയും ചെയ്തു. അവിടുന്ന് എനിക്ക് ഇസ്‌ലാമിനെ സംബന്ധിച്ചും, എന്റെ സമൂഹത്തിൽ മുസ്‌ലിമായവരുടെ പക്കൽനിന്ന് എപ്രകാരമാണ് സകാത് പിരിക്കേണ്ടത് എന്നും പഠിപ്പിച്ചു തന്നു. ശേഷം ഞാൻ നബി(സ)യുടെ അടുത്തേക്ക് മടങ്ങിച്ചെന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടുന്നെനിക്ക് പഠിപ്പിച്ചു തന്നതെല്ലാം ഞാൻ മനഃപാഠമാക്കിയിരിക്കുന്നു, സകാതിന്റെ കാര്യമൊഴികെ. ഞാൻ അവരിൽനിന്ന് (എന്റെ സമൂഹത്തിൽനിന്ന്) പത്തിലൊന്ന് വാങ്ങേണ്ടതുണ്ടോ? അവിടുന്ന് പറഞ്ഞു: "ഇല്ല, പത്തിലൊന്ന് ജൂതർക്കും ക്രസ്ത്യാനികൾക്കും മാത്രമുള്ളതാണ്." (ദ)', 'حَرْبِ بْنِ عُبَيْدِ اللَّهِ بْنِ عُمَيْرٍ الثَّقَفِيِّ، عَنْ جَدِّهِ - رَجُلٍ مِنْ بَنِي تَغْلِبَ - قَالَ', null, null, null, array['د']::text[], array['ദ']::text[], null, null, 49, 49, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنِ الْعِرْبَاضِ بْنِ سَارِيَةَ السُّلَمِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَزَلْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ وَمَعَهُ مَنْ مَعَهُ مِنْ أَصْحَابِهِ، وَكَانَ صَاحِبُ خَيْبَرَ رَجُلًا مَارِدًا مُنْكَرًا، فَأَقْبَلَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا مُحَمَّدُ، أَلَكُمْ أَنْ تَذْبَحُوا حُمُرَنَا، وَتَأْكُلُوا ثَمَرَنَا، وَتَضْرِبُوا نِسَاءَنَا؟ فَغَضِبَ - يَعْنِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَقَالَ: "يَا ابْنَ عَوْفٍ، ارْكَبْ فَرَسَكَ ثُمَّ نَادِ: أَلَا إِنَّ الْجَنَّةَ لَا تَحِلُّ إِلَّا لِمُؤْمِنٍ، وَأَنِ اجْتَمِعُوا لِلصَّلَاةِ". قَالَ: فَاجْتَمَعُوا، ثُمَّ صَلَّى بِهِمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَامَ فَقَالَ: "أَيَحْسَبُ أَحَدُكُمْ - مُتَّكِئًا عَلَى أَرِيكَتِهِ - قَدْ يَظُنُّ أَنَّ اللَّهَ لَمْ يُحَرِّمْ شَيْئًا إِلَّا مَا فِي هَذَا الْقُرْآنِ، أَلَا وَإِنِّي وَاللَّهِ قَدْ وَعَظْتُ وَأَمَرْتُ وَنَهَيْتُ عَنْ أَشْيَاءَ إِنَّهَا لَمِثْلُ الْقُرْآنِ أَوْ أَكْثَرُ، وَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَمْ يُحِلَّ لَكُمْ أَنْ تَدْخُلُوا بُيُوتَ أَهْلِ الْكِتَابِ إِلَّا بِإِذْنٍ، وَلَا ضَرْبَ نِسَائِهِمْ، وَلَا أَكْلَ ثِمَارِهِمْ، إِذَا أَعْطَوْكُمُ الَّذِي عَلَيْهِمْ". (د)', 'ഇർബാളുബ്നു സാരിയതുസ്സുലമി(റ): നബി(സ)യോടൊന്നിച്ച് ഞങ്ങൾ ഖൈബറിലിറങ്ങി. അവിടുത്തോടൊപ്പം കുറേ അനുചരരുമുണ്ടായിരുന്നു. ഖൈബറിലെ ഭരണാധികാരി ധിക്കാരിയും അക്രമിയുമായ ഒരുത്തനായിരുന്നു. അവൻ നബി(സ)യുടെ മുന്നിൽ വന്നുകൊണ്ട് ചോദിച്ചു: മുഹമ്മദേ, ഞങ്ങളുടെ കഴുതകളെ അറുക്കലും, പഴങ്ങൾ ഭക്ഷിക്കലും, സ്ത്രീകളെ അക്രമിക്കലും നിങ്ങൾക്ക് അനുവദനീയമാണോ? അപ്പോൾ നബി(സ) ദേഷ്യപ്പെട്ടുകൊണ്ട് പറഞ്ഞു: "ഇബ്നുഔഫേ, താങ്കൾ കുതരപ്പുറത്ത് കയറി ഇപ്രകാരം വിളിച്ചു പറയുക: അറിയുക, നിശ്ചയം സത്യവിശ്വാസികൾക്കല്ലാതെ സ്വർഗ്ഗം അനുവദനീയമാവുകയില്ല, നിങ്ങൾ നമസ്കാരത്തിന് ഒരുമിച്ചു കൂടുക." നവേദകൻ പറയുന്നു: അങ്ങനെ ജനങ്ങൾ ഒരുമിച്ചു കൂടുകയും നബി(സ) അവർക്ക് ഇമാമായി നമസ്കരിക്കുകയും ചെയ്തു, ശേഷം അവിടുന്ന് എഴുന്നേറ്റ് നിന്ന് പറഞ്ഞു: "ഈ ഖുർആനിലുള്ളത് മാത്രമാണ് നിശ്ചയം അല്ലാഹു നിഷിദ്ധമാക്കിയിട്ടുള്ളതെന്ന് - തന്റെ ചാരുകട്ടിലിൽ ചാരിയിരുന്നുകൊണ്ട് - നിങ്ങളിലൊരുത്തൻ വിചാരിക്കുന്നുണ്ടോ. അറിയുക, അല്ലാഹുവാണ, നിശ്ചയം ഞാൻ ഉപദേശിക്കുകയും കുറേ കാര്യങ്ങൾ കൽപിക്കുകയും വിരോധിക്കുകയും ചെയ്തിട്ടുണ്ട്. അവ ഖുർആനിന്റെ അത്രയോ അതിൽ ഉപരിയോ വരും. മുൻ ഗ്രന്ഥക്കാർ, തങ്ങൾ നൽകേണ്ടത് നിങ്ങൾക്ക് നൽകിയാൽ, അനുവാദമില്ലാതെ അവരുടെ വീടുകളിൽ പ്രവേശിക്കുന്നതോ, അവരിലെ സ്ത്രീകളെ അക്രമിക്കുന്നതോ, അവരുടെ പഴങ്ങൾ ഭക്ഷിക്കുന്നതോ നിശ്ചയം അല്ലാഹു നിങ്ങൾക്ക് അനുവദനീയമാക്കിയിട്ടില്ല." (ദ)', 'الْعِرْبَاضِ بْنِ سَارِيَةَ السُّلَمِيِّ', 'ഇർബാളുബ്നു സാരിയതുസ്സുലമി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 49, 50, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ هِلَال الْوَزَّانِ، عَنْ رَجُلٍ مِنْ ثَقِيفٍ، عَنْ رَجُلٍ مِنْ جُهَيْنَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَعَلَّكُمْ تُقَاتِلُونَ قَوْمًا فَتَظْهَرُونَ عَلَيْهِمْ، فَيَتَّقُونَكُمْ بِأَمْوَالِهِمْ دُونَ أَنْفُسِهِمْ وَأَبْنَائِهِمْ، فَيُصَالِحُونَكُمْ عَلَى صُلْحٍ، فَلَا تُصِيبُوا مِنْهُمْ شَيْئًا فَوْقَ ذَلِكَ، فَإِنَّهُ لَا يَصْلُحُ لَكُمْ". (د)', 'ഹിലാലുനിൽവസാൻ, സഖീഫ് ഗോത്രത്തിൽപെട്ട ഒരാളിൽ നിന്നും, അദ്ദേഹം ജുഹൈന ഗോത്രത്തിൽപെട്ട ഒരാളിൽനിന്നും നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഒരു സമൂഹത്തോട് പോരാടുകയും വിജയം വരിക്കുകയും ചെയ്തേക്കാം. അങ്ങനെ അവർ തങ്ങളെയും തങ്ങളുടെ സന്താനങ്ങളെയും സമ്പത്ത് നൽകിക്കൊണ്ട് നിങ്ങളിൽനിന്ന് സംരക്ഷിക്കുകയും, നിങ്ങളോട് സന്ധിയിലേർപ്പെടുകയും ചെയ്യും. അപ്പോൾ അതിലുപരിയായി ഒന്നുംതന്നെ അവരിൽനിന്ന് നിങ്ങൾ വാങ്ങരുത്. നിശ്ചയം അത് നിങ്ങൾക്ക് അനുവദനീയമല്ല." (ദ)', 'هِلَال الْوَزَّانِ، عَنْ رَجُلٍ مِنْ ثَقِيفٍ، عَنْ رَجُلٍ مِنْ جُهَيْنَةَ قَالَ', null, null, null, array['د']::text[], array['ദ']::text[], null, null, 50, 50, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ صَفْوَانَ بْنِ سُلَيْمٍ، عَنْ عِدَّةٍ مِنْ أَبْنَاءِ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنْ آبَائِهِمْ دِنْيَةً، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَلَا مَنْ ظَلَمَ مُعَاهِدًا أَوِ انْتَقَصَهُ، أَوْ كَلَّفَهُ فَوْقَ طَاقَتِهِ، أَوْ أَخَذَ مِنْهُ شَيْئًا بِغَيْرِ طِيبِ نَفْسٍ، فَأَنَا حَجِيجُهُ يَوْمَ الْقِيَامَةِ". (د)', 'സ്വഫ്വാനുബ്നു സുലൈം, റസൂൽ(സ)യുടെ അനുചരരുടെ സന്താനങ്ങളിൽ കുറേ ആളുകളിൽനിന്നും, അവർ തങ്ങളുടെ വാപ്പമാരിൽനിന്നും നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "അറിയുക, സന്ധിയിലേർപെട്ടവനെ (ബഹുദൈവാരാധകരിലെ) അക്രമിക്കുകയോ, അവനോടുള്ള കരാർ ലംഘിക്കുകയോ, അവന്റെ കഴിവിൽ പെട്ടതിൽ ഉപരിയായി അവനോട് നിർബന്ധിക്കുകയോ, അവന്റെ പൂർണ്ണ തൃപ്തിയോടെയല്ലാതെ വല്ലതും അവനിൽനിന്ന് സ്വീകരിക്കുകയോ ചെയ്തവനെതിരെ അന്ത്യനാളിൽ ഞാൻ സാക്ഷി നിൽക്കുന്നതാണ്." (ദ)', 'صَفْوَانَ بْنِ سُلَيْمٍ، عَنْ عِدَّةٍ مِنْ أَبْنَاءِ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنْ آبَائِهِمْ دِنْيَةً، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ', null, null, null, array['د']::text[], array['ദ']::text[], null, null, 50, 50, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَيْسَ عَلَى الْمُسْلِمِ جِزْيَةٌ". (د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മുസ്‌ലിംകളുടെ മേൽ ജിസ്‌യയില്ല." (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 50, 50, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّا نَمُرُّ بِقَوْمٍ، فَلَا هُمْ يُضَيِّفُونَا، وَلَا هُمْ يُؤَدُّونَ مَا لَنَا عَلَيْهِمْ مِنَ الْحَقِّ، وَلَا نَحْنُ نَأْخُذُ مِنْهُمْ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنْ أَبَوْا إِلَّا أَنْ تَأْخُذُوا كَرْهًا فَخُذُوا". حَسَنٌ. (ق,ت)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): ഞാൻ റസൂൽ(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങൾ ഒരു സമൂഹത്തിന്റെയടുത്ത് കൂടെ നടന്നു പോകുന്നു. അവർ ഞങ്ങളെ സൽക്കരിക്കുകയോ ഞങ്ങളോടുള്ള കടമ നിർവ്വഹിക്കുക്കുകയോ ചെയ്യുന്നില്ല. ഞങ്ങൾ അവരിൽ നിന്ന് ഒന്നും വാങ്ങുന്നുമില്ല. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "ബലാൽക്കാരമായി വാങ്ങിയാലല്ലാതെ അവർ നൽകുന്നില്ലെങ്കിൽ. നിങ്ങൾ ബലാൽക്കാരമായി പിടിച്ചുവാങ്ങുക." ഹദീസ് ഹസനാണ്. (ബു,മു,തു)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 50, 51, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "غَزَا نَبِيٌّ مِنَ الْأَنْبِيَاءِ، فَقَالَ لِقَوْمِهِ: لَا يَتْبَعْنِي رَجُلٌ قَدْ مَلَكَ بُضْعَ امْرَأَةٍ، وَهُوَ يُرِيدُ أَنْ يَبْنِيَ بِهَا وَلَمَّا يَبْنِ. وَلَا آخَرُ قَدْ بَنَى بُنْيَانًا وَلَمَّا يَرْفَعْ سُقُفَهَا. وَلَا آخَرُ قَدِ اشْتَرَى غَنَمًا أَوْ خَلِفَاتٍ وَهُوَ مُنْتَظِرٌ وِلَادَهَا. قَالَ: فَغَزَى فَأَدْنَى لِلْقَرْيَةِ حِينَ صَلَاةِ الْعَصْرِ أَوْ قَرِيبًا مِنْ ذَلِكَ، فَقَالَ لِلشَّمْسِ: أَنْتِ مَأْمُورَةٌ وَأَنَا مَأْمُورٌ، اللَّهُمَّ احْبِسْهَا عَلَيَّ شَيْئًا، قَالَ: فَحُبِسَتْ عَلَيْهِ حَتَّى فَتَحَ اللَّهُ عَلَيْهِ، قَالَ: فَجَمَعُوا مَا غَنِمُوا، فَأَقْبَلَتِ النَّارُ لِتَأْكُلَهُ فَأَبَتْ أَنْ تَطْعَمَهُ، فَقَالَ: فِيكُمْ غُلُولٌ، فَلْيُبَايِعْنِي مِنْ كُلِّ قَبِيلَةٍ رَجُلٌ، فَبَايَعُوهُ فَلَصِقَتْ يَدُ رَجُلٍ بِيَدِهِ، فَقَالَ: فِيكُمُ الْغُلُولُ، فَلْتُبَايِعْنِي قَبِيلَتُكَ، فَبَايَعَتْهُ، قَالَ: فَلَصِقَتْ بِيَدِ رَجُلَيْنِ أَوْ ثَلَاثَةٍ، فَقَالَ: فِيكُمُ الْغُلُولُ، أَنْتُمْ غَلَلْتُمْ، قَالَ: فَأَخْرَجُوا لَهُ مِثْلَ رَأْسِ بَقَرَةٍ مِنْ ذَهَبٍ، قَالَ: فَوَضَعُوهُ فِي الْمَالِ، وَهُوَ بِالصَّعِيدِ، فَأَقْبَلَتِ النَّارُ فَأَكَلَتْهُ، فَلَمْ تَحِلَّ الْغَنَائِمُ لِأَحَدٍ مِنْ قَبْلِنَا، ذَلِكَ بِأَنَّ اللَّهَ تَبَارَكَ وَتَعَالَى رَأَى ضَعْفَنَا وَعَجْزَنَا، فَطَيَّبَهَا لَنَا". (ق)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "പ്രവാചകന്മാരിൽപ്പെട്ട ഒരു പ്രവാചകൻ യുദ്ധം ചെയ്തു. അദ്ദേഹം തന്റെ സമൂഹത്തോട് പറഞ്ഞു: വിവാഹം ചെയ്ത് ഭാര്യയുമായി വീടുകൂടിയിട്ടില്ലാത്തവനും അവളുമായി താമസിക്കാൻ താൽപര്യപ്പെടുന്നവനുമായ വ്യക്തി എന്നെ പിന്തുടരരുത്. വീട് നിർമ്മാണം ചെയ്ത് അതിന്റെ മേൽക്കൂര ഉയർത്താത്തവനും പ്രസവം പ്രതീക്ഷിക്കപ്പെടുന്ന ഒട്ടകങ്ങളെയോ, ആടുകളെയോ വാങ്ങിയവനും എന്നെ പിന്തുടരേണ്ട. അങ്ങനെ അവർ യുദ്ധം ചെയ്ത് അസർ നിസ്കാര സമയത്തോ അതിനോട് ചേർന്ന സമയത്തോ ഗ്രാമത്തോട് അടുത്തു. അപ്പോൾ പ്രവാചകൻ സൂര്യനോട് പറഞ്ഞു: ഞാനും നീയും കൽപനക്ക് വിധേയരാണ്. അല്ലാഹുവേ, സൂര്യനെ എനിക്ക് അൽപനേരം ബന്ധിപ്പിച്ച് തരണേ. നബി(സ) പറഞ്ഞു: അല്ലാഹു അവർക്ക് വിജയം നൽകുന്നതുവരെ സൂര്യൻ ബന്ധിക്കപ്പെട്ടു. ശേഷം അവർ യുദ്ധസമ്പത്ത് ഒരുമിച്ചു കൂട്ടി. അവ തിന്നാൻ തീ വന്നു. പക്ഷേ, അത് തിന്നില്ല. അപ്പോൾ പ്രവാചകൻ പറഞ്ഞു: നിങ്ങളിൽ പൂഴ്തിവെച്ചവരുണ്ട്. എല്ലാ ഗോത്രത്തിൽ നിന്നും എന്നോടൊരാൾ പ്രതിജ്ഞ ചെയ്യണം. അങ്ങനെ അവർ പ്രതിജ്ഞ ചെയ്തു. അപ്പോൾ ഒരാളുടെ കരം കയ്യിൽ ഒട്ടിപ്പിടിച്ചു. അപ്പോൾ പ്രവാചകൻ പറഞ്ഞു: നിങ്ങളുടെ ഗോത്രത്തിലാണ് പൂഴ്തിവെപ്പ് നടന്നിട്ടുള്ളത്. നിങ്ങളുടെ ഗോത്രം എന്നോട് പ്രതിജ്ഞ ചെയ്യട്ടെ. അപ്പോൾ രണ്ടോ മൂന്നോ ആളുകളുടെ കരങ്ങൾ ആ പ്രവാചകന്റെ കയ്യിൽ ഒട്ടിപ്പിടിച്ചു. പ്രവാചകൻ പറഞ്ഞു: നിങ്ങളുടെ പക്കലാണ് പൂഴ്തിവെക്കപ്പെട്ട വസ്തുവുള്ളത്, നിങ്ങളാണ് പൂഴ്തിവെച്ചിരിക്കുന്നത്. അപ്പോൾ അവർ ആ പ്രവാചകന് സ്വർണ്ണം കൊണ്ടുള്ള പശുവിന്റെ തല പോലുള്ള ഒരു വസ്തു പുറത്തെടുത്ത് കൊടുത്തു. പ്രവാചകൻ അത് യുദ്ധമുതലിൽ വെച്ചു. ആ മുതൽ മൈതാനിയിലായിരുന്നു. അങ്ങനെ തീ വന്ന് യുദ്ധമുതൽ കരിച്ചുകളഞ്ഞു. നമുക്ക് മുമ്പ് യുദ്ധമുതൽ ആർക്കും അനുവദനീയമായിട്ടില്ല. ഉന്നതനും പുണ്യവാനുമായ അല്ലാഹു നമ്മുടെ ബലഹീനതയും അശക്തിയും കണ്ടപ്പോൾ അത് നമുക്ക് തൃപ്തിപൂർവ്വം നൽകിയതാണ്." (ബു,മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 51, 51, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللَّهَ فَضَّلَنِي عَلَى الْأَنْبِيَاءِ. أَوْ قَالَ: أُمَّتِي عَلَى الْأُمَمِ، وَأَحَلَّ لِيَ الْغَنَائِمَ". (ت)', 'അബൂഉമാമ(റ): നബി(സ) പറഞ്ഞു: "എന്നെ അല്ലാഹു എല്ലാ പ്രവാചകരേക്കാളും ശ്രേഷ്ഠനാക്കി. അല്ലെങ്കിൽ: എന്റെ സമൂഹത്തെ എല്ലാ സമൂഹങ്ങളേക്കാളും അല്ലാഹു ശ്രേഷ്ഠമാക്കിയിരിക്കുന്നു. അല്ലാഹു എനിക്ക് യുദ്ധമുതൽ അനുവദനീയമാക്കിയിരിക്കുന്നു." (തു)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 51, 52, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "فُضِّلْتُ عَلَى الْأَنْبِيَاءِ بِسِتٍّ: أُعْطِيتُ جَوَامِعَ الْكَلِمِ، وَنُصِرْتُ بِالرُّعْبِ، وَأُحِلَّتْ لِيَ الْغَنَائِمُ، وَجُعِلَتْ لِيَ الْأَرْضُ مَسْجِدًا وَطَهُورًا، وَأُرْسِلْتُ إِلَى الْخَلْقِ كَافَّةً، وَخُتِمَ بِيَ النَّبِيُّونَ". (ق,ت,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഞാൻ ആറ് കാര്യങ്ങൾ കൊണ്ട് സകല പ്രവാചകരേക്കാളും ശ്രേഷ്ഠനാക്കപ്പെട്ടിരിക്കുന്നു: എനിക്ക് സംക്ഷിപ്ത വചനങ്ങൾ നൽകപ്പെട്ടു, ഭയത്താൽ¹ ഞാൻ സഹായിക്കപ്പെട്ടു, യുദ്ധമുതൽ എനിക്ക് അനുവദനീയമാക്കപ്പെട്ടു, ഭൂമി എനിക്ക് പരിശുദ്ധവും സാഷ്ടാംഗസ്ഥാനവുമാക്കപ്പെട്ടു, ഞാൻ സകല സൃഷ്ടികളിലേക്കും നിയുക്തനായി, എന്നെക്കൊണ്ട് പ്രവാചകർക്ക് അവസാനം കുറിക്കപ്പെട്ടു." (ബു,മു,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', '¹. നബി(സ)യെ കണ്ടാൽ ഒറ്റനോട്ടത്തിൽ തന്നെ ശത്രുക്കൾ ഭയന്നുപോകുമായിരുന്നു.', null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 52, 52, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ كَانَ يُنَفِّلُ بَعْضَ مَنْ يَبْعَثُ مِنَ السَّرَايَا لِأَنْفُسِهِمْ خَاصَّةً، سِوَى قَسْمِ عَامَّةِ الْجَيْشِ، وَالْخُمْسُ فِي ذَلِكَ وَاجِبٌ كُلِّهِ. (م)', 'ഇബ്നുഉമർ(റ): നിശ്ചയം റസൂൽ(സ) പൊതുസൈന്യത്തിന്റെ വിഹിതത്തിന് പുറമെ, യുദ്ധസംഘങ്ങളിലായി അവിടന്ന് അയക്കാറുണ്ടായിരുന്ന ചിലർക്ക് പ്രത്യേകമായി യുദ്ധമുതൽ വീതിക്കാറുണ്ടായിരുന്നു. അതിലെല്ലാത്തിലും അഞ്ചിൽ ഒന്ന് നിർബന്ധമാണ്.² (മു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', '². യുദ്ധമുതലിന്റെ അഞ്ചിലൊന്ന് ആദ്യംതന്നെ മാറ്റിവെക്കപ്പെടും. അതിനു ശേഷമായിരുന്നു സർവ്വ വിഹിതവും കണക്കാക്കപ്പെട്ടിരുന്നത് എന്നർത്ഥം.', null, array['م']::text[], array['മു']::text[], null, null, 52, 52, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ عَمْرِو بْنِ عَبَسَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: صَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى بَعِيرٍ مِنَ الْمَغْنَمِ، فَلَمَّا سَلَّمَ أَخَذَ وَبَرَةً مِنْ جَنْبِ الْبَعِيرِ، ثُمَّ قَالَ: "وَلَا يَحِلُّ لِي مِنْ غَنَائِمِكُمْ مِثْلُ هَذَا، إِلَّا الْخُمُسُ، وَالْخُمُسُ مَرْدُودٌ فِيكُمْ". (د,ن,جه)', 'അംറുബ്നു അബസ(റ): റസൂൽ(സ) ഞങ്ങളുമായി യുദ്ധമുതലിൽ പെട്ട ഒരു ഒട്ടകത്തിന്റെ നേരെ നിന്ന് നിസ്കരിച്ചു. അങ്ങനെ സലാം വീട്ടിയപ്പോൾ അവിടുന്ന് ആ ഒട്ടകത്തിന്റെ ഒരു ഭാഗത്തുള്ള മൃദുവായ ഒരു രോമം എടുത്തു, പിന്നെ പറഞ്ഞു: "എനിക്ക് നിങ്ങളുടെ യുദ്ധമുതലിൽ നിന്ന് അഞ്ചിലൊന്നല്ലാത്ത, ഇതുപോലുള്ള ഒന്നുപോലും അനുവദനീയമാവുകയില്ല, അഞ്ചിലൊന്നാണെങ്കിൽ നിങ്ങളിലേക്ക് തന്നെ മടക്കപ്പെടുന്നതുമാണ്." (ദ,ന,ജ)', 'عَمْرِو بْنِ عَبَسَةَ', 'അംറുബ്നു അബസ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 52, 52, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ جَابِرِ بْنِ عَبْدالله الْأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: وُلِدَ لِرَجُلٍ مِنَّا غُلَامٌ، فَسَمَّاهُ الْقَاسِمَ، فَقَالَتِ الْأَنْصَارُ لَا نَكْنِيكَ أَبَا الْقَاسِمِ، وَلَا نُنْعِمُكَ عَيْنًا فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ وُلِدَ لِي غُلَامٌ فَسَمَّيْتُهُ الْقَاسِمَ فَقَالَتِ الْأَنْصَارُ: لَا نَكْنِيكَ أَبَا الْقَاسِمِ، وَلَا نُنْعِمُكَ عَيْنًا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَحْسَنَتِ الْأَنْصَارُ، سَمُّوا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي، فَإِنَّمَا أَنَا قَاسِمٌ". (خ)', 'ജാബിറുബ്നു അബ്ദില്ലാഹിൽ അൻസാരി(റ): ഞങ്ങളിൽ പെട്ട ഒരാൾക്ക് ഒരു കുഞ്ഞ് ജനിച്ചു. അദ്ദേഹമവന് ഖാസിം എന്ന് പേരിട്ടു. അൻസാറുകൾ പറഞ്ഞു: നിന്നെ ഞങ്ങൾ അബുൽഖാസിം എന്ന ഓമനപ്പേര് വിളിക്കില്ല. നിന്നെ ഞങ്ങൾ അനുഗ്രഹിക്കുന്നുമില്ല. അപ്പോൾ അദ്ദേഹം നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: റസൂലേ, എനിക്കൊരു കുഞ്ഞ് പിറന്നു. ഞാനവന് ഖാസിം എന്ന് പേരിട്ടിരിക്കുന്നു. അപ്പോൾ അൻസാറുകൾ പറഞ്ഞു: നിന്നെ ഞങ്ങൾ അബുൽഖാസിം എന്ന് വിളിക്കുന്നില്ല, നിന്നെ ഞങ്ങൾ അനുഗ്രഹിക്കുന്നുമില്ല. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "അൻസാറുകൾ നല്ലതാണ് ചെയ്തത്. നിങ്ങൾ എന്റെ പേരിടുക. എന്റെ ഓമനപ്പേര് നിങ്ങൾ ഇടരുത്. ഞാൻ മാത്രമാണ് ഖാസിം (വീതം വെക്കുന്നവൻ)," (ബു)', 'جَابِرِ بْنِ عَبْدالله الْأَنْصَارِيِّ', 'ജാബിറുബ്നു അബ്ദില്ലാഹിൽ അൻസാരി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 52, 53, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا أُعْطِيكُمْ وَلَا أَمْنَعُكُمْ إِنَّمَا أَنَا قَاسِمٌ أَضَعُ حَيْثُ أُمِرْتُ". (خ)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ നിങ്ങൾക്ക് നൽകുകയോ തടയുകയോ ചെയ്യുന്നില്ല. ഞാൻ ഖാസിം (വീതിക്കുന്നവൻ) ആണ്. എന്നോട് കൽപിക്കപ്പെട്ട സ്ഥാനത്ത് ഞാൻ എല്ലാറ്റിനെയും വെക്കും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 53, 53, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَسْهَمَ لِرَجُلٍ وَلِفَرَسِهِ ثَلَاثَةَ أَسْهُمٍ: سَهْمًا لَهُ، وَسَهْمَيْنِ لِفَرَسِهِ. (ق,ت,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) ഒരാൾക്കും തന്റെ കുതിരക്കും മൂന്ന് ഓഹരികൾ നൽകി. ഒരു ഓഹരി അയാൾക്കും രണ്ടോഹരി തന്റെ കുതിരക്കും. (ബു,മു,തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 53, 53, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ أَبِي عَمْرَةَ، عَنْ أَبِيهِ، قَالَ: أَتَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرْبَعَةَ نَفَرٍ وَمَعَنَا فَرَسٌ، فَأَعْطَى كُلَّ إِنْسَانٍ مِنَّا سَهْمًا، وَأَعْطَى لِلْفَرَسِ سَهْمَيْنِ. وَفِي رِوَايَةٍ: ثَلَاثَةُ نَفَرٍ، وَفِيهَا: فَكَانَ لِلْفَارِسِ ثَلَاثَةُ أَسْهُمٍ. (د)', 'തന്റെ പിതാവിൽ നിന്ന് അബൂഅംറ(റ): ഞങ്ങൾ നാലുപേർ റസൂൽ(സ)യുടെ അടുത്ത് പോയി. ഞങ്ങളുടെ കൂടെ ഒരു കുത്വിരയുമുണ്ട്. ഞങ്ങളിൽ നിന്ന് ഓരോരുത്തർക്കും റസൂൽ(സ) ഓരോ ഓഹരി നൽകി. കുതിരക്ക് രണ്ട് ഓഹരികൾ നൽകി.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=34), 1, 'وَفِي رِوَايَةٍ: ثَلَاثَةُ نَفَرٍ، وَفِيهَا: فَكَانَ لِلْفَارِسِ ثَلَاثَةُ أَسْهُمٍ. (د)', 'മറ്റൊരു നിവേദനത്തിൽ ''മൂന്നുപേർ പോയി'' എന്നാണ്. കുതിരപ്പടയാളിക്ക് മൂന്ന് ഓഹരികളായിരുന്നെന്ന് ആ നിവേദനത്തിൽ ഉണ്ട്. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَسْهَمَ يَوْمَ خَيْبَرَ لِلْفَارِسِ ثَلَاثَةَ أَسْهُمٍ: لِلْفَرَسِ سَهْمَانِ، وَلِلرَّجُلِ سَهْمٌ وَاحِدٌ. (د,جه)', 'ഇബ്നുഉമർ(റ): ഖൈബർ ദിനത്തിൽ നബി(സ) കുതിരപ്പടയാളിക്ക് മൂന്ന് ഓഹരി നൽകി. കുതിരക്ക് രണ്ട് ഓഹരിയും, ആൾക്ക് ഒരോഹരിയും. (ദ,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 53, 53, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ جَاءَ هُوَ وَعُثْمَانُ بْنُ عَفَّانَ - رَضِيَ اللَّهُ عَنْهُ - إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُكَلِّمَانِهِ فِيمَا قَسَمَ مِنْ خُمُسِ خَيْبَرَ لِبَنِي هَاشِمٍ وَبَنِي الْمُطَّلِبِ، فَقَالَا: قَسَمْتَ لِإِخْوَانِنَا بَنِي هَاشِمٍ وَبَنِي الْمُطَّلِبِ، وَقَرَابَتُنَا وَاحِدَةٌ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا أَرَى بَنِي هَاشِمٍ وَبَنِي الْمُطَّلِبِ شَيْئًا وَاحِدًا". (خ,د,ن,جه)', 'ജുബൈറുബ്നു മുത്ഇം(റ): ബനൂമുത്ത്വലിബിനും ബനൂഹാഷിമിനും ഖൈബർ യുദ്ധത്തിലെ യുദ്ധമുതലിൽ നിന്ന് അഞ്ചിലൊന്ന് നൽകിയ വിഷയത്തിൽ സംസാരിക്കാൻ വേണ്ടി, ജുബൈർ(റ)വും ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ)വും റസൂൽ(സ)യുടെ അടുത്തേക്ക് ചെന്നു. അവർ രണ്ടുപേരും പറഞ്ഞു: ഞങ്ങളുടെ സഹോദരങ്ങളായ ബനൂഹാഷിമിനും ബനൂമുത്ത്വലിബിനും അങ്ങ് വിഹിതം നൽകി. ഞങ്ങളുടെ (തിരുമേനി(സ)യുമായുള്ള) കുടുംബബന്ധം ഒന്നു തന്നെയാണല്ലോ? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ ബനൂഹാഷിമിനെയും, ബനൂമുത്ത്വലിബിനെയും ഒന്നായാണ് കാണുന്നത്." (ബു,ദ,ന,ജ)', 'جُبَيْرِ بْنِ مُطْعِمٍ', 'ജുബൈറുബ്നു മുത്ഇം(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 53, 54, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَسَمَ فِي النَّفَلِ لِلْفَرَسِ سَهْمَيْنِ وَلِلرَّجُلِ سَهْمًا. (م)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) യുദ്ധമുതലിലുള്ള അധിക വിഹിതത്തെ കുതിരപ്പടയാളിക്ക് രണ്ട് വിഹിതവും കാലാൾപ്പടയാളിക്ക് ഒരു വിഹിതവുമായി വീതിച്ചു. (മു)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 54, 54, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ مُجَمِّعِ بْنِ جَارِيَةَ الْأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ - وَكَانَ أَحَدَ الْقُرَّاءِ الَّذِينَ قَرَءُوا الْقُرْآنَ - قَالَ: شَهِدْنَا الْحُدَيْبِيَةَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَلَمَّا انْصَرَفْنَا عَنْهَا إِذَا النَّاسُ يَهُزُّونَ الْأَبَاعِرَ، فَقَالَ بَعْضُ النَّاسِ لِبَعْضٍ: مَا لِلنَّاسِ؟ قَالُوا: أُوحِيَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَخَرَجْنَا مَعَ النَّاسِ نُوجِفُ، فَوَجَدْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاقِفًا عَلَى رَاحِلَتِهِ عِنْدَ كُرَاعِ الْغَمِيمِ، فَلَمَّا اجْتَمَعَ عَلَيْهِ النَّاسُ قَرَأَ عَلَيْهِمْ: {إِنَّا فَتَحْنَا لَكَ فَتْحًا مُبِينًا} فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، أَفَتْحٌ هُوَ؟ قَالَ: "نَعَمْ، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، إِنَّهُ لَفَتْحٌ". فَقُسِّمَتْ خَيْبَرُ عَلَى أَهْلِ الْحُدَيْبِيَةِ، فَقَسَمَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى ثَمَانِيَةَ عَشَرَ سَهْمًا، وَكَانَ الْجَيْشُ أَلْفًا وَخَمْسَ مِائَةٍ، فِيهِمْ ثَلَاثُ مِائَةِ فَارِسٍ، فَأَعْطَى الْفَارِسَ سَهْمَيْنِ، وَأَعْطَى الرَّاجِلَ سَهْمًا. (د)', 'മുജമ്മിഉബ്നു ജാരിയതുൽ അൻസാരി(റ) - അദ്ദേഹം ഖുർആൻ പഠിച്ചവരിൽ ഒരാളാണ് -: അദ്ദേഹം പറയുന്നു: ഞങ്ങൾ നബി(സ)യോടൊപ്പം ഹുദൈബിയ്യയിൽ സന്നിഹിതരായി. ഞങ്ങൾ അവിടെ നിന്നും തിരിച്ചു പോന്നപ്പോൾ ജനങ്ങളെല്ലാവരും ഒട്ടകങ്ങളെ വേഗത്തിൽ ഓടിക്കാൻ തുടങ്ങി. അപ്പോൾ ജനങ്ങളിൽ ചിലർ മറ്റുചിലരോട് പറഞ്ഞു: ഈ ജനങ്ങൾക്കെന്തു പറ്റി? അവർ പറഞ്ഞു: നബി(സ)ക്ക് വഹ്യ് ഇറക്കപ്പെട്ടിരിക്കുന്നു. അപ്പോൾ ഞങ്ങളും ജനങ്ങളോടൊപ്പം മൃഗങ്ങളെ വേഗത്തിൽ ഓടിക്കാൻ തുടങ്ങി. അങ്ങനെ കുറാഉൽ ഗമീമിനടുത്ത് റസൂൽ(സ) തന്റെ വാഹനത്തിനുമേൽ നിൽക്കുന്നതായി ഞങ്ങൾ കണ്ടു. നബി(സ)യുടെ ചുറ്റും ജനങ്ങൾ ഒരുമിച്ചുകൂടിയപ്പോൾ അവിടന്ന് അവർക്ക് ഓതിക്കൊടുത്തു: ''തീർച്ചയായും നാം അങ്ങേക്ക് വ്യക്തമായ വിജയം തുറന്നു തന്നിരിക്കുന്നു.'' അപ്പോൾ ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, അതൊരു വിജയമാണോ? അവിടന്ന് പറഞ്ഞു: "അതെ, മുഹമ്മദിന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവൻ തന്നെയാണ് സത്യം, തീർച്ചയായും അതൊരു വിജയമാണ്." അങ്ങനെ ഹുദൈബിയ്യക്കാർക്കായി ഖൈബർ വീതിക്കപ്പെട്ടു. അപ്പോൾ നബി(സ) അതിനെ പതിനെട്ട് വിഹിതമായി വീതിച്ചു. സൈന്യം ആയിരത്തഞ്ഞൂറ് പേരായിരുന്നു. അതിൽ മുന്നൂറ് കുതിരപ്പടയാളികളുണ്ടായിരുന്നു. കുതിരപ്പടയാളികൾക്ക് രണ്ട് വിഹിതവും കാലാൾപ്പടക്ക് ഒരു വിഹിതവും നൽകി. (ദ)', 'مُجَمِّعِ بْنِ جَارِيَةَ الْأَنْصَارِيِّ', 'മുജമ്മിഉബ്നു ജാരിയതുൽ അൻസാരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 54, 54, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ عُمَرَ أَصَابَ جَارِيَتَيْنِ مِنْ سَبْيِ حُنَيْنٍ فَوَضَعَهُمَا فِي بَعْضِ بُيُوتِ مَكَّةَ، قَالَ: فَمَنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى سَبْيِ حُنَيْنٍ، فَجَعَلُوا يَسْعَوْنَ فِي السِّكَكِ، فَقَالَ عُمَرُ: يَا عَبْدَالله، انْظُرْ مَا هَذَا؟ قَالَ: مَنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى السَّبْيِ، قَالَ: اذْهَبْ فَأَرْسِلِ الْجَارِيَتَيْنِ. (خ)', 'ഇബ്നുഉമർ(റ): ഹുനൈൻ ബന്ധികളിൽ നിന്ന് ഉമർ(റ)വിന് രണ്ട് അടിമസ്ത്രീകളെ ലഭിച്ചു, അങ്ങനെ അവരെ മക്കയിലുള്ള ചില വീടുകളിൽ ആക്കി. നിവേദകൻ പറയുന്നു: അങ്ങനെയിരിക്കെ നബി(സ) ഹുനൈൻ ബന്ധികൾക്ക് സ്വാതന്ത്ര്യം നൽകി. അപ്പോൾ അവർ വഴികളിലൂടെ നടക്കാൻ തുടങ്ങി. അപ്പോൾ ഉമർ(റ) ചോദിച്ചു: ഹേ, അബ്ദുല്ലാ, എന്താണിതെന്ന് നീ നോക്ക്. അദ്ദേഹം പറഞ്ഞു: നബി(സ) ബന്ധികളെ മോചിപ്പിച്ചിരിക്കുന്നു. ഉമർ(റ) പറഞ്ഞു: നീ പോയി ആ രണ്ട് അടിമസ്ത്രീകളെ വിട്ടയക്കുക. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 54, 55, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ عَبْدِالله رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا كَانَ يَوْمُ حُنَيْنٍ آثَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُنَاسًا فِي الْقِسْمَةِ فَأَعْطَى الْأَقْرَعَ بْنَ حَابِسٍ مِائَةً مِنَ الْإِبِلِ، وَأَعْطَى عُيَيْنَةَ مِثْلَ ذَلِكَ، وَأَعْطَى أُنَاسًا مِنْ أَشْرَافِ الْعَرَبِ، فَآثَرَهُمْ يَوْمَئِذٍ فِي الْقِسْمَةِ، قَالَ رَجُلٌ: وَاللَّهِ، إِنَّ هَذِهِ الْقِسْمَةَ مَا عُدِلَ فِيهَا وَمَا أُرِيدَ بِهَا وَجْهُ اللَّهِ، فَقُلْتُ: وَاللَّهِ لَأُخْبِرَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَتَيْتُهُ فَأَخْبَرْتُهُ، فَقَالَ: "فَمَنْ يَعْدِلُ إِذَا لَمْ يَعْدِلِ اللَّهُ وَرَسُولُهُ؟ رَحِمَ اللَّهُ مُوسَى، قَدْ أُوذِيَ بِأَكْثَرَ مِنْ هَذَا فَصَبَرَ". (خ)', 'അബ്ദുല്ല(റ): ഹുനൈൻ ദിവസത്തിൽ നബി(സ) വിഹിതത്തിനായി ചില ജനങ്ങളെ പ്രത്യേകം തെരഞ്ഞെടുത്തു. അഖ്റഉബ്നു ഹാബിസ്(റ)വിന് നൂറ് ഒട്ടകങ്ങളെ നൽകി. ഉയൈന(റ)വിനും അതുപോലെ നൽകി. അറേബ്യയിലെ ചില പ്രമുഖന്മാർക്ക് നബി(സ) നൽകുകയും അവർക്ക് (ഓഹരിയിൽ) പ്രാമുഖ്യം നൽകുകയും ചെയ്തു. അപ്പോൾ ഒരാൾ പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, തീർച്ചയായും ഇത് നീതിപൂർവ്വമല്ലാത്തതും അല്ലാഹുവിന്റെ പ്രീതി കാംക്ഷിക്കപ്പെടാത്തതുമായ വീതിക്കലാണ്. അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവാണ, നിശ്ചയം ഞാനിത് നബി(സ)യെ അറിയിക്കും. അങ്ങനെ ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്ന് അവിടുത്തോട് വിവരം പറഞ്ഞു: അവിടന്ന് പറഞ്ഞു: "അല്ലാഹുവും അവന്റെ റസൂലും നീതി പുലർത്തിയിട്ടില്ലെങ്കിൽ പിന്നെ ആരാണ് നീതി പുലർത്തുക, അല്ലാഹു മൂസാ(അ)മിന് കരുണ ചെയ്യട്ടെ. അദ്ദേഹം ഇതിനേക്കാൾ ഉപരിയായി ബുദ്ധിമുട്ടിക്കപ്പെട്ടിരുന്നു. അദ്ദേഹം അതെല്ലാം ക്ഷമിച്ചു." (ബു)', 'عَبْدِالله', 'അബ്ദുല്ല(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 55, 55, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي أُعْطِي قُرَيْشًا أَتَأَلَّفُهُمْ، لِأَنَّهُمْ حَدِيثُ عَهْدٍ بِجَاهِلِيَّةٍ". (د)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "കൂടുതൽ (ഇസ്‌ലാമുമായി) അടുപ്പിക്കാൻ വേണ്ടി ഖുറൈശികൾക്ക് ഞാൻ നൽകും. കാരണം, അജ്ഞാനയുഗത്തോട് കാലം കൊണ്ട് അടുത്തവരാണവർ." (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 55, 55, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: إِنَّ نَاسًا مِنَ الْأَنْصَارِ قَالُوا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ أَفَاءَ اللَّهُ عَلَى رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ أَمْوَالِ هَوَازِنَ مَا أَفَاءَ، فَطَفِقَ يُعْطِي رِجَالًا مِنْ قُرَيْشٍ الْمِائَةَ مِنَ الْإِبِلِ، فَقَالُوا: يَغْفِرُ اللَّهُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يُعْطِي قُرَيْشًا وَيَدَعُنَا، وَسُيُوفُنَا تَقْطُرُ مِنْ دِمَائِهِمْ، قَالَ أَنَسٌ: فَحُدِّثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَقَالَتِهِمْ فَأَرْسَلَ إِلَى الْأَنْصَارِ فَجَمَعَهُمْ فِي قُبَّةٍ مِنْ أَدَمٍ، وَلَمْ يَدْعُ مَعَهُمْ أَحَدًا غَيْرَهُمْ، فَلَمَّا اجْتَمَعُوا جَاءَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: مَا كَانَ حَدِيثٌ بَلَغَنِي عَنْكُمْ؟ قَالَ لَهُ فُقَهَاؤُهُمْ: أَمَّا ذَوُو آرَائِنَا يَا رَسُولَ اللَّهِ فَلَمْ يَقُولُوا شَيْئًا، وَقَدْ تَقَدَّمَ الْحَدِيثُ بِطُولِهِ. (خ)', 'അനസ്(റ): അല്ലാഹു ഹവാസിനിലെ സമ്പത്തിൽ നിന്ന് അല്ലാഹുവിന്റെ റസൂൽ(സ)ക്ക് യുദ്ധമുതലായി നൽകുകയും അവിടന്ന് ഖുറൈശികളിലെ ചിലർക്ക് നൂറ് ഒട്ടകങ്ങൾ (പോലും) നൽകാൻ തുടങ്ങുകയും ചെയ്തപ്പോൾ അൻസ്വാറുകളിൽപെട്ട ചിലയാളുകൾ റസൂൽ(സ)യെക്കുറിച്ച് പറഞ്ഞു: റസൂൽ(സ)ക്ക് അല്ലാഹു പൊറുത്ത് കൊടുക്കട്ടെ. ഞങ്ങളുടെ വാളുകളിൽ നിന്ന് ശത്രുക്കളുടെ രക്തം ഉറ്റിക്കൊണ്ടിരിക്കെ അവിടുന്ന് ഞങ്ങളെ ഒഴിവാക്കുകയും ഖുറൈശികൾക്ക് നൽകുകയും ചെയ്യുന്നു. അനസ്(റ) പറയുന്നു: അവരുടെ സംസാരം റസൂൽ(സ) അറിയാനിടയായി. അപ്പോൾ അവിടുന്ന് അവരിലേക്ക് ആളെ അയക്കുകയും അവരെ തോലിന്റെ ഒരു കൂടാരത്തിൽ ഒരുമിച്ച് കൂട്ടുകയും ചെയ്തു. അവരുടെ കൂടെ അവരല്ലാത്തവരാരെയും വിളിച്ചില്ല. അങ്ങനെ അവർ ഒരുമിച്ച് കൂടിയപ്പോൾ അവരിലേക്ക് അല്ലാഹുവിന്റെ റസൂൽ(സ) വന്ന് ഇപ്രകാരം പറഞ്ഞു: "നിങ്ങളെക്കുറിച്ച് ഞാനറിഞ്ഞ വാർത്തയെന്താണ്?" അപ്പോൾ അവരിലെ തന്റേടമുള്ളവർ അവിടുത്തോട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങളിലെ പക്വതയുള്ളവർ ഒന്നും പറഞ്ഞിട്ടില്ല. ഈ നീണ്ട ഹദീസ് മുമ്പ് വന്നിരിക്കുന്നു. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 55, 56, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ بَيْنَا هُوَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَعَهُ النَّاسُ مُقْبِلًا مِنْ حُنَيْنٍ، عَلِقَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْأَعْرَابُ يَسْأَلُونَهُ، حَتَّى اضْطَرُّوهُ إِلَى سَمُرَةٍ، فَخَطِفَتْ رِدَاءَهُ، فَوَقَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَعْطُونِي رِدَائِي، فَلَوْ كَانَ عَدَدُ هَذِهِ الْعِضَاهِ نَعَمًا لَقَسَمْتُهُ بَيْنَكُمْ، ثُمَّ لَا تَجِدُونِي بَخِيلًا وَلَا كَذُوبًا وَلَا جَبَانًا". (خ)', 'ജുബൈറുബ്നു മുത്ഇം(റ): അദ്ദേഹം റസൂൽ(സ)യോടു കൂടെ ജനങ്ങളോടൊന്നിച്ച് ഹുനൈനിൽ നിന്ന് മടങ്ങി വന്നുകൊണ്ടിരിക്കുമ്പോൾ റസൂൽ(സ)യെ അഅ്റാബികൾ ചോദ്യങ്ങൾ ചോദിച്ച് കൊണ്ട് ബന്ധിക്കുകയും ഒരു മുള്ളങ്കി മരത്തിന്റെ ഭാഗത്തേക്ക് അവർ തിരുമേനി(സ)യെ തള്ളിമാറ്റുകയും ചെയ്തു. അപ്പോൾ ആ മരം അവിടുത്തെ മേൽമുണ്ട് റാഞ്ചിയെടുത്തു. അപ്പോൾ അല്ലാഹുവിന്റെ റസൂൽ(സ) അവിടെ നിന്നുകൊണ്ട് പറഞ്ഞു: "നിങ്ങൾ എനിക്കെന്റെ മേൽത്തട്ടം തരിക. ഈ മുൾമരങ്ങളുടെ എണ്ണമത്രയും ഒട്ടകങ്ങളായിരുന്നുവെങ്കിൽ തീർച്ചയായും ഞാനവയെ നിങ്ങൾക്കിടയിൽ വീതിക്കുമായിരുന്നു. പിന്നീട് നിങ്ങളെന്നെ പിശുക്കനായോ കളവ് പറയുന്നവനായോ ഭീരുവായോ കാണുകയില്ല." (ബു)', 'جُبَيْرِ بْنِ مُطْعِمٍ', 'ജുബൈറുബ്നു മുത്ഇം(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 56, 56, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنْتُ أَمْشِي مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ بُرْدٌ نَجْرَانِيٌّ غَلِيظُ الْحَاشِيَةِ، فَأَدْرَكَهُ أَعْرَابِيٌّ فَجَذَبَهُ جَذْبَةً شَدِيدَةً، حَتَّى نَظَرْتُ إِلَى صَفْحَةِ عَاتِقِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ أَثَّرَتْ بِهِ حَاشِيَةُ الرِّدَاءِ مِنْ شِدَّةِ جَذْبَتِهِ، ثُمَّ قَالَ: مُرْ لِي مِنْ مَالِ اللَّهِ الَّذِي عِنْدَكَ، فَالْتَفَتَ إِلَيْهِ فَضَحِكَ، ثُمَّ أَمَرَ لَهُ بِعَطَاءٍ. (خ)', 'അനസബ്നു മാലിക്(റ): ഞാൻ നബി(സ)യോടൊപ്പം നടക്കുകയായിരുന്നു. വക്കുകൾ കട്ടി കൂടിയ ഒരു നജ്റാനി മേൽത്തട്ടം നബി(സ)യുടെ ദേഹത്തുണ്ടായിരുന്നു. അപ്പോൾ ഒരു അഅ്റാബി ആ മേൽത്തട്ടം കാണുകയും അത് ശക്തമായൊരു വലി വലിക്കുകയും ചെയ്തു. എത്രത്തോളമെന്നാൽ, അവിടുത്തെ തിരുതോളിന്റെ ഒരു ഭാഗത്ത് വലിയുടെ ശക്തി കാരണം മേൽത്തട്ടത്തിന്റെ വക്ക് അടയാളമുണ്ടാക്കിയതായി ഞാൻ കണ്ടു. പിന്നെ അഅ്റാബി പറഞ്ഞു: അങ്ങയുടെ അടുത്തുള്ള അല്ലാഹുവിന്റെ സ്വത്തിൽ നിന്ന് എനിക്ക് നൽകാൻ അങ്ങ് കൽപിച്ചാലും. അപ്പോൾ തിരുമേനി(സ) അയാളിലേക്ക് തിരിഞ്ഞ് നിന്ന് ചിരിക്കുകയും പിന്നെ അയാൾക്ക് വല്ലതും നൽകാൻ കൽപിക്കുകയും ചെയ്തു. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 56, 56, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ قَالَ: يَوْمُ الْخَمِيسِ، وَمَا يَوْمُ الْخَمِيسِ؟ ثُمَّ بَكَى حَتَّى خَضَبَ دَمْعُهُ الْحَصْبَاءَ، فَقَالَ: اشْتَدَّ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَجَعُهُ يَوْمَ الْخَمِيسِ، فَقَالَ: "ائْتُونِي بِكِتَابٍ أَكْتُبْ لَكُمْ كِتَابًا لَنْ تَضِلُّوا بَعْدَهُ أَبَدًا". فَتَنَازَعُوا، وَلَا يَنْبَغِي عِنْدَ نَبِيٍّ تَنَازُعٌ. فَقَالُوا: هَجَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "دَعُونِي، فَالَّذِي أَنَا فِيهِ خَيْرٌ مِمَّا تَدْعُونِي إِلَيْهِ". وَأَوْصَى عِنْدَ مَوْتِهِ بِثَلَاثٍ، أَخْرِجُوا الْمُشْرِكِينَ مِنْ جَزِيرَةِ الْعَرَبِ، وَأَجِيزُوا الْوَفْدَ بِنَحْوِ مَا كُنْتُ أُجِيزُهُمْ، وَنَسِيتُ الثَّالِثَةَ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): വ്യാഴാഴ്ച ദിവസം, എന്താണ് വ്യാഴാഴ്ച? പിന്നീടദ്ദേഹം കരയുകയും അദ്ദേഹത്തിന്റെ കണ്ണുനീർ മണൽ പരപ്പിനെ നനക്കുകയും ചെയ്തു. എന്നിട്ടദ്ദേഹം പറഞ്ഞു: വ്യാഴാഴ്ച ദിവസം അല്ലാഹുവിന്റെ റസൂൽ(സ)ക്ക് രോഗം ശക്തമായി, അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിങ്ങൾ ഒരു രേഖ കൊണ്ടുവരിക. ഞാൻ നിങ്ങൾക്ക് വേണ്ടി ചിലതെഴുതിത്തരാം. അതിന് ശേഷം നിങ്ങളൊരിക്കലും വഴിപിഴക്കുകയില്ല." അപ്പോൾ അവർ തർക്കിച്ചു. ഒരു നബിയുടെ സന്നിധിയിൽ വെച്ച് പരസ്പരം തർക്കം പാടില്ല. അങ്ങനെ അവർ പറഞ്ഞു: റസൂൽ(സ) അബോധാവസ്ഥയിൽ പറയുകയാണ്. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ എന്നെ ഒഴിവാക്കിത്തരൂ, നിങ്ങൾ എന്നെ ക്ഷണിക്കുന്ന കാര്യത്തിലേറെ ഉത്തമമായ ഒന്നിലാണ് ഞാനിപ്പോൾ ഉള്ളത്." അങ്ങനെ അവിടുന്ന് വഫാത്താകുന്ന സമയത്ത് മൂന്ന് കാര്യങ്ങൾ വസിയ്യത് ചെയ്തു. അറേബ്യൻ ഉപഭൂഖണ്ഡത്തിൽ നിന്നും ബഹുദൈവാരാധകരെ പുറത്താക്കുക, ദൗത്യവാഹക സംഘത്തിന് ഞാൻ നൽകാറുണ്ടായിരുന്നത് പോലെ നിങ്ങളും സമ്മാനങ്ങൾ നൽകുക, മൂന്നാമത്തേത് ഞാൻ മറന്നുപോയി. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 56, 57, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ بِخَيْبَرَ بَعْدَ مَا افْتَتَحُوهَا فَقُلْتُ: يَا رَسُولَ اللَّهِ أَسْهِمْ لِي، فَقَالَ بَعْضُ بَنِي سَعِيدِ بْنِ الْعَاصِ: لَا تُسْهِمْ لَهُ يَا رَسُولَ اللَّهِ، فَقَالَ أَبُو هُرَيْرَةَ: هَذَا قَاتِلُ ابْنِ قَوْقَلٍ، فَقَالَ ابْنُ سَعِيدِ بْنِ الْعَاصِ: وَاعَجَبًا لِوَبْرٍ تَدَلَّى عَلَيْنَا مِنْ قَدُومِ ضَأْنٍ يَنْعَى عَلَيَّ قَتْلَ رَجُلٍ مُسْلِمٍ أَكْرَمَهُ اللَّهُ عَلَى يَدَيَّ وَلَمْ يُهِنِّي عَلَى يَدَيْهِ. (خ,د)', 'അബൂഹുറൈറ(റ): അവർ (മുസ്‌ലിംകൾ) ഖൈബർ ജയിച്ചടക്കിയതിനു ശേഷം റസൂൽ(സ) ഖൈബറിലായിരിക്കെ ഞാൻ അവിടുത്തോട് ചെന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് എനിക്കും ഒരു ഓഹരി നൽകുക. അപ്പോൾ സഈദിബ്നിൽ ആസ്വിന്റെ മക്കളിലൊരാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടന്ന് അദ്ദേഹത്തിന് ഓഹരി നൽകരുത്. അപ്പോൾ അബൂഹുറൈറ(റ) പറഞ്ഞു: ഇബ്നു ഖൗഖലിനെ കൊന്നയാളാണിത്³. അപ്പോൾ സഈദിബ്നിൽ ആസ്വിന്റെ മകൻ പറഞ്ഞു: ഖുദൂമുളഅ്നിൽ നിന്ന് ഞങ്ങളിലേക്ക് ഇറങ്ങിവന്ന ഈ ശീമക്കുഴി മുയലിന്റെ⁴ കാര്യം അത്ഭുതകരം തന്നെ. എന്റെ കൈകളാൽ അല്ലാഹു ബഹുമാന്യനാക്കിയ ഒരു മുസ്‌ലിമായ മനുഷ്യനെ കൊന്നുവെന്നതാണിദ്ദേഹം, എന്റെ മേൽ ആരോപിക്കുന്നത്. ആ മനുഷ്യന്റെ കൈകളാൽ അല്ലാഹുവെന്നെ നിന്ദിച്ചിട്ടുമില്ല. (ബു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', '³. സഈദുബ്നുൽ ആസ്വിന്റെ മകനെക്കുറിച്ചാണ് അപ്രകാരം പറഞ്ഞത്.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ شِرَاءِ الْمَغَانِمِ حَتَّى تُقْسَمَ. (ت)', 'അബൂസഈദിനിൽ ഖുദ്‌രി(റ): വീതിക്കപ്പെടുന്നതിനു മുമ്പ് യുദ്ധമുതൽ വിൽപ്പന നടത്തലിനെ റസൂൽ(സ) വിലക്കിയിരിക്കുന്നു. (തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിനിൽ ഖുദ്‌രി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 57, 57, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ يَزِيدَ بْنِ هُرْمُزَ: أَنَّ نَجْدَةَ كَتَبَ إِلَى ابْنِ عَبَّاسٍ يَسْأَلُهُ عَنْ خَمْسِ خِلَالٍ؟ فَقَالَ ابْنُ عَبَّاسٍ: لَوْلَا أَنْ أَكْتُمَ عِلْمًا مَا كَتَبْتُ إِلَيْهِ، كَتَبَ إِلَيْهِ نَجْدَةُ: أَمَّا بَعْدُ، فَأَخْبِرْنِي: هَلْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَغْزُو بِالنِّسَاءِ؟ وَهَلْ كَانَ يَضْرِبُ لَهُنَّ بِسَهْمٍ؟ وَهَلْ كَانَ يَقْتُلُ الصِّبْيَانَ؟ وَمَتَى يَنْقَضِي يُتْمُ الْيَتِيمِ؟ وَعَنِ الْخُمْسِ لِمَنْ هُوَ؟ فَكَتَبَ إِلَيْهِ ابْنُ عَبَّاسٍ: كَتَبْتَ تَسْأَلُنِي: هَلْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَغْزُو بِالنِّسَاءِ؟ وَقَدْ كَانَ يَغْزُو بِهِنَّ، فَيُدَاوِينَ الْجَرْحَى وَيُحْذَيْنَ مِنَ الْغَنِيمَةِ، وَأَمَّا بِسَهْمٍ فَلَمْ يَضْرِبْ لَهُنَّ. وَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَكُنْ يَقْتُلُ الصِّبْيَانَ، فَلَا تَقْتُلِ الصِّبْيَانَ. وَكَتَبْتَ تَسْأَلُنِي: مَتَى يَنْقَضِي يُتْمُ الْيَتِيمِ؟ فَلَعَمْرِي إِنَّ الرَّجُلَ لَتَنْبُتُ لِحْيَتُهُ وَإِنَّهُ لَضَعِيفُ الْأَخْذِ لِنَفْسِهِ، ضَعِيفُ الْعَطَاءِ مِنْهَا، فَإِذَا أَخَذَ لِنَفْسِهِ مِنْ صَالِحِ مَا يَأْخُذُ النَّاسُ فَقَدْ ذَهَبَ عَنْهُ الْيُتْمُ. وَكَتَبْتَ تَسْأَلُنِي عَنِ الْخُمْسِ لِمَنْ هُوَ؟ وَإِنَّا كُنَّا نَقُولُ: هُوَ لَنَا، فَأَبَى عَلَيْنَا قَوْمُنَا ذَاكَ. (م)', 'യസീദുബ്നു ഹുർമുസ്(റ): നജ്ദത് അഞ്ച് കാര്യങ്ങളെക്കുറിച്ച് ചോദിച്ചുകൊണ്ട് ഇബ്നുഅബ്ബാസ്(റ)വിലേക്ക് ഒരു എഴുത്ത് എഴുതി. അപ്പോൾ ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ഞാൻ വിജ്ഞാനം മറച്ചുവെക്കുക എന്നത് (ആക്ഷേപം) ഉണ്ടായിരുന്നില്ലെങ്കിൽ ഞാൻ അദ്ദേഹത്തിന് മറുപടി എഴുതുമായിരുന്നില്ല. അദ്ദേഹത്തിന് നജ്ദത് എഴുതിയതിതാണ്: ഹംദ്, സ്വലാത്ത് എന്നിവക്കുശേഷം, താങ്കൾ എനിക്ക് അറിയിച്ച് തരിക: റസൂൽ(സ) സ്ത്രീകളെക്കൂട്ടി യുദ്ധം ചെയ്യാറുണ്ടായിരുന്നോ? ആ സ്ത്രീകൾക്ക് ഓഹരി വെക്കാറുണ്ടായിരുന്നോ? റസൂൽ(സ) കുട്ടികളെ കൊല്ലാറുണ്ടോ? അനാഥന്റെ അനാഥത്വം എപ്പോഴാണ് തീരുക? (ഓഹരിയിൽ) അഞ്ചിലൊന്ന് ആർക്കുള്ളതാണ്? ഇബ്നുഅബ്ബാസ്(റ) അദ്ദേഹത്തിന് മറുപടി എഴുതി: റസൂൽ(സ) സ്ത്രീകളെക്കൂട്ടി യുദ്ധം ചെയ്യാറുണ്ടായിരുന്നോ എന്ന് ചോദിച്ചുകൊണ്ട് എനിക്ക് നീ കത്തെഴുതി. തീർച്ചയായും അവിടന്ന് സ്ത്രീകളെക്കൂട്ടി യുദ്ധം ചെയ്യാറുണ്ടായിരുന്നു. അവർ മുറിവേറ്റവരെ ചികിത്സിക്കും, യുദ്ധമുതലിൽ നിന്ന് അവർക്ക് നൽകുകയും ചെയ്യും. എന്നാൽ അവർക്ക് ഓഹരിവെക്കപ്പെടുകയില്ല. തീർച്ചയായും തിരുമേനി(സ) കുട്ടികളെ കൊല്ലാറുണ്ടായിരുന്നില്ല. അതുകൊണ്ട് നീയും കുട്ടികളെ കൊല്ലരുത്. എപ്പോഴാണ് അനാഥന്റെ അനാഥത്തം അവസാനിക്കുക എന്ന് ചോദിച്ചുകൊണ്ടും നീ എനിക്കെഴുതി. എന്റെ ആയുസ്സ് തന്നെയാണ് സത്യം, തീർച്ചയായും ഒരു പുരുഷൻ സ്വന്തത്തിനുള്ളത് വാങ്ങാനും മറ്റുള്ളവർക്ക് താൻ നൽകാനുള്ളത് നൽകാനും അശക്തനായിരിക്കെത്തന്നെ അവന്ന് താടി മുളച്ചേക്കാം. എന്നാൽ സാധാരണ ജനങ്ങളെപ്പോലെ തനിയെ ഇടപാടു നടത്താൻ അവൻ തുടങ്ങിയാൽ അവന്റെ അനാഥത്വം നീങ്ങിയിരിക്കുന്നു. അഞ്ചിലൊന്ന് ആർക്കുള്ളതാണെന്നും നീ അന്വേഷിച്ചു. അത് ഞങ്ങൾക്കുള്ളതാണെന്ന് പറയുന്നവരായിരുന്നു ഞങ്ങൾ. പക്ഷേ, ഞങ്ങളുടെ സമുദായം ഞങ്ങൾക്കത് വിലക്കി. (മു)', 'يَزِيدَ بْنِ هُرْمُزَ', 'യസീദുബ്നു ഹുർമുസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 57, 58, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ يَزِيدَ بْنِ هُرْمُزَ قَالَ: كَتَبَ نَجْدَةُ إِلَى ابْنِ عَبَّاسٍ يَسْأَلُهُ عَنْ كَذَا وَكَذَا، وَذَكَرَ أَشْيَاءَ، وَعَنِ الْمَمْلُوكِ: أَلَهُ فِي الْفَيْءِ شَيْءٌ؟ وَعَنِ النِّسَاءِ: هَلْ كُنَّ يَخْرُجْنَ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ وَهَلْ لَهُنَّ نَصِيبٌ؟ فَقَالَ ابْنُ عَبَّاسٍ: لَوْلَا أَنْ يَأْتِيَ أُحْمُوقَةً مَا كَتَبْتُ إِلَيْهِ، أَمَّا الْمَمْلُوكُ فَكَانَ يُحْذَى، وَأَمَّا النِّسَاءُ فَقَدْ كُنَّ يُدَاوِينَ الْجَرْحَى وَيَسْقِينَ الْمَاءَ. (م,د,ت,ن)', 'യസീദുബ്നു ഹുർമുസ്(റ): ഇബ്നുഅബ്ബാസ്(റ)വിനോട് പലകാര്യങ്ങളെക്കുറിച്ചും ചോദിച്ചുകൊണ്ട് നജ്ദത് ഒരു കത്തെഴുതി. പലകാര്യങ്ങളും പറയുകയും അതോടൊപ്പം അടിമകൾക്ക് ഫൈഉൽ (യുദ്ധമില്ലാതെ ശത്രുക്കളിൽനിന്ന് കിട്ടുന്ന സമ്പത്ത്) നിന്നും വല്ലതും ലഭിക്കുമോയെന്നും, സ്ത്രീകൾ നബി(സ)യോടൊപ്പം യുദ്ധത്തിന് പോവാറുണ്ടായിരുന്നോയെന്നും, അവർക്ക് വല്ലവിഹിതവുമുണ്ടോയെന്നും അതിൽ ചോദിച്ചിരുന്നു. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അദ്ദേഹം വിഡ്ഢിത്തം പ്രവർത്തിക്കില്ലെങ്കിൽ ഞാൻ അദ്ദേഹത്തിന് മറുപടി എഴുതുമായിരുന്നില്ല. അടിമക്ക് മുതൽ നൽകപ്പെടാറുണ്ടായിരുന്നു. സ്ത്രീകൾ മുറിവേറ്റവരെ ചികിത്സിക്കുകയും വെള്ളം കുടിപ്പിക്കുകയും ചെയ്തിരുന്നു. (മു,ദ,തു,ന)', 'يَزِيدَ بْنِ هُرْمُزَ قَالَ', 'യസീദുബ്നു ഹുർമുസ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 58, 58, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ يَزِيدَ بْنِ هُرْمُزَ قَالَ: كَتَبَ نَجْدَةُ الْحَرُورِيُّ إِلَى ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا يَسْأَلُهُ عَنِ النِّسَاءِ: هَلْ كُنَّ يَشْهَدْنَ الْحَرْبَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ وَهَلْ كَانَ يَضْرِبُ لَهُنَّ بِسَهْمٍ؟ قَالَ: فَأَنَا كَتَبْتُ كِتَابَ ابْنِ عَبَّاسٍ إِلَى نَجْدَةَ: قَدْ كُنَّ يَحْضُرْنَ الْحَرْبَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَمَّا أَنْ يُضْرَبَ لَهُنَّ بِسَهْمٍ فَلَا، وَقَدْ كَانَ يُرْضَخُ لَهُنَّ. (م,د,ت,ن)', 'യസീദുബ്നു ഹുർമുസ്(റ): സ്ത്രീകളെക്കുറിച്ച്, അവർ റസൂൽ(സ)യോടൊപ്പം യുദ്ധത്തിൽ പങ്കെടുക്കാറുണ്ടായിരുന്നോ? അവർക്ക് റസൂൽ(സ) വിഹിതം നിശ്ചയിക്കാറുണ്ടായിരുന്നോ? എന്നെല്ലാം ചോദിച്ചുകൊണ്ട്, നജ്ദതുൽ ഹറൂരി ഇബ്നുഅബ്ബാസ്(റ)വിന് കത്തെഴുതി. നിവേദകൻ പറയുന്നു: ഇബ്നുഅബ്ബാസ്(റ)വിൽ നിന്ന് നജ്ദതിനുള്ള സന്ദേശം ഞാനാണ് എഴുതിയത് (അത് ഇപ്രകാരമായിരുന്നു): സ്ത്രീകൾ റസൂൽ(സ)യോടൊപ്പം യുദ്ധത്തിന് വരാറുണ്ടായിരുന്നു, എന്നാൽ അവർക്ക് വിഹിതം നിശ്ചയിക്കപ്പെടാറുണ്ടായിരുന്നില്ല. എന്നാലും അവർക്ക് (വിഹിതമല്ലാത്ത) സമ്പത്ത് നൽകപ്പെടാറുണ്ടായിരുന്നു. (മു,ദ,തു,ന)', 'يَزِيدَ بْنِ هُرْمُزَ قَالَ', 'യസീദുബ്നു ഹുർമുസ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 58, 59, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ أُمِّ زِيَادٍ الْأَشْجَعِيَّةِ رَضِيَ اللَّهُ عَنْهَا: أَنَّهَا خَرَجَتْ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ خَيْبَرَ سَادِسَ سِتِّ نِسْوَةٍ، فَبَلَغَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَعَثَ إِلَيْنَا، فَجِئْنَا فَرَأَيْنَا فِيهِ الْغَضَبَ، فَقَالَ: "مَعَ مَنْ خَرَجْتُنَّ وَبِإِذْنِ مَنْ خَرَجْتُنَّ". فَقُلْنَا: يَا رَسُولَ اللَّهِ، خَرَجْنَا نَغْزِلُ الشَّعَرَ، وَنُعِينُ بِهِ فِي سَبِيلِ اللَّهِ، وَمَعَنَا دَوَاءُ الْجَرْحَى، وَنُنَاوِلُ السِّهَامَ، وَنَسْقِي السَّوِيقَ، فَقَالَ: "قُمْنَ". حَتَّى إِذَا فَتَحَ اللَّهُ عَلَيْهِ خَيْبَرَ أَسْهَمَ لَنَا كَمَا أَسْهَمَ لِلرِّجَالِ. (د)', 'ഉമ്മുസിയാദിൽ അശ്ജഇയ്യ(റ): മഹതി ആറു സ്ത്രീകളിൽ ആറാമത്തവളായി റസൂൽ(സ)യോടൊപ്പം ഖൈബർ യുദ്ധത്തിനായി പുറപ്പെട്ടു. ആ വിവരം റസൂൽ(സ)യുടെ അടുക്കൽ എത്തുകയും അവിടന്ന് ഞങ്ങളെ വിളിച്ച് വരുത്തുകയും ചെയ്തു. ഞങ്ങൾ തിരുസന്നിധിയിൽ ചെല്ലുകയും തുരുമേനി(സ) ദേഷ്യത്തിലാണെന്ന് ഞങ്ങൾക്ക് മനസ്സിലാവുകയും ചയ്തു. അവിടന്ന് ചോദിച്ചു: "ആരുടെകൂടെയാണ് നിങ്ങൾ പുറപ്പെട്ടത്? ആരുടെ സമ്മതത്തോടെയാണ് നിങ്ങൾ പുറപ്പെട്ടത്?" ഞങ്ങൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഗാനമാലപിക്കാനും അതുകൊണ്ട് അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ സഹായിക്കുവാനും വേണ്ടിയാണ് ഞങ്ങൾ പുറപ്പെട്ടത്. മാത്രമല്ല, ഞങ്ങളുടെ അടുക്കൽ മുറിവേറ്റവർക്കുള്ള മരുന്നുമുണ്ട്. ഞങ്ങൾ അമ്പുകൾ എടുത്തുകൊടുക്കും, സവീഖ് (പൊടിയും പാലും ചേർത്തുണ്ടാക്കുന്നത്) കുടിപ്പിക്കും. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിങ്ങൾ നിൽക്കുക." അങ്ങനെ അല്ലാഹു അവിടുത്തേക്ക് ഖൈബർ കീഴ്പ്പെടുത്തിക്കൊടുത്തപ്പോൾ, പുരുഷന്മാർക്ക് യുദ്ധമുതൽ വീതിച്ചതുപോലെ അവിടുന്ന് ഞങ്ങൾക്കും വീതിച്ചു തന്നു. (ദ)', 'أُمِّ زِيَادٍ الْأَشْجَعِيَّةِ', 'ഉമ്മുസിയാദിൽ അശ്ജഇയ്യ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 59, 59, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنْتُ أَمِيحُ أَصْحَابِي الْمَاءَ يَوْمَ بَدْرٍ. (د)', 'ജാബിർ(റ): ബദർദിനത്തിൽ എന്റെ കൂട്ടുകാർക്ക് വേണ്ടി എന്റെ കൈകൾ കൊണ്ട് ഞാൻ വെള്ളം നിറച്ചിരുന്നു. (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 59, 59, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ عُمَيْرٍ مَوْلَى أَبِي اللَّحْمِ - رَضِيَ اللَّهُ عَنْهُمَا - قَالَ: شَهِدْتُ خَيْبَرَ مَعَ سَادَتِي، فَكَلَّمُوا فِيَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَكَلَّمُوهُ أَنِّي مَمْلُوكٌ، قَالَ: فَأَمَرَ بِي فَقُلِّدْتُ السَّيْفَ، فَإِذَا أَنَا أَجُرُّهُ، فَأَمَرَ لِي بِشَيْءٍ مِنْ خُرْثِيِّ الْمَتَاعِ، وَعَرَضْتُ عَلَيْهِ رُقْيَةً كُنْتُ أَرْقِي بِهَا الْمَجَانِينَ، فَأَمَرَنِي بِطَرْحِ بَعْضِهَا وَحَبْسِ بَعْضِهَا. (د,ت,جه)', 'ഉമൈർ മൗലാ അബുല്ലഹ്മ്(റ): ഞാൻ എന്റെ യജമാനന്മാരുടെ കൂടെ ഖൈബറിൽ (യുദ്ധത്തിൽ) പങ്കെടുത്തു. അപ്പോൾ അവർ എന്നെക്കുറിച്ച് റസൂൽ(സ)യോട് സംസാരിച്ചു. റസൂൽ(സ)യോട് ഞാനൊരു അടിമയാണെന്ന് അവർ പറഞ്ഞു. നിവേദകൻ പറയുന്നു: അപ്പോൾ റസൂൽ(സ) എന്നെ ആയുധമണിയിക്കാൻ കൽപിക്കുകയും എന്റെ ശരീരത്തിൽ വാള് കെട്ടപ്പെടുകയും ചെയ്തു. ഞാൻ അത് വലിച്ചുകൊണ്ടായിരുന്നു നടന്നിരുന്നത്. റസൂൽ(സ) വില കുറഞ്ഞ ചരക്കുകൾ എനിക്ക് നൽകാൻ കൽപിച്ചു. ഭ്രാന്തന്മാർക്ക് ഞാൻ കെട്ടിക്കൊടുക്കാറുണ്ടായിരുന്ന ചില ഉറുക്കുകൾ ഞാൻ റസൂൽ(സ)ക്ക് കാണിച്ചു കൊടുക്കുകയും അവയിൽ ചിലത് ഒഴിവാക്കാനും ചിലത് സൂക്ഷിക്കാനും അവിടുന്ന് എന്നോട് കൽപിക്കുകയും ചെയ്തു. (ദ,തു,ജ)', 'عُمَيْرٍ مَوْلَى أَبِي اللَّحْمِ -', 'ഉമൈർ മൗലാ അബുല്ലഹ്മ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 59, 59, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ عُمَيْرٍ مَوْلَى أَبِي اللَّحْمِ - رَضِيَ اللَّهُ عَنْهُمَا - قَالَ: غَزَوْتُ مَعَ مَوْلَايَ يَوْمَ خَيْبَرَ وَأَنَا مَمْلُوكٌ، فَلَمْ يَقْسِمْ لِي مِنَ الْغَنِيمَةِ، وَأُعْطِيتُ مِنْ خُرْثِيِّ الْمَتَاعِ سَيْفًا، وَكُنْتُ أَجُرُّهُ إِذَا تَقَلَّدْتُهُ. (د,ت,جه)', 'ഉമൈർ മൗലാ അബുല്ലഹ്മ്(റ): ഞാൻ എന്റെ യജമാനന്റെ കൂടെ ഖൈബറിൽ പങ്കെടുത്തു. എനിക്കായി യുദ്ധമുതൽ വീതിക്കപ്പെട്ടില്ല. എന്നാൽ വില കുറഞ്ഞ ചെരക്കുകളുടെ കൂട്ടത്തിൽനിന്ന് ഒരു വാൾ എനിക്ക് നൽകപ്പെട്ടു. അത് ശരീരത്തിലണിഞ്ഞാൽ ഞാനതിനെ വലിക്കുമായിരുന്നു. (ദ,തു,ജ)', 'عُمَيْرٍ مَوْلَى أَبِي اللَّحْمِ -', 'ഉമൈർ മൗലാ അബുല്ലഹ്മ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 59, 60, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ يَزِيدَ بْنِ هُرْمُزَ: أَنَّ نَجْدَةَ الْحَرُورِيَّ كَتَبَ إِلَى ابْنِ عَبَّاسٍ - رَضِيَ اللَّهُ عَنْهُمَا - يَسْأَلُهُ: هَلْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَغْزُو بِالنِّسَاءِ؟ وَهَلْ كَانَ يَضْرِبُ لَهُنَّ بِسَهْمٍ؟ فَكَتَبَ إِلَيْهِ ابْنُ عَبَّاسٍ: كَتَبْتَ إِلَيَّ تَسْأَلُنِي: هَلْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَغْزُو بِالنِّسَاءِ؟ وَكَانَ يَغْزُو بِهِنَّ: فَيُدَاوِينَ الْمَرْضَى، وَيُحْذَيْنَ مِنَ الْغَنِيمَةِ، وَأَمَّا بِسَهْمٍ فَلَمْ يَضْرِبْ لَهُنَّ بِسَهْمٍ. (م,د,ت,ن)', 'യസീദുബ്നു ഹുർമുസ്(റ): റസൂൽ(സ) സ്ത്രീകളെക്കൂട്ടി യുദ്ധം ചെയ്യാറുണ്ടായിരുന്നോ? അവിടന്ന് അവർക്ക് യുദ്ധമുതൽ വീതിച്ചുനൽകാറുണ്ടായിരുന്നോ? എന്നെല്ലാം ചോദിച്ചുകൊണ്ട് നജ്ദതുൽ ഹറൂരിയ്യ് ഇബ്നുഅബ്ബാസ്(റ)വിലേക്ക് ഒരു എഴുത്ത് എഴുതി. അപ്പോൾ ഇബ്നുഅബ്ബാസ്(റ) അദ്ദേഹത്തിന് തിരിച്ചെഴുതി: റസൂൽ(സ) സ്ത്രീകളെക്കൂട്ടി യുദ്ധം ചെയ്യാറുണ്ടായിരുന്നോ? എന്ന് ചോദിച്ച് കൊണ്ട് നീ എനിക്ക് എഴുത്ത് എഴിതിയിരിക്കുന്നു, അവിടന്ന് സ്ത്രീകളെക്കൂട്ടി യുദ്ധം ചെയ്യാറുണ്ടായിരുന്നു. അങ്ങനെ അവർ രോഗികളെ ചികിത്സിക്കുകയും, യുദ്ധമുതലിൽ നിന്ന് അവർക്ക് നൽകപ്പെടുകയും ചെയ്യുമായിരുന്നു. പക്ഷേ, അവർക്ക് വേണ്ടി റസൂൽ(സ) ഓഹരി വീതിച്ചിട്ടുണ്ടായിരുന്നില്ല. (മു,ദ,തു,ന)', 'يَزِيدَ بْنِ هُرْمُزَ', 'യസീദുബ്നു ഹുർമുസ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 60, 60, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عُرِضَهُ يَوْمَ أُحُدٍ وَهُوَ ابْنُ أَرْبَعَ عَشْرَةَ فَلَمْ يُجِزْهُ، وَعُرِضَهُ يَوْمَ الْخَنْدَقِ وَهُوَ ابْنُ خَمْسَ عَشْرَةَ سَنَةً فَأَجَازَهُ. (ق,د,ت,جه)', 'ഇബ്നുഉമർ(റ): ഉഹ്ദ് യുദ്ധ ദിവസം അദ്ദേഹം നബി(സ)യുടെ മുമ്പിൽ ഹാജരായി. അന്ന് അദ്ദേഹത്തിന് പതിനാല് വയസ്സായിരുന്നു. അതിനാൽ നബി(സ) അദ്ദേഹത്തെ യുദ്ധത്തിൽ പങ്കെടുക്കാൻ അനുവദിച്ചില്ല. ഖൻദഖ് യുദ്ധദിവസവും നബി(സ)യുടെ മുമ്പിൽ അദ്ദേഹം പ്രത്യക്ഷപ്പെട്ടു. അന്ന് പതിനഞ്ച് വയസ്സുണ്ടായിരുന്നു. അപ്പോൾ നബി(സ) അനുമതി നൽകി. (ബു,മു,ദ,തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 60, 60, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ غُلَامًا لِابْنِ عُمَرَ أَبَقَ إِلَى الْعَدُوِّ، فَظَهَرَ عَلَيْهِ الْمُسْلِمُونَ، فَرَدَّهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى ابْنِ عُمَرَ وَلَمْ يَقْسِمْ. (د)', 'ഇബ്നുഉമർ(റ): ഇബ്നുഉമർ(റ)വിന്റെ ഒരടിമ ശത്രുക്കളിലേക്ക് ഓടിപ്പോയി. ശേഷം മുസ്‌ലിംകൾ അവനുമേൽ വിജയം വരിച്ചു. അപ്പോൾ റസൂൽ(സ) അവനെ ഇബ്നുഉമർ(റ)വിന് തന്നെ മടക്കിക്കൊടുത്തു, അവനെ വീതിക്കാനുള്ള സ്വത്തിൽ പെടുത്തിയില്ല. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 60, 60, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: ذَهَبَ فَرَسٌ لَهُ، فَأَخَذَهُ الْعَدُوُّ، فَظَهَرَ عَلَيْهِ الْمُسْلِمُونَ، فَرُدَّ عَلَيْهِ فِي زَمَنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَأَبَقَ عَبْدٌ لَهُ، فَلَحِقَ بِأَرْضِ الرُّومِ، فَظَهَرَ عَلَيْهِمُ الْمُسْلِمُونَ، فَرَدَّهُ عَلَيْهِ خَالِدُ بْنُ الْوَلِيدِ بَعْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ,د,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ)യുടെ കാലത്ത് അദ്ദേഹത്തിന്റെ ഒരു കുതിര പോവുകയും അതിനെ ശത്രുക്കൾ കൈവശപ്പെടുത്തുകയും ചെയ്തു. ശേഷം മുസ്‌ലിംകൾ അതിനെ കീഴടക്കി, അദ്ദേഹത്തിനു തന്നെ തിരിച്ചുനൽകി. നബി(സ)യുടെ കാലശേഷം അദ്ദേഹത്തിന്റെ ഒരടിമ ഓടിപ്പോവുകയും റോമിലെത്തിപ്പെടുകയും ചെയ്തു. പിന്നീട് മുസ്‌ലിംകൾ അവരെ കീഴ്പെടുത്തുകയും, ആ അടിമയെ ഖാലിദുബ്നു വലീദ്(റ) അദ്ദേഹത്തിന് തന്നെ തിരിച്ചുകൊടുക്കുകയും ചെയ്തു. (ബു,ദ,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 60, 61, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ إِلَى بَدْرٍ، حَتَّى إِذَا كَانَ بِحَرَّةِ الْوَبَرَةِ لَحِقَهُ رَجُلٌ مِنَ الْمُشْرِكِينَ، يَذْكُرُ مِنْهُ جُرْأَةً وَنَجْدَةً، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَسْتَ تُؤْمِنُ بِاللَّهِ وَرَسُولِهِ". قَالَ: لَا. قَالَ: "ارْجِعْ، فَلَنْ أَسْتَعِينَ بِمُشْرِكٍ". هَذَا حَدِيثٌ حَسَنٌ. (م,د,ت,جه)', 'ആഇശ(റ): റസൂൽ(സ) ബദ്റിലേക്ക് പുറപ്പെടുകയും ''ഹർറതുൽ വബ്റ'' എന്ന സ്ഥലത്തുവെച്ച് ധീരതയിലും ശൗര്യത്തിലും പ്രശസ്തനായ ഒരു ബഹുദൈവാരാധകൻ നബി(സ)യെ കണ്ടുമുട്ടുകയും ചെയ്തു. അപ്പോൾ നബി(സ) അദ്ദേഹത്തോട് ചോദിച്ചു: "അല്ലാഹുവിനെക്കൊണ്ടും അവന്റെ പ്രവാചകനെക്കൊണ്ടും നീ വിശ്വസിക്കുന്നില്ലേ?" അയാൾ പറഞ്ഞു: ഇല്ല. നബി(സ) പറഞ്ഞു: "എന്നാൽ നീ മടങ്ങിപ്പോവുക, കാരണം ഞാനൊരിക്കലും ഒരു ബഹുദൈവാരാധകനോട് സഹായം തേടുകയില്ല." ഈ ഹദീസ് ഹസനാണ്. (മു,ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 61, 61, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: إِنَّ رَجُلًا مِنَ الْمُشْرِكِينَ لَحِقَ بِالنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُقَاتِلَ مَعَهُ، فَقَالَ: "ارْجِعْ". ثُمَّ اتَّفَقَا فَقَالَ: "إِنَّا لَا نَسْتَعِينُ بِمُشْرِكٍ". (م,د,ت,جه)', 'ആഇശ(റ): ബഹുദൈവാരാധകരിൽപെട്ട ഒരാൾ യുദ്ധംചെയ്യാനായി നബി(സ)യോടൊപ്പം കൂടി. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "നീ മടങ്ങിപ്പോകുക." വീണ്ടും അവർ കണ്ടുമുട്ടി. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "തീർച്ചയായും ഞങ്ങൾ ഒരു ബഹുദൈവാരധകനോട് സഹായം തേടുകയില്ല." (മു,ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 61, 61, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ يُحَدِّثُ سَعِيدَ بْنَ الْعَاصِ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ أَبَانَ بْنَ سَعِيدِ بْنِ الْعَاصِ عَلَى سَرِيَّةٍ مِنَ الْمَدِينَةِ قِبَلَ نَجْدٍ، فَقَدِمَ أَبَانُ بْنُ سَعِيدٍ وَأَصْحَابُهُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِخَيْبَرَ بَعْدَ أَنْ فَتَحَهَا، وَإِنَّ حُزُمَ خَيْلِهِمْ لِيفٌ، فَقَالَ أَبَانُ: اقْسِمْ لَنَا يَا رَسُولَ اللَّهِ، فَقَالَ أَبُو هُرَيْرَةَ: فَقُلْتُ: لَا تَقْسِمْ لَهُمْ يَا رَسُولَ اللَّهِ، فَقَالَ أَبَانُ: أَنْتَ بِهَا يَا وَبْرُ، تَحَدَّرُ عَلَيْنَا مِنْ رَأْسِ ضَالٍ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اجْلِسْ يَا أَبَانُ". وَلَمْ يَقْسِمْ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (د)', 'അബൂഹുറൈറ(റ): അദ്ദേഹം സഈദുബ്നുൽ ആസ്(റ)വിനെ സംബന്ധിച്ച് പറയുന്നു: റസൂൽ(സ) മദീനയിൽ നിന്ന് നജ്ദിന്റെ ഭാഗത്തേക്കുള്ള യുദ്ധസംഘത്തിന്റെ നേതാവായി, അബാനുബ്നു സഈദിബ്നിൽ ആസ്(റ)വിനെ അയച്ചു. അങ്ങനെ അബാനുബ്നു സഈദ്(റ)വും തന്റെ അനുചരന്മാരും, റസൂൽ(സ) ഖൈബർ കീഴടക്കിയതിനു ശേഷം, ഖൈബറിൽ നിൽക്കുകയായിരുന്ന തിരുമേനി(സ)യുടെ അടുക്കൽ വന്നു. അവരുടെ പടക്കുതിരകളുടെ ജീനികൾ പനനാരായിരുന്നു. അപ്പോൾ അബാൻ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങൾക്ക് യുദ്ധമുതൽ വീതിച്ചുതന്നാലും. അബൂഹുറൈറ(റ) പറയുന്നു: അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടന്ന് അവർക്ക് വീതിച്ചുകൊടുക്കാതിരുന്നാലും. അപ്പോൾ അബാൻ(റ) പറഞ്ഞു: ''ളാല്ല്'' എന്ന മലയുടെ മുകളിൽ നിന്നും ഞങ്ങളിലേക്ക് ഇറങ്ങിവന്ന ശീമക്കുഴി മുയലേ, നീയാണോ അതിന്റെയാൾ. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അബാനേ, നീ ഇരിക്കുക." അങ്ങനെ റസൂൽ(സ) അവർക്ക് വിഹിതം നൽകിയില്ല. (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 61, 62, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَدِمْنَا فَوَافَقْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ افْتَتَحَ خَيْبَرَ، فَأَسْهَمَ لَنَا - أَوْ قَالَ: فَأَعْطَانَا مِنْهَا - وَمَا قَسَمَ لِأَحَدٍ غَابَ عَنْ فَتْحِ خَيْبَرَ مِنْهَا شَيْئًا إِلَّا لِمَنْ شَهِدَ مَعَهُ، إِلَّا أَصْحَابَ سَفِينَتِنَا جَعْفَرٌ وَأَصْحَابُهُ، فَأَسْهَمَ لَهُمْ مَعَهُمْ. (ق,د,ت)', 'അബൂമൂസാ(റ): ഞങ്ങൾ (റസൂൽ(സ)യുടെ അടുത്തേക്ക്) വരികയും, ഖൈബർ കീഴടക്കിയ അവസരത്തിൽ ഞങ്ങൾ തിരുമേനി(സ)യെ കണ്ടുമുട്ടുകയും ചെയ്തു. അപ്പോൾ അവിടന്ന് ഞങ്ങൾക്ക് യുദ്ധമുതൽ വീതിച്ചുതന്നു - അല്ലെങ്കിൽ നിവേദകൻ പറഞ്ഞത്: അപ്പോൾ അവിടന്ന് ഞങ്ങൾക്ക് യുദ്ധമുതലിൽ നിന്ന് തന്നു - റസൂൽ(സ)യോടൊപ്പം സന്നിഹിതരായവർക്കല്ലാതെ, ഖൈബർ കീഴടക്കുന്നതിൽ അസന്നിഹിതരായിരുന്ന ഒരാൾക്കും അവിടന്ന് വിഹിതം നൽകിയില്ല. ജഅ്ഫർ(റ)വും അദ്ദേഹത്തിന്റെ അനുചരന്മാരുമടങ്ങിയ ഞങ്ങളുടെ കപ്പലിലെ ആളുകളൊഴികെ. ഇവർക്ക് അവരോടൊപ്പം വിഹിതം നൽകുകയും ചെയ്തു. (ബു,മു,ദ,തു)', 'أَبِي مُوسَى', 'അബൂമൂസാ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 62, 62, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ - يَعْنِي يَوْمَ بَدْرٍ - فَقَالَ: "إِنَّ عُثْمَانَ انْطَلَقَ فِي حَاجَةِ اللَّهِ وَحَاجَةِ رَسُولِ اللَّهِ، وَإِنِّي أُبَايِعُ لَهُ". فَضَرَبَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَهْمٍ، وَلَمْ يَضْرِبْ لِأَحَدٍ غَابَ غَيْرَهُ. (د)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) (ബദ്ർ ദിനത്തിൽ) എഴുന്നേറ്റുനിൽക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "തീർച്ചയായും ഉസ്മാൻ അല്ലാഹുവിന്റെ ആവശ്യത്തിനും അവന്റെ റസൂലിന്റെ ആവശ്യത്തിനുമാണ് പോയിരിക്കുന്നത്, തീർച്ചയായും ഞാൻ അദ്ദേഹത്തോട് ഉടമ്പടി ചെയ്യുന്നവനാണ്." അങ്ങനെ റസൂൽ(സ) അദ്ദേഹത്തിന് ഓഹരി നൽകി. അദ്ദേഹമൊഴിച്ച് അവിടെ അസന്നിഹിതരായിരുന്ന ആർക്കും നൽകിയതുമില്ല. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 62, 62, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ: قَدِمْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نَفَرٍ مِنَ الْأَشْعَرِيِّينَ بِخَيْبَرَ، فَأَسْهَمَ لَنَا مَعَ الَّذِينَ فَتَحُوهَا. (ق,د,ت)', 'അബൂമൂസ(റ): അശ്അരി ഗോത്രത്തിലെ ഒരു സംഘത്തോടൊപ്പം ഞാൻ ഖൈബറിൽ വെച്ച് നബി(സ)യുടെ അടുക്കൽ ചെന്നു. അപ്പോൾ അവിടന്ന് ഞങ്ങൾക്ക് ഖൈബർ കീഴടക്കിയവരോടൊപ്പം യുദ്ധമുതൽ വീതിച്ചുനൽകി. (ബു,മു,ദ,തു)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 62, 62, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ مَالِكِ بْنِ أَوْسِ بْنِ الْحَدَثَانِ قَالَ: سَمِعْتُ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ يَقُولُ: كَانَتْ أَمْوَالُ بَنِي النَّضِيرِ مِمَّا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ، مِمَّا لَمْ يُوجِفِ الْمُسْلِمُونَ عَلَيْهِ بِخَيْلٍ وَلَا رِكَابٍ، وَكَانَتْ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَالِصًا، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعْزِلُ نَفَقَةَ أَهْلِهِ سَنَةً، ثُمَّ يَجْعَلُ مَا بَقِيَ فِي الْكُرَاعِ وَالسِّلَاحِ عُدَّةً فِي سَبِيلِ اللَّهِ. (ق,د,ت,ن,جه)', 'മാലികുബ്നു ഔസുബ്നു ഹദസാൻ(റ): ഉമറുബ്നുൽ ഖത്താബ്(റ) പറയുന്നതായി ഞാൻ കേട്ടു: ബനുന്നളീർ ഗോത്രത്തിന്റെ സ്വത്ത്, ഒട്ടകങ്ങളുമായോ പടക്കുതിരകളുമായോ പടയോട്ടം നടത്താതെ തന്നെ റസൂൽ(സ)ക്ക് ലഭിച്ച യുദ്ധമുതലിൽ പെട്ടതായിരുന്നു. അത് റസൂൽ(സ)ക്ക് മാത്രമുള്ളതായിരുന്നു. റസൂൽ(സ) തന്റെ കുടുംബത്തിന് ഒരു വർഷത്തിനാവശ്യമായ ചെലവ് മാറ്റിവെക്കുകയും, പടക്കുതിരകൾ ആയുധങ്ങൾ എന്നിവയിൽ ബാക്കിവന്നവയെ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ള യുദ്ധ സന്നാഹമായി മാറ്റുകയും ചെയ്യുമായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'مَالِكِ بْنِ أَوْسِ بْنِ الْحَدَثَانِ قَالَ', 'മാലികുബ്നു ഔസുബ്നു ഹദസാൻ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 62, 63, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: دَخَلَ عَلَى مُعَاوِيَةَ، فَقَالَ: حَاجَتَكَ يَا أَبَا عَبْدِ الرَّحْمَنِ، فَقَالَ: عَطَاءُ الْمُحَرَّرِينَ، فَإِنِّي رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوَّلَ مَا جَاءَهُ شَيْءٌ بَدَأَ بِالْمُحَرَّرِينَ. (د)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): അദ്ദേഹം മുആവിയ(റ)യെ സമീപിച്ചു. മുആവിയ(റ) ചോദിച്ചു: അബൂഅബ്ദിറഹ്മാൻ, താങ്കളുടെ ആവശ്യമെന്താണ്? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: സ്വതന്ത്രരായവർക്കുള്ള വിഹിതം നൽകണം. കാരണം, റസൂൽ(സ)യുടെ പക്കൽ വല്ല മുതലുമെത്തിയാൽ ആദ്യമായി സ്വതന്ത്രർക്ക് നൽകി തുടക്കം കുറിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ദ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 63, 63, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِظَبْيَةٍ فِيهَا خَرَزٌ، فَقَسَمَهَا لِلْحُرَّةِ وَالْأَمَةِ، قَالَتْ عَائِشَةُ: كَانَ أَبِي رَضِيَ اللَّهُ عَنْهُ يَقْسِمُ لِلْحُرِّ وَالْعَبْدِ. (د)', 'ആഇശ(റ): രോമാവൃതമായ ഒരിനം സഞ്ചിയിൽ നിറയെ മുത്തുകൾ നബി(സ)ക്ക് നൽകപ്പെട്ടു. നബി(സ) അത് സ്വതന്ത്രരായവർക്കും അടിമസ്ത്രീകൾക്കും വീതിച്ചുനൽകി. ആഇശ(റ) പറയുന്നു: എന്റെ പിതാവും (റ) സ്വതന്ത്രരായവർക്കും അടിമകൾക്കും വീതിക്കാറുണ്ടായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 63, 63, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ عَوْفِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَتَاهُ الْفَيْءُ قَسَمَهُ فِي يَوْمِهِ، فَأَعْطَى الْآهِلَ حَظَّيْنِ، وَأَعْطَى الْعَزَبَ حَظًّا، فَدُعِينَا، وَكُنْتُ أُدْعَى قَبْلَ عَمَّارٍ، فَدُعِيتُ فَأَعْطَانِي حَظَّيْنِ وَكَانَ لِي أَهْلٌ، ثُمَّ دُعِيَ بَعْدِي عَمَّارُ بْنُ يَاسِرٍ فَأَعْطَى لَهُ حَظًّا وَاحِدًا. (د)', 'ഔഫുബ്നു മാലിക്(റ): റസൂൽ(സ)ക്ക് ഫൈഅ് ലഭിച്ചാൽ അന്നുതന്നെ വീതിക്കാറുണ്ടായിരുന്നു. കുടുംബമുള്ളവന് രണ്ട് ഓഹരികൾ നൽകും. അവിവാഹിതന് ഒന്നും. അങ്ങനെ ഞങ്ങൾ വിളിക്കപ്പെട്ടു. അമ്മാറിനു മുമ്പ് ഞാൻ വിളിക്കപ്പെടുമായിരുന്നു. അപ്രകാരം ഞാൻ വിളിക്കപ്പെട്ടു. എനിക്ക് രണ്ട് ഓഹരികൾ തന്നു. കാരണം എനിക്ക് കുടുംബമുണ്ടായിരുന്നു. പിന്നീട് എന്റെ ശേഷം അമ്മാറുബ്നു യാസിർ(റ) വിളിക്കപ്പെട്ടു. അദ്ദേഹത്തിന് ഒരൊറ്റ ഓഹരി മാത്രമാണ് നൽകിയത്. (ദ)', 'عَوْفِ بْنِ مَالِكٍ', 'ഔഫുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 63, 63, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ مُصْعَبِ بْنِ سَعْدٍ، عَنْ أَبِيهِ قَالَ: نَزَلَتْ فِيَّ أَرْبَعُ آيَاتٍ: أَصَبْتُ سَيْفًا، فَأَتَى بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ نَفِّلْنِيهِ، فَقَالَ: "ضَعْهُ". [ثُمَّ قَامَ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ضَعْهُ مِنْ حَيْثُ أَخَذْتَهُ"]. ثُمَّ قَامَ فَقَالَ: نَفِّلْنِيهِ يَا رَسُولَ اللَّهِ، فَقَالَ: "ضَعْهُ". فَقَامَ فَقَالَ: يَا رَسُولَ اللَّهِ نَفِّلْنِيهِ، أَأُجْعَلُ كَمَنْ لَا غَنَاءَ لَهُ؟ فَقَالَ [لَهُ] النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ضَعْهُ مِنْ حَيْثُ أَخَذْتَهُ". قَالَ: فَنَزَلَتْ هَذِهِ الْآيَةُ: {يَسْأَلُونَكَ عَنِ الْأَنْفَالِ قُلِ الْأَنْفَالُ لِلَّهِ وَالرَّسُولِ} [الأنفال: ١]. (م)', 'തന്റെ പിതാവിൽ നിന്ന് മുസ്അബുബ്നു സഅ്ദ്(റ): എന്റെ കാര്യത്തിൽ നാല് ആയത്തുകൾ ഇറങ്ങിയിട്ടുണ്ട്. എനിക്കൊരു വാൾ ലഭിച്ചു. അതുമായി റസൂൽ(സ)യുടെ അടുക്കൽ ചെന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഇതിനെ അവിടുന്ന് എനിക്ക് അധികവിഹിതമായി നൽകിയാലും. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ അത് അവിടെ വെക്കുക." (പിന്നെ അദ്ദേഹം എഴുന്നേറ്റു നിന്നു. അപ്പോൾ നബി(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "അത് നീ എവിടെ നിന്നാണോ എടുത്തത്, അവിടെത്തന്നെ വെക്കുക.") അദ്ദേഹം വീണ്ടും എഴുന്നേറ്റ് നിന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടുന്ന് എനിക്ക് അതിനെ അധികവിഹിതമായി തന്നാലും. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നീയത് അവിടെ വെക്കുക." അപ്പോഴദ്ദേഹം എഴുന്നേറ്റ് നിന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടുന്ന് എനിക്കത് അധികവിഹിതമായി നൽകിയാലും, ഞാൻ യുദ്ധമുതൽ നൽകപ്പെടാത്തവനെപ്പോലെയാക്കപ്പെടുകയാണോ? അപ്പോൾ അദ്ദേഹത്തോട് നബി(സ) പറഞ്ഞു: "അത് നീ എവിടെ നിന്നാണോ എടുത്തത് അവിടത്തന്നെ വെക്കുക." നിവേദകൻ പറയുന്നു: അപ്പോൾ ഈ ആയത്തിറങ്ങി: ''അവർ അങ്ങയോട് അൻഫാലിനെ (യുദ്ധമുതലിലെ അധിക വിഹിതങ്ങൾ) കുറിച്ച് ചോദിക്കും, അങ്ങ് അവരോട് പറയുക. അൻഫാൽ അല്ലാഹുവിനും റസൂലിനുമുള്ളതാണ്.'' (അൻഫാൽ: 1) (മു)', 'مُصْعَبِ بْنِ سَعْدٍ، عَنْ أَبِيهِ قَالَ', 'തന്റെ പിതാവിൽ നിന്ന് മുസ്അബുബ്നു സഅ്ദ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'الأنفال: ١', null, 63, 64, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ بَدْرٍ: "مَنْ فَعَلَ كَذَا وَكَذَا فَلَهُ مِنَ النَّفَلِ كَذَا وَكَذَا". قَالَ: فَتَقَدَّمَ الْفِتْيَانُ وَلَزِمَ الْمَشْيَخَةُ الرَّايَاتِ فَلَمْ يَبْرَحُوهَا، فَلَمَّا فَتَحَ اللَّهُ عَلَيْهِمْ قَالَ الْمَشْيَخَةُ: كُنَّا رِدْءًا لَكُمْ، لَوِ انْهَزَمْتُمْ لَفِئْتُمْ إِلَيْنَا، فَلَا تَذْهَبُوا بِالْمَغْنَمِ وَنَبْقَى. فَأَبَى الْفِتْيَانُ وَقَالُوا: جَعَلَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَنَا، فَأَنْزَلَ اللَّهُ: {يَسْأَلُونَكَ عَنِ الْأَنْفَالِ قُلِ الْأَنْفَالُ لِلَّهِ وَالرَّسُولِ} إِلَى قَوْلِهِ: {كَمَا أَخْرَجَكَ رَبُّكَ مِنْ بَيْتِكَ بِالْحَقِّ وَإِنَّ فَرِيقًا مِنَ الْمُؤْمِنِينَ لَكَارِهُونَ} يَقُولُ: فَكَانَ ذَلِكَ خَيْرًا لَهُمْ، فَكَذَلِكَ أَيْضًا: فَأَطِيعُونِي، فَإِنِّي أَعْلَمُ بِعَاقِبَةِ هَذَا مِنْكُمْ. وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ يَوْمَ بَدْرٍ: "مَنْ قَتَلَ قَتِيلًا فَلَهُ كَذَا وَكَذَا، وَمَنْ أَسَرَ أَسِيرًا فَلَهُ كَذَا وَكَذَا". ثُمَّ سَاقَ نَحْوَهُ. وَفِي رِوَايَةٍ: فَقَسَمَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالسَّوَاءِ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ബദർ ദിനത്തിൽ റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഇന്നാലിന്ന പ്രവർത്തനങ്ങൾ പ്രവർത്തിച്ചാൽ അവന് യുദ്ധമുതലിൽ നിന്ന് ഇന്നാലിന്നതുണ്ട്." നിവേദകൻ പറയുന്നു: അപ്പോൾ യുവാക്കൾ മുന്നേറുകയും കൂടുതൽ പ്രായമുള്ളവർ കൊടികളോട് ചേർന്നു നിൽക്കുകയും ചെയ്തു. അങ്ങനെ ശത്രുക്കൾക്കെതിരെ അല്ലാഹു വിജയം നൽകിയപ്പോൾ പ്രായമുള്ളവർ പറഞ്ഞു: നിങ്ങളെങ്ങാനും പരാജയപ്പെടുകയാണെങ്കിൽ ഞങ്ങളിലേക്ക് വന്നുചേരാൻ പറ്റുന്ന വിധത്തിൽ നിങ്ങൾക്കുള്ള സഹായമായിരുന്നു ഞങ്ങൾ. അതുകൊണ്ട് ഞങ്ങളെക്കൂടാതെ നിങ്ങൾ യുദ്ധമുതലുമായി പോകരുത്. അപ്പോൾ യുവാക്കളതിന് വിസമ്മതിക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: യുദ്ധമുതലിനെ റസൂൽ(സ) ഞങ്ങൾക്കാണ് മാറ്റിവെച്ചിട്ടുള്ളത്. അപ്പോൾ അല്ലാഹു ''അവർ അങ്ങയോട് യുദ്ധമുതലിനെക്കുറിച്ച് ചോദിക്കും. താങ്കൾ പറയുക: യുദ്ധമുതൽ അല്ലാഹുവിനും റസൂലിനുമുള്ളതാണ്.'' എന്ന സൂക്തം ''സത്യവിശ്വാസികളിൽ നിന്നൊരു വിഭാഗത്തിന് ഇഷ്ടമില്ലാതിരിക്കെത്തന്നെ അങ്ങയുടെ രക്ഷിതാവ് അങ്ങയെ സത്യവുമായി അങ്ങയുടെ വീട്ടിൽ നിന്ന് പുറത്ത് കൊണ്ടുവന്നതു പോലെ'' എന്നത് വരെ ഇറക്കി. നിവേദകൻ പറയുന്നു: അപ്പോൾ അത് അവർക്ക് നന്മയായി. അപ്രകാരം തന്നയാണ് ഇതും: അതുകൊണ്ട് നിങ്ങൾ എന്നെ അനുസരിക്കുക. കാരണം തീർച്ചയായും ഞാൻ ഇതിന്റെ അന്ത്യത്തെക്കുറിച്ച് നിങ്ങളെക്കാൾ അറിയുന്നവനാണ്. മറ്റൊരു നിവേദനത്തിൽ: തീർച്ചയായും റസൂൽ(സ) ബദർ ദിനത്തിൽ പറഞ്ഞു: "ആരെങ്കിലും ഒരാളെ കൊന്നാൽ അവന് ഇന്നതെല്ലാം ഉണ്ട്. ആരെങ്കിലും ഒരാളെ ബന്ധിയാക്കിയാൽ അവന് ഇന്നതെല്ലാം ഉണ്ട്." പിന്നീട് തുടർന്നുദ്ധരിച്ചു. മറ്റൊരു നിവേദനത്തിലുള്ളത്: അങ്ങനെ റസൂൽ(സ) അതിനെ സമമായി വീതിച്ചു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 64, 64, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=70), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ يَوْمَ بَدْرٍ: "مَنْ قَتَلَ قَتِيلًا فَلَهُ كَذَا وَكَذَا، وَمَنْ أَسَرَ أَسِيرًا فَلَهُ كَذَا وَكَذَا". ثُمَّ سَاقَ نَحْوَهُ.', 'മറ്റൊരു നിവേദനത്തിൽ: തീർച്ചയായും റസൂൽ(സ) ബദർ ദിനത്തിൽ പറഞ്ഞു: "ആരെങ്കിലും ഒരാളെ കൊന്നാൽ അവന് ഇന്നതെല്ലാം ഉണ്ട്. ആരെങ്കിലും ഒരാളെ ബന്ധിയാക്കിയാൽ അവന് ഇന്നതെല്ലാം ഉണ്ട്." പിന്നീട് തുടർന്നുദ്ധരിച്ചു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=70), 2, 'وَفِي رِوَايَةٍ: فَقَسَمَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالسَّوَاءِ. (د)', 'മറ്റൊരു നിവേദനത്തിലുള്ളത്: അങ്ങനെ റസൂൽ(സ) അതിനെ സമമായി വീതിച്ചു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: جِئْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ بَدْرٍ بِسَيْفٍ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ اللَّهَ قَدْ شَفَى صَدْرِي الْيَوْمَ مِنَ الْعَدُوِّ، فَهَبْ لِي هَذَا السَّيْفَ. قَالَ: "إِنَّ هَذَا السَّيْفَ لَيْسَ لِي وَلَا لَكَ". فَذَهَبْتُ وَأَنَا أَقُولُ: يُعْطَاهُ الْيَوْمَ مَنْ لَمْ يُبْلِ بَلَائِي، فَبَيْنَمَا أَنَا إِذْ جَاءَنِي الرَّسُولُ، فَقَالَ: "أَجِبْ". فَظَنَنْتُ أَنَّهُ نَزَلَ فِيَّ شَيْءٌ بِكَلَامِي، فَجِئْتُ، فَقَالَ لِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّكَ سَأَلْتَنِي هَذَا السَّيْفَ، وَلَيْسَ هُوَ لِي وَلَا لَكَ، وَإِنَّ اللَّهَ قَدْ جَعَلَهُ لِي، فَهُوَ لَكَ". ثُمَّ قَرَأَ: {يَسْأَلُونَكَ عَنِ الْأَنْفَالِ قُلِ الْأَنْفَالُ لِلَّهِ وَالرَّسُولِ} إِلَى آخِرِ الْآيَةِ. (م,د,ت,ن)', 'സഅ്ദ്(റ): ബദർയുദ്ധ ദിനത്തിൽ ഞാനൊരു വാളുമായി നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, തീർച്ചയായും അല്ലാഹു ഇന്ന് ശത്രുവിന്റെ വിഷയത്തിൽ എന്റെ ഹൃദയത്തിന് ആശ്വാസം നൽകി (അവരെ പരാജയപ്പെടുത്തി). അതുകൊണ്ട് അവിടുന്ന് എനിക്ക് ഈ വാള് തന്നാലും. അവിടുന്ന് പറഞ്ഞു: "തീർച്ചയായും ഈ വാൾ എനിക്കോ നിനക്കോ ഉള്ളതല്ല." അപ്പോൾ, ''എന്നെപ്പോലെ യുദ്ധത്തിൽ പരീക്ഷിക്കപ്പെടാത്ത ഒരാൾക്ക് ഇന്ന് ആ വാൾ നൽകപ്പെടും'' എന്ന് പറഞ്ഞുകൊണ്ട് ഞാൻ പോയി. അതിനിടയിൽ റസൂൽ(സ) എന്റെയടുത്ത് വന്ന് ഇപ്രകാരം പറഞ്ഞു: "നീ ഉത്തരം ചെയ്യുക." അപ്പോൾ ഞാൻ വിചാരിച്ചു: എന്റെ സംസാരം കാരണം എന്റെ വിഷയത്തിൽ (ഖുർആൻ) ഇറങ്ങിയിട്ടുണ്ടാവും. അങ്ങനെ ഞാൻ ചെന്നു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "തീർച്ചയായും നീ എന്നോട് ഈ വാൾ ചോദിച്ചു. അതാണെങ്കിൽ എനിക്കോ നിനക്കോ ഉള്ളതല്ല താനും. തീർച്ചയായും അല്ലാഹു അതിനെ എനിക്ക് അവകാശപ്പെട്ടതാക്കിയിരിക്കുന്നു. അതിനാൽ അത് നിനക്കുള്ളതാണ്." പിന്നെ അവിടുന്ന് ''അവർ താങ്കളോട് യുദ്ധമുതലുകളെക്കുറിച്ച് ചോദിക്കും. താങ്കൾ പറയുക: യുദ്ധമുതലുകൾ അല്ലാഹുവിനും തിരുദൂതർക്കുമുള്ളതാണ്.'' എന്ന ആയത്ത് അവസാനം വരെ ഓതി. (മു,ദ,തു,ന)', 'سَعْدٍ', 'സഅ്ദ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 64, 65, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَفَّلَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ بَدْرٍ سَيْفَ أَبِي جَهْلٍ، كَانَ قَتَلَهُ. (د)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ബദ്ർ ദിനത്തിൽ റസൂൽ(സ) എനിക്ക് അബൂജഹലിന്റെ വാൾ അധിക വിഹിതമായി നൽകി. അദ്ദേഹമായിരുന്നു അബൂജഹലിനെ കൊന്നത്. (ദ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 65, 65, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَنَفَّلَ سَيْفَهُ ذَا الْفَقَارِ يَوْمَ بَدْرٍ، وَهُوَ الَّذِي رَأَى فِيهِ الرُّؤْيَا يَوْمَ أُحُدٍ. حَسَنٌ. (ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): തീർച്ചയായും ബദ്ർ ദിനത്തിൽ നബി(സ) അവിടത്തെ വാളായ ദുൽഫുഖാർ യുദ്ധമുതലിലെ അധിക വിഹിതമായി എടുത്തു. ഉഹ്ദ് ദിനത്തിൽ ആ വാളിനെ സംബന്ധിച്ചാണ് അവിടുന്ന് സ്വപ്നം കണ്ടത്. ഹദീസ് ഹസനാണ്. (തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 65, 65, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ حَبِيبِ بْنِ مَسْلَمَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَفَّلَ الثُّلُثَ بَعْدَ الْخُمُسِ وَفِي رِوَايَةٍ: نَفَّلَ فِي الْبَدْأَةِ الرُّبُعَ، وَحِينَ قَفَلَ الثُّلُثَ. (د,ت,جه)', 'ഹബീബുബ്നു മസ്‌ലമ(റ): നബി(സ) അഞ്ചിലൊന്നിന് ശേഷം മൂന്നിലൊന്ന് അധിക വിഹിതമായി നൽകി. മറ്റൊരു നിവേദനം: തുടക്കത്തിൽ നാലിലൊന്നും മടങ്ങിയപ്പോൾ മൂന്നിലൊന്നും അധിക വിഹിതമായി നൽകി. (ദ,തു,ജ)', 'حَبِيبِ بْنِ مَسْلَمَةَ', 'ഹബീബുബ്നു മസ്‌ലമ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 65, 65, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=74), 1, 'وَفِي رِوَايَةٍ: نَفَّلَ فِي الْبَدْأَةِ الرُّبُعَ، وَحِينَ قَفَلَ الثُّلُثَ. (د,ت,جه)', 'മറ്റൊരു നിവേദനം: തുടക്കത്തിൽ നാലിലൊന്നും മടങ്ങിയപ്പോൾ മൂന്നിലൊന്നും അധിക വിഹിതമായി നൽകി. (ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ أَبِي أُمَامَةَ بْنِ عِجْلَانَ رَضِيَ اللَّهُ عَنْهُ، عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَفَّلَ: فِي الْبَدْأَةِ الرُّبُعَ، وَفِي الرَّجْعَةِ الثُّلُثَ. (ت,جه)', 'ഉബാദതുബ്നു സ്വാമിത്(റ)വിൽ നിന്ന് അബൂഉമാമതുബ്നു ഇജ്‌ലാൻ(റ): നബി(സ) തുടക്കത്തിൽ നാലിലൊന്നും മടക്ക സമയത്ത് മൂന്നിലൊന്നും അധിക വിഹിതമായി നൽകി. (തു,ജ)', 'أَبِي أُمَامَةَ بْنِ عِجْلَانَ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 65, 65, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَا نَفْلَ بَعْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَرُدُّ الْمُسْلِمُونَ قَوِيُّهُمْ عَلَى ضَعِيفِهِمْ. (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ)യുടെ കാല ശേഷം നഫ്ൽ (യുദ്ധമുതലിൽ നിന്ന് അധിക ഓഹരിയെടുക്കൽ) സമ്പ്രദായം ഇല്ല. (എന്നാൽ) മുസ്‌ലിംകളിൽ ശക്തിയുള്ളവർ തങ്ങളിലെ ബലഹീനർക്ക് നൽകുകയാണ് വേണ്ടത്. (ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 65, 66, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ سَرِيَّةً قِبَلَ نَجْدٍ وَهُوَ فِيهَا، فَغَنِمُوا إِبِلًا كَثِيرَةً، وَكَانَتْ سِهَامُهُمُ اثْنَيْ عَشَرَ بَعِيرًا أَوْ أَحَدَ عَشَرَ بَعِيرًا وَنُفِّلُوا بَعِيرًا بَعِيرًا. (خ)', 'ഇബ്നുഉമർ(റ): നിശ്ചയം റസൂൽ(സ) നജ്ദിന്റെ ഭാഗത്തേക്ക് അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) അടങ്ങുന്ന ഒരു യുദ്ധസംഘത്തെ അയച്ചു. അങ്ങനെ അവർക്ക് ധാരാളം ഒട്ടകങ്ങൾ യുദ്ധമുതലായി കിട്ടി. അവരുടെ വിഹിതം പന്ത്രണ്ടോ പതിനൊന്നോ ഒട്ടകങ്ങളായിരുന്നു. ഓരോരോ ഒട്ടകങ്ങളാണ് അവർക്ക് അധിക വിഹിതമായി നൽകപ്പെട്ടത്. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 66, 66, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَرِيَّةً إِلَى نَجْدٍ، فَخَرَجْتُ فِيهَا، فَأَصَبْنَا إِبِلًا وَغَنَمًا، فَبَلَغَتْ سُهْمَانُنَا اثْنَيْ عَشَرَ بَعِيرًا، وَنَفَّلَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعِيرًا بَعِيرًا. (م,د)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) നജ്ദിലേക്കൊരു യുദ്ധസംഘത്തെ അയച്ചു. അപ്പോൾ ഞാനും ആ സംഘത്തോടൊപ്പം പുറപ്പെട്ടു. അങ്ങനെ ഞങ്ങൾക്കൊരുപാട് ആടുകളെയും ഒട്ടകങ്ങളെയും കിട്ടി. അങ്ങനെ ഞങ്ങളുടെ ഓഹരി വിഹിതം പന്ത്രണ്ട് ഒട്ടകങ്ങളായി. റസൂൽ(സ) ഞങ്ങൾക്ക് ഓരോരോ ഒട്ടകങ്ങളെ അധിക വിഹിതമായി നൽകി. (മു,ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 66, 66, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَسَمَ فِي النَّفَلِ: لِلْفَرَسِ سَهْمَيْنِ، وَلِلرَّاجِلِ سَهْمًا. (ق,د,ت,جه)', 'ഇബ്നുഉമർ(റ): നിശ്ചയം റസൂൽ(സ) യുദ്ധമുതലിലെ അധിക വിഹിതത്തെ കുതിരപ്പടയാളികൾക്ക് രണ്ട് വിഹിതവും കാലാളുകൾക്ക് ഒരു വിഹിതവും എന്ന നിലയിൽ വീതിച്ചു. (ബു,മു,ദ,തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 66, 66, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: بَعَثَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي جَيْشٍ قِبَلَ نَجْدٍ، وَانْبَعَثَتْ سَرِيَّةٌ مِنَ الْجَيْشِ، فَكَانَ سُهْمَانُ الْجَيْشِ اثْنَيْ عَشَرَ بَعِيرًا، اثْنَيْ عَشَرَ بَعِيرًا وَنَفَّلَ أَهْلَ السَّرِيَّةِ بَعِيرًا بَعِيرًا، فَكَانَتْ سُهْمَانُهُمْ ثَلَاثَةَ عَشَرَ ثَلَاثَةَ عَشَرَ. (د)', 'ഇബ്നുഉമർ(റ): നജ്ദിന്റെ ഭാഗത്തേക്ക് ഒരു സൈന്യത്തോടൊപ്പം റസൂൽ(സ) ഞങ്ങളെ അയച്ചു. ആ സൈന്യത്തിൽ നിന്ന് ഒരു യുദ്ധ സംഘം അയക്കപ്പെട്ടു. അപ്പോൾ സൈന്യത്തിന്റെ ഓഹരി പന്ത്രണ്ട് ഒട്ടകങ്ങൾ വീതമായിരുന്നു. യുദ്ധസംഘത്തിന് നബി(സ) അധികമായി ഓരോ ഒട്ടകം വീതവും നൽകി. അങ്ങനെ അവരുടെ ഓഹരി പതിമൂന്ന് ഒട്ടകങ്ങൾ വീതമായി. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 66, 66, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَرِيَّةً إِلَى نَجْدٍ، فَخَرَجْتُ مَعَهَا، فَأَصَبْنَا نَعَمًا كَثِيرًا، فَنَفَّلَنَا أَمِيرُنَا بَعِيرًا بَعِيرًا لِكُلِّ إِنْسَانٍ، ثُمَّ قَدِمْنَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَسَمَ بَيْنَنَا غَنِيمَتَنَا، فَأَصَابَ كُلُّ رَجُلٍ مِنَّا اثْنَيْ عَشَرَ بَعِيرًا بَعْدَ الْخُمُسِ، وَمَا حَاسَبَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالَّذِي أَعْطَانَا صَاحِبُنَا وَلَا عَابَ عَلَيْهِ بَعْدَ مَا صَنَعَ، فَكَانَ لِكُلِّ رَجُلٍ مِنَّا ثَلَاثَةَ عَشَرَ بَعِيرًا بِنَفْلِهِ. (د)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) നജ്ദിലേക്ക് ഒരു യുദ്ധസംഘത്തെ അയച്ചു. അപ്പോൾ ഞാനും അതോടൊപ്പം പോയി. അങ്ങനെ ഞങ്ങൾക്ക് ധാരാളം ഒട്ടകങ്ങളെ ലഭിച്ചു. അപ്പോൾ ഞങ്ങളുടെ നേതാവ്, ഓരോരുത്തർക്കും ഓരോ ഒട്ടകം വീതം നൽകി. പിന്നെ ഞങ്ങൾ റസൂൽ(സ)യുടെ അടുക്കൽ ചെന്നു. അവിടന്ന് ഞങ്ങൾക്ക് യുദ്ധമുതൽ വീതിച്ചുതന്നു. അഞ്ചിലൊന്ന് മാറ്റിവെച്ച ശേഷം ഞങ്ങളിൽ ഓരോർത്തർക്കും, പന്ത്രണ്ട് ഒട്ടകങ്ങൾ വീതം ലഭിച്ചു. ഞങ്ങളുടെ അമീർ നൽകിയതിനെക്കുറിച്ച് റസൂൽ(സ) ഞങ്ങളോട് കണക്കു ചോദിച്ചില്ല. അമീർ അത് ചെയ്തതിന് ശേഷം ആ വിഷയത്തിൽ ആക്ഷേപം പറഞ്ഞതുമില്ല. അങ്ങനെ ഞങ്ങളിലെ ഓരോർത്തർക്കും യുദ്ധമുതലായി പതിമൂന്ന് ഒട്ടകങ്ങൾ വീതമുണ്ടായിരുന്നു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 66, 67, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عن ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ سَرِيَّةً فِيهَا عَبْدُ اللَّهِ بْنُ عُمَرَ قِبَلَ نَجْدٍ، فَغَنِمُوا إِبِلًا كَثِيرَةً، فَكَانَتْ سُهْمَانُهُمُ اثْنَيْ عَشَرَ بَعِيرًا، وَنُفِّلُوا بَعِيرًا بَعِيرًا، فَلَمْ يُغَيِّرْهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ق,د)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) നജ്ദിന്റെ ഭാഗത്തേക്ക് ഒരു യുദ്ധസംഘത്തെ അയച്ചു. അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)വും അക്കൂട്ടത്തിലുണ്ടായിരുന്നു. അവർക്ക് ധാരാളം ഒട്ടകങ്ങൾ യുദ്ധമുതലായി ലഭിച്ചു. ഓരോർത്തർക്കുമുള്ള വിഹിതം പന്ത്രണ്ട് ഒട്ടകമായിരുന്നു. ഓരോ ഒട്ടകം വീതം അവർക്ക് വിഹിതത്തിലധികമായി നൽകപ്പെട്ടിരുന്നു. റസൂൽ(സ) അതിൽ മാറ്റം വരുത്തിയില്ല. (ബു,മു,ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 67, 67, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ كَانَ يُنَفِّلُ بَعْضَ مَنْ يَبْعَثُ مِنَ السَّرَايَا لِأَنْفُسِهِمْ خَاصَّةَ النَّفَلِ، سِوَى قَسْمِ عَامَّةِ الْجَيْشِ، وَالْخُمُسُ فِي ذَلِكَ وَاجِبٌ كُلُّهُ. (د)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) അയച്ചിരുന്ന ചില യുദ്ധസംഘങ്ങൾക്ക് പൊതു സൈനികർക്കുള്ള വിഹിതത്തിനു പുറമെ, അവിടന്ന് പ്രത്യേകമായി വിഹിതം നൽകാറുണ്ടായിരുന്നു. ആ വിഹിതങ്ങളിലെല്ലാം അഞ്ചിലൊന്ന് നിർബന്ധമാണ് (അഞ്ചിലൊന്ന് മാറ്റിയതിനു ശേഷമാണ് അവ വീതിക്കപ്പെടുക). (ദ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 67, 67, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ يَوْمَ بَدْرٍ فِي ثَلَاثِمِائَةٍ وَخَمْسَةَ عَشَرَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ إِنَّهُمْ حُفَاةٌ فَاحْمِلْهُمُ اللَّهُمَّ إِنَّهُمْ عُرَاةٌ فَاكْسُهُمْ، اللَّهُمَّ إِنَّهُمْ جِيَاعٌ فَأَشْبِعْهُمْ". فَفَتَحَ اللَّهُ لَهُ يَوْمَ بَدْرٍ، فَانْقَلَبُوا حِينَ انْقَلَبُوا وَمَا مِنْهُمْ رَجُلٌ إِلَّا وَقَدْ رَجَعَ بِجَمَلٍ أَوْ جَمَلَيْنِ، وَاكْتَسَوْا، وَشَبِعُوا. (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നിശ്ചയം റസൂൽ(സ) ബദർ ദിനത്തിൽ മുന്നൂറ്റി പതിനഞ്ച് ആളുകളോടൊപ്പം പുറപ്പെട്ടു. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവേ, നിശ്ചയം ഇവർ നഗ്നപാദരാണ്, അതുകൊണ്ട് നീയവർക്ക് പാദരക്ഷയണിയിപ്പിക്കേണമേ. അല്ലാഹുവേ, നിശ്ചയം ഇവർ വസ്ത്രമില്ലാത്തവരാണ്, അതുകൊണ്ട് നീയവരെ വസ്ത്രം ധരിപ്പിക്കേണമേ. അല്ലാഹുവേ, നിശ്ചയം ഇവർ വിശന്നവരാണ്, അതുകൊണ്ട് നീയവരെ വയർ നിറയെ ഭക്ഷിപ്പിക്കേണമേ." അങ്ങനെ അല്ലാഹു അവിടത്തേക്ക് ബദർ ദിവസം വിജയം നൽകി. അങ്ങനെയവർ അവിടെ നിന്ന് തിരിച്ച് യാത്രയാകുമ്പോൾ ഒന്നോ രണ്ടോ ഒട്ടകങ്ങളുള്ളവരല്ലാത്ത ഒരാളും അവരിലുണ്ടായിരുന്നില്ല. മാത്രമല്ല അവർ വയർ നിറഞ്ഞവരും, വസ്ത്രം ധരിച്ചവരും ആയിരുന്നു. (ദ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 67, 67, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ حَبِيبِ بْنِ مَسْلَمَةَ الْفِهْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُنَفِّلُ الثُّلُثَ بَعْدَ الْخُمُسِ. وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُنَفِّلُ الرُّبُعَ بَعْدَ الْخُمُسِ، وَالثُّلُثَ بَعْدَ الْخُمُسِ إِذَا قَفَلَ. وَفِي رِوَايَةٍ: شَهِدْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَفَّلَ الرُّبُعَ فِي الْبَدْأَةِ، وَالثُّلُثَ فِي الرَّجْعَةِ. (د,جه)', 'ഹബീബുബ്നു മസ്‌ലമതുൽ ഫിഹ്‌രി(റ): അഞ്ചിലൊന്നിന്റെ ശേഷം മൂന്നിലൊന്ന് റസൂൽ(സ) അധിക വിഹിതമായി നൽകാറുണ്ടായിരുന്നു. മറ്റൊരു നിവേദനം: റസൂൽ(സ) അഞ്ചിൽ ഒന്നിന് ശേഷം നാലിലൊന്ന് അധിക വിഹിതമായി നൽകാറുണ്ടായിരുന്നു. മടങ്ങുന്ന സമയത്ത് അഞ്ചിലൊന്നിന്റെ ശേഷമുള്ളതിൽ മൂന്നിലൊന്നും അവിടുന്ന് അധിക വിഹിതമായി നൽകിയിരുന്നു. മറ്റൊരു നിവേദനം: റസൂൽ(സ) തുടക്കത്തിൽ നാലിലൊന്നും മടങ്ങുമ്പോൾ മൂന്നിലൊന്നും അധിക വിഹിതമായി നൽകുന്നതിന് ഞാൻ സാക്ഷിയായിട്ടുണ്ട്. (ദ,ജ)', 'حَبِيبِ بْنِ مَسْلَمَةَ الْفِهْرِيِّ', 'ഹബീബുബ്നു മസ്‌ലമതുൽ ഫിഹ്‌രി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 67, 68, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=85), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُنَفِّلُ الرُّبُعَ بَعْدَ الْخُمُسِ، وَالثُّلُثَ بَعْدَ الْخُمُسِ إِذَا قَفَلَ.', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) അഞ്ചിൽ ഒന്നിന് ശേഷം നാലിലൊന്ന് അധിക വിഹിതമായി നൽകാറുണ്ടായിരുന്നു. മടങ്ങുന്ന സമയത്ത് അഞ്ചിലൊന്നിന്റെ ശേഷമുള്ളതിൽ മൂന്നിലൊന്നും അവിടുന്ന് അധിക വിഹിതമായി നൽകിയിരുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=85), 2, 'وَفِي رِوَايَةٍ: شَهِدْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَفَّلَ الرُّبُعَ فِي الْبَدْأَةِ، وَالثُّلُثَ فِي الرَّجْعَةِ. (د,جه)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) തുടക്കത്തിൽ നാലിലൊന്നും മടങ്ങുമ്പോൾ മൂന്നിലൊന്നും അധിക വിഹിതമായി നൽകുന്നതിന് ഞാൻ സാക്ഷിയായിട്ടുണ്ട്. (ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا مَرَّ أَحَدُكُمْ فِي مَسْجِدِنَا – أَوْ: فِي سُوقِنَا – وَمَعَهُ نَبْلٌ، فَلْيُمْسِكْ عَلَى نِصَالِهَا – أَوْ قَالَ: فَلْيَقْبِضْ كَفَّهُ. أَوْ قَالَ: فَلْيَقْبِضْ بِكَفِّهِ – أَنْ تُصِيبَ أَحَدًا مِنَ الْمُسْلِمِينَ". (ق,د,ن,جه)', 'അബൂമൂസ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ ആരെങ്കിലും അമ്പുമായി നമ്മുടെ പള്ളിയിൽ - അല്ലെങ്കിൽ നമ്മുടെ അങ്ങാടിയിൽ - നടക്കുകയാണെങ്കിൽ മുസ്‌ലിംകളിൽ പെട്ട ആരുടെയും ദേഹത്ത് അത് തട്ടാതിരിക്കാനായി അവനതിന്റെ മുനയിൽ പിടിച്ചുകൊള്ളട്ടെ - അല്ലെങ്കിൽ അവിടന്ന് പറഞ്ഞത്: അവന്റെ മുൻകൈ പിടിക്കട്ടെ. അല്ലെങ്കിൽ അവിടന്ന് പറഞ്ഞത്: അവൻ അവന്റെ മുൻകൈകൊണ്ട് പിടിച്ചുകൊള്ളട്ടെ." (ബു,മു,ദ,ന,ജ)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 68, 68, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْمُسْلِمُونَ تَتَكَافَأُ دِمَاؤُهُمْ: يَسْعَى بِذِمَّتِهِمْ أَدْنَاهُمْ، وَيُجِيرُ عَلَيْهِمْ أَقْصَاهُمْ، وَهُمْ يَدٌ عَلَى مَنْ سِوَاهُمْ، يَرُدُّ مُشِدُّهُمْ عَلَى مُضْعِفِهِمْ، وَمُتَسَرِّيهِمْ عَلَى قَاعِدِهِمْ. لَا يُقْتَلُ مُؤْمِنٌ بِكَافِرٍ، وَلَا ذُو عَهْدٍ فِي عَهْدِهِ". (د,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മുസ്‌ലിംകളുടെ രക്തത്തിന് പരസ്പരം തുല്ല്യവിലയാണ്: അവരിൽ ഏറ്റവും താഴ്ന്ന വ്യക്തിക്കും അവരുടെ സംരക്ഷണം ഏറ്റെടുക്കാം. അവരിൽ ഏറ്റവും അകന്ന് കഴിയുന്ന വ്യക്തിക്കും മറ്റുള്ളവർക്ക് (ശത്രുക്കൾക്ക്) സംരക്ഷണം നൽകാം. തങ്ങളല്ലാത്തവർക്കെതിരിൽ അവർ ഒറ്റ ശക്തിയായിരിക്കും. അവരിലെ ശക്തന്മാർ ബലഹീനർക്കും യുദ്ധത്തിലേർപെട്ടവർ അതിൽ ഏർപെടാത്തവർക്കും വിഹിതം നൽകണം. ഒരു സത്യനിഷേധിക്ക് പകരമായി മുസ്‌ലിമോ, സന്ധിയിലായിരിക്കെ സന്ധിയിലേർപ്പെട്ടവനോ (സത്യനിഷേധി) വധിക്കപ്പെടാൻ പാടില്ല." (ദ,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 68, 68, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ سَلَمَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَغَارَ عَبْدُ الرَّحْمَنِ بْنُ عُيَيْنَةَ عَلَى إِبِلِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَتَلَ رَاعِيَهَا، فَخَرَجَ يَطْرُدُهَا هُوَ وَأُنَاسٌ مَعَهُ فِي خَيْلٍ، فَجَعَلْتُ وَجْهِي قِبَلَ الْمَدِينَةِ، ثُمَّ نَادَيْتُ ثَلَاثَ مَرَّاتٍ: يَا صَبَاحَاهْ، ثُمَّ اتَّبَعْتُ الْقَوْمَ فَجَعَلْتُ أَرْمِي وَأَعْقِرُهُمْ، فَإِذَا رَجَعَ إِلَيَّ فَارِسٌ جَلَسْتُ فِي أَصْلِ شَجَرَةٍ، حَتَّى مَا خَلَقَ اللهُ شَيْئًا مِنْ ظَهْرِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَّا جَعَلْتُهُ وَرَاءَ ظَهْرِي، وَحَتَّى أَلْقَوْا أَكْثَرَ مِنْ ثَلَاثِينَ رُمْحًا وَثَلَاثِينَ بُرْدَةً يَسْتَخِفُّونَ مِنْهَا، ثُمَّ أَتَاهُمْ عُيَيْنَةُ مَدَدًا فَقَالَ: لِيَقُمْ إِلَيْهِ نَفَرٌ مِنْكُمْ، فَقَامَ إِلَيَّ أَرْبَعَةٌ مِنْهُمْ فَصَعِدُوا الْجَبَلَ، فَلَمَّا أَسْمَعْتُهُمْ قُلْتُ: أَتَعْرِفُونِي؟ قَالُوا: وَمَنْ أَنْتَ؟ قُلْتُ: أَنَا ابْنُ الْأَكْوَعِ، وَالَّذِي كَرَّمَ وَجْهَ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَا يَطْلُبُنِي رَجُلٌ مِنْكُمْ فَيُدْرِكُنِي، وَلَا أَطْلُبُهُ فَيَفُوتُنِي. فَمَا بَرِحْتُ حَتَّى نَظَرْتُ إِلَى فَوَارِسِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَتَخَلَّلُونَ الشَّجَرَ، أَوَّلُهُمُ الْأَخْرَمُ الْأَسَدِيُّ، فَيَلْحَقُ بِعَبْدِ الرَّحْمَنِ بْنِ عُيَيْنَةَ، وَيَعْطِفُ عَلَيْهِ عَبْدُ الرَّحْمَنِ، فَاخْتَلَفَا طَعْنَتَيْنِ، فَعَقَرَ الْأَخْرَمُ عَبْدَ الرَّحْمَنِ وَطَعَنَهُ عَبْدُ الرَّحْمَنِ فَقَتَلَهُ، فَتَحَوَّلَ عَبْدُ الرَّحْمَنِ عَلَى فَرَسِ الْأَخْرَمِ، فَيَلْحَقُ أَبُو قَتَادَةَ بِعَبْدِ الرَّحْمَنِ، فَاخْتَلَفَا طَعْنَتَيْنِ فَعَقَرَ بِأَبِي قَتَادَةَ وَقَتَلَهُ أَبُو قَتَادَةَ فَتَحَوَّلَ أَبُو قَتَادَةَ عَلَى فَرَسِ الْأَخْرَمِ، ثُمَّ جِئْتُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ عَلَى الْمَاءِ الَّذِي جَلَّيْتُهُمْ عَنْهُ ذُو قَرَدٍ، فَإِذَا نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي خَمْسِ مِائَةٍ، فَأَعْطَانِي سَهْمَ الْفَارِسِ وَالرَّاجِلِ. (ق,د)', 'സലമ(റ): അബ്ദുർറഹ്മാനുബ്നു ഉയൈന റസൂൽ(സ)യുടെ ഒട്ടകക്കൂട്ടത്തിന് നേരെ അക്രമം നടത്തുകയും അവയെ മേച്ചിരുന്നയാളെ കൊല്ലുകയും ചെയ്തു. അങ്ങനെ അവനും അവന്റെ കൂടെയുണ്ടായിരുന്ന കുറച്ച് കുതിരപ്പടയാളികളും അവയെ തെളിച്ചു കൊണ്ടുപോയി. അപ്പോൾ ഞാനെന്റെ മുഖം മദീനയുടെ ഭാഗത്തേക്ക് തിരിക്കുകയും മൂന്ന് പ്രാവശ്യം ഇപ്രകാരം വിളിച്ചുപറയുകയും ചെയ്തു: സഹായിക്കണേ... നാമിതാ അക്രമിക്കപ്പെടുന്നു. പിന്നെ ഞാനവരെ പിന്തുടർന്നു. അങ്ങനെ ഞാനവർക്കു നേരെ അമ്പെറിയാനും അവരുടെ വാഹനങ്ങളെ കൊല്ലാനും തുടങ്ങി. ആ സമയത്ത് ഏതെങ്കിലും ഒരു കുതിരപ്പടയാളി എന്റെ നേരെ തിരിച്ചുവന്നാൽ ഞാനൊരു മരത്തിന്റെ മുരട്ടിൽ ഇരിക്കും. അങ്ങനെ ഞാൻ നബി(സ)യുടെ ഒട്ടകത്തെ പൂർണ്ണമായും എന്റെ ഒട്ടകത്തിന്റെ പിന്നിലാക്കി. അവർ (ശത്രുക്കൾ) മുപ്പതിലേറെ കുന്തങ്ങളും അവർ നിസാരമായി കാണുന്ന മുപ്പത് പുതപ്പുകളും ഉപേക്ഷിച്ച് പോയി. പിന്നെ അവരിലേക്ക് ഉയൈന സഹായവുമായി വരികയും ഇപ്രകാരം പറയുകയും ചെയ്തു. നിങ്ങളിൽ നിന്നൊരു കൂട്ടം അവന്റെയടുക്കൽ ചെല്ലുക. അപ്പോൾ അവരിൽ നിന്ന് നാലുപേർ എന്റെ നേരെ വരികയും മല കയറുകയും ചെയ്തു. അപ്പോൾ അവർ കേൾക്കെ ഞാൻ ചോദിച്ചു: നിങ്ങൾക്കെന്നെയറിയുമോ? അവർ ചോദിച്ചു: ആരാണ് നീ? ഞാൻ പറഞ്ഞു: അക്വഇന്റെ മകനാണ് ഞാൻ, മുഹമ്മദ്(സ)യുടെ തിരുമുഖത്തെ ബഹുമാനിച്ചവൻ തന്നെയാണ് സത്യം, എന്നെത്തേടി വരുന്ന നിങ്ങളിൽ ഒരാൾക്കും എന്നെ എത്തിക്കാൻ സാധ്യമല്ല. ഞാനവനെ തേടിയാൽ എനിക്കവനെ നഷ്ടപ്പെടുകയുമില്ല. ഞാനങ്ങനെയിരിക്കവെ, മരത്തിനടിയിലൂടെ റസൂൽ(സ)യുടെ ചില കുതിരപ്പടയാളികൾ പ്രവേശിക്കുന്നത് ഞാൻ കണ്ടു. അവരിൽ ആദ്യത്തെവർ അഖ്റമുൽ അസദി(റ)വാണ്. അദ്ദേഹം അബ്ദുർറഹ്മാനിബ്നു ഉയൈനയെ പിന്തുടർന്ന് ഒപ്പമെത്തുന്നു. അബ്ദുർറഹ്മാൻ അഖ്റം(റ)വിലേക്ക് തിരിയുന്നു. അടുത്തതായി അവർ രണ്ടുപേരും പരസ്പരം രണ്ടു കുത്തുകൾ കുത്തുന്നു. അങ്ങനെ അഖ്റം(റ) അബ്ദുർറഹ്മാന്റെ വാഹനത്തെ വെട്ടിക്കൊല്ലുകയും അബ്ദുർറഹ്മാൻ അദ്ദേഹത്തെ കുത്തിക്കൊല്ലുകയും ചെയ്യുന്നു. ഉടനെ അബ്ദുർറഹ്മാൻ അഖ്റം(റ)വിന്റെ കുതിരയുടെ മേൽ കയറി. അപ്പോൾ അബൂഖതാദ(റ) അബ്ദുർറഹ്മാനെ പിന്തുടർന്ന് ഒപ്പമെത്തുന്നു. അങ്ങനെ അവർ രണ്ടുപേരും പരസ്പരം രണ്ട് കുത്തുകൾ കുത്തുന്നു. അങ്ങനെ അബ്ദുർറഹ്മാൻ അബൂഖതാദ(റ)വിന്റെ വാഹനത്തെ കൊല്ലുകയും അബൂഖതാദ(റ) അബ്ദുർറഹ്മാനെ വധിക്കുകയും ചെയ്തു. ശേഷം അബൂഖതാദ(റ) അഖ്റം(റ)വിന്റെ കുതിരയുടെ മുകളിൽ കയറുകയും ചെയ്തു. ഞാൻ ശത്രുക്കളെ ആട്ടി വിദൂരത്താക്കിയ, ദൂഖറദ് എന്ന് പേരുള്ള, വെള്ളത്തിന്റെയടുത്ത് റസൂൽ(സ) ഇരിക്കവെ അവിടത്തെ സന്നിധിയിൽ ഞാൻ ചെന്നു. അന്നേരം തിരുനബി(സ) അഞ്ഞൂറ് പേരുടെ കൂട്ടത്തിലായിരുന്നു. അപ്പോളവിടുന്ന് എനിക്ക് കുതിരപ്പടയാളിയുടെയും കാലാൾപ്പടയുടെയും വിഹിതം തന്നു. (ബു,മു,ദ)', 'سَلَمَةَ', 'സലമ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 68, 69, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ أَبِي الْجُوَيْرِيَةِ الْجَرْمِيِّ قَالَ: أَصَبْتُ بِأَرْضِ الرُّومِ جَرَّةً حَمْرَاءَ فِيهَا دَنَانِيرُ، فِي إِمْرَةِ مُعَاوِيَةَ، وَعَلَيْنَا رَجُلٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ بَنِي سُلَيْمٍ، يُقَالُ لَهُ: مَعْنُ بْنُ يَزِيدَ، فَأَتَيْتُهُ بِهَا، فَقَسَمَهَا بَيْنَ الْمُسْلِمِينَ وَأَعْطَانِي مِنْهَا مِثْلَ مَا أَعْطَى رَجُلًا مِنْهُمْ، ثُمَّ قَالَ: لَوْلَا أَنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا نَفْلَ إِلَّا بَعْدَ الْخُمُسِ" لَأَعْطَيْتُكَ، ثُمَّ أَخَذَ يَعْرِضُ عَلَيَّ مِنْ نَصِيبِهِ فَأَبَيْتُ. (د)', 'അബുൽജുവൈരിയത്തിൽ ജർമി(റ): മുആവിയ(റ)വിന്റെ ഭരണകാലത്ത്, നിറയെ ദീനാറുകളുള്ള ചുവന്ന ഒരു മൺഭരണി റോമക്കാരുടെ പ്രദേശത്ത് നിന്ന് എനിക്ക് കിട്ടി. മഅ്നുബ്നു യസീദ്(റ) എന്ന് പേരുള്ള ബനൂസുലൈം ഗോത്രക്കാരനായ, നബി(സ)യുടെ സ്വഹാബാക്കളിൽ പെട്ട ഒരാളായിരുന്നു ഞങ്ങളുടെ നേതാവ്. ഞാനതുമായി അദ്ദേഹത്തെ സമീപിച്ചു. അപ്പോൾ അദ്ദേഹമതിനെ മുസ്‌ലിംകൾക്കിടയിൽ വീതിക്കുകയും മറ്റുള്ളവർക്ക് കൊടുത്തതു പോലെ എനിക്കും നൽകുകയും ചെയ്തു. പിന്നെ അദ്ദേഹം പറഞ്ഞു: "അഞ്ചിലൊന്നിന്റെ ശേഷമല്ലാതെ അധിക വിഹിതം വീതിക്കലില്ല" എന്ന് റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടിട്ടില്ലായിരുന്നുവെങ്കിൽ ഞാനത് നിനക്ക് നൽകുമായിരുന്നു. പിന്നീടദ്ദേഹം അദ്ദേഹത്തിന്റെ ഓഹിരിയിൽ നിന്ന് എനിക്ക് തരാൻ പുറപ്പെട്ടു. അപ്പോൾ ഞാനത് സ്വീകരിച്ചില്ല. (ദ)', 'أَبِي الْجُوَيْرِيَةِ الْجَرْمِيِّ قَالَ', 'അബുൽജുവൈരിയത്തിൽ ജർമി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 69, 69, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'أبي قَتادَة رَضِيَ اللهُ عَنْهُ قال: خَرَجْنَا مَعَ رسول الله صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ في عام حُنَيْنٍ، فَلَمَّا الْتَقَيْنَا كَانَتْ لِلْمُسْلِمِينَ جَوْلَةٌ، قال: فَرَأَيْتُ رَجُلًا مِنَ الْمُشْرِكِينَ قَدْ عَلَا رَجُلًا مِنَ الْمُسْلِمِينَ، قال: فَاسْتَدَرْتُ لَهُ حَتَّى أَتَيْتُهُ مِنْ وَرَائِهِ، فَضَرَبْتُهُ بِالسَّيْفِ عَلَى حَبْلِ عَاتِقِهِ، فَأَقْبَلَ عَلَيَّ، فَضَمَّنِي ضَمَّةً وَجَدْتُ مِنْهَا رِيحَ الْمَوْتِ، ثُمَّ أَدْرَكَهُ الْمَوْتُ فَأَرْسَلَنِي، فَلَحِقْتُ عُمَرَ بْنَ الْخَطَّابِ فَقُلْتُ لَهُ: مَا بَالُ النَّاسِ؟ قال: أَمْرُ الله، ثُمَّ إِنَّ النَّاسَ رَجَعُوا، وَجَلَسَ رَسُولُ الله صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "مَنْ قَتَلَ قَتِيلًا لَهُ عَلَيْهِ بَيِّنَةٌ فَلَهُ سَلَبُهُ". قال: فَقُمْتُ، ثُمَّ قلت: مَنْ يَشْهَدُ لِي؟ ثُمَّ جَلَسْتُ، ثُمَّ قال: ذلك الثَّانِيَةَ: "مَنْ قَتَلَ قَتِيلًا لَهُ عَلَيْهِ بَيِّنَةٌ فَلَهُ سَلَبُهُ". قَالَ: فَقُمْتُ، ثُمَّ قُلْتُ: مَنْ يَشْهَدُ لِي؟ ثُمَّ جَلَسْتُ، ثُمَّ قَالَ ذَلِكَ الثَّالِثَةَ، فَقُمْتُ، فَقَالَ رَسُولُ الله صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا لَكَ يَا أَبَا قَتَادَةَ". قال: فَاقْتَصَصْتُ عَلَيْهِ الْقِصَّةَ، فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: صدق يا رسول الله، وسَلَبُ ذلك الْقَتِيلِ عِنْدِي، فَأَرْضِهِ مِنْهُ. فَقَالَ أبو بكر الصِّدِّيقُ: لَاها الله إذا، يَعْمِدُ إلى أسد من أُسْدِ الله، يُقَاتِلُ عن الله وعن رسوله، فَيُعْطِيكَ سَلَبَهُ. فَقَالَ رسول الله صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "صدق، فَأَعْطِه إيَّاهُ". فَقَالَ أَبُو قَتَادَةَ: فَأَعْطَانِيه، فَبِعْتُ الدِّرْعَ، فَابْتَعْتُ بِهِ مَخْرَفًا في بني سلمة، فَإِنَّهُ لَأَوَّلُ مَالٍ تَأَثَّلْتُهُ فِي الْإِسْلَامِ. (ق,د,ت)', 'അബൂഖതാദ(റ): ഹുനൈൻ വർഷത്തിൽ ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെ പുറപ്പെട്ടു. അങ്ങനെ ഞങ്ങൾ ശത്രുക്കളെ കണ്ടുമുട്ടിയ സമയത്ത് മുസ്‌ലിംകൾക്ക് യുദ്ധത്തിൽ ഉയർച്ചയുണ്ടായി. നിവേദകൻ പറയുന്നു: അപ്പോൾ മുശ്രിക്കുകളിൽ പെട്ട ഒരാൾ മുസ്‌ലിംകളിൽ പെട്ട ഒരാളെ അക്രമിച്ച് തോൽപിച്ചതായി ഞാൻ കണ്ടു. നിവേദകൻ പറയുന്നു: അപ്പോൾ ഞാൻ ആ ശത്രുവിനെ ചുറ്റി അവന്റെ പിന്നിലൂടെ ചെന്ന് വാളുകൊണ്ട് അവന്റെ തോളിന്റെയും പിരടിയുടെയും ഇടയിൽ വെട്ടി. അപ്പോൾ അവൻ എന്റെ നേരെ വന്ന് എന്നെ കെട്ടിപ്പിടിച്ചു. ആ പിടുത്തത്തിൽ നിന്ന് ഞാൻ മരണത്തിന്റെ വാസന എത്തിച്ചു. പിന്നെ അദ്ദേഹത്തെ മരണം പിടികൂടുകയും അപ്പോഴെന്നെ വിടുകയും ചെയ്തു. അപ്പോൾ ഞാൻ ഉമറുബ്നുൽഖത്താബ്(റ)വിനെ സമീപിച്ച് അദ്ദേഹത്തോട് ചോദിച്ചു: എന്താണ് ജനങ്ങളുടെ അവസ്ഥ? അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ നിശ്ചയം. പിന്നീട് ജനങ്ങൾ മടങ്ങിപ്പോവുകയും റസൂൽ(സ) ഇരിക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "ആരെങ്കിലും ഒരാളെ കൊല്ലുകയും അവന് അതിന് തെളിവുണ്ടാവുകയും ചെയ്താൽ കൊല്ലപ്പെട്ടവന്റെ ദേഹത്തുള്ള സാധനങ്ങൾ അവനുള്ളതാണ്." നിവേദകൻ പറയുന്നു: അപ്പോൾ എഴുന്നേറ്റ് നിന്ന് ഞാൻ ചോദിച്ചു: ആരാണെനിക്ക് സാക്ഷി നിൽക്കുക? പിന്നെ ഞാനിരുന്നു. അവിടുന്ന് അതേ വാക്ക് രണ്ടാമതും പറഞ്ഞു: "ആരെങ്കിലും ഒരാളെ കൊല്ലുകയും അവൻ അതിന് തെളിവുണ്ടാവുകയും ചെയ്താൽ കൊല്ലപ്പെട്ടവന്റെ ദേഹത്തുള്ള സാധനങ്ങൾ അവനുള്ളതാണ്." നിവേദകൻ പറയുന്നു: അപ്പോൾ എഴുന്നേറ്റ് നിന്ന് ഞാൻ ചോദിച്ചു: എനിക്ക് വേണ്ടി സാക്ഷി നിൽക്കാൻ ആരുണ്ട്? ശേഷം ഞാൻ ഇരുന്നു. പിന്നെ തിരുമേനി(സ) അതേ വാക്ക് മൂന്നാമതും പറഞ്ഞു. അപ്പോൾ ഞാൻ എഴുന്നേറ്റ് നിന്നു. അന്നേരം റസൂൽ(സ) ചോദിച്ചു: "അബൂഖതാദ, താങ്കൾക്കെന്താണ് വേണ്ടത്?" നിവേദകൻ പറയുന്നു: അപ്പോൾ ഞാനീ കഥ അവിടത്തേക്ക് വിവരിച്ച് കൊടുത്തു. അപ്പോൾ കൂട്ടത്തിൽ നിന്നൊരാൾ പറഞ്ഞു: അദ്ദേഹം സത്യമാണ് പറയുന്നത്, അല്ലാഹുവിന്റെ ദൂതരേ. ആ കൊല്ലപ്പെട്ടവന്റെ ദേഹത്തുണ്ടായിരുന്ന സാധനങ്ങൾ എന്റെ പക്കലാണുള്ളത്. അതുകൊണ്ട് അവിടുന്നെനിക്ക് അത് അദ്ദേഹത്തിൽ നിന്ന് തൃപ്തിപ്പെട്ട് നൽകിയാലും. അപ്പോൾ അബൂബക്കർ സിദ്ദീഖ്(റ) പറഞ്ഞു: അദ്ദേഹം അല്ലാഹുവിന്റെ സിംഹങ്ങളിൽ നിന്നുള്ള ഒരു സിംഹത്തെ പിടിക്കുകയും അല്ലാഹുവിനും അവന്റെ റസൂലിനും വേണ്ടി യുദ്ധം ചെയ്യുകയും ചെയ്യുന്നു, എന്നിട്ട് അവന്നുള്ള മുതൽ നിനക്ക് നൽകുകയും ചെയ്യുകയോ? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അബൂബക്കർ പറഞ്ഞത് സത്യമാണ്. അതിനാൽ അത് അദ്ദേഹത്തിന്ന് തന്നെ നൽകുക." അബൂഖതാദ(റ) പറയുന്നു: അങ്ങനെ അത് അവിടുന്ന് എനിക്ക് നൽകി. അപ്പോൾ ഞാൻ പടയങ്കി വിൽക്കുകയും അതിന് പകരമായി ബനൂസലമിലെ ഒരു പൂന്തോട്ടം വാങ്ങുകയും ചെയ്തു. മുസ്‌ലിമായതിന്റെ ശേഷം ഞാൻ മൂലധനമായി ഒരുമിച്ച് കൂട്ടിയ ആദ്യ സമ്പത്തായിരുന്നു അത് (ബു,മു,ദ,തു)', null, 'അബൂഖതാദ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 70, 71, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَئِذٍ – يَعْنِي يَوْمَ حُنَيْنٍ –: "مَنْ قَتَلَ كَافِرًا فَلَهُ سَلَبُهُ". فَقَتَلَ أَبُو طَلْحَةَ يَوْمَئِذٍ عِشْرِينَ رَجُلًا وَأَخَذَ أَسْلَابَهُمْ، وَلَقِيَ أَبُو طَلْحَةَ أُمَّ سُلَيْمٍ وَمَعَهَا خِنْجَرٌ، فَقَالَ: يَا أُمَّ سُلَيْمٍ، مَا هَذَا مَعَكِ؟ قَالَتْ: أَرَدْتُ وَاللهِ إِنْ دَنَا مِنِّي بَعْضُهُمْ أَبْعَجُ بِهِ بَطْنَهُ، فَأَخْبَرَ بِذَلِكَ أَبُو طَلْحَةَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م,د)', 'അനസുബ്നു മാലിക്(റ): ആ ദിവസം - അഥവാ ഹുനൈൻ ദിവസം - റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു സത്യനിഷേധിയെ വധിച്ചാൽ, അവന്നാണ് അവന്റെ ദേഹത്തിലുള്ള സാധനങ്ങൾ." അപ്പോൾ അബൂത്വൽഹ(റ) ആ ദിവസം ഇരുപത് ആളുകളെ കൊല്ലുകയും അവരുടെ ദേഹത്തുള്ള സാധനങ്ങൾ എടുക്കുകയും ചെയ്തു. ഉമ്മുസുലൈം(റ) ഒരു കത്തിയുമായി നിൽക്കുന്നത് അബൂത്വൽഹ(റ) കണ്ടു. അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: ഏ ഉമ്മുസുലൈമാ, നിന്റെകൂടെ എന്താണിത്? മഹതി പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, ശത്രുക്കളിൽ നിന്ന് ആരെങ്കിലും എന്റെയടുത്ത് വന്നാൽ ഇതുമായി അവന്റെ വയറ് കുത്തിക്കീറാനാണ് ഞാനുദ്ദേശിച്ചത്. അപ്പോൾ അബൂത്വൽഹ(റ) ഈ വിവരം റസൂൽ(സ)യെ അറിയിച്ചു. (മു,ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 71, 71, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللهُ عَنْهُ قَالَ: غَزَوْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ هَوَازِنَ، فَبَيْنَا نَحْنُ نَتَضَحَّى مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، إِذْ جَاءَ رَجُلٌ عَلَى جَمَلٍ أَحْمَرَ فَأَنَاخَهُ، ثُمَّ انْتَزَعَ طَلَقًا مِنْ حِقَبِهِ فَقَيَّدَ بِهِ الْجَمَلَ، ثُمَّ تَقَدَّمَ يَتَغَدَّى مَعَ الْقَوْمِ، وَجَعَلَ يَنْظُرُ، وَفِينَا ضَعْفَةٌ وَرِقَّةٌ فِي الظَّهْرِ وَبَعْضُنَا مُشَاةٌ، إِذْ خَرَجَ يَشْتَدُّ، فَأَتَى جَمَلَهُ فَأَطْلَقَ قَيْدَهُ، ثُمَّ أَنَاخَهُ وَقَعَدَ عَلَيْهِ فَأَثَارَهُ فَاشْتَدَّ بِهِ الْجَمَلُ، فَاتَّبَعَهُ رَجُلٌ عَلَى نَاقَةٍ وَرْقَاءَ، قَالَ سَلَمَةُ: وَخَرَجْتُ أَشْتَدُّ، فَكُنْتُ عِنْدَ وَرِكِ النَّاقَةِ، ثُمَّ تَقَدَّمْتُ حَتَّى كُنْتُ عِنْدَ وَرِكِ الْجَمَلِ، ثُمَّ تَقَدَّمْتُ حَتَّى أَخَذْتُ بِخِطَامِ الْجَمَلِ فَأَنَخْتُهُ، فَلَمَّا وَضَعَ رُكْبَتَهُ فِي الْأَرْضِ اخْتَرَطْتُ سَيْفِي فَضَرَبْتُ رَأْسَ الرَّجُلِ فَنَدَرَ، ثُمَّ جِئْتُ بِالْجَمَلِ أَقُودُهُ، عَلَيْهِ رَحْلُهُ وَسِلَاحُهُ، فَاسْتَقْبَلَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَالنَّاسُ مَعَهُ، فَقَالَ: "مَنْ قَتَلَ الرَّجُلَ". قَالُوا: ابْنُ الْأَكْوَعِ، قَالَ: "لَهُ سَلَبُهُ أَجْمَعُ". (ق)', 'സലമതുബ്നുൽ അക്വഅ്(റ): ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം ഹവാസിൻ ഗോത്രത്തോട് യുദ്ധം ചെയ്തു. അങ്ങനെ ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം പ്രഭാതഭക്ഷണം കഴിച്ചുകൊണ്ടിരിക്കുന്നതിനിടയിൽ (ശത്രുക്കളിൽ നിന്നുള്ള) ഒരാൾ ഒരു ചുവന്ന ആൺഒട്ടകത്തിന്റെ പുറത്ത് വന്ന് അതിനെ മുട്ടുകുത്തിച്ചു. പിന്നെ അയാൾ തന്റെ അരപ്പട്ടയിൽ നിന്ന് ഒരു തോലിന്റെ കയർ ഊരിയെടുക്കുകയും അതുകൊണ്ട് ഒട്ടകത്തെ കെട്ടിയിടുകയും ചെയ്തു. പിന്നീടയാൾ ജനങ്ങളോടൊപ്പം പ്രാതൽ കഴിക്കാനായി മുന്നോട്ട് വരികയും (എല്ലാവരെയും) വീക്ഷിക്കാൻ തുടങ്ങുകയും ചെയ്തു. ഞങ്ങൾക്കാണെങ്കിൽ വാഹനക്കുറവും ക്ഷീണവും ഉണ്ടായിരുന്നു. ഞങ്ങളിൽ ചിലർ നടക്കുന്നവരുമായിരുന്നു. എന്നിട്ടയാൾ വേഗം പുറപ്പെടുകയും തന്റെ ഒട്ടകത്തിന്റെയടുത്ത് ചെന്ന് അതിന്റെ കെട്ടഴിച്ച് അതിനെ മുട്ടുകുത്തിച്ച് അതിന്റെ മേലിലിരുന്ന് അതിനെ ഇളക്കിവിടുകയും അപ്പോൾ ആ ഒട്ടകം അയാളുമായി വേഗത്തിൽ പോവുകയും ചെയ്തു. അപ്പോൾ തവിട്ട് നിറത്തിലുള്ള ഒരു പെൺഒട്ടകത്തിന്റെ മേൽ ഒരാൾ അദ്ദേഹത്തെ പിന്തുടർന്നു. സലമ(റ) പറയുന്നു: ഞാൻ അതിവേഗം പുറപ്പെട്ടു. (ഞാൻ അയാളെ പിന്തുടർന്നു.) ഞാൻ പെൺഒട്ടകത്തിന്റെ ഊരയുടെ ഭാഗത്തായിരുന്നു. ഞാൻ മുന്നിട്ട് ചെന്ന് ആൺഒട്ടകത്തിന്റെ ഊരവരെ എത്തി. വീണ്ടും മുന്നോട്ട് ചെന്ന് അതിന്റെ മൂക്കുകയർ പിടിക്കുകയും അതിനെ മുട്ടുകുത്തിക്കുകയും ചെയ്തു. അങ്ങനെ അത് ഭൂമിയിൽ അതിന്റെ കാൽമുട്ട് വെച്ചപ്പോൾ ഞാൻ എന്റെ വാൾ ഊരുകയും അയാളുടെ തലവെട്ടുകയും, തല പറന്ന് വീഴുകയും ചെയ്തു. പിന്നെ ഞാൻ ആ ഒട്ടകത്തെയും തെളിച്ച് വന്നു. അതിന്റെ മേൽ അയാളുടെ ചരക്കുകളും ആയുധങ്ങളുമുണ്ടായിരുന്നു. അപ്പോൾ റസൂൽ(സ) ജനങ്ങളോടൊപ്പം എന്നിലേക്ക് മുന്നിട്ടുവന്നു. അവിടന്ന് ചോദിച്ചു: "അയാളെ കൊന്നതാരാണ്?" അവർ പറഞ്ഞു: ഇബ്നുൽ അക്വഅ്. അവിടുന്ന് പറഞ്ഞു: "അയാളുടെ മുഴുവൻ സാമഗ്രികളും അദ്ദേഹത്തിനാണ്." (ബു,മു)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമതുബ്നുൽ അക്വഅ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 71, 72, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَتَلَ قَتِيلًا، لَهُ عَلَيْهِ بَيِّنَةٌ، فَلَهُ سَلَبُهُ". (ق,د,ت,جه)', 'അബൂഖതാദ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരാളെ കൊല്ലുകയും കൊന്നതിന് തെളിവുണ്ടാവുകയും ചെയ്താൽ, കൊല്ലപ്പെട്ടയാളുടെ ശരീരത്തിലുള്ള സാധനങ്ങൾ (സലബ്) കൊന്നവനുള്ളതാണ്." (ബു,മു,ദ,തു,ജ)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 72, 72, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ وَخَالِدِ بْنِ الْوَلِيدِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَضَى بِالسَّلَبِ لِلْقَاتِلِ، وَلَمْ يُخَمِّسِ السَّلَبَ. (د)', 'ഔഫുബ്നു മാലികിൽ അശ്ജഇൗ(റ), ഖാലിദുബ്നു വലീദ്(റ): നിശ്ചയം റസൂൽ(സ), സലബ് (കൊല്ലപ്പെട്ട ആളുടെ ദേഹത്തിലുള്ള സാധനങ്ങൾ) കൊന്നവന് നൽകാനാണ് വിധിച്ചത്. അതിനെ അവിടുന്ന് അഞ്ചിലൊന്നായി വീതിച്ചതുമില്ല. (ദ)', 'عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ وَخَالِدِ بْنِ الْوَلِيدِ', 'ഔഫുബ്നു മാലികിൽ അശ്ജഇൗ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 72, 72, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: بَيْنَا أَنَا وَاقِفٌ فِي الصَّفِّ يَوْمَ بَدْرٍ، نَظَرْتُ عَنْ يَمِينِي [وَشِمَالِي] فَإِذَا أَنَا بَيْنَ غُلَامَيْنِ مِنَ الْأَنْصَارِ حَدِيثَةٍ أَسْنَانُهُمَا، تَمَنَّيْتُ لَوْ كُنْتُ بَيْنَ أَضْلَعَ مِنْهُمَا، فَغَمَزَنِي أَحَدُهُمَا فَقَالَ: يَا عَمِّ، هَلْ تَعْرِفُ أَبَا جَهْلٍ؟ قَالَ: قُلْتُ: نَعَمْ، وَمَا حَاجَتُكَ إِلَيْهِ يَا ابْنَ أَخِي؟ قَالَ: أُخْبِرْتُ أَنَّهُ يَسُبُّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَالَّذِي نَفْسِي بِيَدِهِ لَئِنْ رَأَيْتُهُ لَا يُفَارِقُ سَوَادِي سَوَادَهُ حَتَّى يَمُوتَ الْأَعْجَلُ مِنَّا. قَالَ: فَتَعَجَّبْتُ لِذَلِكَ، فَغَمَزَنِي الْآخَرُ، فَقَالَ مِثْلَهَا، قَالَ: فَلَمْ أَنْشَبْ أَنْ نَظَرْتُ إِلَى أَبِي جَهْلٍ يَزُولُ فِي النَّاسِ، فَقُلْتُ: أَلَا تَرَيَانِ؟ هَذَا صَاحِبُكُمَا الَّذِي تَسْأَلَانِ عَنْهُ، قَالَ: فَابْتَدَرَاهُ فَضَرَبَاهُ بِسَيْفَيْهِمَا حَتَّى قَتَلَاهُ، ثُمَّ انْصَرَفَا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَاهُ، فَقَالَ: "أَيُّكُمَا قَتَلَهُ". فَقَالَ كُلُّ وَاحِدٍ مِنْهُمَا: أَنَا قَتَلْتُهُ، فَقَالَ: "هَلْ مَسَحْتُمَا سَيْفَيْكُمَا". قَالَا: لَا، فَنَظَرَ فِي السَّيْفَيْنِ، فَقَالَ: "كِلَاكُمَا قَتَلَهُ". وَقَضَى بِسَلَبِهِ لِمُعَاذِ بْنِ عَمْرِو بْنِ الْجَمُوحِ، وَالرَّجُلَانِ: مُعَاذُ بْنُ عَمْرِو بْنِ الْجَمُوحِ، وَمُعَاذُ بْنُ عَفْرَاءَ. (ق)', 'അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ): ഞാൻ ബദർ ദിനത്തിൽ അണിയിൽ നിൽക്കുന്നതിനിടയിൽ എന്റെ വലഭാഗത്തേക്കും ഇടഭാഗത്തേക്കും നോക്കി. അന്നേരം ഞാൻ ചെറുപ്രായക്കാരായ അൻസാറുകളിൽ പെട്ട രണ്ട് കുട്ടികളുടെ നടുവിലായിരുന്നു. അവരേക്കാൾ ശക്തരായ രണ്ടാളുടെ നടുവിലായിരുന്നെങ്കിൽ എന്ന് ഞാനാശിച്ചു. അപ്പോൾ അവരിലൊരാൾ എന്നെ തോണ്ടിക്കൊണ്ട് ചോദിച്ചു: പിതൃവ്യാ, താങ്കൾ അബൂജഹലിനെ അറിയുമോ? ഞാൻ പറഞ്ഞു: അതെ, നിനക്ക് അയാളെക്കൊണ്ട് എന്താണാവശ്യം, എന്റെ സഹോദര പുത്രാ? ആ ചെറുപ്പക്കാരൻ പറഞ്ഞു: അബൂജഹൽ തിരുമേനി(സ)യെ ശകാരിക്കുന്നത് ഞാനറിഞ്ഞു. എന്റെ ആത്മാവിനെ നിയന്ത്രിക്കുന്നവൻ തന്നെ സത്യം, ഞാനവനെ കണ്ടെത്തിയാൽ, ഞങ്ങളിൽ ആദ്യം ആയുസ്സ് തീരേണ്ടവൻ മരിച്ചശേഷമല്ലാതെ എന്റെ ശരീരം അവന്റെ ശരീരത്തെ വിട്ടുപിരിയുകയില്ല. അവന്റെ സംസാരം കേട്ട് ഞാൻ അത്ഭുതപ്പെട്ടുപോയി. അപ്പോൾ മറ്റവനും എന്നെ തോണ്ടിയിട്ട് ആദ്യത്തെയാൾ പറഞ്ഞ പോലെ പറഞ്ഞു. അധികം താമസിയാതെ, അബൂജഹൽ ജനങ്ങൾക്കിടയിൽ ചുറ്റിനടക്കുന്നത് ഞാൻ കണ്ടു. അപ്പോൾ ഞാൻ പറഞ്ഞു: നിങ്ങൾ കാണുന്നില്ലേ, നിങ്ങൾ എന്നോട് ചോദിച്ചയാൾ ഇതാണ്. ഉടനെ തങ്ങളുടെ വാളുകളും കൊണ്ട് ധൃതിയിൽ അവർ രണ്ടുപേരും അബൂജഹലിന്റെയടുത്ത് ഓടിച്ചെല്ലുകയും അവനെ വെട്ടിക്കൊലപ്പെടുത്തുകയും ചെയ്തു. ശേഷമവർ റസൂൽ(സ)യുടെ സന്നിധിയിലേക്ക് തിരിച്ചുവരികയും അവിടത്തോട് വിവരങ്ങൾ പറയുകയും ചെയ്തു. അപ്പോൾ അവിടുന്ന് ചോദിച്ചു: "നിങ്ങളിൽ ആരാണ് അവനെ കൊന്നത്?" ഞാനാണവനെ കൊന്നതെന്ന് അവരിലോരോരുത്തരും പറഞ്ഞു. അവിടന്ന് ചോദിച്ചു: "നിങ്ങൾ നിങ്ങളുടെ വാളുകൾ തുടച്ച് വെടിപ്പാക്കിയോ?" അവർ പറഞ്ഞു: ഇല്ല. അപ്പോൾ അവിടുന്ന് രണ്ട് വാളുകളിലും സൂക്ഷിച്ച് നോക്കിയിട്ട് പറഞ്ഞു: "അവനെ കൊന്നത് നിങ്ങൾ രണ്ടുപേരുമാണ്." എന്നിട്ടവിടുന്ന് അബൂജഹലിന്റെ പടക്കോപ്പുകൾ മുആദുബ്നു അംറുബ്നുൽ ജമൂഹ്(റ)വിന് നൽകി. മുആദുബ്നു അഫ്റാഅ്(റ)വും മുആദുബ്നു അംറുബ്നുൽ ജമൂഹ്(റ)വുമായിരുന്നു ആ രണ്ട് യുവാക്കൾ. (ബു,മു)', 'عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ', 'അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], 'وَشِمَالِي', null, 72, 73, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ عَوْفِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَتَلَ رَجُلٌ مِنْ حِمْيَرَ رَجُلًا مِنَ الْعَدُوِّ فَأَرَادَ سَلَبَهُ، فَمَنَعَهُ خَالِدُ ابْنُ الْوَلِيدِ رَضِيَ اللهُ عَنْهُ، وَكَانَ وَالِيًا عَلَيْهِمْ، فَأَتَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَوْفُ بْنُ مَالِكٍ فَأَخْبَرَهُ، فَقَالَ لِخَالِدٍ: "مَا مَنَعَكَ أَنْ تُعْطِيَهُ سَلَبَهُ". قَالَ: اسْتَكْثَرْتُهُ يَا رَسُولَ اللهِ، قَالَ: "ادْفَعْهُ إِلَيْهِ". فَمَرَّ خَالِدٌ بِعَوْفٍ فَجَرَّ بِرِدَائِهِ، ثُمَّ قَالَ: هَلْ أَنْجَزْتُ لَكَ مَا ذَكَرْتُ لَكَ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ فَسَمِعَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاسْتُغْضِبَ فَقَالَ: "لَا تُعْطِهِ يَا خَالِدُ، لَا تُعْطِهِ يَا خَالِدُ، هَلْ أَنْتُمْ تَارِكُونَ لِي أُمَرَائِي؟ إِنَّمَا مَثَلُكُمْ وَمَثَلُهُمْ كَمَثَلِ رَجُلٍ اسْتُرْعِيَ إِبِلًا أَوْ غَنَمًا، فَرَعَاهَا، ثُمَّ تَحَيَّنَ سَقْيَهَا فَأَوْرَدَهَا حَوْضًا فَشَرَعَتْ فِيهِ، فَشَرِبَتْ صَفْوَهُ وَتَرَكَتْ كَدْرَهُ، فَصَفْوُهُ لَكُمْ وَكَدْرُهُ عَلَيْهِمْ". (م)', 'ഔഫുബ്നു മാലിക്(റ): ഹിംയർ ഗോത്രത്തിൽ പെട്ട ഒരാൾ ശത്രുക്കളിൽ പെട്ട ഒരാളെ കൊല്ലുകയും അയാളുടെ ദേഹത്തിലുള്ള സാധനങ്ങളെടുക്കാൻ ഉദ്ദേശിക്കുകയും ചെയ്തു. അപ്പോൾ ഖാലിദുബ്നു വലീദ്(റ) അദ്ദേഹത്തെ തടഞ്ഞു. അദ്ദേഹം അവരുടെ നേതാവായിരുന്നു. അപ്പോൾ ഔഫുബ്നു മാലിക്(റ) റസൂൽ(സ)യുടെ അടുത്ത് വരികയും അവിടത്തോട് വിവരം പറയുകയും ചെയ്തു. അപ്പോൾ അവിടന്ന് ഖാലിദ്(റ)വിനോട് ചോദിച്ചു: "അദ്ദേഹത്തിനുള്ള സലബ് അദ്ദേഹത്തിന് നൽകുന്നതിൽ നിന്ന് നിന്നെ തടഞ്ഞതെന്താണ്?" ഖാലിദ്(റ) പറഞ്ഞു: അത് കൂടുതലുണ്ടെന്ന് എനിക്ക് തോന്നിയതിനാലാണ് അല്ലാഹുവിന്റെ റസൂലേ. അവിടുന്ന് പറഞ്ഞു: "നീയത് അദ്ദേഹത്തിന് തന്നെ നൽകുക." അങ്ങനെ ഖാലിദ്(റ) ഔഫ്(റ)വിന്റെ അടുത്ത് കൂടെ നടക്കുകയും അദ്ദേഹം ഖാലിദ്(റ)വിന്റെ മേൽതട്ടം വലിച്ച് ഇപ്രകാരം പറയുകയും ചെയ്തു: റസൂൽ(സ)യോട് പറയുമെന്ന് ഞാൻ നിന്നോട് പറഞ്ഞത് ഞാൻ നിറവേറ്റിയില്ലയോ? അപ്പോളത് റസൂൽ(സ) കേൾക്കുകയും അവിടുന്ന് ദേഷ്യപ്പെടുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "ഖാലിദേ. നീയത് അദ്ദേഹത്തിന് നൽകേണ്ട. ഖാലിദേ, നീയത് അദ്ദേഹത്തിന് നൽകേണ്ട. (ഞാൻ നിങ്ങൾക്ക് നിശ്ചയിച്ച് തന്ന) എന്റെ നേതാക്കന്മാരെ നിങ്ങൾ എനിക്ക് ഒഴിവാക്കിത്തരുമോ? നിശ്ചയം നിങ്ങളുടെയും ഇവരുടെയും ഉദാഹരണം ഒരാളെപ്പോലെയാണ്. അയാളോട് ഒരു ആട്ടിൻപറ്റത്തെയോ അല്ലെങ്കിൽ ഒട്ടകക്കൂട്ടത്തെയോ മേക്കാൻ ആവശ്യപ്പെടുന്നു. അങ്ങനെ അയാളവയെ മേയ്ച്ചു. പിന്നീടവയ്ക്ക് വെള്ളം കൊടുക്കേണ്ട സമയമായി. അപ്പോഴവയെ ഒരു തടാകത്തിന്റെ അടുത്തേക്ക് കൊണ്ടുവന്നു. അപ്പോഴവ ആ വെള്ളത്തിൽ പ്രവേശിക്കുകയും അതിൽ നിന്ന് തെളിഞ്ഞത് കുടിക്കുകയും കലങ്ങിയത് ഒഴിവാക്കുകയും ചെയ്തു. അങ്ങനെ അതിൽ നിന്ന് തെളിഞ്ഞത് നിങ്ങൾക്കും കലങ്ങിയത് അവർക്കും ലഭിക്കുന്നു." (മു)', 'عَوْفِ بْنِ مَالِكٍ', 'ഔഫുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 73, 74, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْتُ مَعَ زَيْدِ بْنِ حَارِثَةَ فِي غَزْوَةِ مُؤْتَةَ، فَرَافَقَنِي مَدَدٌ مِنْ أَهْلِ الْيَمَنِ لَيْسَ مَعَهُ غَيْرُ سَيْفِهِ، فَنَحَرَ رَجُلٌ مِنَ الْمُسْلِمِينَ جَزُورًا، فَسَأَلَهُ الْمَدَدِيُّ طَائِفَةً مِنْ جِلْدِهِ فَأَعْطَاهُ إِيَّاهُ، فَاتَّخَذَهُ كَهَيْئَةِ الدَّرَقِ، وَمَضَيْنَا فَلَقِينَا جُمُوعَ الرُّومِ، وَفِيهِمْ رَجُلٌ عَلَى فَرَسٍ لَهُ أَشْقَرَ، عَلَيْهِ سَرْجٌ مُذْهَبٌ وَسِلَاحٌ مُذْهَبٌ، فَجَعَلَ الرُّومِيُّ يُغْرِي بِالْمُسْلِمِينَ، فَقَعَدَ لَهُ الْمَدَدِيُّ خَلْفَ صَخْرَةٍ، فَمَرَّ بِهِ الرُّومِيُّ فَعَرْقَبَ فَرَسَهُ فَخَرَّ، وَعَلَاهُ فَقَتَلَهُ وَحَازَ فَرَسَهُ وَسِلَاحَهُ، فَلَمَّا فَتَحَ اللهُ عَزَّ وَجَلَّ لِلْمُسْلِمِينَ بَعَثَ إِلَيْهِ خَالِدُ بْنُ الْوَلِيدِ فَأَخَذَ مِنَ السَّلَبِ، قَالَ عَوْفٌ: فَأَتَيْتُهُ فَقُلْتُ: يَا خَالِدُ، أَمَا عَلِمْتَ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَضَى بِالسَّلَبِ لِلْقَاتِلِ؟ قَالَ: بَلَى، وَلَكِنِّي اسْتَكْثَرْتُهُ، قُلْتُ: لَتَرُدَّنَّهُ عَلَيْهِ أَوْ لَأُعَرِّفَنَّكَهَا عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَأَبَى أَنْ يَرُدَّ عَلَيْهِ، قَالَ عَوْفٌ: فَاجْتَمَعْنَا عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَصَصْتُ عَلَيْهِ قِصَّةَ الْمَدَدِيِّ وَمَا فَعَلَ خَالِدٌ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا خَالِدُ، مَا حَمَلَكَ عَلَى مَا صَنَعْتَ". قَالَ: يَا رَسُولَ اللهِ، لَقَدِ اسْتَكْثَرْتُهُ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا خَالِدُ، رُدَّ عَلَيْهِ مَا أَخَذْتَ مِنْهُ". قَالَ عَوْفٌ: فَقُلْتُ لَهُ: دُونَكَ يَا خَالِدُ، أَلَمْ أَفِ لَكَ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَمَا ذَلِكَ". قَالَ: فَغَضِبَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "يَا خَالِدُ، لَا تَرُدَّ عَلَيْهِ، هَلْ أَنْتُمْ تَارِكُونَ لِي أُمَرَائِي؟ لَكُمْ صَفْوَةُ أَمْرِهِمْ وَعَلَيْهِمْ كَدَرُهُ". (م,د)', 'ഔഫുബ്നു മാലികിൽ അശ്ജഇൗ(റ): മുഅ്തത് യുദ്ധത്തിൽ ഞാൻ സൈദുബ്നു ഹാരിസ(റ)വിനോടൊപ്പം പുറപ്പെട്ടു. അപ്പോൾ യുദ്ധത്തിൽ മുസ്‌ലിംകളെ സഹായിക്കാനായി യമനിൽ നിന്ന് വന്ന ഒരാൾ എന്നോട് കൂട്ടുകൂടി. അദ്ദേഹത്തിന്റെ കൂടെ അദ്ദേഹത്തിന്റെ വാളല്ലാതെ ഒന്നുമുണ്ടായിരുന്നില്ല. അപ്പോൾ മുസ്‌ലിംകളിൽ പെട്ട ഒരാൾ ഒരു ഒട്ടകത്തെ അറുത്തു. അപ്പോൾ ഈ സഹായി അദ്ദേഹത്തോട് അതിന്റെ തോലുകളിൽ അൽപം ചോദിച്ചു. അദ്ദേഹമത് ഇയാൾക്ക് നൽകുകയും ചെയ്തു. അപ്പോൾ അയാളതിനെ ഒരു പരിചയുടെ രൂപത്തിലാക്കി. അങ്ങനെ ഞങ്ങൾ അവിടെനിന്നും യാത്രയാവുകയും ഒരു റോമൻ സംഘത്തെ കണ്ടുമുട്ടുകയും ചെയ്തു. ഒരു ഇളം ചുവപ്പ് നിറമുള്ള കുതിരയുടെ മുകളിലായി അവരിൽ ഒരാളുണ്ടായിരുന്നു. കുതിരയുടെ മുകളിൽ സ്വർണ്ണം പൂശിയ ഒരു ജീനിയും സ്വർണ്ണം പൂശിയ ആയുധവുമുണ്ടായിരുന്നു. അങ്ങനെ ആ റോമക്കാരൻ മുസ്‌ലിംകളെ അക്രമിക്കാൻ തുടങ്ങി. അപ്പോൾ അയാളെ ഉദ്ദേശിച്ചുകൊണ്ട് ഈ സഹായി ഒരു പാറക്ക് പിന്നിലിരുന്നു. അപ്പോൾ ആ റോമക്കാരൻ ഇദ്ദേഹത്തിന്റെ അടുത്ത് കൂടെ നടന്നുപോവുകയും അദ്ദേഹമയാളുടെ കുതിരയുടെ കൃതിഞരമ്പ് മുറിക്കുകയും അയാൾ നിലത്ത് വീഴുകയും ചെയ്തു. അപ്പോൾ ഇദ്ദേഹമയാളെ അക്രമിക്കുകയും കൊല്ലുകയും അദ്ദേഹത്തിന്റെ കുതിരയും ആയുധവും ഒരുമിച്ചുകൂട്ടുകയും ചെയ്തു. അങ്ങനെ അല്ലാഹു മുസ്‌ലിംകൾക്ക് വിജയം നൽകിയപ്പോൾ ഖാലിദുബ്നുൽ വലീദ്(റ) അദ്ദേഹത്തിന്റെയടുത്തേക്ക് ആളെ അയക്കുകയും ഇദ്ദേഹം ഒരുമിച്ചുകൂട്ടിയ (ഈ റോമക്കാരന്റെ ദേഹത്തുണ്ടായിരുന്ന) സാധനങ്ങളിൽനിന്ന് അൽപം വാങ്ങുകയും ചെയ്തു. ഔഫ്(റ) പറഞ്ഞു: അപ്പോൾ ഞാൻ ഖാലിദുബ്നു വലീദ്(റ)വിനെ സമീപിക്കുകയും അദ്ദേഹത്തോട് പറയുകയും ചെയ്തു: ഖാലിദേ, കൊല്ലപ്പെട്ടവന്റെ ദേഹത്തിലെ സാധനങ്ങൾ കൊന്നുവന് നൽകാനാണ് റസൂൽ(സ) വിധിച്ചതെന്ന് താങ്കൾക്കറിയില്ലേയോ? അദ്ദേഹം പറഞ്ഞു: അതെ. പക്ഷേ, ഇത് കുറച്ച് കൂടുതലാണെന്നാണ് ഞാൻ മനസ്സിലാക്കുന്നത്. ഞാൻ പറഞ്ഞു: താങ്കളത് അദ്ദേഹത്തിന് തിരിച്ചുകൊടുക്കുക തന്നെ വേണം. അല്ലെങ്കിൽ റസൂൽ(സ)യുടെ സന്നിധിയിൽ വെച്ച് ഞാൻ നിങ്ങൾക്ക് കാണിച്ചുതരാം. അദ്ദേഹമത് തിരിച്ചുകൊടുക്കാൻ വിസമ്മതിച്ചു. അങ്ങനെ ഞങ്ങൾ റസൂൽ(സ)യുടെ സന്നിധിയിൽ ഒരുമിച്ചുകൂടുകയും, ഞാൻ അവിടത്തോടു ഈ സഹായിയുടെ കഥയും ഖാലിദ്(റ) ചെയ്ത കാര്യവും വിവരിച്ച് കൊടുക്കുകയും ചെയ്തു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "ഖാലിദേ, ഈ ചെയ്തിക്ക് താങ്കളെ പ്രേരിപ്പിച്ചതെന്താണ്." അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അത് കുറച്ച് കൂടുതലാണെന്ന് എനിക്ക് തോന്നുന്നതിനാലാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഖാലിദേ, താങ്കൾ അദ്ദേഹത്തിൽ നിന്ന് വാങ്ങിയത് അദ്ദേഹത്തിന് തന്നെ തിരിച്ചുനൽക്കുക." ഔഫ്(റ) പറയുന്നു: അപ്പോൾ ഞാൻ ഖാലിദ്(റ)വിനോട് പറഞ്ഞു: ഖാലിദേ നീ അനുഭവിച്ച് കൊള്ളൂ. (അപ്പോൾ തന്നെ) ഞാൻ നിന്നോട് പറഞ്ഞത് നിറവേറ്റിയില്ലേ? അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "അതെന്താണ്?" അപ്പോൾ ഞാനവിടത്തോട് വിവരങ്ങളെല്ലാം പറഞ്ഞു: നിവേകൻ പറയുന്നു. അപ്പോൾ റസൂൽ(സ) ദേഷ്യം പിടിക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "ഖാലിദേ, നീയത് അയാൾക്ക് തിരിച്ചുകൊടുക്കേണ്ട. (ഞാൻ നിശ്ചയിച്ച) നേതാക്കന്മാരെ നിങ്ങൾ എനിക്ക് ഒഴിവാക്കിത്തരുമോ? അവരുടെ കാര്യങ്ങളിൽ നിന്നുള്ള നല്ലത് നിങ്ങൾക്കുള്ളതാണ്. അതിൽ നിന്ന് സങ്കീർണ്ണമായത് അവരുടെമേൽ തന്നെയാണ്." (മു,ദ)', 'عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ', 'ഔഫുബ്നു മാലികിൽ അശ്ജഇൗ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 74, 75, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْسِمُ غَنِيمَةً بِالْجِعْرَانَةِ [اسْمُ مَكَانٍ] إِذْ قَالَ لَهُ رَجُلٌ اعْدِلْ فَقَالَ: "لَقَدْ شَقِيتَ إِنْ لَمْ أَعْدِلْ". (خ)', 'ജാബിർ(റ): ജിഅ്റാന എന്ന സ്ഥലത്തുവെച്ച് റസൂൽ(സ) യുദ്ധമുതൽ വീതിക്കുന്നതിനിടയിൽ ഒരാൾ അവിടുത്തോട് പറഞ്ഞു: അങ്ങ് നീതി പാലിക്കുക. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "ഞാൻ നീതി പാലിച്ചിട്ടില്ലായിരുന്നുവെങ്കിൽ തീർച്ചയായും നീ പരാജിതനാകുമായിരുന്നു." (ബു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], 'اسْمُ مَكَانٍ', null, 75, 75, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ خَوْلَةَ الْأَنْصَارِيَّةِ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ رِجَالًا يَتَخَوَّضُونَ فِي مَالِ اللهِ بِغَيْرِ حَقٍّ فَلَهُمُ النَّارُ يَوْمَ الْقِيَامَةِ". (خ)', 'ഖൗലതുൽ അൻസാരി(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിശ്ചയം, ചിലയാളുകൾ അവകാശം കൂടാതെ അല്ലാഹുവിന്റെ ധനത്തിൽ കൈകടത്തുന്നു. അവർക്ക് അന്ത്യനാളിൽ നരകമുണ്ട്." (ബു)', 'خَوْلَةَ الْأَنْصَارِيَّةِ', 'ഖൗലതുൽ അൻസാരി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 75, 75, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِيَّاكُمْ وَالْقُسَامَةَ". فَقِيلَ: وَمَا الْقُسَامَةُ؟ قَالَ: "الشَّيْءُ يَكُونُ بَيْنَ النَّاسِ، فَيَجِيءُ فَيَنْتَقِصُ مِنْهُ". وَفِي رِوَايَةٍ مُرْسَلَةٍ عَنْ عَطَاءِ بْنِ يَسَارٍ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَحْوَهُ، قَالَ: "الرَّجُلُ يَكُونُ عَلَى الْفِئَامِ مِنَ النَّاسِ، فَيَأْخُذُ مِنْ حَظِّ هَذَا وَحَظِّ هَذَا". (د)', 'അബൂസഇൗദിൽ ഖുദ്രി(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ നിങ്ങളെയും ഖുസാമതിനെയും സൂക്ഷിക്കുക." അപ്പോൾ ചോദിക്കപ്പെട്ടു: എന്താണ് ഖുസാമത്? അവിടന്ന് പറഞ്ഞു: "ഒരു വസ്തു ജനങ്ങൾക്ക് അവകാശപ്പെട്ടതാവുകയും (അവർക്കിടയിൽ വീതിക്കാൻ) അപ്പോൾ ഒരാൾ വരികയും അതിൽ നിന്ന് ചുരുക്കുകയും ചെയ്യുന്നു." അത്വാഉബ്നു യസാർ(റ)യിൽ നിന്നുള്ള മുർസലായ ഒരു റിപ്പോർട്ടിൽ നബി(സ)യെ തൊട്ട് ഇതുപോലെയുള്ള ഒരു ഹദീസ് ഉണ്ട്: "ഒരാൾ ഒരു ജനക്കൂട്ടത്തിന്റെ നേതൃത്വത്തിൽ എത്തുകയും അങ്ങനെ ഇവന്റെയും ഇവന്റെയുമെല്ലാം വിഹിതത്തിൽ നിന്ന് അവൻ എടുക്കുകയും ചെയ്യുന്നു." (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഇൗദിൽ ഖുദ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 75, 75, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=100), 1, 'وَفِي رِوَايَةٍ مُرْسَلَةٍ عَنْ عَطَاءِ بْنِ يَسَارٍ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَحْوَهُ، قَالَ: "الرَّجُلُ يَكُونُ عَلَى الْفِئَامِ مِنَ النَّاسِ، فَيَأْخُذُ مِنْ حَظِّ هَذَا وَحَظِّ هَذَا". (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ رُوَيْفِعِ بْنِ ثَابِتٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ كَانَ يُؤْمِنُ بِاللهِ وَبِالْيَوْمِ الْآخِرِ فَلَا يَرْكَبْ دَابَّةً مِنْ فَيْءِ الْمُسْلِمِينَ، حَتَّى إِذَا أَعْجَفَهَا رَدَّهَا فِيهِ. وَمَنْ كَانَ يُؤْمِنُ بِاللهِ وَبِالْيَوْمِ الْآخِرِ فَلَا يَلْبَسْ ثَوْبًا مِنْ فَيْءِ الْمُسْلِمِينَ، حَتَّى إِذَا أَخْلَقَهُ رَدَّهُ فِيهِ". (د)', 'റുവൈഫിഉബ്നു സാബിതിൽ അൻസാരി(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും അല്ലാഹുവിലും അന്ത്യനാളിലും വിശ്വസിക്കുന്നുവെങ്കിൽ മുസ്‌ലിംകളുടെ യുദ്ധമുതലിൽ പെട്ട മൃഗത്തെ അവൻ വാഹനമാക്കാതിരിക്കട്ടെ, അങ്ങനെ അത് മെലിഞ്ഞാൽ അവനതിനെ തിരിച്ച് നൽകുകയും ചെയ്യും. ആരെങ്കിലും അല്ലാഹുവിലും അന്ത്യനാളിലും വിശ്വസിക്കുന്നുവെങ്കിൽ മുസ്‌ലിംകളുടെ യുദ്ധമുതലിൽ പെട്ട വസ്ത്രം അവൻ ധരിക്കാതിരിക്കട്ടെ, അങ്ങനെ അത് നുരുമ്പിയാൽ യുദ്ധമുതലിലേക്ക് തന്നെ അവനത് നൽകുകയും ചെയ്യും." (ദ)', 'رُوَيْفِعِ بْنِ ثَابِتٍ الْأَنْصَارِيِّ', 'റുവൈഫിഉബ്നു സാബിതിൽ അൻസാരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 75, 76, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: السِّجِلُّ كَاتِبٌ كَانَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): സിജില്ല് നബി(സ)യുടെ എഴുത്തുകാരനായിരുന്നു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 76, 76, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ رَافِعِ بْنِ خَدِيجٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْعَامِلُ عَلَى الصَّدَقَةِ بِالْحَقِّ كَالْغَازِي فِي سَبِيلِ اللهِ حَتَّى يَرْجِعَ إِلَى بَيْتِهِ". (د,ت,جه)', 'റാഫിഉബ്നു ഖദീജ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "സത്യസന്ധമായി നിർബന്ധ ദാനം (സകാത്) പിരിച്ചെടുക്കുന്നവൻ, തന്റെ വീട്ടിലേക്ക് മടങ്ങുവോളം, അല്ലാഹുവിന്റെ മാർഗത്തിൽ യുദ്ധം ചെയ്യുന്നവനെപ്പോലെയാണ്." (ദ,തു,ജ)', 'رَافِعِ بْنِ خَدِيجٍ', 'റാഫിഉബ്നു ഖദീജ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 76, 76, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَدْخُلُ الْجَنَّةَ صَاحِبُ مَكْسٍ". وَعَنْ مُحَمَّدِ بْنِ إِسْحَاقَ: أَنَّ صَاحِبَ الْمَكْسِ الَّذِي يَعْشُرُ النَّاسَ. (د)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): റസൂൽ(സ) പറഞ്ഞത് ഞാൻ കേട്ടു: "അതിക്രമമായി സ്വദഖ പിരിക്കുന്നവൻ സ്വർഗത്തിൽ പ്രവേശിക്കുകയില്ല." മുഹമ്മദുബ്നു ഇസ്ഹാഖ് പറഞ്ഞു: ''സ്വാഹിബു മക്സ്'' എന്നാൽ അതിക്രമമായി നികുതി പിരിക്കുന്നവനാണ്. (ദ)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 76, 76, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنِ اسْتَعْمَلْنَاهُ عَلَى عَمَلٍ، فَرَزَقْنَاهُ رِزْقًا، فَمَا أَخَذَ بَعْدَ ذَلِكَ فَهُوَ غُلُولٌ". (د)', 'ബുറൈദ(റ): നബി(സ) പറഞ്ഞു: "നാം ആരെയെങ്കിലും ഒരു ഉദ്യോഗത്തിൽ നിയമിച്ചാൽ, അവന് ഒരു വിഹിതം നീക്കും. അതിനപ്പുറമുള്ളതെടുത്താൽ അത് വഞ്ചനയാണ്." (ദ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 76, 76, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنِ ابْنِ السَّاعِدِيِّ قَالَ: اسْتَعْمَلَنِي عُمَرُ رَضِيَ اللهُ عَنْهُ عَلَى الصَّدَقَةِ، فَلَمَّا فَرَغْتُ أَمَرَ لِي بِعُمَالَةٍ، فَقُلْتُ: إِنَّمَا عَمِلْتُ لِلَّهِ، قَالَ: خُذْ مَا أُعْطِيتَ، فَإِنِّي قَدْ عَمِلْتُ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَعَمَّلَنِي. (ق,د,ن)', 'ഇബ്നുസ്സാഇദീ(റ): ഉമർ(റ) എന്നെ സകാത്ത് പിരിക്കാൻ ചുമതലപ്പെടുത്തി. പിന്നീട് ഞാനെന്റെ ജോലി പൂർത്തീകരിച്ചപ്പോൾ അദ്ദേഹമെനിക്ക് കൂലി നൽകാൻ കൽപിച്ചു. അന്നേരം ഞാൻ പറഞ്ഞു: ഞാൻ അല്ലാഹുവിന് വേണ്ടിയാണ് ജോലിയെടുത്തത്. അദ്ദേഹം പറഞ്ഞു: നിനക്ക് തരുന്നത് നീ വാങ്ങുക. നബി(സ)യുടെ കാലത്ത് ഞാൻ ഉദ്യോഗം ചെയ്തപ്പോൾ എനിക്ക് കൂലി നൽകിയിട്ടുണ്ട്. (ബു,മു,ദ,ന)', 'ابْنِ السَّاعِدِيِّ قَالَ', 'ഇബ്നുസ്സാഇദീ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 76, 77, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنِ الْمُسْتَوْرِدِ بْنِ شَدَّادٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ كَانَ لَنَا عَامِلًا فَلْيَكْتَسِبْ زَوْجَةً، فَإِنْ لَمْ يَكُنْ لَهُ خَادِمٌ فَلْيَكْتَسِبْ خَادِمًا، فَإِنْ لَمْ يَكُنْ لَهُ مَسْكَنٌ فَلْيَكْتَسِبْ مَسْكَنًا". قَالَ: قَالَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ: أُخْبِرْتُ أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنِ اتَّخَذَ غَيْرَ ذَلِكَ فَهُوَ غَالٌّ أَوْ سَارِقٌ". (د)', 'മുസ്തൗരിദുബ്നു ശദ്ദാദ്(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "ആരെങ്കിലും നമുക്കു വേണ്ടി ഉദ്യോഗം ചെയ്യുന്നുണ്ടെങ്കിൽ അവനൊരു ഭാര്യയെ നേടിയെടുക്കട്ടെ. അവന് സേവകനില്ലെങ്കിൽ ഒരു സേവകനെ നിർത്താം. വീടില്ലെങ്കിൽ ഒരു വീട് വെക്കട്ടെ." നിവേദകൻ: അബൂബക്ർ(റ) പറഞ്ഞു: നബി(സ) പറഞ്ഞതായി ഞാനറിയിക്കപ്പെട്ടു: "അതിൽ കൂടുതൽ സമ്പാദിച്ചാൽ അവൻ വഞ്ചകനോ മോഷ്ടാവോ ആണ്." (ദ)', 'الْمُسْتَوْرِدِ بْنِ شَدَّادٍ', 'മുസ്തൗരിദുബ്നു ശദ്ദാദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 77, 77, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ عَدِيِّ بْنِ عَمِيرَةَ الْكِنْدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنِ اسْتَعْمَلْنَاهُ مِنْكُمْ عَلَى عَمَلٍ، فَكَتَمَنَا مِخْيَطًا فَمَا فَوْقَهُ كَانَ غُلُولًا يَأْتِي بِهِ يَوْمَ الْقِيَامَةِ". قَالَ: فَقَامَ إِلَيْهِ رَجُلٌ أَسْوَدُ مِنَ الْأَنْصَارِ كَأَنِّي أَنْظُرُ إِلَيْهِ، فَقَالَ: يَا رَسُولَ اللهِ، اقْبَلْ عَنِّي عَمَلَكَ. قَالَ: "وَمَا لَكَ". قَالَ: سَمِعْتُكَ تَقُولُ كَذَا وَكَذَا، قَالَ: "وَأَنَا أَقُولُهُ الْآنَ: مَنِ اسْتَعْمَلْنَاهُ مِنْكُمْ عَلَى عَمَلٍ، فَلْيَجِئْ بِقَلِيلِهِ وَكَثِيرِهِ، فَمَا أُوتِيَ مِنْهُ أَخَذَ، وَمَا نُهِيَ عَنْهُ انْتَهَى". (م)', 'അദിയ്യുബ്നു അമീറതുൽ കിന്ദി(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "ഞാൻ നിങ്ങളിലൊരാളെ ഒരു അധികാരമേൽപിക്കുകയും അങ്ങനെ (അയാൾക്ക് കിട്ടിയ) ഒരു സൂചിയോ അതിലേറെ മുന്തിയ മറ്റെന്തെങ്കിലുമോ എന്നിൽ നിന്നയാൾ മറച്ചു വെക്കുകയും ചെയ്താൽ അത് പൂഴ്തിവെപ്പാണ്. അതുമായി അവൻ അന്ത്യദിനത്തിൽ വരും." നിവേദകൻ പറയുന്നു: അപ്പോൾ അൻസാരികളിൽപെട്ട കറുത്ത ഒരു മനുഷ്യൻ റസൂൽ(സ)യിലേക്ക് എഴുന്നേറ്റു നിന്ന് പറഞ്ഞു, ഞാനിപ്പോഴും അയാളെ നോക്കിക്കൊണ്ടിരിക്കുന്ന പോലെയുണ്ട്: അല്ലാഹുവിന്റെ പ്രവാചകരേ, അങ്ങയുടെ അധികാരം എന്നിൽനിന്ന് അങ്ങ് തിരികെ വാങ്ങിയാലും. അവിടുന്ന് ചോദിച്ചു: "താങ്കൾക്കെന്തു പറ്റി?" അദ്ദേഹം പറഞ്ഞു: അവിടുന്ന് ഇപ്രകാരമെല്ലാം പറയുന്നത് ഞാൻ കേട്ടല്ലോ. അവിടുന്ന് പറഞ്ഞു: "ഇപ്പോഴിതാ ഞാനത് ഒന്നുകൂടെ പറയുന്നു: നിങ്ങളിലൊരാളെ നാം വല്ല അധികാരവും ഏൽപിച്ചാൽ അതിലെ കൂടിയതും കുറഞ്ഞതുമെല്ലാം അവൻ കൊണ്ടുവരട്ടെ. അതിൽനിന്ന് നൽകപ്പെട്ടത് അവൻ സ്വീകരിക്കുകയും വിലക്കപ്പെട്ടതിൽ നിന്ന് വിട്ടുനിൽക്കുകയും ചെയ്യട്ടെ." (മു)', 'عَدِيِّ بْنِ عَمِيرَةَ الْكِنْدِيِّ', 'അദിയ്യുബ്നു അമീറതുൽ കിന്ദി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 77, 77, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: اسْتَعْمَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلًا مِنَ الْأَزْدِ عَلَى صَدَقَاتِ بَنِي سُلَيْمٍ يُدْعَى ابْنَ الْأُتْبِيَّةِ، فَلَمَّا جَاءَ حَاسَبَهُ، قَالَ: هَذَا مَالُكُمْ وَهَذَا هَدِيَّةٌ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَهَلَّا جَلَسْتَ فِي بَيْتِ أَبِيكَ وَأُمِّكَ حَتَّى تَأْتِيَكَ هَدِيَّتُكَ إِنْ كُنْتَ صَادِقًا". ثُمَّ خَطَبَنَا فَحَمِدَ اللهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: "أَمَّا بَعْدُ، فَإِنِّي أَسْتَعْمِلُ الرَّجُلَ مِنْكُمْ عَلَى الْعَمَلِ مِمَّا وَلَّانِي اللهُ، فَيَأْتِي فَيَقُولُ: هَذَا مَالُكُمْ، وَهَذَا هَدِيَّةٌ أُهْدِيَتْ لِي، أَفَلَا جَلَسَ فِي بَيْتِ أَبِيهِ وَأُمِّهِ حَتَّى تَأْتِيَهُ هَدِيَّتُهُ إِنْ كَانَ صَادِقًا؟ وَاللهِ لَا يَأْخُذُ أَحَدٌ مِنْكُمْ مِنْهَا شَيْئًا بِغَيْرِ حَقِّهِ إِلَّا لَقِيَ اللهَ تَعَالَى يَحْمِلُهُ يَوْمَ الْقِيَامَةِ، فَلَأَعْرِفَنَّ أَحَدًا مِنْكُمْ لَقِيَ اللهَ يَحْمِلُ بَعِيرًا لَهُ رُغَاءٌ، أَوْ بَقَرَةً لَهَا خُوَارٌ، أَوْ شَاةً تَيْعَرُ". ثُمَّ رَفَعَ يَدَيْهِ حَتَّى رُئِيَ بَيَاضُ إِبْطَيْهِ يَقُولُ: "اللَّهُمَّ هَلْ بَلَّغْتُ". بَصُرَ عَيْنِي، وَسَمِعَ أُذُنِي. (ق,د)', 'അബൂഹുമൈദിനിസ്സാഇദീ(റ): അസദ് ഗേത്രക്കാരനായ, ഇബ്നുൽഉത്ബിയ്യ എന്നു വിളിക്കപ്പെടുന്ന ഒരാളെ ബനൂസുലൈം ഗോത്രത്തിലെ സ്വദഖഃ പിരിക്കാനായി നബി(സ) നിയോഗിച്ചു. അങ്ങനെ അദ്ദേഹം വന്നപ്പോൾ അദ്ദേഹത്തോട് കണക്കു ചോദിച്ചു. അപ്പോഴദ്ദേഹം പറഞ്ഞു: ഇത് നിങ്ങൾക്കുള്ള സമ്പത്തും ഇത് (എനിക്ക്) സമ്മാനമായി നൽകപ്പെട്ടതുമാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിനക്ക് നിന്റെ പിതാവിന്റെയോ മാതാവിന്റെയോ വീട്ടിൽ ഇരുന്നുകൂടായിരുന്നോ. നീ സത്യവാനാണെങ്കിൽ നിനക്കുള്ള സമ്മാനം നിന്റെ അടുത്തേക്ക് വരുമല്ലോ." ശേഷം അവിടുന്ന് ഞങ്ങളോട് പ്രസംഗിച്ചു. അല്ലാഹുവിനെ സ്തുതിക്കുകയും അവനെ വാഴ്ത്തുകയും ചെയ്ത ശേഷം അവിടുന്ന് പറഞ്ഞു: "മുഖവുരക്കുശേഷം, അല്ലാഹു എന്നെ ഏൽപിച്ച കാര്യങ്ങളിലൊന്നിൽ നിങ്ങളിലൊരാളെ ഞാൻ അധികാരമേൽപിക്കുന്നു. അങ്ങനെ അയാൾ വന്ന് ഇപ്രകാരം പറയുന്നു: ഇത് നിങ്ങൾക്കുള്ള മുതലും ഇത് എനിക്ക് സമ്മാനമായി നൽകപ്പെട്ടതുമാണ്. അയാൾക്കെന്താ തന്റെ പിതാവിന്റെയോ മാതാവിന്റെയോ വീട്ടിൽ ഇരുന്നു കൂടായിരുന്നോ? അയാൾ സത്യവാനാണെങ്കിൽ അയാൾക്കുള്ള സമ്മാനങ്ങൾ അയാളുടെ അടുക്കൽ വരുമല്ലോ? അല്ലാഹുവാണ് സത്യം, നിങ്ങളിൽ നിന്നാരെങ്കിലും അതിൽനിന്ന് വല്ലതുമെടുത്താൽ അന്ത്യദിനത്തിൽ അതുമായി അല്ലാഹുവിനെ കണ്ടുമുട്ടാതിരിക്കുകയില്ല. ശബ്ദമുണ്ടാക്കുന്ന ഒട്ടകത്തെയോ, പശുവിനെയോ, ആടിനെയോ ചുമന്ന് അല്ലാഹുവിനെ കണ്ടുമുട്ടുന്ന നിങ്ങളിലൊരാളെ ഞാൻ അറിയുക തന്നെചെയ്യും." ശേഷമവിടുന്ന് കക്ഷത്തിന്റെ വെളുപ്പ് കാണപ്പെടുംവിധം തന്റെ ഇരു കൈകളും മേൽപോട്ടുയർത്തി ഇപ്രകാരം പറഞ്ഞു: "അല്ലാഹുവേ, ഞാൻ എത്തിച്ചു കൊടുത്തില്ലെയോ?" (ഈ സംഭവം) എന്റെ കണ്ണുകൾ കാണുകയും എന്റെ ചെവികൾ കേൾക്കുകയും ചെയ്തിരിക്കുന്നു. (ബു,മു,ദ)', 'أَبِي حُمَيْدٍ السَّاعِدِيِّ', 'അബൂഹുമൈദിനിസ്സാഇദീ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 77, 78, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ أَبِي مَسْعُودٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَنِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَاعِيًا، ثُمَّ قَالَ: "انْطَلِقْ أَبَا مَسْعُودٍ، وَلَا أُلْفِيَنَّكَ يَوْمَ الْقِيَامَةِ تَجِيءُ وَعَلَى ظَهْرِكَ بَعِيرٌ مِنْ إِبِلِ الصَّدَقَةِ لَهُ رُغَاءٌ، قَدْ غَلَلْتَهُ". قَالَ: إِذًا لَا أَنْطَلِقُ، قَالَ: "إِذًا لَا أُكْرِهُكَ". (د)', 'അബൂമസ്ഊദിൽ അൻസാരി(റ): നബി(സ) എന്നെ സകാത്ത് പിരിക്കാനായി അയച്ചുകൊണ്ട് പറഞ്ഞു: "നീ പോവുക, അബൂമസ്ഊദ്. സകാത്തിന്റെ വിഹിതത്തിൽ നിന്ന് അന്യായമായി കൈവശപ്പെടുത്തിയ, ശബ്ദിക്കുന്ന ഒട്ടകത്തെ ചുമലിലേറ്റി അന്ത്യനാളിൽ നീ നടന്നുവരുന്നത് ഞാൻ കാണാതിരിക്കട്ടെ." അബൂമസ്ഊദ്(റ) പറഞ്ഞു: എങ്കിൽ ഞാൻ പോകുന്നില്ല. നബി(സ) പറഞ്ഞു: "എന്നാൽ ഞാൻ നിന്നെ നിർബന്ധിക്കുന്നില്ല." (ദ)', 'أَبِي مَسْعُودٍ الْأَنْصَارِيِّ', 'അബൂമസ്ഊദിൽ അൻസാരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 78, 78, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَامَ فِينَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ فَذَكَرَ الْغُلُولَ، فَعَظَّمَهُ وَعَظَّمَ أَمْرَهُ، ثُمَّ قَالَ: "لَا أُلْفِيَنَّ أَحَدَكُمْ يَجِيءُ يَوْمَ الْقِيَامَةِ عَلَى رَقَبَتِهِ بَعِيرٌ لَهُ رُغَاءٌ، يَقُولُ: يَا رَسُولَ اللهِ أَغِثْنِي، فَأَقُولُ: لَا أَمْلِكُ لَكَ شَيْئًا، قَدْ أَبْلَغْتُكَ. لَا أُلْفِيَنَّ أَحَدَكُمْ يَجِيءُ يَوْمَ الْقِيَامَةِ عَلَى رَقَبَتِهِ فَرَسٌ لَهُ حَمْحَمَةٌ، فَيَقُولُ: يَا رَسُولَ اللهِ أَغِثْنِي، فَأَقُولُ: لَا أَمْلِكُ لَكَ شَيْئًا، قَدْ أَبْلَغْتُكَ. لَا أُلْفِيَنَّ أَحَدَكُمْ يَجِيءُ يَوْمَ الْقِيَامَةِ عَلَى رَقَبَتِهِ شَاةٌ لَهَا ثُغَاءٌ، يَقُولُ: يَا رَسُولَ اللهِ أَغِثْنِي، فَأَقُولُ: لَا أَمْلِكُ لَكَ شَيْئًا، قَدْ أَبْلَغْتُكَ. لَا أُلْفِيَنَّ أَحَدَكُمْ يَجِيءُ يَوْمَ الْقِيَامَةِ عَلَى رَقَبَتِهِ نَفْسٌ لَهَا صِيَاحٌ، فَيَقُولُ: يَا رَسُولَ اللهِ أَغِثْنِي، فَأَقُولُ: لَا أَمْلِكُ لَكَ شَيْئًا، قَدْ أَبْلَغْتُكَ. لَا أُلْفِيَنَّ أَحَدَكُمْ يَجِيءُ يَوْمَ الْقِيَامَةِ عَلَى رَقَبَتِهِ رِقَاعٌ تَخْفِقُ، فَيَقُولُ: يَا رَسُولَ اللهِ أَغِثْنِي، فَأَقُولُ: لَا أَمْلِكُ لَكَ شَيْئًا، قَدْ أَبْلَغْتُكَ. لَا أُلْفِيَنَّ أَحَدَكُمْ يَجِيءُ يَوْمَ الْقِيَامَةِ عَلَى رَقَبَتِهِ صَامِتٌ، فَيَقُولُ: يَا رَسُولَ اللهِ أَغِثْنِي، فَأَقُولُ: لَا أَمْلِكُ لَكَ شَيْئًا، قَدْ أَبْلَغْتُكَ". (م)', 'അബൂഹുറൈറ(റ): ഒരു ദിവസം റസൂൽ(സ) ഞങ്ങൾക്കിടയിൽ ഏഴുന്നേറ്റു നിന്ന്, യുദ്ധമുതൽ (വീതിക്കപ്പെടുന്നതിനു മുമ്പ് ഇമാമിന്റെ സമ്മതം കൂടാതെ) സ്വന്തമാക്കുന്നതിനെ പറ്റി പറഞ്ഞു. അവിടുന്ന് അതിനെ ഗൗരവമുള്ളതായി കാണുകയും അക്കാര്യം സാരമുള്ളതാക്കുകയും ചെയ്തു. ശേഷം അവിടുന്ന് പറഞ്ഞു: "അല്ലാഹുവിന്റെ റസൂലേ, എന്നെ സഹായിച്ചാലും എന്നു പറഞ്ഞുകൊണ്ട്, പിരടിയിൽ കരയുന്ന ഒട്ടകവുമായി വരുന്നതായി നിങ്ങളിലൊരാളെയും അന്ത്യദിനത്തിൽ ഞാൻ കണ്ടുമുട്ടാതിരിക്കട്ടെ. അന്നേരം ഞാൻ പറയും: നിന്റെ കാര്യത്തിൽ എനിക്കൊന്നും ചെയ്യാൻ കഴിയുകയില്ല, നിശ്ചയം ഞാൻ നിനക്ക് എത്തിച്ചു തന്നിരിക്കുന്നു. അല്ലാഹുവിന്റെ റസൂലേ, എന്നെ സഹായിച്ചാലും എന്ന് പറഞ്ഞുകൊണ്ട് പിരടിയിൽ കരയുന്ന ഒരു കുതിരയെയും വഹിച്ച് വരുന്നതായിട്ട് അന്ത്യദിനത്തിൽ നിങ്ങളിലൊരാളെയും ഞാൻ കണ്ടുമുട്ടാതിരിക്കട്ടെ. അന്നേരം ഞാൻ പറയും: നിന്റെ കാര്യത്തിൽ എനിക്ക് ഒന്നും ചെയ്യാൻ കഴിയുകയില്ല, നിശ്ചയം ഞാൻ നിനക്ക് എത്തിച്ചുതന്നിരിക്കുന്നു. അല്ലാഹുവിന്റെ റസൂലേ, എന്നെ സഹായിച്ചാലും എന്നു പറഞ്ഞുകൊണ്ട്, കരയുന്ന ഒരു ആടിനെ പിരടിയിൽ വഹിച്ച് വരുന്നതായിട്ട് അന്ത്യദിനത്തിൽ നിങ്ങളിലൊരാളെയും ഞാൻ കണ്ടുമുട്ടാതിരക്കട്ടെ. അന്നേരം ഞാൻ പറയും: നിന്റെ കാര്യത്തിൽ എനിക്കൊന്നും ചെയ്യാൻ കഴിയുകയില്ല, നിശ്ചയം ഞാൻ നിനക്ക് എത്തിച്ചുതന്നിരിക്കുന്നു. അല്ലാഹുവിന്റെ റസൂലേ, എന്നെ സഹായിച്ചാലും എന്നു പറഞ്ഞുകൊണ്ട് നിലവിളിക്കുന്ന ഒരു ശരീരത്തെ പിരടിയിൽ വഹിച്ച് വരുന്നതായിട്ട് അന്ത്യദിനത്തിൽ നിങ്ങളിലൊരാളെയും ഞാൻ കണ്ടുമുട്ടാതിരിക്കട്ടെ. അന്നേരം ഞാൻ പറയും: നിന്റെ കാര്യത്തിൽ എനിക്കൊന്നും ചെയ്യാൻ കഴിയുകയില്ല, നിശ്ചയം ഞാൻ നിനക്ക് എത്തിച്ചുതന്നിരിക്കുന്നു. അല്ലാഹുവിന്റെ റസൂലേ, എന്നെ സഹായിച്ചാലും എന്നു പറഞ്ഞുകൊണ്ട് ഇളകുന്ന വസ്ത്രം പിരടിയിൽ വെച്ചുകൊണ്ട് അന്ത്യദിനത്തിൽ നിങ്ങളിലൊരാളെയും ഞാൻ കണ്ടുമുട്ടാതിരക്കട്ടെ. അന്നേരം ഞാൻ പറയും: നിന്റെ കാര്യത്തിൽ എനിക്കൊന്നും ചെയ്യാൻ കഴിയുകയില്ല, നിശ്ചയം ഞാൻ നിനക്ക് എത്തിച്ചുതന്നിരിക്കുന്നു. അല്ലാഹുവിന്റെ റസൂലേ, എന്നെ സഹായിച്ചാലും എന്നു പറഞ്ഞുകൊണ്ട് സ്വർണ്ണവും വെള്ളിയും പിരടിയിൽ വെച്ചുകൊണ്ട് നിങ്ങളെ ഞാൻ അന്ത്യദിനത്തിൽ കണ്ടുമുട്ടാതിരിക്കട്ടെ. അന്നേരം ഞാൻ പറയും: നിന്റെ കാര്യത്തിൽ എനിക്കൊന്നും ചെയ്യാൻ കഴിയുകയില്ല, നിശ്ചയം ഞാൻ നിനക്ക് എത്തിച്ചുതന്നിരിക്കുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 78, 79, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَامَ فِينَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ الْغُلُولَ فَعَظَّمَهُ وَعَظَّمَ أَمْرَهُ، فَقَالَ: "لَا أُلْفِيَنَّ أَحَدَكُمْ يَوْمَ الْقِيَامَةِ عَلَى رَقَبَتِهِ شَاةٌ لَهَا ثُغَاءٌ، عَلَى رَقَبَتِهِ فَرَسٌ لَهُ حَمْحَمَةٌ، يَقُولُ: يَا رَسُولَ اللهِ أَغِثْنِي، فَأَقُولُ: لَا أَمْلِكُ لَكَ شَيْئًا قَدْ أَبْلَغْتُكَ، وَعَلَى رَقَبَتِهِ بَعِيرٌ لَهُ رُغَاءٌ، يَقُولُ: يَا رَسُولَ اللهِ أَغِثْنِي، فَأَقُولُ: لَا أَمْلِكُ لَكَ شَيْئًا قَدْ أَبْلَغْتُكَ، وَعَلَى رَقَبَتِهِ صَامِتٌ، فَيَقُولُ: يَا رَسُولَ اللهِ أَغِثْنِي، فَأَقُولُ: لَا أَمْلِكُ لَكَ شَيْئًا قَدْ أَبْلَغْتُكَ، أَوْ عَلَى رَقَبَتِهِ رِقَاعٌ تَخْفِقُ، فَيَقُولُ: يَا رَسُولَ اللهِ أَغِثْنِي، فَأَقُولُ: لَا أَمْلِكُ لَكَ شَيْئًا قَدْ أَبْلَغْتُكَ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) ഞങ്ങളുടെ മുമ്പിൽ എഴുന്നേറ്റ് നിന്ന് പ്രസംഗിച്ചപ്പോൾ വഞ്ചനയെക്കുറിച്ച് പറഞ്ഞു. അതിനെയും അതിന്റെ കാര്യങ്ങളെയും വളരെ ഗൗരവത്തിലെടുത്ത് സംസാരിക്കുകയും ചെയ്തു. എന്നിട്ട് അവിടന്ന് പറഞ്ഞു: "പുനരുത്ഥാന ദിവസം നിങ്ങളിലൊരാളും കരയുന്ന ഒരു ആടിനെ ചുമന്നുകൊണ്ടുവരുന്നതോ, (അല്ലെങ്കിൽ) പിരടിയിലൊരു കരയുന്ന കുതിരയുമായി വരുന്നതോ ഞാൻ കാണാതിരിക്കട്ടെ, എന്നിട്ടവൻ പറയും: അല്ലാഹുവിന്റെ റസൂലേ, എന്നെ സഹായിച്ചാലും. അപ്പോൾ ഞാൻ പറയും: നിന്റെ കാര്യത്തിൽ എനിക്കൊന്നും ചെയ്യാൻ കഴിയില്ല. നിനക്ക് ഞാൻ എത്തിച്ച് തന്നിരിക്കുന്നു. (അല്ലെങ്കിൽ) തന്റെ പിരടിയിലൊരു കരയുന്ന ഒട്ടകത്തെ വഹിച്ചുകൊണ്ടുവരുന്നതായും ഞാൻ കാണാതിരിക്കട്ടെ. എന്നിട്ട് അവൻ പറയും: അല്ലാഹുവിന്റെ റസൂലേ, എന്നെ സഹായിച്ചാലും. അപ്പോൾ ഞാൻ പറയും: നിന്റെ കാര്യത്തിൽ എനിക്ക് ഒന്നും ചെയ്യാൻ കഴിയില്ല. ഞാൻ നിനക്ക് എത്തിച്ചു തന്നിരിക്കുന്നു. ചുമലിൽ കുറച്ച് സ്വർണ്ണവുമായി വരുന്നവനെയും ഞാൻ കണ്ടുമുട്ടാതിരിക്കട്ടെ. എന്നിട്ട് അവൻ പറയും: അല്ലാഹുവിന്റെ റസൂലേ, എന്നെ സഹായിച്ചാലും. അപ്പോൾ ഞാൻ പറയും: നിന്റെ കാര്യത്തിൽ എനിക്ക് ഒന്നും ചെയ്യാൻ കഴിയില്ല. ഞാൻ നിനക്ക് എത്തിച്ചു തന്നിരിക്കുന്നു. തന്റെ ചുമലിൽ പാറിക്കളിച്ചുകൊണ്ടിരിക്കുന്ന വസ്ത്രവുമായി വരുന്നവനെയും ഞാൻ കാണാതിരിക്കട്ടെ. എന്നിട്ട് അവൻ പറയും: അല്ലാഹുവിന്റെ റസൂലേ, എന്നെ സഹായിച്ചാലും. അപ്പോൾ ഞാൻ പറയും: നിന്റെ കാര്യത്തിൽ എനിക്ക് ഒന്നും ചെയ്യാൻ കഴിയില്ല. ഞാൻ നിനക്ക് എത്തിച്ചു തന്നിരിക്കുന്നു." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 79, 80, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ عَبْدِاللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ عَلَى ثَقَلِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ يُقَالُ لَهُ كِرْكِرَةُ فَمَاتَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "هُوَ فِي النَّارِ". فَذَهَبُوا يَنْظُرُونَ إِلَيْهِ فَوَجَدُوا عَبَاءَةً قَدْ غَلَّهَا. (خ,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): തിരുമേനി(സ)യുടെ യാത്രാസാമഗ്രികൾ സൂക്ഷിക്കാനേൽപ്പിച്ചിരുന്നത് കിർകിറ എന്ന് പേരായ ഒരാളെയായിരുന്നു. അവൻ മരിച്ചപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവർ നരകത്തിലാണ്." അനുചരന്മാർ അയാളുടെ സ്ഥിതി അന്വേഷിക്കാൻ ചെന്നപ്പോൾ അയാൾ വഞ്ചിച്ചെടുത്ത ഒരു പുതപ്പ് അവർക്ക് കിട്ടി. (ബു,ജ)', 'عَبْدِاللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 80, 80, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَامَ خَيْبَرَ، فَلَمْ نَغْنَمْ ذَهَبًا وَلَا وَرِقًا إِلَّا الثِّيَابَ وَالْمَتَاعَ وَالْأَمْوَالَ، قَالَ: فَوَجَّهَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَحْوَ وَادِي الْقُرَى – وَقَدْ أُهْدِيَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَبْدٌ أَسْوَدُ يُقَالُ لَهُ مِدْعَمٌ – حَتَّى إِذَا كَانُوا بِوَادِي الْقُرَى، فَبَيْنَا مِدْعَمٌ يَحُطُّ رَحْلَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذْ جَاءَهُ سَهْمٌ فَقَتَلَهُ، فَقَالَ النَّاسُ: هَنِيئًا لَهُ الْجَنَّةُ. فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كَلَّا، وَالَّذِي نَفْسِي بِيَدِهِ، إِنَّ الشَّمْلَةَ الَّتِي أَخَذَهَا يَوْمَ خَيْبَرَ مِنَ الْمَغَانِمِ لَمْ تُصِبْهَا الْمَقَاسِمُ لَتَشْتَعِلُ عَلَيْهِ نَارًا". فَلَمَّا سَمِعُوا ذَلِكَ جَاءَ رَجُلٌ بِشِرَاكٍ أَوْ شِرَاكَيْنِ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "شِرَاكٌ مِنْ نَارٍ". أَوْ قَالَ: "شِرَاكَانِ مِنْ نَارٍ". (ق,د,ن)', 'അബൂഹുറൈറ(റ): ഖൈബറിന്റെ വർഷം ഞങ്ങൾ റസൂൽ(സ)യോട് കൂടെ പുറപ്പെട്ടു. വസ്ത്രങ്ങളും ചരക്കുകളും മറ്റു ധനവുമല്ലാതെ സ്വർണ്ണമോ വെള്ളിയോ ഞങ്ങൾക്ക് യുദ്ധമുതലായി ലഭിച്ചില്ല. നിവേദകൻ പറയുന്നു: അങ്ങനെ റസൂൽ(സ) വാദിൽഖുറായുടെ ഭാഗത്തേക്ക് തിരിഞ്ഞു. റസൂൽ(സ)ക്ക് മിദ്അം എന്ന് പേരായ ഒരു കറുത്ത അടിമ സമ്മാനമായി നൽകപ്പെട്ടിരുന്നു. അങ്ങനെ അവർ വാദിൽഖുറയിലെത്തി. മിദ്അം റസൂൽ(സ)യുടെ ഒട്ടകക്കട്ടിൽ ഇറക്കുന്നതിനിടയിൽ അദ്ദേഹത്തിന് അമ്പേൽക്കുകയും മരിക്കുകയും ചെയ്തു. അപ്പോൾ ജനങ്ങൾ പറഞ്ഞു: അദ്ദേഹത്തിന് സ്വർഗ്ഗം തന്നെ. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഒരിക്കലുമില്ല, എന്റെ ശരീരം ആരുടെ കയ്യിലാണോ അവൻ തന്നെയാണ് സത്യം. തീർച്ചയായും ഖൈബർ ദിവസം അദ്ദേഹം എടുത്ത വസ്ത്രം വിഹിതം വെക്കപ്പെടാത്തതാണ്. നിശ്ചയം അത് അവന്റെ മേൽ തീയായി ആളിക്കത്തുക തന്നെ ചെയ്യും." അവർ ഇത് കേട്ടപ്പോൾ ഒരാൾ ചെരുപ്പിന്റെ ഒരു വാറ്, അല്ലെങ്കിൽ രണ്ട് വാറ്, കൊണ്ട് റസൂൽ(സ)യുടെ സന്നിധിയിൽ വന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നരകത്തിലെ ഒരു വാറ്" അല്ലെങ്കിൽ പറഞ്ഞത്: "നരകത്തിലെ രണ്ട് വാറുകൾ." (ബു,മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 80, 80, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ مَاتَ وَهُوَ بَرِيءٌ مِنْ ثَلَاثٍ: الْكِبْرِ وَالْغُلُولِ وَالدَّيْنِ، دَخَلَ الْجَنَّةَ". (ت,جه)', 'സൗബാൻ(റ): റസൂൽ(സ) പറയുന്നു: "അഹങ്കാരം, വഞ്ചന, കടം ഈ മൂന്നെണ്ണത്തിൽ നിന്നും മുക്തനായിട്ട് ആരെങ്കിലും മരിച്ചാൽ അവൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിച്ചു." (തു,ജ)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 80, 81, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: حَدَّثَنِي عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: قِيلَ: يَا رَسُولَ اللهِ، إِنَّ فُلَانًا قَدِ اسْتُشْهِدَ. قَالَ: "كَلَّا، قَدْ رَأَيْتُهُ فِي النَّارِ بِعَبَاءَةٍ قَدْ غَلَّهَا". قَالَ: "قُمْ يَا عُمَرُ فَنَادِ: إِنَّهُ لَا يَدْخُلُ الْجَنَّةَ إِلَّا الْمُؤْمِنُونَ، ثَلَاثًا". (م,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): ഉമറുബ്നുൽ ഖത്താബ്(റ) എന്നോട് പറഞ്ഞു: റസൂൽ(സ)യോട് പറയപ്പെട്ടു: ഇന്നയാൾ രക്തസാക്ഷിയായിട്ടുണ്ട്. അവിടുന്ന് പറഞ്ഞു: "ഒരിക്കലും ഇല്ല, വഞ്ചിച്ചെടുത്ത വസ്ത്രവുമായി ഞാൻ അവനെ നരകത്തിൽ കണ്ടിട്ടുണ്ട്." നബി(സ) പറഞ്ഞു: "ഉമർ, എഴുന്നേറ്റ് നിന്ന് മൂന്ന് പ്രാവശ്യം വിളിച്ചു പറയുക: മുഅ്മിനുകളല്ലാതെ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുകയില്ല." (മു,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 81, 81, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: تُوُفِّيَ رَجُلٌ مِنْ أَشْجَعَ بِخَيْبَرَ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "صَلُّوا عَلَى صَاحِبِكُمْ". فَأَنْكَرَ النَّاسُ ذَلِكَ وَتَغَيَّرَتْ لَهُ وُجُوهُهُمْ، فَلَمَّا رَأَى ذَلِكَ قَالَ: "إِنَّ صَاحِبَكُمْ غَلَّ فِي سَبِيلِ اللهِ". قَالَ زَيْدٌ: فَالْتَمَسُوا فِي مَتَاعِهِ، فَإِذَا خَرَزَاتٌ مِنْ خَرَزِ يَهُودَ، مَا تُسَاوِي دِرْهَمَيْنِ. (د,ن,جه)', 'സൈദുബ്നു ഖാലിദുൽജുഹനി(റ): ഖൈബറിൽ വെച്ച് അശ്ജഅ് ഗോത്രത്തിലെ ഒരാൾ മരിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ സഹോദരന്റെ മേൽ നിങ്ങൾ നിസ്കരിക്കുക."⁵ അപ്പോൾ ജനങ്ങൾ അതിൽ അസന്തുഷ്ടരാവുകയും അവരുടെ മുഖങ്ങൾ വിവർണ്ണമാകുകയും ചെയ്തു. ഇത് കണ്ടപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ സഹോദരൻ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ (പോരാട്ട ഭൂമിയിൽ) വഞ്ചന നടത്തിയിരിക്കുന്നു." സൈദ്(റ) പറയുന്നു: അവർ അദ്ദേഹത്തിന്റെ ചരക്കുകൾ അന്വേഷിച്ചു. അപ്പോൾ അതിൽ രണ്ട് ദിർഹം പോലും വിലമതിക്കാത്ത, യഹൂദികളുടെ മുത്തുകളിൽ പെട്ട കുറച്ച് മുത്തുകളുണ്ടായിരുന്നു. (ദ,ന,ജ)', 'زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ', 'സൈദുബ്നു ഖാലിദുൽജുഹനി(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 81, 81, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ حُنَيْنٍ إِلَى جَنْبِ بَعِيرٍ مِنَ الْمَقَاسِمِ، ثُمَّ تَنَاوَلَ شَيْئًا مِنَ الْبَعِيرِ، فَأَخَذَ مِنْهُ قَرَدَةً، يَعْنِي وَبَرَةً، فَجَعَلَ بَيْنَ إِصْبَعَيْهِ، ثُمَّ قَالَ: "يَا أَيُّهَا النَّاسُ، إِنَّ هَذَا مِنْ غَنَائِمِكُمْ، أَدُّوا الْخَيْطَ وَالْمِخْيَطَ، فَمَا فَوْقَ ذَلِكَ فَمَا دُونَ ذَلِكَ، فَإِنَّ الْغُلُولَ عَارٌ عَلَى أَهْلِهِ يَوْمَ الْقِيَامَةِ وَشَنَارٌ وَنَارٌ". (جه)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): ഹുനൈൻ ദിവസം റസൂൽ(സ) യുദ്ധമുതലായി ലഭിച്ച ഒരു ഒട്ടകത്തിന്റെ അടുത്ത് വെച്ച് ഞങ്ങൾക്ക് ഇമാമായി, നിസ്കരിച്ചു. പിന്നെ ഒട്ടകത്തിൽ നിന്ന് എന്തോ എടുത്ത ശേഷം അതിൽനിന്ന് ഒരു രോമമെടുത്ത് അവിടുത്തെ രണ്ട് വിരലുകൾക്കിടയിൽ വെച്ചു, ശേഷം പറഞ്ഞു: "ഓ ജനങ്ങളേ, ഇത് നിങ്ങളുടെ യുദ്ധമുതലിൽ പെട്ടതാണ്, നിങ്ങൾ നൂലും സൂചിയും എത്തിക്കുക, അതിന് മുകളിലോ താഴെയോ ഉള്ളതും എത്തിക്കുക. കാരണം, വഞ്ചന അന്ത്യനാളിൽ അത് ചെയ്തവർക്ക് അപമാനവും കുറ്റവും തീയുമാണ്." (ജ)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', '⁵. കപട വിശ്വാസികൾ, കടമുള്ളവർ, യുദ്ധമുതലിൽ വഞ്ചന നടത്തിയവർ തുടങ്ങിയവരുടെ മേൽ റസൂൽ(സ) മയ്യിത്ത് നമസ്കരിക്കാറുണ്ടായിരുന്നില്ല. ഞാൻ നമസ്കരിക്കുന്നില്ല, നിങ്ങൾ നമസ്കരിക്കുക എന്നാണിവിടെ തിരുമേനി(സ) പറയുന്നത്.', null, array['جه']::text[], array['ജ']::text[], null, null, 81, 81, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أَصَابَ غَنِيمَةً أَمَرَ بِلَالًا فَنَادَى فِي النَّاسِ فَيَجِيئُونَ بِغَنَائِمِهِمْ، فَيُخَمِّسُهُ وَيُقَسِّمُهُ، فَجَاءَ رَجُلٌ بَعْدَ ذَلِكَ بِزِمَامٍ مِنْ شَعَرٍ فَقَالَ: يَا رَسُولَ اللهِ، هَذَا فِيمَا كُنَّا أَصَبْنَاهُ مِنَ الْغَنِيمَةِ. فَقَالَ: "أَسَمِعْتَ بِلَالًا يُنَادِي؟" ثَلَاثًا، قَالَ: نَعَمْ، قَالَ: "فَمَا مَنَعَكَ أَنْ تَجِيءَ بِهِ؟". فَاعْتَذَرَ إِلَيْهِ، فَقَالَ: "كُنْ أَنْتَ تَجِيءُ بِهِ يَوْمَ الْقِيَامَةِ، فَلَنْ أَقْبَلَهُ عَنْكَ". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): യുദ്ധമുതൽ ലഭിച്ചാൽ (അവ കൊണ്ടുവരണമെന്ന്) ജനങ്ങളോട് വിളിച്ചുപറയാൻ റസൂൽ(സ) ബിലാൽ(റ)വിനോട് കൽപിക്കുമായിരുന്നു. അപ്പോൾ ജനങ്ങൾ അവരുടെ യുദ്ധമുതലുകൾ കൊണ്ടുവരികയും റസൂൽ(സ) അതിൽനിന്ന് അഞ്ചിലൊന്ന് മാറ്റിവെക്കുകയും (ബാക്കിയുള്ളത്) വീതിച്ചു നൽകുകയും ചെയ്യുമായിരുന്നു. ഒരിക്കൽ അതിനുശേഷം ഒരാൾ മുടിയാലുള്ള ഒരു കടിഞ്ഞാണുമായി വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഇത് ഞങ്ങൾക്ക് ലഭിച്ച യുദ്ധമുതലിൽ പെട്ടതാണ്. തിരുമേനി(സ) ചോദിച്ചു: "ബിലാൽ വിളിച്ചുപറഞ്ഞത് നീ കേട്ടിരുന്നോ?" മൂന്നു പ്രാവശ്യം അവിടുന്ന് അപ്രകാരം ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: അതെ. റസൂൽ(സ) ചോദിച്ചു: "പിന്നെ എന്ത് കാരണത്താൽ നീ അത് കൊണ്ടുവന്നില്ല." അദ്ദേഹം നബി(സ)യോട് കാരണം ബോധിപ്പിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ തന്നെ അതുമായി അന്ത്യനാളിൽ വരിക, ഞാൻ അത് ഒരിക്കലും സ്വീകരിക്കുകയില്ല." (ദ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 81, 82, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ صَالِحِ بْنِ مُحَمَّدِ بْنِ زَائِدَةَ قَالَ: دَخَلْتُ مَعَ مَسْلَمَةَ أَرْضَ الرُّومِ فَأُتِيَ بِرَجُلٍ قَدْ غَلَّ، فَسَأَلَ سَالِمًا عَنْهُ، فَقَالَ: سَمِعْتُ أَبِي يُحَدِّثُ عَنْ عُمَرَ بْنِ الْخَطَّابِ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا وَجَدْتُمُ الرَّجُلَ قَدْ غَلَّ فَأَحْرِقُوا مَتَاعَهُ وَاضْرِبُوهُ". قَالَ: فَوَجَدْنَا فِي مَتَاعِهِ مُصْحَفًا، فَسَأَلَ سَالِمًا عَنْهُ، فَقَالَ: بِعْهُ وَتَصَدَّقْ بِثَمَنِهِ. (د,ت)', 'സ്വാലിഹുബ്നു മുഹമ്മദുബ്നു സാഇദ(റ): റോമിന്റെ പ്രദേശത്തേക്ക് മസ്ലമ(റ)വിന്റെ കൂടെ ഞാൻ കടന്നപ്പോൾ വഞ്ചന ചെയ്ത ഒരാളെ കൊണ്ടുവരപ്പെട്ടു. അദ്ദേഹം സാലിം(റ)വിനോട് അതിനെക്കുറിച്ച് ചോദിച്ചു: അദ്ദേഹം പറഞ്ഞു: എന്റെ പിതാവ് ഉമറുബ്നുൽ ഖത്താബ്(റ)വിൽ നിന്ന് ഇപ്രകാരം ഹദീസ് പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: നബി(സ) പറയുന്നു: "വഞ്ചന നടത്തിയവനെ കിട്ടിയാൽ അവന്റെ ചരക്കുകൾ കത്തിക്കുകയും അവനെ അടിക്കുകയും ചെയ്യുക." നിവേദകൻ പറയുന്നു: അദ്ദേഹത്തിന്റെ ചരക്കുകളിൽ നിന്ന് ഞങ്ങൾക്ക് ഒരു മുസ്ഹഫ് കിട്ടി. അദ്ദേഹം അതിനെക്കുറിച്ച് സാലിം(റ)വിനോട് ചോദിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നീയത് വിൽക്കുകയും അതിന്റെ വില ദാനംചെയ്യുകയും ചെയ്യുക. (ദ,തു)', 'صَالِحِ بْنِ مُحَمَّدِ بْنِ زَائِدَةَ قَالَ', 'സ്വാലിഹുബ്നു മുഹമ്മദുബ്നു സാഇദ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 82, 82, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ صَالِحِ بْنِ مُحَمَّدٍ قَالَ: غَزَوْنَا مَعَ الْوَلِيدِ بْنِ هِشَامٍ وَمَعَنَا سَالِمُ بْنُ عَبْدِ اللهِ بْنِ عُمَرَ وَعُمَرُ بْنُ عَبْدِ الْعَزِيزِ، فَغَلَّ رَجُلٌ مَتَاعًا، فَأَمَرَ الْوَلِيدُ بِمَتَاعِهِ فَأُحْرِقَ، وَطِيفَ بِهِ، وَلَمْ يُعْطِهِ سَهْمَهُ. (د)', 'സ്വാലിഹുബ്നു മുഹമ്മദ്(റ): വലീദുബ്നു ഹിശാമിന്റെ കൂടെ ഞങ്ങൾ യുദ്ധം ചെയ്തു. ഞങ്ങളുടെ കൂടെ സാലിമുബിൻ അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)വും ഉമറുബ്നു അബ്ദുൽ അസീസ്(റ)വും ഉണ്ടായിരുന്നു. അപ്പോൾ ഒരാൾ ചരക്ക് വഞ്ചിച്ചെടുത്തു. അങ്ങനെ വലീദ് അവന്റെ ചരക്ക് കൊണ്ടുവരാൻ കൽപിക്കുകയും അത് കരിക്കുകയും അവന് ചുറ്റും ജനങ്ങൾ കൂടിനിൽക്കുകയും ചെയ്തു. അവന് അവന്റെ വിഹിതം (യുദ്ധമുതലിൽ നിന്നുള്ളത്) കൊടുക്കുകയും ചെയ്തില്ല. (ദ)', 'صَالِحِ بْنِ مُحَمَّدٍ قَالَ', 'സ്വാലിഹുബ്നു മുഹമ്മദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 82, 82, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبَا بَكْرٍ وَعُمَرَ حَرَّقُوا مَتَاعَ الْغَالِّ وَضَرَبُوهُ. وَفِي رِوَايَةٍ: وَمَنَعُوهُ سَهْمَهُ. (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ)യും അബൂബക്ർ(റ)വും ഉമർ(റ)വും വഞ്ചന നടത്തിയവന്റെ ചരക്കുകൾ കരിക്കുകയും അവനെ അടിക്കുകയും ചെയ്തു. മറ്റൊരു നിവേദനത്തിൽ: അവന്റെ വിഹിതം അവർ തടഞ്ഞുവെച്ചു. (ദ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 82, 82, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=122), 1, 'وَفِي رِوَايَةٍ: وَمَنَعُوهُ سَهْمَهُ. (د)', 'മറ്റൊരു നിവേദനത്തിൽ: അവന്റെ വിഹിതം അവർ തടഞ്ഞുവെച്ചു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَّا بَعْدُ، وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ كَتَمَ غَالًّا فَإِنَّهُ مِثْلُهُ". (د)', 'സമുറതുബ്നു ജുൻദുബ്(റ): ആമുഖത്തിനു ശേഷം, റസൂൽ(സ) പറയാറുണ്ടായിരുന്നു: "ആരെങ്കിലും വഞ്ചന നടത്തിയവനെ മറച്ചുവെച്ചാൽ അവനും അത് പോലെത്തന്നെയാണ് (വഞ്ചന നടത്തിയവനെ പോലെത്തന്നെയാണ്)." (ദ)', 'سَمُرَةَ بْنِ جُنْدُبٍ', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 83, 83, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ أَبِي مَرْيَمَ الْأَزْدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلْتُ عَلَى مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ فَقَالَ: مَا أَنْعَمَنَا بِكَ أَبَا فُلَانٍ. وَهِيَ كَلِمَةٌ تَقُولُهَا الْعَرَبُ، فَقُلْتُ: حَدِيثًا سَمِعْتُهُ أُخْبِرُكَ بِهِ، سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ وَلَّاهُ اللهُ عَزَّ وَجَلَّ شَيْئًا مِنْ أَمْرِ الْمُسْلِمِينَ، فَاحْتَجَبَ دُونَ حَاجَتِهِمْ وَخَلَّتِهِمْ وَفَقْرِهِمْ، احْتَجَبَ اللهُ عَنْهُ دُونَ حَاجَتِهِ وَخَلَّتِهِ وَفَقْرِهِ". قَالَ: فَجَعَلَ رَجُلًا عَلَى حَوَائِجِ النَّاسِ. (د,ت)', 'അബൂമർയമിൽ അസ്ദീ(റ): ഞാൻ മുആവിയ(റ)വിനെ സമീപിച്ചു. അപ്പോൾ മുആവിയ(റ) പറഞ്ഞു: ഹോ! താങ്കളെക്കൊണ്ട് (സന്ദർശനം) നമുക്ക് എന്തു ഗുണമായെന്നോ, ഇന്നയാളുടെ പിതാവേ. അറബികൾ പറയാറുള്ള വാക്യമാണിത്. അപ്പോൾ ഞാൻ പറഞ്ഞു: ഞാൻ കേട്ട ഒരു ഹദീസ് താങ്കൾക്ക് പറഞ്ഞുതരാം. റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "മുസ്ലിംകളുടെ വല്ല കാര്യങ്ങളും അല്ലാഹു ആരെയെങ്കിലും ഏൽപിച്ചിട്ട്, അവരുടെ ആവശ്യങ്ങളിൽ നിന്നും മറ്റു കാര്യങ്ങളിൽ നിന്നും ദാരിദ്ര്യത്തിൽ നിന്നും അവൻ മുഖം തിരിച്ചാൽ അവന്റെ ആവശ്യങ്ങളോടും കാര്യങ്ങളോടും ദാരിദ്ര്യങ്ങളോടും അല്ലാഹുവും മുഖം തിരിക്കും." അദ്ദേഹം പറയുന്നു: ശേഷം, മുസ്ലിംകളുടെ ആവശ്യങ്ങൾ നിറവേറ്റാൻ മുആവിയ(റ) ഒരാളെ ചുമതലപ്പെടുത്തി. (ദ,തു)', 'أَبِي مَرْيَمَ الْأَزْدِيِّ', 'അബൂമർയമിൽ അസ്ദീ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 83, 83, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا أُوتِيكُمْ مِنْ شَيْءٍ وَمَا أَمْنَعُكُمُوهُ، إِنْ أَنَا إِلَّا خَازِنٌ أَضَعُ حَيْثُ أُمِرْتُ". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ നിങ്ങൾക്ക് ഒന്നും തന്നെ കൊണ്ടുവരികയോ തടയുകയോ ചെയ്യുന്നില്ല. ഞാനൊരു സൂക്ഷിപ്പുകാരൻ മാത്രമാണ്. എന്നോട് കൽപിക്കപ്പെടുന്നതിനനുസരിച്ച് ഞാൻ ചെയ്യുന്നു." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 83, 83, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ مَالِكِ بْنِ أَوْسِ بْنِ الْحَدَثَانِ رَضِيَ اللهُ عَنْهُ قَالَ: ذَكَرَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ يَوْمًا الْفَيْءَ فَقَالَ: مَا أَنَا بِأَحَقَّ بِهَذَا الْفَيْءِ مِنْكُمْ، وَمَا أَحَدٌ مِنَّا بِأَحَقَّ بِهِ مِنْ أَحَدٍ، إِلَّا أَنَّا عَلَى مَنَازِلِنَا مِنْ كِتَابِ اللهِ عَزَّ وَجَلَّ، وَقَسْمِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: فَالرَّجُلُ وَقِدَمُهُ، وَالرَّجُلُ وَبَلَاؤُهُ، وَالرَّجُلُ وَعِيَالُهُ، وَالرَّجُلُ وَحَاجَتُهُ. (د)', 'മാലികുബ്നു ഔസിബ്നിൽ ഹദസാൻ(റ): ഒരു ദിവസം ''ഫൈഇ''നെക്കുറിച്ച് (യുദ്ധം ചെയ്യാതെ ലഭിക്കുന്ന യുദ്ധമുതൽ) ഉമർ(റ) പറഞ്ഞു: ഈ യുദ്ധമുതലിന് ഞാൻ നിങ്ങളേക്കാൾ അർഹനല്ല. നമ്മിലൊരാളും മറ്റൊരാളേക്കാൾ അതിനർഹനല്ല. ഉന്നതനായ അല്ലാഹുവിന്റെ കിതാബിലും റസൂൽ(സ)യുടെ വിഹിതംവെക്കലിലും നിശ്ചയിക്കപ്പെട്ട നമുക്കിടയിലെ സ്ഥാനങ്ങളിൽ നാം നിൽക്കുന്നുവെന്ന് മാത്രം: ഒരാളുടെ ഇസ്ലാമിലുള്ള പഴക്കം, ഒരാളുടെ ആപത്തുകൾ, ഒരാളുടെ കുടുംബം, ഒരാളുടെ ആവശ്യങ്ങൾ (എന്നിവയാണവ). (ദ)', 'مَالِكِ بْنِ أَوْسِ بْنِ الْحَدَثَانِ', 'മാലികുബ്നു ഔസിബ്നിൽ ഹദസാൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 83, 83, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَنَا أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ، مَنْ تَرَكَ مَالًا فَلِأَهْلِهِ، وَمَنْ تَرَكَ دَيْنًا أَوْ ضَيَاعًا فَإِلَيَّ وَعَلَيَّ". (م,د,ن,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറയാറുണ്ടായിരുന്നു: "വിശ്വാസികളോട്, അവരുടെ ശരീരങ്ങളേക്കാൾ കൂടുതൽ ഞാൻ ബന്ധപ്പെട്ടിരിക്കുന്നു. ആരെങ്കിലും സമ്പത്ത് ഉപേക്ഷിച്ചിട്ടാൽ അതവന്റെ കുടുംബത്തിനാണ്. ആരെങ്കിലും കടമോ നിരാലംബരെയോ ഉപേക്ഷിച്ചാൽ അതെന്നിലേക്കും എന്റെ ഉത്തരവാദിത്തത്തിലുമായിരിക്കും." (മു,ദ,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 84, 84, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَرَكَ مَالًا فَلِوَرَثَتِهِ، وَمَنْ تَرَكَ كَلًّا فَإِلَيْنَا". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും സമ്പത്ത് ഉപേക്ഷിച്ചാൽ അതവന്റെ അനന്തരാവകാശികൾക്കാണ്. ആരെങ്കിലും നിരാലംബരെ ഉപേക്ഷിച്ചാൽ അത് എന്നിലേക്കാണ് (ഉത്തരവാദിത്തം)." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 84, 84, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "أَنَا أَوْلَى بِكُلِّ مُؤْمِنٍ مِنْ نَفْسِهِ، فَأَيُّمَا رَجُلٍ مَاتَ وَتَرَكَ دَيْنًا فَإِلَيَّ، وَمَنْ تَرَكَ مَالًا فَلِوَرَثَتِهِ". (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) പറയാറുണ്ടായിരുന്നു: "എല്ലാ വിശ്വാസികളോടും അവരുടെ ശരീരത്തേക്കാൾ ഞാനാണ് ഏറ്റവുമടുത്തവൻ. അതിനാൽ, ഏതെങ്കിലുമൊരാൾ കടം ബാക്കിയാക്കി മരണപ്പെട്ടാൽ ആ കടം എനിക്കാണ്. ആരെങ്കിലും സ്വത്ത് ഉപേക്ഷിച്ചാൽ അത് അവന്റെ അനന്തരാവകാശികൾക്ക് ഉള്ളതാണ്." (ദ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 84, 84, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ مُطَيْرٍ: أَنَّهُ خَرَجَ حَاجًّا، حَتَّى إِذَا كَانَ بِالسُّوَيْدَاءِ، قَالَ: إِذَا بِرَجُلٍ قَدْ جَاءَ كَأَنَّهُ يَطْلُبُ دَوَاءً وَحُضُضًا، فَقَالَ: أَخْبَرَنِي مَنْ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي حَجَّةِ الْوَدَاعِ، وَهُوَ يَعِظُ النَّاسَ وَيَأْمُرُهُمْ وَيَنْهَاهُمْ، فَقَالَ: "يَا أَيُّهَا النَّاسُ خُذُوا الْعَطَاءَ مَا كَانَ عَطَاءً، فَإِذَا تَجَاحَفَتْ قُرَيْشٌ عَلَى الْمُلْكِ، وَكَانَ عَنْ دِينِ أَحَدِكُمْ، فَدَعُوهُ". وَفِي رِوَايَةٍ قَالَ: سَمِعْتُ رَجُلًا يَقُولُ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي حَجَّةِ الْوَدَاعِ، فَأَمَرَ النَّاسَ وَنَهَاهُمْ، ثُمَّ قَالَ: "اللَّهُمَّ هَلْ بَلَّغْتُ". قَالُوا: اللَّهُمَّ نَعَمْ، ثُمَّ قَالَ: "إِذَا تَجَاحَفَتْ قُرَيْشٌ عَلَى الْمُلْكِ فِيمَا بَيْنَهَا وَعَادَ الْعَطَاءُ – أَوْ كَانَ – رُشًا فَدَعُوهُ". فَقِيلَ: مَنْ هَذَا؟ قَالُوا: هَذَا ذُو الزَّوَائِدِ، صَاحِبُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د)', 'മുതൈ്വർ: അദ്ദേഹം ഹജ്ജിന് പുറപ്പെട്ടു. അങ്ങനെ സുവൈദാഅ് എന്ന സ്ഥലത്തെത്തി. അദ്ദേഹം പറയുന്നു: പെട്ടെന്ന് ഒരാൾ വന്നു. അയാൾ മരുന്നും, ഒരു മരത്തിന്റെ (കുരുമുളക് പോലുള്ള വിളയുള്ള ഒരു മരം) നീരും തേടിവന്നതായിരുന്നു. അയാൾ പറഞ്ഞു: ഹജ്ജത്തുൽ വിദാഇന്റെ ദിവസം റസൂൽ(സ) ജനങ്ങളോട് പ്രസംഗിക്കുന്നതും അവരോട് കൽപിക്കുന്നതും നിരോധിക്കുന്നതും കേട്ട ഒരാൾ എന്നോട് പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങളേ, ദാനങ്ങൾ ദാനങ്ങളായിരിക്കുന്ന കാലത്തോളം നിങ്ങൾ സ്വീകരിക്കുക. എന്നാൽ, ഖുറൈശികൾ അധികാരത്തിന് വേണ്ടി തർക്കിക്കുന്ന കാലത്ത്, നിങ്ങളിലൊരാളുടെ ദീനിന് പകരമായി ദാനം നൽകപ്പെടുന്ന അവസരത്തിൽ, നിങ്ങളവ വർജിക്കുക." മറ്റൊരു നിവേദനത്തിൽ: ഒരാൾ പറയുന്നത് ഞാൻ കേട്ടു: ഹജ്ജത്തുൽ വിദാഇൽ റസൂൽ(സ) ജനങ്ങളെ കൽപിക്കുന്നതും വിലക്കുന്നതും ഞാൻ കേട്ടു. ശേഷം അവിടുന്ന് പറഞ്ഞു: "അല്ലാഹുവേ, ഞാനെത്തിച്ചില്ലെയോ." ജനങ്ങൾ പറഞ്ഞു: അല്ലാഹുവാണ, അതെ. ശേഷം റസൂൽ(സ) പറഞ്ഞു: "ഖുറൈശികൾ പരസ്പരം അധികാരത്തിനുവേണ്ടി തർക്കിക്കുമ്പോൾ, ദാനങ്ങൾ കൈക്കൂലിയായി മാറുന്ന അവസരത്തിൽ അവ നിങ്ങളുപേക്ഷിക്കുക." അപ്പോൾ ചോദിക്കപ്പെട്ടു: ആരാണിത് (റിപ്പോർട്ട് ചെയ്തത്)? അവർ പറഞ്ഞു: ''ദൂ സവാഇദ്'' എന്ന റസൂൽ(സ)യുടെ അനുചരൻ. (ദ)', 'مُطَيْرٍ', 'മുതൈ്വർ', null, null, array['د']::text[], array['ദ']::text[], null, null, 84, 85, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=130), 1, 'وَفِي رِوَايَةٍ قَالَ: سَمِعْتُ رَجُلًا يَقُولُ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي حَجَّةِ الْوَدَاعِ، فَأَمَرَ النَّاسَ وَنَهَاهُمْ، ثُمَّ قَالَ: "اللَّهُمَّ هَلْ بَلَّغْتُ". قَالُوا: اللَّهُمَّ نَعَمْ، ثُمَّ قَالَ: "إِذَا تَجَاحَفَتْ قُرَيْشٌ عَلَى الْمُلْكِ فِيمَا بَيْنَهَا وَعَادَ الْعَطَاءُ – أَوْ كَانَ – رُشًا فَدَعُوهُ". فَقِيلَ: مَنْ هَذَا؟ قَالُوا: هَذَا ذُو الزَّوَائِدِ، صَاحِبُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د)', 'മറ്റൊരു നിവേദനത്തിൽ: ഒരാൾ പറയുന്നത് ഞാൻ കേട്ടു: ഹജ്ജത്തുൽ വിദാഇൽ റസൂൽ(സ) ജനങ്ങളെ കൽപിക്കുന്നതും വിലക്കുന്നതും ഞാൻ കേട്ടു. ശേഷം അവിടുന്ന് പറഞ്ഞു: "അല്ലാഹുവേ, ഞാനെത്തിച്ചില്ലെയോ." ജനങ്ങൾ പറഞ്ഞു: അല്ലാഹുവാണ, അതെ. ശേഷം റസൂൽ(സ) പറഞ്ഞു: "ഖുറൈശികൾ പരസ്പരം അധികാരത്തിനുവേണ്ടി തർക്കിക്കുമ്പോൾ, ദാനങ്ങൾ കൈക്കൂലിയായി മാറുന്ന അവസരത്തിൽ അവ നിങ്ങളുപേക്ഷിക്കുക." അപ്പോൾ ചോദിക്കപ്പെട്ടു: ആരാണിത് (റിപ്പോർട്ട് ചെയ്തത്)? അവർ പറഞ്ഞു: ''ദൂ സവാഇദ്'' എന്ന റസൂൽ(സ)യുടെ അനുചരൻ. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ عَبْدِ اللهِ بْنِ كَعْبِ بْنِ مَالِكٍ الْأَنْصَارِيِّ: أَنَّ جَيْشًا مِنَ الْأَنْصَارِ كَانُوا بِأَرْضِ فَارِسَ مَعَ أَمِيرِهِمْ، وَكَانَ عُمَرُ يُعَقِّبُ الْجُيُوشَ فِي كُلِّ عَامٍ، فَشُغِلَ عَنْهُمْ عُمَرُ، فَلَمَّا مَرَّ الْأَجَلُ قَفَلَ أَهْلُ ذَلِكَ الثَّغْرِ، فَاشْتَدَّ عَلَيْهِمْ وَتَوَاعَدَهُمْ وَهُمْ أَصْحَابُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: يَا عُمَرُ، إِنَّكَ غَفَلْتَ عَنَّا، وَتَرَكْتَ فِينَا الَّذِي أَمَرَ بِهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ إِعْقَابِ بَعْضِ الْغَزِيَّةِ بَعْضًا. (د)', 'അബ്ദുല്ലാഹിബ്നു കഅ്ബുബ്നു മാലികിൽ അൻസാരി(റ): അൻസാറുകളുടെ ഒരു സൈന്യം അവരുടെ നേതാവിനോടൊപ്പം ഒരു പേർഷ്യൻ പ്രദേശത്തായിരുന്നു. ഉമർ(റ) ഓരോ വർഷവും സൈന്യാംഗങ്ങളെ മാറ്റാറുണ്ടായിരുന്നു. എന്നാൽ, ഉമർ(റ) ഇവരുടെ കാര്യത്തിൽ അശ്രദ്ധനായി. അങ്ങനെ കാലാവധി തീർന്നപ്പോൾ സൈന്യം അതിർത്തി പ്രദേശത്തുനിന്ന് മടങ്ങി. അവർ റസൂൽ(സ)യുടെ അനുചരരായിരുന്നിട്ടും ഉമർ(റ) അവർക്കെതിരെ ശക്തമായ നടപടിയെടുക്കുകയും ഭീഷണിപ്പെടുത്തുകയും ചെയ്തു. അന്നേരം അവർ പറഞ്ഞു: ഉമറേ, താങ്കൾ ഞങ്ങളുടെ കാര്യത്തിൽ അശ്രദ്ധനായി. യോദ്ധാക്കളെ പരസ്പരം മാറ്റുക യെന്ന, റസൂൽ(സ) കൽപിച്ച കാര്യം ഞങ്ങളിൽ താങ്കൾ നടപ്പാക്കിയില്ല. (ദ)', 'عَبْدِ اللهِ بْنِ كَعْبِ بْنِ مَالِكٍ الْأَنْصَارِيِّ', 'അബ്ദുല്ലാഹിബ്നു കഅ്ബുബ്നു മാലികിൽ അൻസാരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 85, 85, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ رَضِيَ اللهُ عَنْهُ كَتَبَ: إِنَّ مَنْ سَأَلَ عَنْ مَوَاضِعِ الْفَيْءِ فَهُوَ مَا حَكَمَ فِيهِ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ، فَرَآهُ الْمُؤْمِنُونَ عَدْلًا، مُوَافِقًا لِقَوْلِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "جَعَلَ اللهُ الْحَقَّ عَلَى لِسَانِ عُمَرَ وَقَلْبِهِ". فَرَضَ الْأَعْطِيَةَ لِلْمُسْلِمِينَ، وَعَقَدَ لِأَهْلِ الْأَدْيَانِ ذِمَّةً بِمَا فَرَضَ عَلَيْهِمْ مِنَ الْجِزْيَةِ، لَمْ يَضْرِبْ فِيهَا بِخُمُسٍ وَلَا مَغْنَمٍ. (د)', 'ഉമറുബ്നു അബ്ദിൽ അസീസ്(റ) എഴുതി: ഫൈഅ് നൽകേണ്ട അവകാശികളെക്കുറിച്ച് ആരെങ്കിലും ചോദിച്ചാൽ, ഉമറുബ്നുൽ ഖത്താബ്(റ) അതിൽ വിധിച്ചത് അവലംബിക്കുക. നബി(സ)യുടെ ഈ വാക്ക് കണക്കിലെടുത്തുകൊണ്ട്, വിശ്വാസികൾ അദ്ദേഹത്തെ നീതിമാനാണെന്ന് മനസ്സിലാക്കുകയും ചെയ്തിട്ടുണ്ട്: "ഉമറിന്റെ ഹൃദയത്തിലും നാവിലും അല്ലാഹു സത്യത്തെ സ്ഥാപിച്ചിരിക്കുന്നു." മുസ്‌ലിംകൾക്കദ്ദേഹം വേതനം നിർബന്ധമാക്കി. മറ്റു മതസ്ഥർക്ക്, ജിസ്‌യ നിർബന്ധമാക്കി സംരക്ഷണം നൽകി. അത് അഞ്ചിലൊന്നായിട്ടും ഗനീമത്തായിട്ടും വിഹിതം വെച്ചിട്ടില്ല. (ദ)', 'عُمَرَ بْنِ عَبْدِ الْعَزِيزِ', 'ഉമറുബ്നു അബ്ദിൽ അസീസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 85, 85, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ اللهَ وَضَعَ الْحَقَّ عَلَى لِسَانِ عُمَرَ يَقُولُ بِهِ". (د,جه)', 'അബൂദർറ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഉമർ സംസാരിക്കുന്ന നാവിന്മേൽ അല്ലാഹു സത്യത്തെ സ്ഥാപിച്ചിട്ടുണ്ട്." (ദ,ജ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 85, 85, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنِ الزُّهْرِيِّ قَالَ: قَالَ عُمَرُ رَضِيَ اللهُ عَنْهُ: {وَمَا أَفَاءَ اللهُ عَلَى رَسُولِهِ مِنْهُمْ فَمَا أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ} [الحشر: ٦] قَالَ عُمَرُ: هَذِهِ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَاصَّةً، قُرَى عُرَيْنَةَ، فَدَكَ، وَكَذَا، وَكَذَا: {مَا أَفَاءَ اللهُ عَلَى رَسُولِهِ مِنْ أَهْلِ الْقُرَى فَلِلَّهِ وَلِلرَّسُولِ وَلِذِي الْقُرْبَى وَالْيَتَامَى وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ} [الحشر: ٧] وَ: {لِلْفُقَرَاءِ الَّذِينَ أُخْرِجُوا مِنْ دِيَارِهِمْ وَأَمْوَالِهِمْ} [الحشر: ٨] وَ: {وَالَّذِينَ تَبَوَّءُوا الدَّارَ وَالْإِيمَانَ مِنْ قَبْلِهِمْ} [الحشر: ٩]. {وَالَّذِينَ جَاءُوا مِنْ بَعْدِهِمْ} [الحشر: ١٠] فَاسْتَوْعَبَتْ هَذِهِ الْآيَةُ النَّاسَ، فَلَمْ يَبْقَ أَحَدٌ مِنَ الْمُسْلِمِينَ إِلَّا لَهُ فِيهَا حَقٌّ – وَفِي رِوَايَةٍ: حَظٌّ – إِلَّا بَعْضَ مَنْ تَمْلِكُونَ مِنْ أَرِقَّائِكُمْ. (د)', 'സുഹ്‌രി: ഉമർ(റ) പറഞ്ഞു: ''അവരിൽ നിന്ന് (യഹൂദികൾ) അല്ലാഹു തന്റെ ദൂതർക്ക് ഉടമപ്പെടുത്തിക്കൊടുത്തത് (ഫൈഅ്), കുതിരയെയോ ഒട്ടകങ്ങളെയോ അതിന്റെ മേൽ നിങ്ങൾ ഓടിച്ചിരുന്നില്ല.'' (ഹശ്‌ർ: 6). ഉമർ(റ) പറയുന്നു: ഇത് റസൂൽ(സ)ക്ക് പ്രത്യേകമായുള്ളതാണ്. ഉറൈനയുടെ ഗ്രാമങ്ങളും ഫദകും അതുപോലെയുള്ളവയും. ''അല്ലാഹു അവന്റെ റസൂലിന്, വ്യത്യസ്ത പ്രവിശ്യക്കാരിൽനിന്ന് കൈവരുത്തിക്കൊടുത്തതെന്തോ അത് അല്ലാഹുവിനും അവന്റെ റസൂലിനും അടുത്ത കുടംബങ്ങൾക്കും അനാഥകൾക്കും അഗതികൾക്കും യാത്രക്കാർക്കുമുള്ളതാണ്.'' (ഹശ്‌ർ: 7) ''സ്വന്തം വീടുകളിൽ നിന്നും സ്വത്തുക്കളിൽ നിന്നും കുടിയൊഴിപ്പിക്കപ്പെട്ട ദരിദ്രർക്കും (ഉള്ളതാണ്)'' (ഹശ്‌ർ: 8). ''അവരുടെ (മുഹാജിറുകളുടെ) വരവിന് മുമ്പായി വാസസ്ഥലവും വിശ്വാസവും ഒരുക്കിവെച്ചവർക്കും (അൻസാറുകൾക്ക്)'' (ഹശ്‌ർ: 9) ''അവരുടെ ശേഷം വന്നവർക്കും.'' (ഹശ്‌ർ: 10) ഈ സൂക്തം ജനങ്ങളെ മുഴുവനും പൂർണമായും ഉൾപെടുത്തിയിരിക്കുന്നു. മുസ്‌ലിംകളിലൊരാളും ഇതിൽ അവകാശം - മറ്റൊരു നിവേദനം: വിഹിതം - ഇല്ലാതെ അവശേഷിച്ചിട്ടില്ല, നിങ്ങളുടെ ഉടമസ്ഥതയിലുള്ള അടിമകളിൽ ചിലരൊഴികെ. (ദ)', 'الزُّهْرِيِّ قَالَ', 'സുഹ്‌രി', null, null, array['د']::text[], array['ദ']::text[], 'الحشر: ١٠', null, 86, 86, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=134), 1, 'وَفِي رِوَايَةٍ: حَظٌّ – إِلَّا بَعْضَ مَنْ تَمْلِكُونَ مِنْ أَرِقَّائِكُمْ. (د)', 'മറ്റൊരു നിവേദനം: വിഹിതം - ഇല്ലാതെ അവശേഷിച്ചിട്ടില്ല, നിങ്ങളുടെ ഉടമസ്ഥതയിലുള്ള അടിമകളിൽ ചിലരൊഴികെ. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ مَالِكِ بْنِ أَوْسِ بْنِ الْحَدَثَانِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ فِيمَا احْتَجَّ بِهِ عُمَرُ – رَضِيَ اللهُ عَنْهُ – أَنَّهُ قَالَ: كَانَتْ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثَلَاثُ صَفَايَا: بَنُو النَّضِيرِ، وَخَيْبَرُ، وَفَدَكُ. فَأَمَّا بَنُو النَّضِيرِ: فَكَانَتْ حُبُسًا لِنَوَائِبِهِ، وَأَمَّا فَدَكُ فَكَانَتْ حُبُسًا لِأَبْنَاءِ السَّبِيلِ، وَأَمَّا خَيْبَرُ فَجَزَّأَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثَلَاثَةَ أَجْزَاءٍ: جُزْأَيْنِ بَيْنَ الْمُسْلِمِينَ، وَجُزْءًا نَفَقَةً لِأَهْلِهِ، فَمَا فَضَلَ عَنْ نَفَقَةِ أَهْلِهِ جَعَلَهُ بَيْنَ فُقَرَاءِ الْمُهَاجِرِينَ. (د)', 'മാലികുബ്നു ഔസിബ്നിൽ ഹദസാൻ(റ): ഉമർ(റ) ഉന്നയിച്ച തെളിവുകളിൽ ഒന്നായിരുന്നു ഇത്, അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ)ക്ക് ലഭിച്ച മൂന്ന് (വീതിക്കാതെയുള്ള) യുദ്ധമുതലുകളാണ് ബനൂന്നളീർ, ഖൈബർ, ഫദക് എന്നിവ. ബനൂന്നളീറിന്റെ മുതൽ നബി(സ)യുടെ അടിയന്തിര (അതിഥികൾക്കും ദൂതന്മാർക്കുമുള്ള ചെലവ്) ആവശ്യങ്ങൾക്കുള്ളതായിരുന്നു. ഫദക് യാത്രക്കാർക്ക് നീക്കിവെച്ചതായിരുന്നു. ഖൈബറിനെ റസൂൽ(സ) മൂന്ന് ഭാഗങ്ങളാക്കി: രണ്ട് ഭാഗങ്ങൾ മുസ്‌ലിംകൾക്കിടയിലും ഒന്ന് കുടുംബത്തിനുള്ള ചെലവിനും. കുടുംബത്തിന്റെ ചെലവിൽ നിന്ന് ബാക്കിവരുന്നത് മുഹാജിറുകളിലെ ദരിദ്രർക്ക് നീക്കിവെച്ചു. (ദ)', 'مَالِكِ بْنِ أَوْسِ بْنِ الْحَدَثَانِ', 'മാലികുബ്നു ഔസിബ്നിൽ ഹദസാൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 86, 86, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ فَاطِمَةَ بِنْتَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَرْسَلَتْ إِلَى أَبِي بَكْرٍ الصِّدِّيقِ – رَضِيَ اللهُ عَنْهُ – تَسْأَلُهُ مِيرَاثَهَا مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِمَّا أَفَاءَ اللهُ عَلَيْهِ بِالْمَدِينَةِ، وَفَدَكَ، وَمَا بَقِيَ مِنْ خُمْسِ خَيْبَرَ، فَقَالَ أَبُو بَكْرٍ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا نُورَثُ، مَا تَرَكْنَا صَدَقَةٌ، إِنَّمَا يَأْكُلُ آلُ مُحَمَّدٍ مِنْ هَذَا الْمَالِ". وَإِنِّي وَاللهِ لَا أُغَيِّرُ شَيْئًا مِنْ صَدَقَةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ حَالِهَا الَّتِي كَانَتْ عَلَيْهَا فِي عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَأَعْمَلَنَّ فِيهَا بِمَا عَمِلَ بِهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَأَبَى أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ أَنْ يَدْفَعَ إِلَى فَاطِمَةَ عَلَيْهَا السَّلَامُ مِنْهَا شَيْئًا.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=136), 1, 'وَفِي رِوَايَةٍ: وَفَاطِمَةُ عَلَيْهَا السَّلَامُ حِينَئِذٍ تَطْلُبُ صَدَقَةَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الَّتِي بِالْمَدِينَةِ وَفَدَكَ، وَمَا بَقِيَ مِنْ خُمْسِ خَيْبَرَ، قَالَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا: فَقَالَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا نُورَثُ، مَا تَرَكْنَا صَدَقَةٌ، وَإِنَّمَا يَأْكُلُ آلُ مُحَمَّدٍ فِي هَذَا الْمَالِ" يَعْنِي مَالَ اللهِ، لَيْسَ لَهُمْ أَنْ يَزِيدُوا عَلَى الْمَأْكَلِ.', 'മറ്റൊരു നിവേദനം: മദീനയിലും ഫദകിലുമായി റസൂൽ(സ)ക്ക് ദാനമായി ലഭിച്ച മുതലും, ഖൈബറിലെ അഞ്ചിലൊന്നിൽ അവശേഷിച്ച മുതലും ആ സന്ദർഭത്തിൽ ഫാതിമ(റ) ആവശ്യപ്പെടുന്നുണ്ടായിരുന്നു. ആഇശ(റ) പറയുന്നു: അപ്പോൾ അബൂബക്ർ(റ) പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞിട്ടുണ്ട്: "നാം അനന്തരമെടുക്കപ്പെടുകയില്ല. നാം ഉപേക്ഷിച്ചത് സ്വദഖയാണ്. മുഹമ്മദിന്റെ കുടുംബം ഈ ധനത്തിൽ നിന്ന് ഭക്ഷിക്കും." അതായത് അല്ലാഹുവിന്റെ ധനം. ഭക്ഷിക്കാനുള്ള ആഹാരത്തിൽ കൂടുതൽ അവർക്കെടുക്കാൻ പാടില്ല.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=136), 2, 'وَفِي رِوَايَةٍ: فَأَبَى أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ عَلَيْهَا ذَلِكَ، وَقَالَ: لَسْتُ تَارِكًا شَيْئًا كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعْمَلُ بِهِ إِلَّا عَمِلْتُ بِهِ، وَإِنِّي أَخْشَى إِنْ تَرَكْتُ شَيْئًا مِنْ أَمْرِهِ أَنْ أَزِيغَ. فَأَمَّا صَدَقَتُهُ بِالْمَدِينَةِ فَدَفَعَهَا عُمَرُ إِلَى عَلِيٍّ وَعَبَّاسٍ رَضِيَ اللهُ عَنْهُمْ، فَغَلَبَهُ عَلِيٌّ عَلَيْهَا، وَأَمَّا خَيْبَرُ وَفَدَكُ فَأَمْسَكَهُمَا عُمَرُ، وَقَالَ: هُمَا صَدَقَةُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَتَا لِحُقُوقِهِ الَّتِي تَعْرُوهُ وَنَوَائِبِهِ، وَأَمْرُهُمَا إِلَى مَنْ وَلِيَ الْأَمْرَ، قَالَ: فَهُمَا عَلَى ذَلِكَ إِلَى الْيَوْمِ. (ق,د,ن)', 'മറ്റൊരു നിവേദനം: അബൂബക്ർ(റ) അത് മഹതിക്ക് നൽകാൻ വിസമ്മതിച്ചു. അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) ചെയ്തിരുന്ന ഒരു പ്രവൃത്തി ഞാൻ ചെയ്യുകയല്ലാതെ, ഒന്നും തന്നെ ഞാൻ ഒഴിവാക്കുകയില്ല. അങ്ങനെ നബി(സ)യുടെ വല്ല കാര്യവും ഞാൻ ഒഴിവാക്കുകയാണെങ്കിൽ സത്യത്തിൽ നിന്ന് വ്യതിചലിച്ചു പോകുന്നതിനെ ഞാൻ ഭയക്കുന്നു. മദീനയിലുണ്ടായിരുന്ന നബി(സ)യുടെ ദാനം ഉമർ(റ) അലി(റ)വിനും അബ്ബാസ്(റ)വിനും നൽകി. അങ്ങനെ അലി(റ) അതിന്റെ മേൽ അധികാരം സ്ഥാപിച്ചു. ഖൈബറും ഫദകും ഉമർ(റ) പിടിച്ചുവെച്ചു. അദ്ദേഹം പറഞ്ഞു: അവ രണ്ടും റസൂൽ(സ) നിർബന്ധമായി ചെയ്യുന്ന ഇടപാടുകൾക്കും അത്യാവശ്യ കാര്യങ്ങൾക്കുമുള്ള അവിടുത്തെ ദാനമാണ്. ഭരണകർത്താവിനാണ് അവയുടെ നടത്തിപ്പ്. അദ്ദേഹം പറഞ്ഞു: ഇന്നേ വരെ അതേ അവസ്ഥയിൽ തന്നെയാണ് അവ നിലകൊള്ളുന്നത്. (ബു,മു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنِ الزُّهْرِيِّ فِي قَوْلِهِ: {فَمَا أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ} [الحشر: ٦] صَالَحَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَهْلَ فَدَكَ وَقُرًى قَدْ سَمَّاهَا لَا أَحْفَظُهَا، وَهُوَ مُحَاصِرٌ قَوْمًا آخَرِينَ، فَأَرْسَلُوا إِلَيْهِ بِالصُّلْحِ، قَالَ: {فَمَا أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ} يَقُولُ: بِغَيْرِ قِتَالٍ. قَالَ الزُّهْرِيُّ: وَكَانَتْ بَنُو النَّضِيرِ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَالِصًا، لَمْ يَفْتَحُوهَا عَنْوَةً افْتَتَحُوهَا عَلَى صُلْحٍ، فَقَسَمَهَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَ الْمُهَاجِرِينَ، لَمْ يُعْطِ الْأَنْصَارَ مِنْهَا شَيْئًا، إِلَّا رَجُلَيْنِ كَانَتْ بِهِمَا حَاجَةٌ. (د)', 'സുഹ്‌രി: ''കുതിരകളെയോ ഒട്ടകങ്ങളെയോ അവരുടെ മേൽ നിങ്ങൾ ഓടിച്ചില്ല'' (ഹശ്‌ർ: 6) എന്ന് അല്ലാഹു പറഞ്ഞു. ഫദകുകാരോടും ചില ഗ്രാമങ്ങളോടും - അവയുടെ പേര് പറഞ്ഞിട്ടുണ്ട്. പക്ഷേ, ഞാന തോർക്കുന്നില്ല - നബി(സ) സന്ധിയായി. മറ്റുചില പട്ടണങ്ങളെ ഉപരോധിക്കുകയും ചെയ്തു. അപ്പോഴവർ നബി(സ)യുടെയടുത്തേക്ക് സന്ധിയുമായി ദൂതരെ അയച്ചു. നിവേദകൻ പറയുന്നു: ''കുതിരകളെയോ ഒട്ടകങ്ങളെയോ അവരുടെ മേൽ നിങ്ങൾ ഓടിച്ചില്ല.'' അതായത്, ഒരു യുദ്ധവും കൂടാതെ. സുഹ്‌രി പറഞ്ഞു: ബനുന്നളീറിന്റെ മുതൽ നബി(സ)ക്ക് മാത്രമുള്ളതായിരുന്നു. അത് ബലമായി പിടിച്ചെടുത്തതല്ല. മറിച്ച് സന്ധി പ്രകാരമായിരുന്നു. നബി(സ) അത് മുഹാജിറുകൾക്കിടയിൽ വീതിച്ചുകൊടുത്തു. അൻസ്വാറുകൾക്ക് ഒന്നും തന്നെ നൽകിയില്ല, രണ്ട് പേർക്കൊഴികെ. അവർ അതിന് ആവശ്യക്കാരായിരുന്നു. (ദ)', 'الزُّهْرِيِّ فِي قَوْلِهِ', 'സുഹ്‌രി', null, null, array['د']::text[], array['ദ']::text[], 'الحشر: ٦', null, 87, 88, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنِ الْمُغِيرَةِ بْنِ حَكِيمٍ الصَّنْعَانِيِّ قَالَ: جَمَعَ عُمَرُ بْنُ عَبْدِ الْعَزِيزِ بَنِي مَرْوَانَ حِينَ اسْتُخْلِفَ فَقَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَتْ لَهُ فَدَكُ، فَكَانَ يُنْفِقُ مِنْهَا، وَيَعُودُ مِنْهَا عَلَى صَغِيرِ بَنِي هَاشِمٍ، وَيُزَوِّجُ مِنْهَا أَيِّمَهُمْ، وَإِنَّ فَاطِمَةَ سَأَلَتْهُ أَنْ يَجْعَلَهَا لَهَا، فَأَبَى، فَكَانَتْ كَذَلِكَ فِي حَيَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى مَضَى لِسَبِيلِهِ، فَلَمَّا أَنْ وُلِّيَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ عَمِلَ فِيهَا بِمَا عَمِلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي حَيَاتِهِ حَتَّى مَضَى لِسَبِيلِهِ، فَلَمَّا أَنْ وُلِّيَ عُمَرُ عَمِلَ فِيهَا بِمِثْلِ مَا عَمِلَا حَتَّى مَضَى لِسَبِيلِهِ، ثُمَّ أُقْطِعَهَا مَرْوَانُ، ثُمَّ صَارَتْ لِعُمَرَ بْنِ عَبْدِ الْعَزِيزِ: قَالَ عُمَرُ بْنُ عَبْدِ الْعَزِيزِ: فَرَأَيْتُ أَمْرًا مَنَعَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاطِمَةَ عَلَيْهَا السَّلَامُ لَيْسَ لِي بِحَقٍّ، وَأَنَا أُشْهِدُكُمْ أَنِّي قَدْ رَدَدْتُهَا عَلَى مَا كَانَتْ، يَعْنِي عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د)', 'മുഗീറതുബ്നു ഹകീമു സ്വൻആനീ: ഉമറുബ്നു അബ്ദിൽ അസീസ്(റ) ഖലീഫയായി തെരഞ്ഞെടുക്കപ്പെട്ടപ്പോൾ ബനൂമർവാനെ വിളിച്ചുകൂട്ടി പറഞ്ഞു: ഫദകിലെ മുതൽ റസൂൽ(സ)യുടേതായിരുന്നു. അതിൽ നിന്ന് നബി(സ) ചെലവഴിക്കുമായിരുന്നു. ബനൂഹാശിമിലെ ചെറിയവർക്ക് (പാവപ്പെട്ടവർക്ക്), അവരുടെ ആവശ്യങ്ങൾക്കനുസരിച്ച് നബി(സ) അതിൽ നിന്ന് ചെലവഴിച്ചു. അവരിൽ വിവാഹം കഴിക്കാത്തവർക്ക് വിവാഹം കഴിച്ചുകൊടുത്തു. അങ്ങനെ ഫാതിമ(റ) അത് തനിക്ക് നൽകാൻ നബി(സ)യോട് അഭ്യർത്ഥിച്ചു. നബി(സ) വിസമ്മതിച്ചു. നബി(സ)യുടെ ജീവിതകാലം മുഴുവൻ ഇതേ അവസ്ഥയിൽ തുടർന്നു. അങ്ങനെ അവിടുന്ന് വഫാത്തായി. പിന്നീട് അബൂബക്ർ(റ) അധികാരമേറ്റെടുത്തപ്പോൾ, അദ്ദേഹത്തിന്റെ ജീവിതകാലത്തും ഈ കാര്യത്തിൽ നബി(സ) ചെയ്തതു പോലെ അദ്ദേഹവും ചെയ്തു. അദ്ദേഹവും വഫാത്തായി. ശേഷം ഉമർ(റ) അധികാരമേറ്റെടുത്തപ്പോഴും ഇവർ രണ്ടുപേരും ചെയ്തതു പോലെ, മരണം വരെ അദ്ദേഹവും ചെയ്തു. പിന്നീട് മർവാന് അത് വിഹിതമായി ലഭിച്ചു. അനന്തരം അത് ഉമറുബ്നു അബ്ദിൽ അസീസിനുമായി. ഉമറുബ്നു അബ്ദിൽ അസീസ്(റ) പറഞ്ഞു: അപ്പോൾ ഞാനൊരു കാര്യം മനസ്സിലാക്കുന്നത്, ഫാതിമ(റ)ക്ക് റസൂൽ(സ) നിഷേധിച്ച ഒരു കാര്യത്തിൽ എനിക്ക് ഒരു അവകാശവുമില്ലെന്നാണ്. അതുകൊണ്ട് നിങ്ങളെ ഞാൻ സാക്ഷിനിർത്തുന്നു, അതുണ്ടായിരുന്ന അവസ്ഥയിലേക്ക് തന്നെ ഞാനതിനെ മടക്കുകയാണ്. അതായത് റസൂൽ(സ)യുടെ കാലത്തുണ്ടായിരുന്നതു പോലെ. (ദ)', 'الْمُغِيرَةِ بْنِ حَكِيمٍ الصَّنْعَانِيِّ قَالَ', 'മുഗീറതുബ്നു ഹകീമു സ്വൻആനീ', null, null, array['د']::text[], array['ദ']::text[], null, null, 88, 88, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ أَبِي الطُّفَيْلِ عَامِرِ بْنِ وَاثِلَةَ اللَّيْثِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَتْ فَاطِمَةُ رَضِيَ اللهُ عَنْهَا إِلَى أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُ تَطْلُبُ مِيرَاثَهَا مِنَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ اللهَ عَزَّ وَجَلَّ إِذَا أَطْعَمَ نَبِيًّا طُعْمَةً فَهِيَ لِلَّذِي يَقُومُ مِنْ بَعْدِهِ". (د)', 'അബൂത്വുഫൈൽ ആമിറുബ്നു വാസിലതില്ലൈസീ(റ): നബി(സ)യിൽ നിന്നുള്ള അനന്തരാവകാശം തേടിക്കൊണ്ട് അബൂബക്ർ(റ)വിന്റെയടുക്കലേക്ക് ഫാതിമ(റ) വന്നു. അപ്പോൾ അബൂബക്ർ(റ) പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഏതെങ്കിലുമൊരു പ്രവാചകനെ അല്ലാഹു ഒരു ഭക്ഷണം കഴിപ്പിച്ചിട്ടുണ്ടെങ്കിൽ അത് (അതിന്റെ അവകാശം) അദ്ദേഹത്തിനുശേഷം ഭരണം നിർവഹിക്കുന്ന പിൻഗാമിക്കുള്ളതാണ്." (ദ)', 'أَبِي الطُّفَيْلِ عَامِرِ بْنِ وَاثِلَةَ اللَّيْثِيِّ', 'അബൂത്വുഫൈൽ ആമിറുബ്നു വാസിലതില്ലൈസീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 88, 89, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ أَبِي الْبَخْتَرِيِّ قَالَ: سَمِعْتُ حَدِيثًا مِنْ رَجُلٍ فَأَعْجَبَنِي، فَقُلْتُ: اكْتُبْهُ لِي، فَأَتَى بِهِ مَكْتُوبًا مُذَبَّرًا: دَخَلَ الْعَبَّاسُ وَعَلِيٌّ عَلَى عُمَرَ، وَعِنْدَهُ طَلْحَةُ وَالزُّبَيْرُ وَعَبْدُ الرَّحْمَنِ وَسَعْدٌ رَضِيَ اللهُ عَنْهُمْ، وَهُمَا يَخْتَصِمَانِ، فَقَالَ عُمَرُ لِطَلْحَةَ وَالزُّبَيْرِ وَعَبْدِ الرَّحْمَنِ وَسَعْدٍ: أَلَمْ تَعْلَمُوا أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كُلُّ مَالِ النَّبِيِّ صَدَقَةٌ، إِلَّا مَا أَطْعَمَهُ أَهْلَهُ وَكَسَاهُمْ، إِنَّا لَا نُورَثُ؟" قَالُوا: بَلَى، قَالَ: فَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُنْفِقُ مِنْ مَالِهِ عَلَى أَهْلِهِ وَيَتَصَدَّقُ بِفَضْلِهِ، ثُمَّ تُوُفِّيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَوَلِيَهَا أَبُو بَكْرٍ سَنَتَيْنِ، فَكَانَ يَصْنَعُ الَّذِي كَانَ يَصْنَعُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ... ثُمَّ ذَكَرَ شَيْئًا مِنْ حَدِيثِ مَالِكِ بْنِ أَوْسٍ. (د)', 'അബുൽ ബഖ്തരി: ഞാനൊരാളിൽ നിന്ന് ഒരു ഹദീസ് കേട്ടു. അതെന്നെ അത്ഭുതപ്പെടുത്തി. ഞാൻ പറഞ്ഞു: അതെനിക്ക് എഴുതിത്തരിക. അപ്പോൾ പുള്ളികളൊക്കെയിട്ട് വ്യക്തമായി എഴുതി അദ്ദേഹമെനിക്ക് കൊണ്ടുതന്നു (അതിൽ ഇപ്രകാരമാണ് ഉണ്ടായിരുന്നത്): അബ്ബാസ്(റ)വും അലി(റ)വും ഉമർ(റ)വിന്റടുക്കൽ വന്നു. അദ്ദേഹത്തിന്റെ സമീപം ത്വൽഹ(റ)വും സുബൈർ(റ)വും അബ്ദുർറഹ്മാൻ(റ)വും സഅ്ദ്(റ)വുമുണ്ടായിരുന്നു. അവർ രണ്ടുപേരും (അലി(റ)വും അബ്ബാസ്(റ)വും) തർക്കിക്കുന്നുണ്ടായിരുന്നു. അപ്പോൾ ത്വൽഹ(റ)വിനോടും സുബൈർ(റ)വിനോടും അബ്ദുർറഹ്മാൻ(റ)വിനോടും സഅ്ദ്(റ)വിനോടുമായി ഉമർ(റ) ചോദിച്ചു: റസൂൽ(സ) പറഞ്ഞത് നിങ്ങൾക്കറിയില്ലേ: "നബി(സ)യുടെ സമ്പത്തെല്ലാം സ്വദഖയാണ്. തന്റെ കുടുംബത്തെ ഭക്ഷിപ്പിച്ചതും ധരിപ്പിച്ചതുമൊഴികെ. നിശ്ചയം നാം അനന്തരമെടുക്കപ്പെടുകയില്ല." അവർ പറഞ്ഞു: അതെ. അദ്ദേഹം പറഞ്ഞു: നബി(സ) തന്റെ മുതലിൽ നിന്ന് കുടുംബത്തിന് വേണ്ടി ചെലവഴിക്കുകയും ബാക്കി സ്വദഖ ചെയ്യുകയുമാണുണ്ടായിരുന്നത്. പിന്നീട് റസൂൽ(സ) വഫാത്തായി. ശേഷം അബൂബക്ർ(റ) രണ്ട് വർഷം ഭരണം നടത്തി. റസൂൽ(സ) ചെയ്തിരുന്നത് തന്നെ അദ്ദേഹവും ചെയ്തു... ശേഷം നിവേദകൻ മാലികുബ്നു ഔസ്(റ)വിന്റെ ഹദീസിൽ നിന്ന് അൽപം പറഞ്ഞു. (ദ)', 'أَبِي الْبَخْتَرِيِّ قَالَ', 'അബുൽ ബഖ്തരി', null, null, array['د']::text[], array['ദ']::text[], null, null, 89, 89, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: إِنَّ أَزْوَاجَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ تُوُفِّيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَرَدْنَ أَنْ يَبْعَثْنَ عُثْمَانَ بْنَ عَفَّانَ إِلَى أَبِي بَكْرٍ الصِّدِّيقِ، فَيَسْأَلْنَهُ ثُمُنَهُنَّ مِنَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ لَهُنَّ عَائِشَةُ: أَلَيْسَ قَدْ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا نُورَثُ، مَا تَرَكْنَا فَهُوَ صَدَقَةٌ". وَفِي رِوَايَةٍ قَالَتْ: قُلْتُ: أَلَا تَتَّقِينَ اللهَ؟ أَلَمْ تَسْمَعْنَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا نُورَثُ، مَا تَرَكْنَا فَهُوَ صَدَقَةٌ، وَإِنَّمَا هَذَا الْمَالُ لِآلِ مُحَمَّدٍ لِنَائِبَتِهِمْ وَلِضَيْفِهِمْ، فَإِذَا مُتُّ فَهُوَ إِلَى وَلِيِّ الْأَمْرِ مِنْ بَعْدِي". (ق,د)', 'ആഇശ(റ): നബി(സ) വഫാതായപ്പോൾ അവിടുത്തെ ഭാര്യമാർ, നബി(സ)യിൽനിന്നുള്ള അനന്തരവിഹിതമായ എട്ടിലൊന്ന് ചോദിക്കാൻ ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ)വിനെ അബൂബക്ർ(റ)വിന്റടുക്കലേക്ക് പറഞ്ഞയക്കാൻ ഉദ്ദേശിച്ചു. അപ്പോൾ ആഇശ(റ) അവരോട് പറഞ്ഞു: നബി(സ) പറഞ്ഞിട്ടില്ലേ: "നാം അനന്തരമെടുക്കപ്പെടുകയില്ല. നാം ഉപേക്ഷിച്ചത് സ്വദഖയാണ്." മറ്റൊരു നിവേദനത്തിൽ മഹതി പറഞ്ഞു: ഞാൻ ചോദിച്ചു: നിങ്ങൾ അല്ലാഹുവിനെ സൂക്ഷിക്കുന്നില്ലേ? റസൂൽ(സ) പറയുന്നത് നിങ്ങൾ കേട്ടിട്ടില്ലേ: "നാം അനന്തരമെടുക്കപ്പെടുകയില്ല. നാം ഉപേക്ഷിച്ചിട്ടത് സ്വദഖയാണ്. നിശ്ചയം ഈ മുതൽ മുഹമ്മദിന്റെ കുടുംബത്തിന്റെ അത്യാവശ്യ ചെലവുകൾക്കും അതിഥികൾക്കുമുള്ളതാണ്. ഞാൻ മരണപ്പെട്ടാൽ എന്റെ ശേഷമുള്ള ഭരണാധികാരിക്കാണത്." (ബു,മു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 89, 90, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=141), 1, 'وَفِي رِوَايَةٍ قَالَتْ: قُلْتُ: أَلَا تَتَّقِينَ اللهَ؟ أَلَمْ تَسْمَعْنَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا نُورَثُ، مَا تَرَكْنَا فَهُوَ صَدَقَةٌ، وَإِنَّمَا هَذَا الْمَالُ لِآلِ مُحَمَّدٍ لِنَائِبَتِهِمْ وَلِضَيْفِهِمْ، فَإِذَا مُتُّ فَهُوَ إِلَى وَلِيِّ الْأَمْرِ مِنْ بَعْدِي". (ق,د)', 'മറ്റൊരു നിവേദനത്തിൽ മഹതി പറഞ്ഞു: ഞാൻ ചോദിച്ചു: നിങ്ങൾ അല്ലാഹുവിനെ സൂക്ഷിക്കുന്നില്ലേ? റസൂൽ(സ) പറയുന്നത് നിങ്ങൾ കേട്ടിട്ടില്ലേ: "നാം അനന്തരമെടുക്കപ്പെടുകയില്ല. നാം ഉപേക്ഷിച്ചിട്ടത് സ്വദഖയാണ്. നിശ്ചയം ഈ മുതൽ മുഹമ്മദിന്റെ കുടുംബത്തിന്റെ അത്യാവശ്യ ചെലവുകൾക്കും അതിഥികൾക്കുമുള്ളതാണ്. ഞാൻ മരണപ്പെട്ടാൽ എന്റെ ശേഷമുള്ള ഭരണാധികാരിക്കാണത്." (ബു,മു,ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا نُورَثُ مَا تَرَكْنَا صَدَقَةٌ". وَكَانَ يُنْفِقُ مِنَ الْمَالِ الَّذِي أَفَاءَ اللهُ عَلَيْهِ، عَلَى أَهْلِهِ نَفَقَةَ سَنَتِهِمْ، ثُمَّ يَأْخُذُ مَا بَقِيَ فَيَجْعَلُهُ مَجْعَلَ مَالِ اللهِ، ثُمَّ قَالَ لِمَنْ حَضَرَهُ مِنَ الصَّحَابَةِ: أَنْشُدُكُمْ بِاللهِ الَّذِي بِإِذْنِهِ تَقُومُ السَّمَاءُ وَالْأَرْضُ، هَلْ تَعْلَمُونَ ذَلِكَ؟ قَالُوا: نَعَمْ، وَكَانَ فِي الْمَجْلِسِ عَلِيٌّ وَعَبَّاسٌ وَعُثْمَانُ وَعَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ وَالزُّبَيْرُ وَسَعْدُ بْنُ أَبِي وَقَّاصٍ، وَذَكَرَ حَدِيثَ عَلِيٍّ وَالْعَبَّاسِ وَمُنَازَعَتِهِمَا. وَلَيْسَ الْإِتْيَانُ بِهِ مِنْ شَرْطِنَا. (خ)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): നബി(സ) പറഞ്ഞു: "നാം അനന്തരമെടുക്കപ്പെടുകയില്ല. നാം ബാക്കിവെച്ച് പോയത് സ്വദഖയാണ്." നബി(സ) തന്റെ കുടുംബത്തിന്റെ ഒരു വർഷത്തെ ചെലവ്, തനിക്ക് അല്ലാഹു യുദ്ധമുതലായി നൽകിയതിൽ നിന്ന് ചെലവഴിക്കുമായിരുന്നു. പിന്നെ ബാക്കിയുള്ളതെടുത്ത് അല്ലാഹുവിന്റെ സമ്പത്ത് ചെലവഴിക്കും പോലെ ചെലവഴിക്കും. പിന്നീട് (ഇതു പറഞ്ഞ ശേഷം) ഉമർ(റ) സ്വഹാബാക്കളിൽ നിന്ന് അവിടെ സന്നിഹിതരായവരോട് പറഞ്ഞു: ആരുടെ സമ്മതം കൊണ്ടാണോ ആകാശഭൂമികൾ നിലനിൽക്കുന്നത്, അങ്ങനെയുള്ള അല്ലാഹുവിനെക്കൊണ്ട് ഞാൻ നിങ്ങളോട് സത്യം ചെയ്യുന്നു, നിങ്ങൾക്കതറിയില്ലേ? അവർ പറഞ്ഞു: അതെ. ആ സദസ്സിൽ അലി(റ), അബ്ബാസ്(റ), ഉസ്മാൻ(റ), അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ), സുബൈർ(റ), സഅ്ദുബ്നു അബീവഖാസ്(റ) എന്നിവരുണ്ടായിരുന്നു. പിന്നീട് അലി(റ)വിന്റെയും അബ്ബാസ്(റ)വിന്റെയും സംസാരത്തെക്കുറിച്ചും അവരുടെ പരസ്പര തർക്കത്തെക്കുറിച്ചും നിവേദകൻ വിവരിച്ചു. അതിവിടെ കൊണ്ടുവരൽ നമ്മുടെ വ്യവസ്ഥയിൽ പെട്ടതല്ല. (ബു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 90, 90, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَتْ فَاطِمَةُ إِلَى أَبِي بَكْرٍ – رَضِيَ اللهُ عَنْهُمَا – فَقَالَتْ: مَنْ يَرِثُكَ؟ فَقَالَ: أَهْلِي وَوَلَدِي. قَالَتْ: فَمَا لِي لَا أَرِثُ أَبِي؟ فَقَالَ أَبُو بَكْرٍ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا نُورَثُ". وَلَكِنِّي أَعُولُ مَنْ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُولُهُ، وَأُنْفِقُ عَلَى مَنْ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُنْفِقُ عَلَيْهِ. (ق,ت)', 'അബൂഹുറൈറ(റ): ഫാതിമ(റ) അബൂബക്കർ(റ)വിന്റെ അടുത്ത് വന്ന് ഇപ്രകാരം ചോദിച്ചു: ആരാണ് നിങ്ങളെ അനന്തരമെടുക്കുക? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: എന്റെ മക്കളും എന്റെ കുടുംബക്കാരും. മഹതി ചോദിച്ചു: അപ്പോൾ എനിക്ക് എന്റെ ഉപ്പയെ അനന്തരമെടുക്കാൻ പറ്റാത്തത് എന്തുകൊണ്ടാണ്? അപ്പോൾ അബൂബക്കർ(റ) പറഞ്ഞു: നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "നാം അനന്തരമെടുക്കപ്പെടുകയില്ല." പക്ഷേ, നബി(സ) ചെലവ് നടത്തിയിരുന്നവർക്ക് ഞാൻ ചെലവ് കൊടുക്കുകയും നബി(സ) ആർക്ക് വേണ്ടിയെല്ലാം ചെലവാക്കിയിരുന്നോ അവർക്കെല്ലാം ഞാനും (ധനം) ചെലവാക്കുകയും ചെയ്യും. (ബു,മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 90, 90, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّ فَاطِمَةَ جَاءَتْ أَبَا بَكْرٍ وَعُمَرَ رَضِيَ اللهُ عَنْهُمَا تَسْأَلُ مِيرَاثَهَا مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَا: سَمِعْنَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنِّي لَا أُورَثُ". قَالَتْ: وَاللهِ لَا أُكَلِّمُكُمَا أَبَدًا. فَمَاتَتْ وَلَا تُكَلِّمُهُمَا. (ت)', 'അബൂഹുറൈറ(റ): ഫാതിമ(റ) നബി(സ)യിൽ നിന്നുള്ള തന്റെ അനന്തരസ്വത്ത് ചോദിച്ചുകൊണ്ട് അബൂബക്കർ(റ)വിനെയും ഉമർ(റ)വിനെയും സമീപിച്ചു. അപ്പോൾ അവർ രണ്ടുപേരും പറഞ്ഞു: നബി(സ) പറയുന്നതായി ഞങ്ങൾ കേട്ടിട്ടുണ്ട്: "തീർച്ചയായും ഞാൻ അനന്തരമെടുക്കപ്പെടുകയില്ല." മഹതി പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, നിങ്ങളോട് രണ്ടുപേരോടും ഞാൻ ഒരിക്കലും സംസാരിക്കുകയില്ല. അങ്ങനെ അവരോട് സംസാരിക്കാതെ മഹതി വഫാതായി. (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 90, 91, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ مَالِكِ بْنِ أَوْسِ بْنِ الْحَدَثَانِ رَضِيَ اللهُ عَنْهُ قَالَ: أُرْسِلَ إِلَيَّ عُمَرُ حِينَ تَعَالَى النَّهَارُ، فَجِئْتُهُ، فَوَجَدْتُهُ جَالِسًا عَلَى سَرِيرٍ مُفْضِيًا إِلَى رُمَالِهِ، فَقَالَ حِينَ دَخَلْتُ عَلَيْهِ: يَا مَالِ، إِنَّهُ قَدْ دَفَّ أَهْلُ أَبْيَاتٍ مِنْ قَوْمِكَ، وَإِنِّي قَدْ أَمَرْتُ فِيهِمْ بِشَيْءٍ، فَأقْسِمْ فِيهِمْ. قُلْتُ: لَوْ أَمَرْتَ غَيْرِي بِذَلِكَ، فَقَالَ: خُذْهُ، فَجَاءَهُ يَرْفَأُ فَقَالَ: يَا أَمِيرَ الْمُؤْمِنِينَ، هَلْ لَكَ فِي عُثْمَانَ بْنِ عَفَّانَ، وَعَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ، وَالزُّبَيْرِ بْنِ الْعَوَّامِ، وَسَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُمْ؟ قَالَ: نَعَمْ، فَأَذِنَ لَهُمْ فَدَخَلُوا، ثُمَّ جَاءَهُ يَرْفَأُ، فَقَالَ: يَا أَمِيرَ الْمُؤْمِنِينَ، هَلْ لَكَ فِي الْعَبَّاسِ وَعَلِيٍّ رَضِيَ اللهُ عَنْهُمَا؟ قَالَ: نَعَمْ، فَأَذِنَ لَهُمْ فَدَخَلُوا، فَقَالَ الْعَبَّاسُ: يَا أَمِيرَ الْمُؤْمِنِينَ، اقْضِ بَيْنِي وَبَيْنَ هَذَا، يَعْنِي عَلِيًّا. فَقَالَ بَعْضُهُمْ: أَجَلْ يَا أَمِيرَ الْمُؤْمِنِينَ، اقْضِ بَيْنَهُمَا وَأَرِحْهُمَا. قَالَ مَالِكُ بْنُ أَوْسٍ: خُيِّلَ إِلَيَّ أَنَّهُمَا قَدَّمَا أُولَئِكَ النَّفَرَ لِذَلِكَ، فَقَالَ عُمَرُ رَحِمَهُ اللهُ: اتَّئِدَا، ثُمَّ أَقْبَلَ عَلَى أُولَئِكَ الرَّهْطِ فَقَالَ: أَنْشُدُكُمْ بِاللهِ الَّذِي بِإِذْنِهِ تَقُومُ السَّمَاءُ وَالْأَرْضُ، هَلْ تَعْلَمُونَ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا نُورَثُ، مَا تَرَكْنَا صَدَقَةٌ". قَالُوا: نَعَمْ، ثُمَّ أَقْبَلَ عَلَى عَلِيٍّ وَالْعَبَّاسِ رَضِيَ اللهُ عَنْهُمَا فَقَالَ: أَنْشُدُكُمَا بِاللهِ الَّذِي بِإِذْنِهِ تَقُومُ السَّمَاءُ وَالْأَرْضُ، هَلْ تَعْلَمَانِ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا نُورَثُ، مَا تَرَكْنَا صَدَقَةٌ". فَقَالَا: نَعَمْ، قَالَ: فَإِنَّ اللهَ خَصَّ رَسُولَهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِخَاصَّةٍ لَمْ يَخُصَّ بِهَا أَحَدًا مِنَ النَّاسِ، فَقَالَ اللهُ تَعَالَى: {وَمَا أَفَاءَ اللهُ عَلَى رَسُولِهِ مِنْهُمْ فَمَا أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ وَلَكِنَّ اللهَ يُسَلِّطُ رُسُلَهُ عَلَى مَنْ يَشَاءُ وَاللهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ} [الحشر: ٦]. وَكَانَ اللهُ أَفَاءَ عَلَى رَسُولِهِ بَنِي النَّضِيرِ، فَوَاللهِ مَا اسْتَأْثَرَ بِهَا عَلَيْكُمْ وَلَا أَخَذَهَا دُونَكُمْ، فَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْخُذُ مِنْهَا نَفَقَةَ سَنَةٍ، أَوْ نَفَقَتَهُ وَنَفَقَةَ أَهْلِهِ سَنَةً، وَيَجْعَلُ مَا بَقِيَ أُسْوَةَ الْمَالِ. ثُمَّ أَقْبَلَ عَلَى أُولَئِكَ الرَّهْطِ فَقَالَ: أَنْشُدُكُمْ بِاللهِ الَّذِي بِإِذْنِهِ تَقُومُ السَّمَاءُ وَالْأَرْضُ، هَلْ تَعْلَمُونَ ذَلِكَ؟ قَالُوا: نَعَمْ. ثُمَّ أَقْبَلَ عَلَى الْعَبَّاسِ وَعَلِيٍّ رَضِيَ اللهُ عَنْهُمَا فَقَالَ: أَنْشُدُكُمَا بِاللهِ الَّذِي بِإِذْنِهِ تَقُومُ السَّمَاءُ وَالْأَرْضُ، هَلْ تَعْلَمَانِ ذَلِكَ؟ قَالَا: نَعَمْ. فَلَمَّا تُوُفِّيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ أَبُو بَكْرٍ: أَنَا وَلِيُّ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَجِئْتَ أَنْتَ وَهَذَا إِلَى أَبِي بَكْرٍ تَطْلُبُ أَنْتَ مِيرَاثَكَ مِنِ ابْنِ أَخِيكَ، وَيَطْلُبُ هَذَا مِيرَاثَ امْرَأَتِهِ مِنْ أَبِيهَا، فَقَالَ أَبُو بَكْرٍ رَحِمَهُ اللهُ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا نُورَثُ، مَا تَرَكْنَا صَدَقَةٌ". وَاللهُ يَعْلَمُ إِنَّهُ لَصَادِقٌ بَارٌّ رَاشِدٌ تَابِعٌ لِلْحَقِّ، فَوَلِيَهَا أَبُو بَكْرٍ، فَلَمَّا تُوُفِّيَ أَبُو بَكْرٍ قُلْتُ: أَنَا وَلِيُّ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَوَلِيُّ أَبِي بَكْرٍ، فَوَلِيتُهَا مَا شَاءَ اللهُ أَنْ أَلِيَهَا، فَجِئْتَ أَنْتَ وَهَذَا، وَأَنْتُمَا جَمِيعٌ وَأَمْرُكُمَا وَاحِدٌ، فَسَأَلْتُمَانِيهَا. فَقُلْتُ: إِنْ شِئْتُمَا أَنْ أَدْفَعَهَا إِلَيْكُمَا: عَلَى أَنَّ عَلَيْكُمَا عَهْدَ اللهِ أَنْ تَلِيَاهَا بِالَّذِي كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَلِيهَا، فَأَخَذْتُمَاهَا مِنِّي عَلَى ذَلِكَ، ثُمَّ جِئْتُمَانِي لِأَقْضِيَ بَيْنَكُمَا بِغَيْرِ ذَلِكَ، وَاللهِ لَا أَقْضِي بَيْنَكُمَا بِغَيْرِ ذَلِكَ حَتَّى تَقُومَ السَّاعَةُ، فَإِنْ عَجَزْتُمَا عَنْهَا فَرُدَّاهَا إِلَيَّ.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=145), 1, 'وَفِي رِوَايَةٍ: وَهُمَا – يَعْنِي عَلِيًّا وَالْعَبَّاسَ، رَضِيَ اللهُ عَنْهُمَا – يَخْتَصِمَانِ فِيمَا أَفَاءَ اللهُ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، مِنْ أَمْوَالِ بَنِي النَّضِيرِ.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ فَاطِمَةَ رَضِيَ اللَّهُ عَنْهَا بِنْتَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرْسَلَتْ إِلَى أَبِي بَكْرٍ الصِّدِّيقِ رَضِيَ اللَّهُ عَنْهُ تَسْأَلُهُ مِيرَاثَهَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، مِمَّا أَفَاءَ اللَّهُ عَلَيْهِ بِالْمَدِينَةِ وَفَدَك وَمَا بَقِيَ مِنْ خُمْسِ خَيْبَرَ، فَقَالَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا نُورَثُ، مَا تَرَكْنَا صَدَقَةٌ، إِنَّمَا يَأْكُلُ آلُ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي هَذَا الْمَالِ". وَإِنِّي وَاللَّهِ لَا أُغَيِّرُ شَيْئًا مِنْ صَدَقَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ حَالِهَا الَّتِي كَانَتْ عَلَيْهَا فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَأَعْمَلَنَّ فِيهَا بِمَا عَمِلَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَبَى أَبُو بَكْرٍ أَنْ يَدْفَعَ إِلَى فَاطِمَةَ شَيْئًا، فَوَجَدَتْ فَاطِمَةُ عَلَى أَبِي بَكْرٍ فِي ذَلِكَ، قَالَ: فَهَجَرَتْهُ فَلَمْ تُكَلِّمْهُ حَتَّى تُوُفِّيَتْ، وَعَاشَتْ بَعْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سِتَّةَ أَشْهُرٍ، فَلَمَّا تُوُفِّيَتْ دَفَنَهَا زَوْجُهَا عَلِيُّ بْنُ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ لَيْلًا، وَلَمْ يُؤْذِنْ بِهَا أَبَا بَكْرٍ، وَصَلَّى عَلَيْهَا عَلِيٌّ. وَكَانَ لِعَلِيٍّ مِنَ النَّاسِ وَجْهَةٌ حَيَاةَ فَاطِمَةَ رَضِيَ اللَّهُ عَنْهُمَا، فَلَمَّا تُوُفِّيَتْ اسْتَنْكَرَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ وُجُوهَ النَّاسِ، فَالْتَمَسَ مُصَالَحَةَ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُ وَمُبَايَعَتَهُ، وَلَمْ يَكُنْ بَايَعَ تِلْكَ الْأَشْهُرَ، فَأَرْسَلَ إِلَى أَبِي بَكْرٍ: أَنِ ائْتِنَا، وَلَا يَأْتِنَا مَعَكَ أَحَدٌ – كَرَاهِيَةً مَحْضَرِ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ – فَقَالَ عُمَرُ لِأَبِي بَكْرٍ: وَاللَّهِ لَا تَدْخُلْ عَلَيْهِمْ وَحْدَكَ، فَقَالَ أَبُو بَكْرٍ: وَمَا عَسَاهُمْ أَنْ يَفْعَلُوا بِي، [إِنِّي] وَاللَّهِ لَآتِيَنَّهُمْ. فَدَخَلَ عَلَيْهِمْ أَبُو بَكْرٍ فَتَشَهَّدَ عَلِيُّ بْنُ أَبِي طَالِبٍ، ثُمَّ قَالَ: إِنَّا قَدْ عَرَفْنَا يَا أَبَا بَكْرٍ فضيلتك وَمَا أَعْطَاكَ اللَّهُ، وَلَمْ نَنْفَسْ عَلَيْكَ خَيْرًا سَاقَهُ اللَّهُ إِلَيْكَ، وَلَكِنَّكَ اسْتَبْدَدْتَ عَلَيْنَا بِالْأَمْرِ، وَكُنَّا نَحْنُ نَرَى لَنَا حَقًّا لِقَرَابَتِنَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمْ يَزَلْ يُكَلِّمُ أَبَا بَكْرٍ حَتَّى فَاضَتْ عَيْنَا أَبِي بَكْرٍ، فَلَمَّا تَكَلَّمَ أَبُو بَكْرٍ قَالَ: وَالَّذِي نَفْسِي بِيَدِهِ لَقَرَابَةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحَبُّ إِلَيَّ أَنْ أَصِلَ مِنْ قَرَابَتِي، وَأَمَّا الَّذِي شَجَرَ بَيْنِي وَبَيْنَكُمْ مِنْ هَذِهِ الْأَمْوَالِ فَإِنِّي لَمْ آلُ فِيهَا عَنِ الْحَقِّ، وَلَمْ أَتْرُكْ أَمْرًا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُهُ فِيهَا إِلَّا صَنَعْتُهُ فَقَالَ عَلِيٌّ لِأَبِي بَكْرٍ: مَوْعِدُكَ الْعَشِيَّةُ لِلْبَيْعَةِ، فَلَمَّا صَلَّى أَبُو بَكْرٍ صَلَاةَ الظُّهْرِ رَقِيَ عَلَى الْمِنْبَرِ، فَتَشَهَّدَ، وَذَكَرَ شَأْنَ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ وَتَخَلُّفَهُ عَنِ الْبَيْعَةِ، وَعُذْرَهُ بِالَّذِي اعْتَذَرَ إِلَيْهِ ثُمَّ اسْتَغْفَرَ. وَتَشَهَّدَ عَلِيُّ بْنُ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ فَعَظَّمَ حَقَّ أَبِي بَكْرٍ، وَأَنَّهُ لَمْ يَحْمِلْهُ عَلَى الَّذِي صَنَعَ نَفَاسَةً عَلَى أَبِي بَكْرٍ، وَلَا إِنْكَارًا لِلَّذِي فَضَّلَهُ اللَّهُ عَزَّ وَجَلَّ بِهِ، وَلَكِنَّا كُنَّا نَرَى لَنَا فِي الْأَمْرِ نَصِيبًا فَاسْتُبِدَّ عَلَيْنَا بِهِ، فَوَجَدْنَا فِي أَنْفُسِنَا. فَسُرَّ بِذَلِكَ الْمُسْلِمُونَ، وَقَالُوا: أَصَبْتَ، فَكَانَ الْمُسْلِمُونَ إِلَى عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَرِيبًا، حِينَ رَاجَعَ الْأَمْرَ الْمَعْرُوفَ. (م)', 'ആഇശ(റ): അല്ലാഹു റസൂൽ(സ)ക്ക് മദീനയിൽ വെച്ചും ഫദകിൽ വെച്ചും നൽകിയ യുദ്ധമുതലിൽ നിന്നും, ഖൈബറിലെ (യുദ്ധമുതലിന്റെ) അഞ്ചിലൊന്നിൽ നിന്ന് ബാക്കിയായതിൽ നിന്നും, തനിക്ക് ലഭിക്കേണ്ട അനന്തര സ്വത്ത് ചോദിച്ചുകൊണ്ട് റസൂൽ(സ)യുടെ മകൾ ഫാതിമ(റ) അബൂബക്കർ(റ)വിലേക്ക് ആളെ അയച്ചു. അപ്പോൾ അബൂബക്കർ(റ) പറഞ്ഞു: തീർച്ചയായും റസൂൽ(സ) പറഞ്ഞിട്ടുണ്ട്: "നാം അനന്തരമെടുക്കപ്പെടുകയില്ല. നാം ഉപേക്ഷിച്ചിട്ടത് സ്വദഖയാണ്, തീർച്ചയായും മുഹമ്മദ്(സ)യുടെ കുടുംബത്തിന്റെ ഭക്ഷണം ഈ സമ്പത്തിൽ നിന്നാണ്." അല്ലാഹുവാണ് സത്യം, റസൂൽ(സ)യുടെ സ്വദഖയിൽ നിന്ന് ഒന്നിനെപ്പോലും ഞാൻ റസൂൽ(സ)യുടെ കാലത്തുണ്ടായിരുന്ന അവസ്ഥയിൽ നിന്ന് മാറ്റം വരുത്തുകയില്ല. തീർച്ചയായും ഞാനതിൽ അല്ലാഹുവിന്റെ റസൂൽ(സ) ചെയ്യാറുണ്ടായിരുന്നത് പോലെ ചെയ്യും. അങ്ങനെ അബൂബക്കർ(റ) (അതിൽ നിന്ന്) ഒന്നും ഫാതിമ(റ)യ്ക്ക് നൽകിയില്ല. അപ്പോൾ ഫാതിമ(റ)ക്ക് ഇവ്വിഷയകമായി അബൂബക്കർ(റ)വിനോട് വെറുപ്പ് തോന്നി. നിവേദകൻ പറയുന്നു: അങ്ങനെ മഹതി അദ്ദേഹവുമായി പിണങ്ങി. മഹതിയുടെ മരണം വരെ അദ്ദേഹത്തോട് സംസാരിച്ചിട്ടുമില്ല. റസൂൽ(സ)യുടെ ശേഷം മഹതി ആറുമാസം ജീവിച്ചു. അങ്ങനെ മഹതി വഫാത്തായപ്പോൾ അവരുടെ ഭർത്താവായ അലിയ്യുബ്നു അബീത്വാലിബ്(റ) മഹതിയെ രാത്രി സമയത്ത് മറവ് ചെയ്തു. അബൂബക്കർ(റ)വിനെ വിവരം അറിയിച്ചതുമില്ല. അലി(റ) തന്നെ മഹതിയുടെ മേൽ നിസ്കരിച്ചു. ഫാതിമ(റ)യുടെ ജീവിതകാലത്ത് അലി(റ)വിന് ജനങ്ങൾക്കിടയിൽ സ്വീകാര്യതയുണ്ടായിരുന്നു. മഹതി വഫാത്തായപ്പോൾ, അലി(റ) ജനങ്ങൾക്കിടയിലെ സ്വീകാര്യതയെ വെറുക്കുകയും, അബൂബക്കർ(റ)വുമായി സന്ധിയിലേർപ്പെടാനും അദ്ദേഹത്തോട് ഉടമ്പടി ചെയ്യാനുമുള്ള മാർഗ്ഗം തേടുകയും ചെയ്തു. പ്രസ്തുത മാസങ്ങളത്രയും അദ്ദേഹം ഉടമ്പടി ചെയ്തിരുന്നില്ല. അങ്ങനെ അദ്ദേഹം അബൂബക്കർ(റ)വിലേക്ക് ഇപ്രകാരം പറഞ്ഞുകൊണ്ട് ഒരാളെ അയച്ചു: താങ്കൾ എന്റെ അടുക്കൽ വരിക, കൂടെ മറ്റാരെയും കൂട്ടി വരരുത് - ഉമർ(റ)വിന്റെ വരവ് വെറുത്തതിനാലാണ് ഇപ്രകാരം പറഞ്ഞത് - അപ്പോൾ ഉമർ(റ) അബൂബക്കർ(റ)വിനോട് പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, താങ്കൾ ഒരിക്കലും ഒറ്റക്ക് അവരുടെ അടുക്കൽ ചെല്ലരുത്. അപ്പോൾ അബൂബക്കർ(റ) പറഞ്ഞു: അവർ എന്നെ എന്തു ചെയ്യാനാണ്. അല്ലാഹുവാണ് സത്യം, ഞാൻ അവരുടെയടുത്ത് പോകുക തന്നെ ചെയ്യും. അങ്ങനെ അബൂബക്കർ(റ) അവരുടെയടുത്ത് വന്നു. അലി(റ) സാക്ഷ്യവചനം ചൊല്ലി. ശേഷം ഇപ്രകാരം പറഞ്ഞു: അബൂബക്റേ, തീർച്ചയായും താങ്കളുടെ ശ്രേഷ്ഠതയും അല്ലാഹു താങ്കൾക്ക് നൽകിയ(ഔന്നത്യം)തിനെയും ഞങ്ങൾക്കറിയാം, അല്ലാഹു താങ്കൾക്ക് നൽകിയ ഒരു നന്മ കാരണത്താലും ഞങ്ങൾ താങ്കളോട് അസൂയപ്പെട്ടിട്ടുമില്ല. പക്ഷേ, താങ്കൾ (നമുക്കിടയിലെ) പ്രശ്നത്തിൽ ഞങ്ങളോട് സ്വേഛാധിപത്യം കാട്ടി. ഞങ്ങളാണെങ്കിൽ, റസൂൽ(സ)യോടുള്ള ഞങ്ങളുടെ കുടുംബബന്ധം കാരണം ഞങ്ങൾക്കൊരു അവകാശത്തെക്കാണാറുണ്ടായിരുന്നു. അങ്ങനെ അലി(റ) അബൂബക്കർ(റ)വിനോട് സംസാരിച്ച് കൊണ്ടേയിരിക്കുകയും, അബൂബക്കർ(റ)വിന്റെ കണ്ണുകൾ നിറഞ്ഞൊഴുകുകയും ചെയ്തു. അങ്ങനെ അബൂബക്കർ(റ) സംസാരിച്ചുകൊണ്ട് പറഞ്ഞു: എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവൻ തന്നെ സത്യം, എന്റെ കുടുംബ ബന്ധം ചേർക്കുന്നതിനേക്കാൾ എനിക്കിഷ്ടം റസൂൽ(സ)യുടെ കുടുംബബന്ധം ചേർക്കലാണ്. പക്ഷേ, ഈ സമ്പത്തിന്റെ വിഷയത്തിൽ എന്റെയും നിങ്ങളുടെയും ഇടയിൽ ഉണ്ടായിട്ടുള്ള പ്രശ്നത്തിൽ ഞാനൊരിക്കലും സത്യത്തിൽനിന്ന് വ്യതിചലിച്ചിട്ടില്ല. റസൂൽ(സ) ചെയ്യുന്നതായി ഞാൻ കണ്ട ഒരു കാര്യത്തെയും ചെയ്തിട്ടല്ലാതെ ഞാൻ ഉപേക്ഷിക്കുകയില്ല. അപ്പോൾ അലി(റ) അബൂബക്കർ(റ)വിനോട് പറഞ്ഞു: ഉടമ്പടിക്കായി താങ്കൾക്ക് നിശ്ചയിച്ച സമയം സന്ധ്യാസമയമാണ്. അങ്ങനെ, അബൂബക്കർ(റ) ളുഹ്ർ നമസ്കാരം നിസ്കരിച്ച് കഴിഞ്ഞപ്പോൾ മിമ്പറിൽ കയറുകയും സാക്ഷ്യവചനം ചൊല്ലുകയും, അലി(റ)വിനെക്കുറിച്ചും അദ്ദേഹം ഉടമ്പടിയിൽ നിന്ന് പിന്തിയതിനെക്കുറിച്ചും പറയുകയും ചെയ്തു. അലി(റ) അദ്ദേഹത്തോട് പറഞ്ഞ കാരണം അദ്ദേഹം പറയുകയും പിന്നെ പൊറുക്കലിനെ തേടുകയും ചെയ്തു. അപ്പോൾ അലിയ്യുബ്നു അബീത്വാലിബ്(റ) സാക്ഷ്യവചനം ചൊല്ലുകയും അബൂബക്കർ(റ)വിന്റെ മഹത്വം പറയുകയും ചെയ്തു. ശേഷം പറഞ്ഞു: താൻ ചെയ്ത ഈ പ്രവർത്തനത്തിന് തന്നെ പ്രേരിപ്പിച്ചത് അബൂബക്കർ(റ)വിനോടുള്ള അസൂയയോ, അല്ലാഹു അദ്ദേഹത്തിന് നൽകിയ ശ്രേഷ്ഠതയോടുള്ള നിഷേധമോ അല്ല. മറിച്ച്, നമുക്കിടയിലെ ഈ വിഷയത്തിൽ ഞങ്ങൾക്കൊരു വിഹിതമുണ്ടെന്ന് ഞങ്ങൾ മനസ്സിലാക്കിയിരുന്നു. എന്നാൽ അവ്വിഷയകമായി ഞങ്ങളോട് സ്വേഛാധിപത്യപരമായി പെരുമാറപ്പെട്ടു. അതിനാൽ ഞങ്ങൾക്ക് ഞങ്ങളുടെ മനസ്സിൽ വെറുപ്പുളവായി. അപ്പോൾ (അലി(റ) സംസാരിച്ചു കഴിഞ്ഞപ്പോൾ) മുസ്ലിംകൾ അതിയായി സന്തോഷിച്ചു. അവർ പറഞ്ഞു: താങ്കൾ പറഞ്ഞത് ശരിയാണ്. അലി(റ) നല്ല രീതിയിൽ പ്രശ്നം അവസാനിപ്പിച്ച സമയത്ത് മുസ്ലിംകളെല്ലാം അലി(റ)വിനോട് (മാനസികമായി) അടുത്തവരായിരുന്നു. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], 'إِنِّي', null, 93, 95, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَقْتَسِمُ وَرَثَتِي دِينَارًا، مَا تَرَكْتُ بَعْدَ نَفَقَة نسائي ومَئُونَة عاملي فهو صَدَقَةٌ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ അനന്തരസ്വത്ത് ദീനാറുകളായി വീതിക്കപ്പെടരുത്. എന്റെ ഭാര്യമാരുടെ ചെലവും എന്റെ ജോലിക്കാരുടെ കൂലിയും കഴിച്ച് ബാക്കിവന്നത് സ്വദഖയാണ്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 95, 95, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ جَاءَ هُوَ وَعُثْمَانُ بْنُ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ يُكَلِّمَانِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيمَا قَسَمَ مِنَ الْخُمُسِ بَيْنَ بَنِي هَاشِمٍ وَبَنِي الْمُطَّلِبِ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، قَسَمْتَ لِإِخْوَانِنَا بَنِي الْمُطَّلِبِ، وَلَمْ تُعْطِنَا شَيْئًا، وَقَرَابَتُنَا وَقَرَابَتُهُمْ مِنْكَ وَاحِدَةٌ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا بَنُو هَاشِمٍ وَبَنُو الْمُطَّلِبِ شَيْءٌ وَاحِدٌ". قَالَ جُبَيْرٌ: وَلَمْ يَقْسِمْ لِبَنِي عَبْدِ شَمْسٍ وَلَا لِبَنِي نَوْفَلٍ مِنْ ذَلِكَ الْخُمُسِ كَمَا قَسَمَ لِبَنِي هَاشِمٍ وَبَنِي الْمُطَّلِبِ. قَالَ: وَكَانَ أَبُو بَكْرٍ يَقْسِمُ الْخُمُسَ نَحْوَ قَسْمِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، غَيْرَ أَنَّهُ لَمْ يَكُنْ يُعْطِي قُرْبَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعْطِيهِمْ. قَالَ: وَكَانَ عُمَرُ بْنُ الْخَطَّابِ يُعْطِيهِمْ مِنْهُ، وَعُثْمَانُ بَعْدَهُ. (خ,د,ن,جه)', 'ജുബൈറുബ്നു മുത്ഇം(റ): അഞ്ചിലൊന്ന് വിഹിതത്തിൽനിന്ന് ഹാശിം സന്തതികൾക്കും മുത്വലിബ് സന്തതികൾക്കും വീതിച്ചു നൽകപ്പെട്ടതിനെക്കുറിച്ച് സംസാരിക്കാൻവേണ്ടി അദ്ദേഹവും ഉസ്മാനുബ്നു അഫാൻ(റ)വും റസൂൽ(സ)യുടെ അടുത്ത് ചെന്നു. ജുബൈർ(റ) പറയുന്നു: ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങളുടെ സഹോദരങ്ങളായ മുത്വലിബ് സന്തതികൾക്ക് അവിടുന്ന് വിഹിതം നൽകിയിരിക്കുന്നു, എന്നാൽ ഞങ്ങൾക്ക് ഒന്നുംതന്നെ നൽകിയിട്ടില്ല. ഞങ്ങളുടെയും അവരുടെയും (അവിടുത്തോടുള്ള) കുടുംബബന്ധം ഒന്നുതന്നെയാണല്ലോ? നബി(സ) പറഞ്ഞു: "ഹാശിം സന്തതികളും മുത്വലിബ് സന്തതികളും ഒന്നു തന്നെയാണ്." ജുബൈർ(റ) പറയുന്നു: ഹാശിം സന്തതികൾക്കും മുത്വലിബ് സന്തതികൾക്കും റസൂൽ(സ) അഞ്ചിലൊന്നിൽ നിന്നുള്ള വിഹിതം നൽകിയിരുന്നതുപോലെ അബ്ദുശ്ശംസ് സന്തതികൾക്കും നൗഫൽ സന്തതികൾക്കും വിഹിതം നൽകിയിരുന്നില്ല. നിവേദകൻ പറയുന്നു: റസൂൽ(സ) അഞ്ചിലൊന്ന് വിഹിതം വെച്ചിരുന്നതുപോലെ തന്നെയായിരുന്നു അബൂബക്കർ(റ)വും വിഹിതം വെച്ചിരുന്നത്. എന്നാൽ റസൂൽ(സ) നൽകാറുണ്ടായിരുന്നതുപോലെ അദ്ദേഹം റസൂൽ(സ)യുടെ കുടുംബങ്ങൾക്ക് നൽകാറുണ്ടായിരുന്നില്ല. നിവേദകൻ പറയുന്നു: ഉമർ(റ)വും അദ്ദേഹത്തിനുശേഷം ഉസ്മാൻ(റ)വും അവർക്ക് അതിൽനിന്ന് വിഹിതം നൽകാറുണ്ടായിരുന്നു. (ബു,ദ,ന,ജ)', 'جُبَيْرِ بْنِ مُطْعِمٍ', 'ജുബൈറുബ്നു മുത്ഇം(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 95, 96, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'وَعَنْهُ قَالَ: لَمَّا كَانَ يَوْمُ خَيْبَرَ وَضَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَهْمَ ذِي الْقُرْبَى فِي بَنِي هَاشِمٍ وَبَنِي الْمُطَّلِبِ، وَتَرَكَ بَنِي نَوْفَلٍ وَبَنِي عَبْدِ شَمْسٍ، فَانْطَلَقْتُ أَنَا وَعُثْمَانُ بْنُ عَفَّانَ حَتَّى أَتَيْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْنَا: يَا رَسُولَ اللَّهِ، هَؤُلَاءِ بَنُو هَاشِمٍ، لَا نُنْكِرُ فَضْلَهُمْ لِلْمَوْضِعِ الَّذِي وَضَعَكَ اللَّهُ بِهِ مِنْهُمْ، فَمَا بَالُ إِخْوَانِنَا بَنِي الْمُطَّلِبِ أَعْطَيْتَهُمْ وَتَرَكْتَنَا، وَقَرَابَتُنَا وَاحِدَةٌ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّا وَبَنُو الْمُطَّلِبِ لَا نَفْتَرِقُ فِي جَاهِلِيَّةٍ وَلَا إِسْلَامٍ، وَإِنَّمَا نَحْنُ وَهُمْ شَيْءٌ وَاحِدٌ" وَشَبَّكَ بَيْنَ أَصَابِعِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (د)', 'ജുബൈറുബ്നു മുത്ഇം(റ): ഖൈബർ ദിവസം റസൂൽ(സ) തന്റെ കുടുംബങ്ങൾക്കുള്ള വിഹിതത്തെ മുത്വലിബ് സന്തതികൾക്കും ഹാശിം സന്തതികൾക്കും നൽകി. അബ്ദുശ്ശംസ് സന്തതികളെയും നൗഫൽ സന്തതികളെയും അവിടുന്ന് (അതിൽനിന്ന്) ഒഴിവാക്കുകയും ചെയ്തു. അങ്ങനെ ഞാനും ഉസ്മാനുബ്നു അഫാൻ(റ)വും റസൂൽ(സ)യുടെ അടുത്ത് ചെന്നു. ഞങ്ങൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഹാശിം സന്തതികളിൽ അല്ലാഹു അങ്ങയെ ഉൾപെടുത്തിയതു മുഖേന അവർക്കുണ്ടായ ശ്രേഷ്ഠതയെ ഞങ്ങൾ നിഷേധിക്കുന്നില്ല. എന്നാൽ ഞങ്ങളുടെ സഹോദരങ്ങളായ മുത്വലിബ് സന്തതികളുടെ അവസ്ഥയെന്താണ്, ഞങ്ങളുടെയെല്ലാം (അവിടുത്തോടുള്ള) കുടുംബബന്ധം ഒന്നായിരിക്കെത്തന്നെ അങ്ങ് അവർക്ക് നൽകുകയും ഞങ്ങളെ ഒഴിവാക്കുകയും ചെയ്തിരിക്കുന്നുവല്ലോ? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം, ഞങ്ങളും മുത്വലിബ് സന്തതികളും അജ്ഞാനകാലത്തോ ഇസ്ലാമിലോ വേർപിരിയുകയില്ല. നിശ്ചയം ഞങ്ങളും അവരും ഒന്നുതന്നെയാണ്." റസൂൽ(സ) അവിടുത്തെ വിരലുകൾ കോർത്തു പിടിച്ചു. (ദ)', null, 'ജുബൈറുബ്നു മുത്ഇം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 96, 96, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ يَزِيدَ بْنِ هُرْمُزَ: أَنَّ نَجْدَةَ الْحَرُورِيَّ حِينَ حَجَّ فِي فِتْنَةِ ابْنِ الزُّبَيْرِ أَرْسَلَ إِلَى ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا يَسْأَلُهُ عَنْ سَهْمِ ذِي الْقُرْبَى، وَيَقُولُ: لِمَنْ تَرَاهُ؟ قَالَ ابْنُ عَبَّاسٍ: لِقُرْبَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَسَمَهُ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَدْ كَانَ عُمَرُ عَرَضَ عَلَيْنَا مِنْ ذَلِكَ عَرْضًا رَأَيْنَاهُ دُونَ حَقِّنَا، فَرَدَدْنَاهُ عَلَيْهِ وَأَبَيْنَا أَنْ نَقْبَلَهُ. (د,ن)', 'യസീദുബ്നു ഹുർമുസ്(റ): ഇബ്നുസുബൈർ(റ)വിന്റെ കാലത്തെ കുഴപ്പങ്ങളുടെ സമയത്ത് നജ്ദതുൽ ഹറൂരി ഹജ്ജിനു ചെന്നപ്പോൾ (റസൂൽ(സ)യുടെ) കുടുംബങ്ങൾക്കുള്ള വിഹിതത്തെക്കുറിച്ച് ചോദിച്ചുകൊണ്ട് അദ്ദേഹം ഇബ്നുഅബ്ബാസ്(റ)വിന്റെ അടുത്തേക്ക് ആളെ അയച്ചു. അദ്ദേഹത്തിന്റെ ചോദ്യമിതായിരുന്നു: അത് ആർക്കാണെന്നാണ് താങ്കളുടെ അഭിപ്രായം? ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: റസൂൽ(സ)യുടെ കുടുംബങ്ങൾക്കുള്ളതാണ്. റസൂൽ(സ) അവർക്കാണത് വീതിച്ചു നൽകിയത്. ഞങ്ങളുടെ അവകാശങ്ങളേക്കാൾ കുറഞ്ഞതെന്ന് ഞങ്ങൾ മനസ്സിലാക്കിയ ഒരു വിഹിതം ഞങ്ങൾക്ക് നൽകാൻ ഉമർ(റ) തയ്യാറായി. എന്നാൽ ഞങ്ങളത് തിരിച്ചു നൽകുകയും സ്വീകരിക്കാൻ വിസമ്മതിക്കുകയും ചെയ്തു. (ദ,ന)', 'يَزِيدَ بْنِ هُرْمُزَ', 'യസീദുബ്നു ഹുർമുസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 96, 96, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: وَلَّانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خُمُسَ الْخُمُسِ، فَوَضَعْتُهُ مَوَاضِعَهُ حياة رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَحَيَاةَ أَبِي بَكْرٍ، وَحَيَاةَ عُمَرَ، فَأُتِيَ بِمَالٍ فَدَعَانِي، فَقَالَ: خُذْهُ، فَقُلْتُ: لَا أُرِيدُهُ، قَالَ: خُذْهُ فَأَنْتُمْ أَحَقُّ بِهِ، قُلْتُ: قَدِ اسْتَغْنَيْنَا عَنْهُ، فَجَعَلَهُ فِي بَيْتِ الْمَالِ. (د)', 'അലി(റ): അഞ്ചിലൊന്നിൽ നിന്നുള്ള അഞ്ചിലൊന്നിന്റെ ഉത്തരവാദിത്തം റസൂൽ(സ) എന്നെ ഏൽപിച്ചു. റസൂൽ(സ)യുടെ ജീവിത കാലത്തും അബൂബക്ർ(റ)വിന്റെയും ഉമർ(റ)വിന്റെയും ജീവിത കാലങ്ങളിലും ഞാനത് വെക്കേണ്ട സ്ഥാനങ്ങളിൽ വെച്ചു. ശേഷം ഉമർ(റ)വിന്റെ അടുത്ത് ഒരു മുതൽ എത്തിയപ്പോൾ അദ്ദേഹം എന്നെ വിളിച്ചിട്ട് പറഞ്ഞു: അത് താങ്കൾ എടുക്കുക. ഞാൻ പറഞ്ഞു: അത് ഞാൻ ആഗ്രഹിക്കുന്നില്ല. അദ്ദേഹം പറഞ്ഞു: അതെടുക്കുക, നിങ്ങളാണതിന് അവകാശപ്പെട്ടവർ. ഞാൻ പറഞ്ഞു: ഞങ്ങൾക്കത് ആവശ്യമില്ലാതായിരിക്കുന്നു. അങ്ങനെ ഉമർ(റ) അത് പൊതു ഖജനാവിൽ നിക്ഷേപിച്ചു. (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 97, 97, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: اجْتَمَعْتُ أَنَا وَالْعَبَّاسُ وَفَاطِمَةُ وَزَيْدُ بْنُ حَارِثَةَ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنْ رَأَيْتَ أَنْ تُوَلِّيَنِي حَقَّنَا مِنْ هَذَا الْخُمُسِ فِي كِتَابِ اللَّهِ، فَأَقْسِمَهُ حَيَاتَكَ، كَيْ لَا يُنَازِعَنِي أَحَدٌ بَعْدَكَ، فَافْعَلْ. قَالَ: فَفَعَلَ ذَلِكَ، قَالَ: فَقَسَمْتُهُ حَيَاةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ وَلَّانِيهِ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ، حَتَّى إِذَا كَانَتْ آخِرُ سَنَةٍ مِنْ سِنِي عُمَرَ رَضِيَ اللَّهُ عَنْهُ فَإِنَّهُ أَتَاهُ مَالٌ كَثِيرٌ، فَعَزَلَ حَقَّنَا، ثُمَّ أَرْسَلَ إِلَيَّ، فَقُلْتُ: بِنَا عَنْهُ الْعَامَ غِنًى، وَبِالْمُسْلِمِينَ إِلَيْهِ حَاجَةٌ، فَارْدُدْهُ عَلَيْهِمْ. فَرَدَّهُ عَلَيْهِمْ، ثُمَّ لَمْ يَدْعُنِي إِلَيْهِ أَحَدٌ بَعْدَ عُمَرَ، فَلَقِيتُ الْعَبَّاسَ بَعْدَمَا خَرَجْتُ مِنْ عِنْدِ عُمَرَ، فَقَالَ: يَا عَلِيُّ، حَرَمْتَنَا الْغَدَاةَ شَيْئًا لَا يُرَدُّ عَلَيْنَا أَبَدًا، وَكَانَ رَجُلًا دَاهِيًا. (د)', 'അലി(റ): ഞാനും അബ്ബാസ്(റ)വും ഫാതിമ(റ)യും സൈദുബ്നു ഹാരിസ(റ)വും നബി(സ)യുടെ സന്നിധിയിൽ ഒരുമിച്ചുകൂടി. ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിൽ പ്രതിപാദിക്കപ്പെട്ട അഞ്ചിലൊന്നിൽ നിന്നുള്ള ഞങ്ങളുടെ അവകാശത്തിന്റെ ഉത്തരവാദിത്തം, അവിടുത്തെ കാലശേഷം എന്നോടൊരാളും തർക്കിക്കാത്ത വിധം, എന്നെ ഏൽപിക്കണമെന്നും അവിടുത്തെ ജീവിത കാലത്ത് ഞാനത് വീതിക്കണമെന്നും അവിടുത്തേക്ക് അഭിപ്രായമുണ്ടെങ്കിൽ അങ്ങനെ ചെയ്താലും. അലി(റ) പറയുന്നു: അപ്പോൾ റസൂൽ(സ) അങ്ങനെ ചെയ്തു. അലി(റ) പറയുന്നു: അങ്ങനെ റസൂൽ(സ)യുടെ കാലത്ത് ഞാനത് വീതിച്ചു. ശേഷം അബൂബക്ർ(റ)വും എന്നെ അത് ഏൽപിച്ചു. പിന്നീട് ഉമർ(റ)വിന്റെ ഭരണത്തിന്റെ അവസാന വർഷം ധാരാളം സമ്പത്ത് അദ്ദേഹത്തിനടുത്ത് എത്തുകയും അദ്ദേഹം ഞങ്ങളുടെ അവകാശം പിൻവലിക്കുകയും ശേഷം എന്റെ അടുത്തേക്ക് ആളെ അയക്കുകയും ചെയ്തു. ഞാൻ പറഞ്ഞു: ഈ വർഷം അത് ആവശ്യമില്ലാത്ത വിധം ഞങ്ങൾക്ക് ഐശ്വര്യമുണ്ട്, മുസ്ലിംകൾക്കാണെങ്കിൽ അത് ആവശ്യവുമുണ്ട്. അതിനാൽ അത് മുസ്ലിംകൾക്ക് നൽകുക.. അപ്പോൾ ഉമർ(റ) അത് മുസ്ലിംകൾക്ക് നൽകി. ഉമർ(റ)വിനു ശേഷം ഒരാളും എന്നെ അതിനുവേണ്ടി ക്ഷണിച്ചിട്ടില്ല. ഉമർ(റ)വിന്റെ അടുത്തുനിന്ന് പുറത്തു വന്നപ്പോൾ ഞാൻ അബ്ബാസ്(റ)വിനെ കണ്ടു. അദ്ദേഹം പറഞ്ഞു: അലീ, ഇന്നു പ്രഭാതത്തിൽ ഒരു കാര്യത്തെ താങ്കൾ ഞങ്ങൾക്ക് വിലക്കിയിരിക്കുന്നു. ഇനിയൊരിക്കലും നമുക്ക് അത് തിരിച്ചു നൽകപ്പെടുകയില്ല. അബ്ബാസ്(റ) കൂർമ്മ ബുദ്ധിയുള്ളവരായിരുന്നു. (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 97, 97, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ عَبْدِ الْمُطَّلِبِ بْنِ رَبِيعَةَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ أَبَاهُ رَبِيعَةَ بْنَ الْحَارِثِ، وَعَبَّاسَ بْنَ عَبْدِ الْمُطَّلِبِ قَالَا لِعَبْدِ الْمُطَّلِبِ بْنِ رَبِيعَةَ، وَلِلْفَضْلِ بْنِ عَبَّاسٍ: ائْتِيَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُولَا لَهُ: يَا رَسُولَ اللَّهِ، قَدْ بَلَغْنَا مِنَ السِّنِّ مَا تَرَى، وَأَحْبَبْنَا أَنْ نَتَزَوَّجَ، وَأَنْتَ يَا رَسُولَ اللَّهِ أَبَرُّ النَّاسِ وَأَوْصَلُهُمْ، وَلَيْسَ عِنْدَ أَبَوَيْنَا مَا يُصْدِقَانِ عَنَّا، فَاسْتَعْمِلْنَا يَا رَسُولَ اللَّهِ عَلَى الصَّدَقَاتِ، فَلْنُؤَدِّ إِلَيْكَ مَا يُؤَدِّي الْعُمَّالُ، وَلْنُصِبْ مَا كَانَ فِيهَا مِنْ مَرْفَقٍ. قَالَ: فَأَتَى عَلِيُّ بْنُ أَبِي طَالِبٍ وَنَحْنُ عَلَى تِلْكَ الْحَالِ، فَقَالَ لَنَا: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – لَا وَاللَّهِ – لَا يَسْتَعْمِلُ مِنْكُمْ أَحَدًا عَلَى الصَّدَقَةِ. فَقَالَ لَهُ رَبِيعَةُ: هَذَا مِنْ أَمْرِكَ، قَدْ نِلْتَ صِهْرَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمْ نَحْسُدْكَ عَلَيْهِ. فَأَلْقَى عَلِيٌّ رِدَاءَهُ، ثُمَّ اضْطَجَعَ عَلَيْهِ، فَقَالَ: أَنَا أَبُو حَسَنٍ الْقَرْمُ، وَاللَّهِ لَا أَرِيمُ حَتَّى يَرْجِعَ إِلَيْكُمَا بِجَوَابِ مَا بَعَثْتُمَا بِهِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ عَبْدُ الْمُطَّلِبِ: فَانْطَلَقْتُ أَنَا وَالْفَضْلُ إِلَى بَابِ حُجْرَةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، حَتَّى نُوَافِقَ صَلَاةَ الظُّهْرِ قَدْ قَامَتْ، فَصَلَّيْنَا مَعَ النَّاسِ، ثُمَّ أَسْرَعْتُ أَنَا وَالْفَضْلُ إِلَى بَابِ حُجْرَةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهُوَ يَوْمَئِذٍ عِنْدَ زَيْنَبَ بِنْتِ جَحْشٍ، فَقُمْنَا بِالْبَابِ حَتَّى أَتَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَخَذَ بِأُذُنِي وَأُذُنِ الْفَضْلِ، ثُمَّ قَالَ: "أَخْرِجَا مَا تُصَرِّرَانِ". ثُمَّ دَخَلَ فَأَذِنَ لِي وَلِلْفَضْلِ، فَدَخَلْنَا، فَتَوَاكَلْنَا الْكَلَامَ قَلِيلًا، ثُمَّ كَلَّمْتُهُ، أَوْ كَلَّمَهُ الْفَضْلُ، قَالَ: كَلَّمَهُ بِالْأَمْرِ الَّذِي أَمَرَنَا بِهِ أَبَوَانَا، فَسَكَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَاعَةً وَرَفَعَ بَصَرَهُ قِبَلَ سَقْفِ الْبَيْتِ حَتَّى طَالَ عَلَيْنَا: أَنَّهُ لَا يَرْجِعُ إِلَيْنَا شَيْئًا، حَتَّى رَأَيْنَا زَيْنَبَ تَلْمَعُ مِنْ وَرَاءِ الْحِجَابِ بِيَدِهَا، تُرِيدُ أَنْ لَا تَعْجَلَا، وَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي أَمْرِنَا، ثُمَّ خَفَضَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأْسَهُ، فَقَالَ لَنَا: "إِنَّ هَذِهِ الصَّدَقَةَ إِنَّمَا هِيَ أَوْسَاخُ النَّاسِ، وَإِنَّهَا لَا تَحِلُّ لِمُحَمَّدٍ وَلَا لِآلِ مُحَمَّدٍ، ادْعُوا لِي نَوْفَلَ بْنَ الْحَارِثِ". فَدُعِيَ لَهُ نَوْفَلُ بْنُ الْحَارِثِ، فَقَالَ: "يَا نَوْفَلُ، أَنْكِحْ عَبْدَ الْمُطَّلِبِ". فَأَنْكَحَنِي نَوْفَلٌ، ثُمَّ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ادْعُوا لِي مَحْمِئَةَ بْنَ جَزْءٍ". وَهُوَ رَجُلٌ مِنْ بَنِي زُبَيْدٍ، كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْتَعْمَلَهُ عَلَى الْأَخْمَاسِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِمَحْمِئَةَ: "أَنْكِحِ الْفَضْلَ". فَأَنْكَحَهُ، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قُمْ فَأَصْدِقْ عَنْهُمَا مِنَ الْخُمُسِ كَذَا وَكَذَا". (م,د)', 'അബ്ദുൽ മുത്വലിബുബ്നു റബീഅ(റ): അദ്ദേഹത്തിന്റെ പിതാവ് റബീഅതബ്നു ഹാരിസ്(റ)വും അബ്ബാസുബ്നു അബ്ദിൽ മുത്വലിബ്(റ)വും ഫള്ലുബ്നു അബ്ബാസ്(റ)വിനോടും അബ്ദുൽ മുത്വലിബുബ്നു റബീഅ(റ)വിനോടും ഇപ്രകാരം പറഞ്ഞു: നിങ്ങൾ രണ്ടുപേരും റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് ഇപ്രകാരം പറയുക: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങൾക്ക് എത്ര പ്രായമായെന്ന് അവിടുത്തേക്കറിയാമല്ലോ, ഞങ്ങൾ വിവാഹം കഴിക്കാൻ ആഗ്രഹിക്കുന്നു, അല്ലാഹുവിന്റെ റസൂലേ, അവിടുന്ന് ജനങ്ങളിൽവെച്ച് ഏറ്റവും ഗുണം ചെയ്യുന്നവരും ഏറ്റവും കൂടുതൽ കുടുംബബന്ധം ചേർക്കുന്നവരുമാണ്. ഞങ്ങൾക്ക് മഹ്റ് നൽകാൻ വേണ്ട ധനം ഞങ്ങളുടെ പിതാക്കളുടെ പക്കലില്ല. അതിനാൽ അല്ലാഹുവിന്റെ റസൂലേ, സകാത് പിരിക്കാനുള്ള ഉദ്യോഗസ്ഥരായി അവിടുന്ന് ഞങ്ങളെ നിയമിച്ചാലും. മറ്റു ഉദ്യോഗസ്ഥർ നൽകുന്നത് ഞങ്ങൾ അങ്ങേക്ക് നൽകുകയും അതിൽനിന്നുള്ള ആനുകൂല്യങ്ങൾ ഞങ്ങൾക്ക് ലഭിക്കുകയും ചെയ്യും. നിവേദകൻ പറയുന്നു: ഞങ്ങൾ അങ്ങനെ നിൽക്കുമ്പോൾ അലിയ്യുബ്നു അബീത്വാലിബ്(റ) കടന്നുവന്നു. അദ്ദേഹം ഞങ്ങളോട് പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, നിശ്ചയം റസൂൽ(സ) നിങ്ങളിൽ ആരെയും സകാത് പിരിക്കാനുള്ള ഉദ്യോഗസ്ഥരായി നിയമിക്കുകയില്ല. അപ്പോൾ റബീഅ(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: ഇതാണോ താങ്കളുടെ അവസ്ഥ, താങ്കൾ റസൂൽ(സ)യുടെ മരുമകനായി, അക്കാര്യത്തിൽ ഞങ്ങൾ താങ്കളോട് അസൂയ വെച്ചിട്ടില്ല. അപ്പോൾ അലി(റ) തന്റെ തട്ടം നിലത്തിട്ട് അതിന്മേൽ കിടന്നു, എന്നിട്ട് പറഞ്ഞു: ഞാൻ കാര്യങ്ങൾ മുൻകൂട്ടിക്കാണുന്ന അബൂഹസൻ (ഹസന്റെ പിതാവ്) ആണ്. അല്ലാഹുവാണ് സത്യം, നിങ്ങൾ രണ്ടുപേരും നബി(സ)യുടെ അടുത്തേക്കയച്ച കാര്യത്തിനുള്ള മറുപടി എത്തുന്നതുവരെ ഞാനിവിടെ നിന്നും പോവുകയില്ല. അബ്ദുൽമുത്വലിബ്(റ) പറയുന്നു: അങ്ങനെ ഞാനും ഫള്ൽ(റ)വും നബി(സ)യുടെ വീടിന്റെ വാതിലിനടുത്ത് ചെന്നു. ളുഹർ നമസ്കാരത്തിന് ഇഖാമത് കൊടുത്ത സമയമായിരുന്നു അത്. ഞങ്ങൾ ജനങ്ങളോടൊപ്പം നമസ്കരിക്കുകയും ശേഷം ഞാനും ഫള്ൽ(റ)വും ധൃതിയിൽ നബി(സ)യുടെ വീടിന്റെ വാതിലിനടുത്തേക്ക് ചെല്ലുകയും ചെയ്തു. അന്ന് നബി(സ) സൈനബുബിൻതു ജഹ്ഷ്(റ)യുടെ അടുത്തായിരുന്നു. ഞങ്ങൾ വാതിൽക്കൽ നിൽക്കുകയും റസൂൽ(സ) വരികയും ചെയ്തു. അവിടുന്ന് എന്റെയും ഫള്ൽ(റ)വിന്റെയും ചെവിയിൽ പിടിച്ചുകൊണ്ട് പറഞ്ഞു: "നിങ്ങളുടെ മനസ്സുകളിലുള്ളത് തുറന്നുപറയുക." ശേഷം റസൂൽ(സ) ഉള്ളിൽ പ്രവേശിക്കുകയും അവിടുന്ന് എനിക്കും ഫള്ൽ(റ)വിനും അനുവാദം നൽകിയതു പ്രകാരം ഞങ്ങൾ ഉള്ളിൽ പ്രവേശിക്കുകയും ചെയ്തു. അൽപനേരം ആരു സംസാരിക്കണം എന്ന സംശയത്തിൽ ഞങ്ങളവിടെ നിന്നു. ശേഷം ഞാൻ അവിടുത്തോട് സംസാരിച്ചു, അല്ലെങ്കിൽ ഫള്ൽ(റ) സംസാരിച്ചു. നിവേദകൻ പറയുന്നു: ഞങ്ങളുടെ ബാപ്പമാർ ഞങ്ങളോട് പറഞ്ഞിരുന്ന വിഷയം അദ്ദേഹം അവിടുത്തോട് സംസാരിച്ചു. അപ്പോൾ റസൂൽ(സ) കുറേ സമയം മൗനമവലംബിക്കുകയും വീടിന്റെ മേൽക്കൂരയുടെ ഭാഗത്തേക്ക് തന്റെ കാഴ്ചയുയർത്തി കുറേ സമയം നിൽക്കുകയും ചെയ്തു. അവിടുന്ന് ഞങ്ങളോടൊന്നും മറുപടി പറയുകയില്ലേ എന്നുപോലും ഞങ്ങൾ ശങ്കിച്ചു. അപ്പോൾ സൈനബ്(റ) വിരിക്കപ്പുറത്തു നിന്നും ആംഗ്യം കാണിക്കുന്നത് ഞങ്ങൾ കണ്ടു. ഞങ്ങൾ ധൃതി കാണിക്കേണ്ടെന്നും ഞങ്ങളുടെ കാര്യമാണ് റസൂൽ(സ) ശ്രദ്ധിക്കുന്നതെന്നുമാണ് മഹതി ഉദ്ദേശിച്ചത്. ശേഷം റസൂൽ(റ) തന്റെ തല താഴ്ത്തി, എന്നിട്ട് പറഞ്ഞു: "നിശ്ചയം ഈ സകാത് ജനങ്ങളുടെ മാലിന്യങ്ങളാണ്, അവ മുഹമ്മദിനോ മുഹമ്മദിന്റെ കുടുംബത്തിനോ അനുവദനീയമാവുകയില്ല. എനിക്കുവേണ്ടി നിങ്ങൾ നൗഫലുബ്നു ഹാരിസിനെ വിളിക്കുക." അപ്പോൾ അവിടുത്തേക്കുവേണ്ടി നൗഫലുബ്നു ഹാരിസ്(റ)വിനെ വിളിക്കപ്പെട്ടു. അവിടുന്ന് പറഞ്ഞു: "നൗഫലേ, നീ അബ്ദുൽമുത്വലിബിനെ വാവാഹം കഴിപ്പിക്കുക." അങ്ങനെ നൗഫൽ(റ) എന്നെ വിവാഹം കഴിപ്പിച്ചു. ശേഷം നബി(സ) പറഞ്ഞു: "എനിക്കുവേണ്ടി മഹ്മിഅതുബ്നു ജസ്ഇനെ വിളിക്കുക." ബനൂസുബൈദിൽപെട്ട ആളാണദ്ദേഹം. അഞ്ചിലൊന്നിനോട് ബന്ധപ്പെട്ട കാര്യങ്ങളിൽ റസൂൽ(സ) അദ്ദേഹത്തെ ഉദ്യോഗമേൽപിച്ചിരുന്നു. റസൂൽ(സ) മഹ്മിഅഃ(റ)വിനോട് പറഞ്ഞു: "ഫള്ലിനെ നീ വിവാഹം കഴിപ്പിക്കുക." അങ്ങനെ അദ്ദേഹം ഫള്ൽ(റ)വിനെ വിവാഹം കഴിപ്പിച്ചു. ശേഷം റസൂൽ(സ) (അദ്ദേഹത്തോട്) പറഞ്ഞു: "നീ ചെന്ന് അവർ രണ്ടുപേർക്കുംവേണ്ടി അഞ്ചിലൊന്നിൽ നിന്ന് ഇത്രയും ഇത്രയും മഹ്റ് (വിവാഹമൂല്യം) നൽകുക." (മു,ദ)', 'عَبْدِ الْمُطَّلِبِ بْنِ رَبِيعَةَ', 'അബ്ദുൽ മുത്വലിബുബ്നു റബീഅ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 97, 99, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَتْ لِي شَارِفٌ مِنْ نَصِيبِي مِنَ الْمَغْنَمِ يَوْمَ بَدْرٍ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْطَانِي شَارِفًا مِنَ الْخُمُسِ يَوْمَئِذٍ، فَلَمَّا أَرَدْتُ أَنْ أَبْنِيَ بِفَاطِمَةَ بِنْتِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاعَدْتُ رَجُلًا صَوَّاغًا مِنْ بَنِي قَيْنُقَاعٍ أَنْ يَرْتَحِلَ مَعِي فَنَأْتِيَ بِإِذْخِرٍ، أَرَدْتُ أَنْ أَبِيعَهُ مِنَ الصَّوَّاغِينَ فَأَسْتَعِينَ بِهِ فِي وَلِيمَةِ عُرْسِي، فَبَيْنَا أَنَا أَجْمَعُ لِشَارِفَيَّ مَتَاعًا مِنَ الْأَقْتَابِ وَالْغَرَائِرِ وَالْحِبَالِ، وَشَارِفَايَ مُنَاخَانِ إِلَى جَنْبِ حُجْرَةِ رَجُلٍ مِنَ الْأَنْصَارِ، أَقْبَلْتُ حِينَ جَمَعْتُ مَا جَمَعْتُ، فَإِذَا بِشَارِفَيَّ: قَدِ اجْتُبَّتْ أَسْنِمَتُهُمَا وَبُقِرَتْ خَوَاصِرُهُمَا وَأُخِذَ مِنْ أَكْبَادِهِمَا، فَلَمْ أَمْلِكْ عَيْنَيَّ حِينَ رَأَيْتُ ذَلِكَ الْمَنْظَرَ، فَقُلْتُ: مَنْ فَعَلَ هَذَا؟ قَالُوا: فَعَلَهُ حَمْزَةُ بْنُ عَبْدِ الْمُطَّلِبِ، وَهُوَ فِي هَذَا الْبَيْتِ فِي شَرْبٍ مِنَ الْأَنْصَارِ، غَنَّتْهُ قَيْنَةٌ وَأَصْحَابَهُ، فَقَالَتْ فِي غِنَائِهَا: أَلَا يَا حَمْزُ لِلشُّرُفِ النِّوَاءِ. فَوَثَبَ إِلَى السَّيْفِ، فَاجْتَبَّ أَسْنِمَتَهُمَا وَبَقَرَ خَوَاصِرَهُمَا وَأَخَذَ مِنْ أَكْبَادِهِمَا، قَالَ عَلِيٌّ: فَانْطَلَقْتُ حَتَّى أَدْخُلَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعِنْدَهُ زَيْدُ بْنُ حَارِثَةَ، قَالَ: فَعَرَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الَّذِي لَقِيتُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا لَكَ". قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، مَا رَأَيْتُ كَالْيَوْمِ، عَدَا حَمْزَةُ عَلَى نَاقَتَيَّ، فَاجْتَبَّ أَسْنِمَتَهُمَا وَبَقَرَ خَوَاصِرَهُمَا، وَهَا هُوَ ذَا فِي بَيْتٍ مَعَهُ شَرْبٌ، فَدَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بردائه فَارْتَدَاهُ، ثُمَّ انْطَلَقَ يَمْشِي، وَاتَّبَعْتُهُ أَنَا وَزَيْدُ بْنُ حارثة حَتَّى جَاءَ الْبَيْتَ الَّذِي فيه حَمْزَةُ، فَاسْتَأْذَنَ فَأَذِنَ لَهُ، فَإِذَا هُمْ شَرْبٌ، فَطَفِقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَلُومُ حَمْزَةَ فِيمَا فَعَلَ، فَإِذَا حَمْزَةُ ثَمِلٌ مُحْمَرَّةٌ عَيْنَاهُ، فَنَظَرَ حَمْزَةُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ صَعَّدَ النَّظَرَ فَنَظَرَ إِلَى رُكْبَتَيْهِ، ثُمَّ صَعَّدَ النَّظَرَ فَنَظَرَ إِلَى سُرَّتِهِ، ثُمَّ صَعَّدَ النَّظَرَ فَنَظَرَ إلى وجهه، ثُمَّ قَالَ حَمْزَةُ: وَهَلْ أَنْتُمْ إِلَّا عَبِيدٌ لِأَبِي؟ فَعَرَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ ثَمِلٌ، فَنَكَصَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى عَقِبَيْهِ الْقَهْقَرَى، فَخَرَجَ وَخَرَجْنَا مَعَهُ. (ق,د)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): ബദർ യുദ്ധദിവസത്തെ യുദ്ധമുതലിൽനിന്ന് എനിക്ക് ലഭിച്ച വിഹിതത്തിൽ പ്രായംചെന്ന ഒരു പെണ്ണൊട്ടകമുണ്ടായിരുന്നു. അന്ന് അഞ്ചിലൊന്നിൽനിന്ന് റസൂൽ(സ) പ്രായമായ ഒരു പെണ്ണൊട്ടകത്തെ എനിക്ക് നൽകുകയും ചെയ്തിരുന്നു. ശേഷം റസൂൽ(സ)യുടെ പുത്രി ഫാതിമ(റ)യുമായി വീടുകൂടാൻ ഞാൻ ഉദ്ദേശിച്ചപ്പോൾ ബനൂഖൈനുഖാഅ് ഗോത്രത്തിലെ ഒരു ആഭരണപ്പണിക്കാരനുമായി ഞാൻ ഇപ്രകാരം തീരുമാനത്തിലെത്തി. അവൻ എന്റെകൂടെ വാഹനത്തിൽ വരികയും അങ്ങനെ ഞങ്ങൾ ''ഇദ്ഖിർ'' ചെടി കൊണ്ടുവരികയും ചെയ്യും. അവ ആഭരണപ്പണിക്കാർക്ക് വിറ്റ് അതുമായി എന്റെ വിവാഹസദ്യക്ക് പണമുണ്ടാക്കാം എന്നായിരുന്നു ഞാൻ ഉദ്ദേശിച്ചത്. എന്റെ ഒട്ടകങ്ങൾ രണ്ടും ഒരു അൻസ്വാരിയുടെ വീടിനു സമീപത്തായിരുന്നു മുട്ടുകുത്തിയിരുന്നത്. ഞാനാണെങ്കിൽ (വാഹനത്തിന്മേലിടുന്ന) വിരിപ്പുകൾ, വലിയ സഞ്ചികൾ, കയറുകൾ തുടങ്ങി (യാത്രക്കാവശ്യമായ) ചരക്കുകൾ ശേഖരിക്കുകയായിരുന്നു. വേണ്ടതെല്ലാം ശേഖരിച്ചു ഞാൻ തിരിച്ചെത്തിയപ്പോൾ എന്റെ രണ്ടു ഒട്ടകങ്ങളുടെയും പൂഞ്ഞകൾ മുറിക്കപ്പെടുകയും അവയുടെ ഊരകൾ അറുക്കപ്പെടുകയും കരൾ പറിക്കപ്പെടുകയും ചെയ്തിരിക്കുന്നു. ആ കാഴ്ച കണ്ടപ്പോൾ എനിക്കെന്റെ കണ്ണുകളെ നിയന്ത്രിക്കാൻ സാധിച്ചില്ല. ഞാൻ ചോദിച്ചു: ആരാണിത് ചെയ്തത്? ജനങ്ങൾ പറഞ്ഞു: ഹംസതുബ്നു അബ്ദുൽമുത്വലിബാണത് ചെയ്തത്. അൻസ്വാരികളിലെ ഒരു മദ്യപാന സംഘത്തോടൊപ്പം അദ്ദേഹം ഈ വീടിനകത്തുണ്ട്. അദ്ദഹത്തിനും കൂട്ടർക്കുംവേണ്ടി ഗാനം ആലപിക്കുകയായിരുന്ന ഒരു സ്ത്രീ തന്റെ പാട്ടിനിടയിൽ ഇപ്രകാരം പറഞ്ഞു: ഓ ഹംസാ, തടിച്ചുകൊഴുത്ത പ്രസവിക്കാനടുത്ത ആ ഒട്ടകങ്ങളെ ശ്രദ്ധിക്കൂ. ഉടൻതന്നെ ഹംസ(റ) വാളെടുക്കുകയും അവയുടെ പൂഞ്ഞകൾ മുറിക്കുകയും ഊരകൾ അറുക്കുകയും കരൾ പുറത്തെടുക്കുകയും ചെയ്തു. അലി(റ) പറയുന്നു: ഞാൻ പോയി റസൂൽ(സ)യുടെ വീട്ടിൽ പ്രവേശിച്ചു. അവിടുത്തോടൊപ്പം സൈദുബ്നു ഹാരിസ(റ)വും ഉണ്ടായിരുന്നു. അലി(റ) പറയുന്നു: എന്റെ വിഷമം റസൂൽ(സ) മനസ്സിലാക്കി. അവിടുന്ന് ചോദിച്ചു: "നിനക്കെന്തു പറ്റി." ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഇന്നത്തേതുപോലെ ഞാൻ മുമ്പ് വിഷമിച്ചിട്ടില്ല. ഹംസ(റ) എന്റെ രണ്ട് ഒട്ടകങ്ങളുടെ അടുത്തുചെന്ന് അവയുടെ പൂഞ്ഞകൾ മുറിച്ചെടുക്കുകയും ഊരകൾ അറുക്കുകയും ചെയ്തിരിക്കുന്നു. ഒരു മദ്യപാന സംഘത്തോടൊപ്പം അദ്ദേഹം ഒരു വീട്ടിൽ നിൽക്കുന്നുണ്ട്. ഉടൻതന്നെ റസൂൽ(സ) തന്റെ തട്ടം എടുക്കാനാവശ്യപ്പെടുകയും അതു ധരിച്ച് ഇറങ്ങിനടക്കുകയും ചെയ്തു. ഞാനും സൈദുബ്നു ഹാരിസ(റ)വും റസൂൽ(സ)യെ അനുഗമിച്ചു. അങ്ങനെ ഹംസ(റ)വുള്ള വീടിനടുത്ത് ചെന്ന് തിരുമേനി(സ) അകത്തുകടക്കാൻ അനുവാദം ചോദിക്കുകയും അനുവാദം നൽകപ്പെടുകയും ചെയ്തു. നോക്കുമ്പോൾ മദ്യപിച്ച ഒരു സംഘമായിരുന്നു അത്. റസൂൽ(സ) ഹംസ(റ)വിനെ അദ്ദേത്തിന്റെ ചെയ്തിയുടെ പേരിൽ ആക്ഷേപിക്കാൻ തുടങ്ങി. എന്നാൽ ഹംസ(റ) ലഹരിപിടിച്ച് കണ്ണുകൾ ചുവന്ന അവസ്ഥയിലായിരുന്നു. ഹംസ(റ) റസൂൽ(സ)യെ നോക്കി. ശേഷം നോട്ടമുയർത്തി റസൂൽ(സ)യുടെ കാൽമുട്ടുകളിലേക്ക് നോക്കി, വീണ്ടും നോട്ടമുയർത്തി റസൂൽ(സ)യുടെ പുക്കിൾ ഭാഗത്തേക്ക് നോക്കി. വീണ്ടും നോട്ടമുയർത്തി തിരുമേനി(സ)യുടെ മുഖത്തേക്ക് നോക്കി. ശേഷം ഹംസ(റ) പറഞ്ഞു: നിങ്ങളെല്ലാം എന്റെ പിതാവിന്റെ അടിമകളാണല്ലോ? അദ്ദേഹം ലഹരിപിടച്ച അവസ്ഥയിലാണെന്ന് അപ്പോൾ റസൂൽ(സ)ക്ക് മനസ്സിലായി. തിരുമേനി(സ) തന്റെ കാലുകൾ പിന്നോട്ടുവെച്ച് തിരിച്ചു പോവുകയും ഞങ്ങളും റസൂൽ(സ)യും പുറത്തു പോവുകയും ചെയ്തു. (ബു,മു,ദ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 99, 100, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ أُمِّ الْحَكَمِ، أَوْ ضُبَاعَةَ – ابْنَتَيِ الزُّبَيْرِ بْنِ عَبْدِ الْمُطَّلِبِ – رَضِيَ اللَّهُ عَنْهُمَا قَالَتْ: أَصَابَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَبْيًا، فَذَهَبْتُ أَنَا وَأُخْتِي وَفَاطِمَةُ بِنْتُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، شَكَوْنَا إِلَيْهِ مَا نَحْنُ فِيهِ، وَسَأَلْنَاهُ أَنْ يَأْمُرَ لَنَا بِشَيْءٍ مِنَ السَّبْيِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "سَبَقَكُنَّ يَتَامَى بَدْرٍ، لَكِنْ سَأَدُلُّكُنَّ عَلَى مَا هُوَ خَيْرٌ لَكُنَّ مِنْ ذَلِكَ: تُكَبِّرْنَ اللَّهَ عَلَى إِثْرِ كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ تَكْبِيرَةً، وَثَلَاثًا وَثَلَاثِينَ تَسْبِيحَةً، وَثَلَاثًا وَثَلَاثِينَ تَحْمِيدَةً، وَلَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ". (د)', 'സുബൈറുബ്നു അബ്ദുൽമുത്വലിബിന്റെ പുത്രിമാരായ ഉമ്മുൽഹകം(റ), അല്ലെങ്കിൽ ലുബാഅ(റ): റസൂൽ(സ)ക്ക് കുറേ ബന്ധികളെ ലഭിച്ചു. അപ്പോൾ ഞാനും എന്റെ സഹോദരിയും റസൂൽ(സ)യുടെ പുത്രി ഫാതിമ(റ)യും റസൂൽ(സ)യുട അടുത്തുചെന്ന് ഞങ്ങളനുഭവിക്കുന്ന പ്രയാസങ്ങളെക്കുറിച്ച് വേവലാതി ബോധിപ്പിക്കുകയും ബന്ധികളിൽനിന്ന് ഏതെങ്കിലുമൊന്നിനെ ഞങ്ങൾക്ക് നിശ്ചയിച്ചു തരാൻ ആവശ്യപ്പെടുകയും ചെയ്തു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ബദർ ദിനത്തിലെ (അന്ന് അനാഥരായ) അനാഥർ നിങ്ങളെ മുൻകടന്നിരിക്കുന്നു: എന്നാൽ അതിനേക്കാൾ ഉത്തമമായ ഒരു കാര്യം ഞാൻ നിങ്ങൾക്ക് പറഞ്ഞുതരാം: എല്ലാ നമസ്കാരങ്ങൾക്കു ശേഷവും നിങ്ങൾ മുപ്പത്തിമൂന്ന് പ്രാവശ്യം അല്ലാഹുവിന് തക്ബീർ (അല്ലാഹു അക്ബർ എന്ന്) ചൊല്ലുകയും മുപ്പത്തിമൂന്ന് പ്രാവശ്യം തസ്ബീഹ് (സുബ്ഹാനല്ലാഹ് എന്ന്) ചൊല്ലുകയും മുപ്പത്തിമൂന്ന് പ്രാവശ്യം തഹ്മീദ് (അൽഹംദുലില്ലാഹ് എന്ന്) ചൊല്ലുകയും ശേഷം ''ലാഇലാഹ ഇല്ലല്ലാഹു വഹ്ദഹു ലാശരീകലഹു ലഹുൽമുൽകു വലഹുൽഹംദു വഹുവ അലാകുല്ലി ശൈഇൻ ഖദീർ'' (അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല, അവൻ ഏകനാണ്, അവന് പങ്കുകാരനില്ല, അവന്നാണ് സർവ്വ അധികാരവും, അവന്നാണ് സർവ്വ സ്തുതിയും, അവൻ എല്ലാറ്റിനും കഴിവുള്ളവനാകുന്നു) എന്ന് ചൊല്ലുകയും ചെയ്യുക." (ദ)', 'أُمِّ الْحَكَمِ، أَوْ ضُبَاعَةَ – ابْنَتَيِ الزُّبَيْرِ بْنِ عَبْدِ الْمُطَّلِبِ –', 'സുബൈറുബ്നു അബ്ദുൽമുത്വലിബിന്റെ പുത്രിമാരായ ഉമ്മുൽഹകം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 101, 101, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ عَلِيِّ بْنِ أَعْبُدَ قَالَ: قَالَ لِي عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ: أَلَا أُحَدِّثُكَ عَنِّي وَعَنْ فَاطِمَةَ بِنْتِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَتْ مِنْ أَحَبِّ أَهْلِهِ إِلَيْهِ؟ قُلْتُ: بَلَى، قَالَ: إِنَّهَا جَرَّتْ بِالرَّحَى حَتَّى أَثَّرَ فِي يَدِهَا، وَاسْتَقَتْ بِالْقِرْبَةِ حَتَّى أَثَّرَ فِي نَحْرِهَا، وَكَنَسَتِ الْبَيْتَ حَتَّى اغْبَرَّتْ ثِيَابُهَا، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَدَمٌ، فَقُلْتُ: لَوْ أَتَيْتِ أَبَاكِ فَسَأَلْتِيهِ خَادِمًا. فَأَتَتْهُ، فَوَجَدَتْ عِنْدَهُ حُدَّاثًا، فَرَجَعَتْ، فَأَتَاهَا مِنَ الْغَدِ، فَقَالَ: "مَا كَانَ حَاجَتُكِ". فَسَكَتَتْ، فَقُلْتُ: أَنَا أُحَدِّثُكَ يَا رَسُولَ اللَّهِ، جَرَّتْ بِالرَّحَى حَتَّى أَثَّرَتْ فِي يَدِهَا، وَحَمَلَتْ بِالْقِرْبَةِ حَتَّى أَثَّرَتْ فِي نَحْرِهَا، فَلَمَّا أَنْ جَاءَكَ الْخَدَمُ أَمَرْتُهَا أَنْ تَأْتِيَكَ فَتَسْتَخْدِمَكَ خَادِمًا يَقِيهَا حَرَّ مَا هِيَ فِيهِ. قَالَ: "اتَّقِي اللَّهَ يَا فَاطِمَةُ، وَأَدِّي فَرِيضَةَ رَبِّكِ، وَاعْمَلِي عَمَلَ أَهْلِكِ، فَإِذَا أَخَذْتِ مَضْجَعَكِ فَسَبِّحِي ثَلَاثًا وَثَلَاثِينَ، وَاحْمَدِي ثَلَاثًا وَثَلَاثِينَ، وَكَبِّرِي أَرْبَعًا وَثَلَاثِينَ، فَتِلْكَ مِائَةٌ، فَهِيَ خَيْرٌ لَكِ مِنْ خَادِمٍ". قَالَتْ: رَضِيتُ عَنِ اللَّهِ عَزَّ وَجَلَّ، وَعَنْ رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَفِي رِوَايَةٍ قَالَ: وَلَمْ يُخْدِمْهَا. (ق,د)', 'അലിയ്യുബ്നു അഅ്ബുദ്(റ): അലി(റ) എന്നോട് ചോദിച്ചു: റസൂൽ(സ)യുടെ കുടുംബത്തിൽ അവിടുത്തേക്ക് ഏറ്റവും ഇഷ്ടപ്പെട്ട അവിടത്തെ പുത്രിയായ ഫാതിമ(റ)യുടെയും എന്റെയും ഒരു സംഭവം ഞാൻ നിനക്ക് പറഞ്ഞുതരട്ടെയോ? ഞാൻ പറഞ്ഞു: അതെ. അലി(റ) പറഞ്ഞു: ഫാത്വിമ(റ) ആസുകല്ല് തിരിച്ച് തന്റെ കൈകളിൽ പാടുവീണു, മഹതി തോൽപാത്രത്തിൽ വെള്ളം കൊണ്ടുവന്ന് കഴുത്തിൽ അടയാളം വീണു. മഹതി വീട് അടിച്ചുവാരി വസ്ത്രത്തിൽ പൊടിപുരണ്ടു. അങ്ങനെയിരിക്കെ നബി(സ)യുടെ അടുത്ത് കുറേ അടിമകളെത്തി. അപ്പോൾ ഞാൻ പറഞ്ഞു: നീ നിന്റെ പിതാവിന്റെ അടുത്തു ചെന്ന് ഒരു അടിമയെ ചോദിച്ചാൽ നന്നാകും. അങ്ങനെ മഹതി നബി(സ)യുടെ അടുത്തുചെന്നു. എന്നാൽ തിരുമേനി(സ)യുടെ അടുത്ത് സംസാരിച്ചുകൊണ്ടിരിക്കുന്ന കുറേ ആളുകളെക്കണ്ട് മഹതി തിരിച്ചു പോന്നു. പിറ്റേദിവസം മഹതി തിരുമേനി(സ)യുടെ അടുത്തു ചെന്നു. അവിടുന്ന് ചോദിച്ചു: "എന്താണ് നിന്റെ ആവശ്യം?" മഹതി മൗനമവലംബിച്ചു. അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ പറഞ്ഞുതരാം, അവൾ ആസുകല്ല് തിരിച്ച് തന്റെ കൈകളിൽ പാടുവീണിരിക്കുന്നു, തോൽപാത്രത്തിൽ വെള്ളം കൊണ്ടുവന്ന് തന്റെ കഴുത്തിൽ അടയാളം വീണിരിക്കുന്നു. അതിനാൽ അവിടുത്തെ പക്കൽ അടിമകളെത്തിയപ്പോൾ, അവൾ അനുഭവിക്കുന്ന പ്രയാസങ്ങൾ ഇല്ലാതാക്കാൻ കഴിയുംവിധത്തിലുള്ള ഒരു അടിമയെ ആവശ്യപ്പെടാനായി അങ്ങയുടെ അടുത്തുവരാൻ ഞാൻ അവളോട് ആവശ്യപ്പെട്ടു. റസൂൽ(സ) പറഞ്ഞു: "ഫാതിമ, നീ അല്ലാഹുവിനെ സൂക്ഷിക്കുകയും നിന്റെ രക്ഷിതാവിനോടുള്ള നിർബന്ധ ബാധ്യതകൾ വീട്ടുകയും നിന്റെ കുടുംബത്തിന്റെ ജോലികൾ നിർവ്വഹിക്കുകയും ചെയ്യുക. നീ ഉറങ്ങാൻ കിടന്നാൽ മുപ്പത്തിമൂന്ന് പ്രാവശ്യം തസ്ബീഹ് ചൊല്ലുകയും മുപ്പത്തിമൂന്ന് പ്രാവശ്യം തഹ്മീദ് (അൽഹംദുലില്ലാഹ് എന്ന്) ചൊല്ലുകയും മുപ്പത്തിനാല് പ്രാവശ്യം തക്ബീർ ചൊല്ലുകയും ചെയ്യുക. അവ മൊത്തം നൂറാണ്. അത് ഒരു സേവകനേക്കാൾ നിനക്കുത്തമമാണ്." മഹതി പറഞ്ഞു: അല്ലാഹുവിന്റെയും അവന്റെ റസൂലിന്റെയും തീരുമാനം ഞാൻ തൃപ്തിപ്പെട്ടിരിക്കുന്നു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=156), 1, 'وَفِي رِوَايَةٍ قَالَ: وَلَمْ يُخْدِمْهَا. (ق,د)', 'മറ്റൊരു നിവേദനം: അലി(റ) പറഞ്ഞു: മഹതിക്ക് റസൂൽ(സ) സേവകനെ നൽകിയില്ല. (ബു,മു,ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ مُجَّاعَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَطْلُبُ دِيَةَ أخيه – قَتَلَتْهُ بَنُو سَدُوسٍ مِنْ بَنِي ذُهْلٍ – فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَوْ كُنْتُ جَاعِلًا لِمُشْرِكٍ دِيَةً جَعَلْتُ لأخيك، وَلَكِنْ سَأُعْطِيكَ مِنْهُ عُقْبَى". فَكَتَبَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمِائَةٍ مِنَ الْإِبِلِ مِنْ أَوَّلِ خُمُسٍ يَخْرُجُ مِنْ مُشْرِكِي بَنِي ذُهْلٍ، فَأَخَذَ طَائِفَةً مِنْهَا، وَأَسْلَمَتْ بَنُو ذُهْلٍ، فَطَلَبَهَا بَعْدُ مُجَّاعَةُ إِلَى أَبِي بَكْرٍ، وَأَتَاهُ بِكِتَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَكَتَبَ لَهُ أَبُو بَكْرٍ بِاثْنَيْ عَشَرَ أَلْفَ صَاعٍ مِنْ صَدَقَةِ الْيَمَامَةِ: أَرْبَعَةُ آلَافٍ بُرًّا وَأَرْبَعَةُ آلَافٍ شَعِيرًا وَأَرْبَعَةُ آلَافٍ تَمْرًا، وَكَانَ فِي كِتَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِمُجَّاعَةَ: "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ، هَذَا كِتَابٌ مِنْ مُحَمَّدٍ النَّبِيِّ، لِمُجَّاعَةَ بْنِ مَرَارَةَ مِنْ بَنِي سُلْمَى، إِنِّي أَعْطَيْتُهُ مِائَةً مِنَ الْإِبِلِ مِنْ أَوَّلِ خُمُسٍ يَخْرُجُ مِنْ مُشْرِكِي بَنِي ذُهْلٍ، عُقْبَةً مِنْ أخيه". (د)', 'മുജ്ജാഅ(റ): തന്റെ സഹോദരനുള്ള നഷ്ടപരിഹാരം ആവശ്യപ്പെട്ടുകൊണ്ട് അദ്ദേഹം നബി(സ)യുടെ അടുത്ത് ചെന്നു - ബനൂദുഹ്ലിൽപെട്ട ബനൂസദൂസുകാരായിരുന്നു അദ്ദേഹത്തിന്റെ സഹോദരന്റെ ഘാതകർ - അപ്പോൾ നബി(സ) പറഞ്ഞു: "ബഹുദൈവാരാധകരിൽ ആരെയെങ്കിലും വധിച്ചതിന് ഞാൻ നഷ്ടപരിഹാരം വിധിക്കുകയാണെങ്കിൽ നിന്റെ സഹോദരന്റെ കാര്യത്തിൽ വിധിക്കുമായിരുന്നു. എങ്കിലും ഞാൻ നിനക്ക് മറ്റുവല്ലതും ഉഖ്ബയായി (വധിക്കപ്പെടുന്നവന്റെ കുടുംബത്തിന് നഷ്ടപരിഹാരമായിട്ടല്ലാതെ നൽകുന്ന മുതൽ) നൽകാം." അങ്ങനെ ബനൂദുഹ്ലിലെ ബഹുദൈവാരാധകരിൽനിന്ന് പിടിക്കപ്പെടുന്ന ആദ്യ അഞ്ചിലൊന്നിൽനിന്ന് നൂറ് ഒട്ടകങ്ങളെ നബി(സ) അദ്ദേഹത്തിന് എഴുതി നിശ്ചയിച്ചു. അതിൽപെട്ട ഒരു കൂട്ടത്തെ അദ്ദേഹം കൈപറ്റി. ശേഷം ബനൂദുഹ്ലുകാർ ഇസ്ലാം സ്വീകരിച്ചു. ശേഷം മുജ്ജാഅ(റ) അബൂബക്ർ(റ)വിനോട് അക്കാര്യം ആവശ്യപ്പെടുകയും നബി(സ)യുടെ എഴുത്തുമായി അദ്ദേഹത്തിന്റെയടുത്ത് ചെല്ലുകയും ചെയ്തു. അപ്പോൾ അബൂബക്ർ(റ) അദ്ദേഹത്തിന് യമാമയിലെ സകാത് വിഹിതത്തിൽ നിന്ന് പന്ത്രണ്ടായിരം സ്വാഅ് എഴുതി നിശ്ചയിച്ചു കൊടുത്തു. നാലായിരം സ്വാഅ് ഗോതമ്പും നാലായിരം സ്വാഅ് ബാർളിയും നാലായിരം സ്വാഅ് കാരക്കയുമായിരുന്നു അത്. മുജ്ജാഅ(റ)വിന് റസൂൽ(സ) നൽകിയ എഴുത്തിൽ ഇപ്രകാരമാണ് ഉണ്ടായിരുന്നത്: "കരുണാനിധിയും കാരുണ്യവാനുമായ അല്ലാഹുവിന്റെ നാമത്തിൽ, മുഹമ്മദ്നബി(സ) ബനൂസുൽമാ ഗോത്രത്തിൽപെട്ട മുജ്ജാഅതുബ്നു മറാറക്ക് നൽകുന്ന എഴുത്താണിത്; നിശ്ചയം ബനൂദുഹ്ൽ ഗോത്രത്തിലെ ബഹുദൈവാരാധകരിൽ നിന്ന് പിടിക്കപ്പെടുന്ന ആദ്യ അഞ്ചിലൊന്നിൽനിന്ന് നൂറ് ഒട്ടകങ്ങളെ അദ്ദേഹത്തിന് ഞാൻ നൽകിയിരിക്കുന്നു. അദ്ദേഹത്തിന്റെ സഹോദരനുള്ള ഉഖ്ബ (നഷ്ടപരിഹാരമല്ലാതെ നൽകുന്ന മുതൽ) ആയിട്ടാണത്." (ദ)', 'مُجَّاعَةَ', 'മുജ്ജാഅ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 102, 102, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ عَامِرٍ الشَّعْبِيِّ قَالَ: كَانَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَهْمٌ يُدْعَى الصَّفِيَّ، إِنْ شَاءَ عَبْدًا وَإِنْ شَاءَ فَرَسًا، يَخْتَارُهُ قَبْلَ الْخُمُسِ. مرسل. (د)', 'ആമിറുശ്ശഅ്ബി(റ): നബി(സ)ക്ക് സ്വഫിയ്യ് (തെരഞ്ഞെടുക്കപ്പെട്ടത്) എന്ന് വിളിക്കപ്പെടുന്ന ഒരു പ്രത്യേക വിഹിതമുണ്ടായിരുന്നു. അവിടുന്ന് ഉദ്ദേശിക്കുംവിധം അടിമയെയോ കുതിരയെയോ ആയിരുന്നു അവിടുന്ന് സ്വഫിയ്യായി സ്വീകരിച്ചിരുന്നത്. അഞ്ചിലൊന്നിന് മുമ്പ് അവിടുന്ന് തെരഞ്ഞെടുക്കുന്ന വിഹിതമായിരുന്നു അത്. ഹദീസ് മുർസലാണ്. (ദ)', 'عَامِرٍ الشَّعْبِيِّ قَالَ', 'ആമിറുശ്ശഅ്ബി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 103, 103, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنِ ابْنِ عَوْنٍ قَالَ: سَأَلْتُ مُحَمَّدًا عَنْ سَهْمِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالصَّفِيِّ، قَالَ: كَانَ يُضْرَبُ لَهُ بِسَهْمٍ مَعَ الْمُسْلِمِينَ وَإِنْ لَمْ يَشْهَدْ، وَالصَّفِيُّ: يُؤْخَذُ لَهُ رَأْسٌ مِنَ الْخُمُسِ قَبْلَ كُلِّ شَيْءٍ. مرسل. (د)', 'ഇബ്നുഔൻ(റ): നബി(സ)യുടെ വിഹിതത്തെക്കുറിച്ചും സ്വഫിയ്യിനെക്കുറിച്ചും ഞാൻ മുഹമ്മദ്(റ)വിനോട് ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: തരുമേനി(സ) യുദ്ധത്തിൽ പങ്കെടുത്തിട്ടില്ലെങ്കിലും മുസ്ലിംകളോടൊപ്പം അവിടുത്തേക്ക് ഒരു വിഹിതം നൽകപ്പെടാറുണ്ടായിരുന്നു. സർവ്വ വിഹിതങ്ങൾക്കും മുമ്പ് അഞ്ചിലൊന്ന് വിഹിതത്തിന്റെ ഭാഗമായി നബി(സ)ക്ക് നൽകപ്പെടുന്ന വിഹിതമാണ് സ്വഫിയ്യ്. ഹദീസ് മുർസലാണ്. (ദ)', 'ابْنِ عَوْنٍ قَالَ', 'ഇബ്നുഔൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 103, 103, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ قَتَادَةَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا غَزَا كَانَ لَهُ سَهْمٌ صَافٍ يَأْخُذُهُ مِنْ حَيْثُ شَاءَهُ، فَكَانَتْ صَفِيَّةُ مِنْ ذَلِكَ السَّهْمِ، وَكَانَ إِذَا لَمْ يَغْزُ بِنَفْسِهِ ضُرِبَ لَهُ بِسَهْمِهِ وَلَمْ يُخَيَّرْ. مرسل. (د)', 'ഖതാദ(റ): റസൂൽ(സ) യുദ്ധം ചെയ്യുകയാണെങ്കിൽ അവിടുത്തേക്ക് ശുദ്ധമായ ഒരു വിഹിതം ഉണ്ടാകാറുണ്ടായിരുന്നു. തിരുമേനി(സ) ഉദ്ദേശിക്കുന്ന ഭാഗത്തുനിന്ന് അവിടുന്ന് അത് എടുക്കും. സ്വഫിയ്യ(റ) ആ വിഹിതത്തിൽ പെട്ടതായിരുന്നു. തിരുമേനി(സ) യുദ്ധത്തിൽ പങ്കെടുക്കുന്നില്ലെങ്കിലും അവിടുത്തേക്ക് വിഹിതം നൽകപ്പെടാറുണ്ടായിരുന്നു. എന്നാൽ അവിടുന്നതിനെ തെരഞ്ഞെടുക്കാറുണ്ടായിരുന്നില്ല. ഹദീസ് മുർസലാണ്. (ദ)', 'قَتَادَةَ قَالَ', 'ഖതാദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 103, 103, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَتْ صَفِيَّةُ مِنَ الصَّفِيِّ. (د)', 'ആഇശ(റ): സ്വഫിയ്യ(റ) സ്വഫിയ്യ് വിഹിതത്തിൽ പെട്ടവരായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 103, 103, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَدِمْنَا خَيْبَرَ، فَلَمَّا فَتَحَ اللَّهُ تَعَالَى الْحِصْنَ ذُكِرَ لَهُ جَمَالُ صَفِيَّةَ بِنْتِ حُيَيٍّ، وَقَدْ قُتِلَ زَوْجُهَا، وَكَانَتْ عَرُوسًا، فَاصْطَفَاهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِنَفْسِهِ، فَخَرَجَ بِهَا حَتَّى بَلَغْنَا سَدَّ الصَّهْبَاءِ حَلَّتْ، فَبَنَى بِهَا. (د)', 'അനസുബ്നു മാലിക്(റ): ഞങ്ങൾ ഖൈബറിലെത്തി. അങ്ങനെ അവിടത്തെ കോട്ട അല്ലാഹു ജയിച്ചടക്കിത്തന്നപ്പോൾ സ്വഫിയ്യതുബിൻതു ഹുയയ്യ്(റ)യുടെ സൗന്ദര്യത്തെക്കുറിച്ച് തിരുമേനി(സ)യോട് പറയപ്പെട്ടു. മഹതിയുടെ ഭർതാവ് വധിക്കപ്പെട്ടിട്ടുണ്ടായിരുന്നു. മഹതി നവവധുവായിരുന്നു. അങ്ങനെ മഹതിയെ റസൂൽ(സ) സ്വന്തത്തിനുവേണ്ടി തെരഞ്ഞെടുത്തു. മഹതിയുമായി റസൂൽ(സ) യാത്ര തിരിക്കുകയും ഞങ്ങൾ സുദ്ധസ്സഹ്ബാഅ് എന്ന സ്ഥലത്തെത്തിയപ്പോൾ മഹതി (ആർത്തവത്തിൽ നിന്ന്) ശുദ്ധിയുള്ളവരാവുകയും റസൂൽ(സ) മഹതിയുമായി വീടുകൂടുകയും ചെയ്തു. (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 103, 103, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: صَارَتْ صَفِيَّةُ لِدَحْيَةَ الْكَلْبِيِّ، ثُمَّ صَارَتْ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ق,د)', 'അനസുബ്നുമാലിക്(റ): സ്വഫിയ്യ(റ)യെ ദിഹ്യതുൽകൽബി(റ)വിനായിരുന്നു ലഭിച്ചിരുന്നത്. ശേഷം മഹതിയെ റസൂൽ(സ)ക്ക് ലഭിച്ചു. (ബു,മു,ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 103, 104, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: وَقَعَ فِي سَهْمِ دِحْيَةَ جَارِيَةٌ جَمِيلَةٌ، فَاشْتَرَاهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَبْعَةِ أَرْؤُسٍ، ثُمَّ دَفَعَهَا إِلَى أُمِّ سُلَيْمٍ تَصْنَعُهَا وَتُهَيِّئُهَا وَتَعْتَدُّ فِي بَيْتِهَا: صَفِيَّةُ بِنْتُ حُيَيٍّ. (م,د)', 'അനസ്(റ): ദിഹ്യ(റ)വിന്റെ വിഹിതത്തിൽ സുന്ദരിയായ ഒരു അടിമസ്ത്രീ ഉൾപെട്ടിരുന്നു. അങ്ങനെ ഏഴു മൃഗങ്ങൾക്കു പകരമായി റസൂൽ(സ) അവളെ വാങ്ങുകയും ശേഷം അവളെ ഉമ്മുസുലൈം(റ)യെ ഏൽപിക്കുകയും ചെയ്തു. അവളെ അണിയിച്ചൊരുക്കാനും (തനിക്കുവേണ്ടി) തയ്യാറാക്കാനും ഉമ്മുസുലൈം(റ)യുടെ വീട്ടിൽ അവൾ ഇദ്ദ ഇരിക്കാനും വേണ്ടിയായിരുന്നു അപ്രകാരം ചെയ്തത്. സ്വഫിയ്യബിൻതു ഹുയയ്യ്(റ)യായിരുന്നു ആ അടിമസ്ത്രീ. (മു,ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 104, 104, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: جُمِعَ السَّبْيُ – يَعْنِي بِخَيْبَرَ – فَجَاءَ دِحْيَةُ فَقَالَ: يَا رَسُولَ اللَّهِ، أَعْطِنِي جَارِيَةً مِنَ السَّبْيِ. قَالَ: "اذْهَبْ فَخُذْ جَارِيَةً". فَأَخَذَ صَفِيَّةَ بِنْتَ حُيَيٍّ، فَجَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا نَبِيَّ اللَّهِ، أَعْطَيْتَ دِحْيَةَ صَفِيَّةَ بِنْتَ حُيَيٍّ سَيِّدَةَ قُرَيْظَةَ وَالنَّضِيرِ؟ مَا تَصْلُحُ إِلَّا لَكَ. قَالَ: "ادْعُوهُ بِهَا". فَلَمَّا نَظَرَ إِلَيْهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ: "خُذْ جَارِيَةً مِنَ السَّبْيِ غَيْرَهَا". وَإِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْتَقَهَا وَتَزَوَّجَهَا. (ق,د,ن)', 'അനസ്(റ): ഖൈബറിലെ ബന്ധികളെ ഒരുമിച്ചുകൂട്ടപ്പെട്ടപ്പോൾ ദിഹ്യ(റ) വന്നുകൊണ്ട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ബന്ധികളിൽനിന്ന് ഒരു അടിമസ്ത്രീയെ എനിക്ക് നൽകിയാലും. അവിടുന്ന് പറഞ്ഞു: "നീ പോയി ഒരു അടിമസ്ത്രീയെ എടുത്തുകൊള്ളുക." അങ്ങനെ അദ്ദേഹം സ്വഫിയ്യബിൻതു ഹുയയ്യ്(റ)യെ എടുത്തു. അപ്പോൾ ഒരാൾ നബി(സ)യുടെ അടുത്ത്വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, ഖുറൈള ഗോത്രത്തിന്റെയും നളീർ ഗോത്രത്തിന്റെയും നേതാവായ സ്വഫിയ്യബിൻതു ഹുയയ്യിനെ അങ്ങ് ദിഹ്യ(റ)വിന് നൽകിയോ? അവൾ അങ്ങേക്കല്ലാതെ യോജിക്കുകയില്ല. അവിടുന്ന് പറഞ്ഞു: "അദ്ദേഹത്തോട് അവളെ കൂട്ടി വരാൻ ആവശ്യപ്പെടുക." അവളിലേക്ക് നോക്കിയിട്ട് നബി(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "ബന്ധികളിൽനിന്ന് അവളല്ലാത്ത ഒരു അടിമസ്ത്രീയെ എടുത്തുകൊള്ളുക." നിശ്ചയം നബി(സ) സ്വഫിയ്യ(റ)യെ മോചിപ്പിക്കുകയും വിവാഹം കഴിക്കുകയും ചെയ്തു. (ബു,മു,ദ,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 104, 104, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ قَالَ: كُنَّا بِالْمِرْبَدِ، فَجَاءَ رَجُلٌ أَشْعَثُ الرَّأْسِ، بِيَدِهِ قِطْعَةُ أَدِيمٍ أَحْمَرَ، فَقُلْنَا: كَأَنَّكَ مِنْ أَهْلِ الْبَادِيَةِ، فَقَالَ: أَجَلْ، قُلْنَا: نَاوِلْنَا هَذِهِ الْقِطْعَةَ الْأَدِيمَ الَّتِي فِي يَدِكَ، فَنَاوَلَنَاهَا، فَقَرَأْنَاهَا، فَإِذَا فِيهَا: "مِنْ مُحَمَّدٍ رَسُولِ اللَّهِ إِلَى بَنِي زُهَيْرِ بْنِ أُقَيْشٍ، إِنَّكُمْ إِنْ شَهِدْتُمْ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَأَقَمْتُمُ الصَّلَاةَ، وَآتَيْتُمُ الزَّكَاةَ، وَأَدَّيْتُمُ الْخُمُسَ مِنَ الْمَغْنَمِ، وَسَهْمَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الصَّفِيَّ، أَنْتُمْ آمِنُونَ بِأَمَانِ اللَّهِ وَرَسُولِهِ". فَقُلْنَا: مَنْ كَتَبَ لَكَ هَذَا الْكِتَابَ؟ قَالَ: رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (د)', 'യസീദുബ്നു അബ്ദില്ലാഹിബ്നുശ്ശഖീർ(റ): ഞങ്ങൾ മിർബദിൽ നിൽക്കുമ്പോൾ മുടി ജടപിടിച്ച ഒരാൾ വന്നു. അദ്ദേഹത്തിന്റെ കയ്യിൽ ചുവന്ന നിറത്തിലുള്ള ഒരു തോൽകഷ്ണമുണ്ടായിരുന്നു. ഞങ്ങൾ (അദ്ദേഹത്തോട്) പറഞ്ഞു: താങ്കൾ നാട്ടിൻപുറത്ത് താമസിക്കുന്നയാളാണെന്ന് തോന്നുന്നു. അദ്ദേഹം പറഞ്ഞു: അതെ. ഞങ്ങൾ പറഞ്ഞു: താങ്കളുടെ കയ്യിലുള്ള ആ തോൽകഷ്ണമൊന്ന് തന്നാലും. അദ്ദേഹമത് ഞങ്ങളുടെ പക്കൽ നൽകി. ഞങ്ങളത് വായിച്ചുനോക്കി. അതിൽ ഇപ്രകാരമുണ്ടായിരുന്നു: "ബനൂസുഹൈറുബ്നു ഉഖൈശ് ഗോത്രക്കാർക്ക് മുഹമ്മദുർറസൂലുല്ലാഹി(സ)യിൽ നിന്നുള്ള സന്ദേശം: നിശ്ചയം അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും മുഹമ്മദ്(സ) അല്ലാഹുവിന്റെ ദൂതരാണെന്നും നിങ്ങൾ സാക്ഷ്യം വഹിക്കുകയും, നമസ്കാരം നിലനിർത്തുകയും, സകാത് നൽകുകയും, ഗനീമതിൽ നിന്നുള്ള അഞ്ചിലൊന്ന് വിഹിതവും നബി(സ)ക്കുള്ള സ്വഫിയ്യ് എന്ന വിഹിതവും നൽകുകയും ചെയ്യുന്നുവെങ്കിൽ അല്ലാഹുവിന്റെയും അവന്റെ റസൂലിന്റെയും സംരക്ഷണത്തിൽ നിങ്ങൾ സുരക്ഷിതരായിരിക്കും." ഞങ്ങൾ ചോദിച്ചു: ആരാണ് താങ്കൾക്ക് ഈ സന്ദേശമെഴുതിത്തന്നത്? അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ). (ദ)', 'يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ قَالَ', 'യസീദുബ്നു അബ്ദില്ലാഹിബ്നുശ്ശഖീർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 104, 105, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَاتَلَ أَهْلَ خَيْبَرَ، فَغَلَبَ عَلَى النَّخْلِ وَالْأَرْضِ، وَأَلْجَأَهُمْ إِلَى قَصْرِهِمْ، فَصَالَحُوهُ عَلَى أَنَّ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الصَّفْرَاءَ وَالْبَيْضَاءَ وَالْحَلْقَةَ، وَلَهُمْ مَا حَمَلَتْ رِكَابُهُمْ، عَلَى أَنْ لَا يَكْتُمُوا وَلَا يُغَيِّبُوا شَيْئًا، فَإِنْ فَعَلُوا فَلَا ذِمَّةَ لَهُمْ وَلَا عَهْدَ. فَغَيَّبُوا مَسْكًا لِحُيَيِّ بْنِ أَخْطَبَ، وَقَدْ كَانَ قُتِلَ قَبْلَ خَيْبَرَ، كَانَ احْتَمَلَهُ مَعَهُ يَوْمَ بَنِي النَّضِيرِ حِينَ أُجْلِيَتِ النَّضِيرُ، فِيهِ حُلِيُّهُمْ، قَالَ: فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِسَعْيَةَ: "أَيْنَ مَسْكُ حُيَيِّ بْنِ أَخْطَبَ". قَالَ: أَذْهَبَتْهُ الْحُرُوبُ وَالنَّفَقَاتُ. فَوَجَدُوا الْمَسْكَ، فَقَتَلَ ابْنَ أَبِي الْحُقَيْقِ وَسَبَى نِسَاءَهُمْ وَذَرَارِيَّهُمْ، وَأَرَادَ أَنْ يُجْلِيَهُمْ، فَقَالُوا: يَا مُحَمَّدُ، دَعْنَا نَعْمَلْ فِي هَذِهِ الْأَرْضِ وَلَنَا الشَّطْرُ مَا بَدَا لَكَ وَلَكُمُ الشَّطْرُ. وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعْطِي كُلَّ امْرَأَةٍ مِنْ نِسَائِهِ ثَمَانِينَ وَسْقًا مِنْ تَمْرٍ وَعِشْرِينَ وَسْقًا مِنْ شَعِيرٍ. (د)', 'ഇബ്നുഉമർ(റ): നബി(സ) ഖൈബറുകാരോട് യുദ്ധംചെയ്യുകയും അവരുടെ ഈത്തപ്പനത്തോട്ടങ്ങളും ഭൂമിയുമെല്ലാം ജയിച്ചടക്കുകയും അവരെ തങ്ങളുടെ കോട്ടയിലേക്ക് ഒതുക്കുകയും ചെയ്തു.. അങ്ങനെ സ്വർണ്ണവും വെള്ളിയും ആയുധങ്ങളുമെല്ലാം റസൂൽ(സ)ക്ക് നൽകാമെന്നും, ഒന്നും പൂഴ്തിവെക്കുകയോ മറച്ചുവെക്കുകയോ ചെയ്യാതെ തങ്ങളുടെ വാഹനങ്ങളിൽ ചുമക്കാവുന്നത് മാത്രം അവരെടുക്കുമെന്നും, അവർ മറച്ചുവെക്കുകയാണെങ്കിൽ അവർക്ക് സംരക്ഷണമോ ഉത്തരവാദിത്തമോ ഉണ്ടാവുകയില്ലെന്നും അവർ റസൂൽ(സ)യോട് സന്ധിചെയ്തു. അങ്ങനെ അവർ ഹുയയ്യുബ്നു അഖ്ത്വബിന്റെ ഒരു തോൽപാത്രം മറച്ചുവെച്ചു. അവൻ ഖൈബർ യുദ്ധത്തിനു മുമ്പുതന്നെ വധിക്കപ്പെട്ടിട്ടുണ്ടായിരുന്നു. ബനുന്നളീറിനോടുള്ള യുദ്ധദിവസം ബനുന്നളീറുകാർ നാടുകടത്തപ്പെട്ടപ്പോൾ അവൻ എടുത്തു കൊണ്ടുപോയതായിരുന്നു ആ തോൽപാത്രം. അതിൽ അവരുടെ ആഭരണങ്ങളുണ്ടായിരുന്നു. നിവേദകൻ പറയുന്നു: നബി(സ) സഅ്യയോട് ചോദിച്ചു: "ഹുയയ്യുബ്നു അഖ്ത്വബിന്റെ തോൽപാത്രം എവിടെയാണ്?" അയാൾ പറഞ്ഞു: യുദ്ധങ്ങളും മറ്റു ചെലവുകളും അതിനെ (അതിലുള്ള മുതൽ) ഇല്ലാതാക്കിയിരിക്കുന്നു. എന്നാൽ അവർ (മുസ്ലിംകൾ) ആ തോൽപാത്രം കണ്ടെടുത്തു. തുടർന്ന് റസൂൽ(സ) ഇബ്നുഅബിൽഹുഖൈഖിനെ വധിക്കുകയും അവരിലെ സ്ത്രീകളെയും കുട്ടികളെയും ബന്ധികളായി പിടിക്കുകയും അവരെ നാടുകടത്താൻ ആഗ്രഹിക്കുകയും ചെയ്തു. അപ്പോൾ അവർ പറഞ്ഞു: മുഹമ്മദേ, ഞങ്ങൾക്ക് പകുതി നിങ്ങൾക്ക് പകുതി (വരുമാനം) എന്ന വ്യവസ്ഥയിൽ ഈ ഭൂമിയിൽ ജോലി ചെയ്യുന്നവരായി, താങ്കൾക്ക് തോന്നുന്ന കാലത്തോളം, ഞങ്ങളെ ഒഴിവാക്കിയിട്ടാലും. റസൂൽ(സ) തന്റെ പത്നിമാരിൽ ഓരോരുത്തർക്കും എൺപത് വസ്ഖ് കാരക്കയും ഇരുപത് വസ്ഖ് ബാർളിയും (ആ സമ്പത്തിൽനിന്ന്) നൽകാറുണ്ടായിരുന്നു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 105, 105, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ عُمَرَ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَيُّهَا النَّاسُ، إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ عَامَلَ يَهُودَ خَيْبَرَ عَلَى أَنَّا نُخْرِجُهُمْ إِذَا شِئْنَا، فَمَنْ كَانَ لَهُ مَالٌ فَلْيَلْحَقْ بِهِ، فَإِنِّي مُخْرِجٌ يَهُودَ. فَأَخْرَجَهُمْ. (د)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നിശ്ചയം ഉമർ(റ) പറഞ്ഞു: ഓ ജനങ്ങളേ, നാം ഉദ്ദേശിക്കുന്ന സമയത്ത് പുറത്താക്കുമെന്ന വ്യവസ്ഥയിലായിരുന്നു റസൂൽ(സ) ഖൈബറിലെ ജൂതരെ അവിടത്തെ ജോലി ഏൽപിച്ചിരുന്നത്. അതിനാൽ ആർക്കെങ്കിലും വല്ല മുതലുമുണ്ടെങ്കിൽ അതെടുത്തുകൊള്ളുക. ഞാൻ ജൂതരെ പുറത്താക്കാൻ പോവുകയാണ്. അങ്ങനെ ഉമർ(റ) അവരെ പുറത്താക്കി. (ദ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 105, 106, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَمَّا افْتُتِحَتْ خَيْبَرُ سَأَلَتْ يَهُودُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُقِرَّهُمْ عَلَى أَنْ يَعْمَلُوا عَلَى النِّصْفِ مِمَّا خَرَجَ مِنْهَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أُقِرُّكُمْ فِيهَا عَلَى ذَلِكَ مَا شِئْنَا". فَكَانُوا عَلَى ذَلِكَ، وَكَانَ التَّمْرُ يُقْسَمُ عَلَى السُّهْمَانِ مِنْ نِصْفِ خَيْبَرَ، وَيَأْخُذُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْخُمُسَ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَطْعَمَ كُلَّ امْرَأَةٍ مِنْ أَزْوَاجِهِ مِنَ الْخُمُسِ مِائَةَ وَسْقٍ تَمْرًا وَعِشْرِينَ وَسْقًا شَعِيرًا، فَلَمَّا أَرَادَ عُمَرُ إِخْرَاجَ الْيَهُودِ أَرْسَلَ إِلَى أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لَهُنَّ: مَنْ أَحَبَّ مِنْكُنَّ أَنْ أَقْسِمَ لَهَا نَخْلًا بِخَرْصِهَا مِائَةَ وَسْقٍ، فَيَكُونَ لَهَا أَصْلُهَا وَأَرْضُهَا وَمَاؤُهَا، وَمِنَ الزَّرْعِ مَزْرَعَةَ خَرْصِ عِشْرِينَ وَسْقًا، فَعَلْنَا. وَمَنْ أَحَبَّ أَنْ نَعْزِلَ الَّذِي لَهَا فِي الْخُمُسِ كَمَا هُوَ، فَعَلْنَا. (م,د)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഖൈബർ ജയിച്ചടക്കപ്പെട്ടപ്പോൾ, അതിലെ വരുമാനത്തിന്റെ പകുതിക്കു പകരം (അവിടെ) ജോലി ചെയ്യാമെന്ന വ്യവസ്ഥയിൽ തങ്ങളെ അവിടെത്തന്നെ നിലനിർത്തണമെന്ന് ജൂതന്മാർ റസൂൽ(സ)യോട് ആവശ്യപ്പെട്ടു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഞങ്ങൾ ഉദ്ദേശിക്കുന്ന കാലത്തോളം ആ വ്യവസ്ഥയിൽ ഞാൻ നിങ്ങളെ അവിടെത്തന്നെ നിലനിർത്താം." അങ്ങനെ അവർ അപ്രകാരം കഴിഞ്ഞുകൂടി. കാരക്ക വ്യത്യസ്ത ഓഹരികളായി വീതം വെക്കപ്പെട്ടിരുന്നത് ഖൈബറിലെ ഈ പകുതിയിൽ നിന്നായിരുന്നു. റസൂൽ(സ) അതിൽനിന്ന് അഞ്ചിലൊന്ന് എടുക്കും. അവിടുന്ന് ആ അഞ്ചിലൊന്നിൽ നിന്ന് തന്റെ പത്നിമാരിൽ ഓരോരുത്തർക്കും നൂറ് വസ്ഖ് കാരക്കയും ഇരുപത് വസ്ഖ് ബാർളിയും ഭക്ഷണത്തിനായി നൽകാറുണ്ടായിരുന്നു. ശേഷം ഉമർ(റ) ജൂതരെ പുറത്താക്കാൻ ഉദ്ദേശിച്ചപ്പോൾ നബി(സ)യുടെ പത്നിമാർക്ക് ഇപ്രകാരം സന്ദേശമയച്ചു: നിങ്ങളിൽ ആർക്കെങ്കിലും നൂറ് വസ്ഖ് കാരക്കയുടെ മതിപ്പു കണക്കാക്കി ഈത്തപ്പനകൾ ഞാൻ വീതിച്ചു നൽകുന്നതും, അങ്ങനെ അവയും അവയുടെ ഭൂമിയും അവയുടെ വെള്ളവും തനിക്കാവുന്നതും, കൃഷിയിടങ്ങളിൽനിന്ന് ഇരുപത് വസ്ഖ് ധാന്യങ്ങളുടെ മതിപ്പു കണക്കാക്കിയുള്ള കൃഷിയിടം വീതിച്ചു നൽകുന്നതും ഇഷ്ടപ്പെടുന്നവർ ഉണ്ടെങ്കിൽ നാം അങ്ങനെ ചെയ്യാം. അതല്ല അഞ്ചിലൊന്നിൽനിന്ന് തനിക്കുള്ള വിഹിതം അതേപോലെ നിലനിർത്തിത്തരാൻ ആരെങ്കിലും ഇഷ്ടപ്പെടുന്നുണ്ടെങ്കിൽ നാം അങ്ങനെയും ചെയ്യാം. (മു,ദ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 106, 106, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَزَا خَيْبَرَ، فَأَصَبْنَاهَا عَنْوَةً، فَجُمِعَ السَّبْيُ. (ق,د)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) ഖൈബറിനോട് യുദ്ധംചെയ്യുകയും അതിനെ ഞങ്ങൾ ബലമായി പിടിച്ചെടുക്കുകയും ചെയ്തു. അങ്ങനെ ബന്ധികളെല്ലാം ഒരുമിച്ചുകൂട്ടപ്പെട്ടു. (ബു,മു,ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 106, 106, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ سَهْلِ بْنِ أَبِي حَثْمَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَسَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ نِصْفَيْنِ: نِصْفًا لِنَوَائِبِهِ وَحَاجَتِهِ، وَنِصْفًا بَيْنَ الْمُسْلِمِينَ، قَسَمَهَا بَيْنَهُمْ عَلَى ثَمَانِيَةَ عَشَرَ سَهْمًا. (د)', 'സഹ്ലുബ്നു അബീഹസ്മ(റ): റസൂൽ(സ) ഖൈബറിനെ രണ്ടു ഭാഗങ്ങളായി വീതിച്ചു. ഒരു പകുതി അതിൽതന്നെയുള്ള ആവശ്യങ്ങൾക്കും ചെലവുകൾക്കും വേണ്ടിയായിരുന്നു. മറ്റൊരു പകുതി മുസ്ലിംകൾക്കിടയിൽ വീതിക്കാനുള്ളതായിരുന്നു. അതിനെ പതിനെട്ട് ഓഹരി ആക്കിക്കൊണ്ടാണ് അവിടുന്ന് അവർക്കിടയിൽ വീതിച്ചത്. (ദ)', 'سَهْلِ بْنِ أَبِي حَثْمَةَ', 'സഹ്ലുബ്നു അബീഹസ്മ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 106, 106, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ بُشَيْرِ بْنِ يَسَارٍ: أَنَّهُ سَمِعَ نَفَرًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالُوا، فَذَكَرَ هَذَا الْحَدِيثَ، قَالَ: فَكَانَ النِّصْفُ سِهَامَ الْمُسْلِمِينَ وَسَهْمَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَزَلَ النِّصْفَ لِلْمُسْلِمِينَ، لِمَا يَنُوبُهُ مِنَ الْأُمُورِ وَالنَّوَائِبِ.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=172), 1, 'وَفِي رِوَايَةٍ: عَنْ رِجَالٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا ظَهَرَ عَلَى خَيْبَرَ قَسَمَهَا عَلَى سِتَّةٍ وَثَلَاثِينَ سَهْمًا، جَمَعَ كُلَّ سَهْمٍ مِائَةَ سَهْمٍ، فَكَانَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلِلْمُسْلِمِينَ النِّصْفُ مِنْ ذَلِكَ، وَعَزَلَ النِّصْفَ الْبَاقِيَ لِمَنْ نَزَلَ بِهِ مِنَ الْوُفُودِ وَالْأُمُورِ وَنَوَائِبِ النَّاسِ.', 'മറ്റൊരു നിവേദനം: നബി(സ)യുടെ അനുചരരിൽപെട്ട ആളുകളിൽനിന്ന് (നിവേദനം): റസൂൽ(സ) ഖൈബർ ജയിച്ചടക്കിയപ്പോൾ അതിനെ മുപ്പത്തിയാറ് ഓഹരികളായി വീതിച്ചു. അവയിൽ ഓരോ ഓഹരിയും നൂറ് ഓഹരികളെ ഉൾകൊള്ളുന്നതായിരുന്നു. അതിൽനിന്നുള്ള പകുതി റസൂൽ(സ)ക്കും മുസ്ലിംകൾക്കുമുള്ളതായിരുന്നു. ബാക്കിവന്ന പകുതിഭാഗത്തെ അവിടെ വരുന്ന യാത്രാ സംഘങ്ങൾക്കും അതിൽതന്നെ വരുന്ന ചെലവുകൾക്കും ജനങ്ങൾ നേരിടുന്ന വിപത്തുകൾക്കും വേണ്ടി നബി(സ) ഒഴിച്ചിട്ടതാണ്.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=172), 2, 'وَفِي رِوَايَةٍ مُرْسَلَةٍ قَالَ: لَمَّا أَفَاءَ اللَّهُ عَلَى نَبِيِّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ قَسَمَهَا عَلَى سِتَّةٍ وَثَلَاثِينَ سَهْمًا، جَمَعَ كُلَّ سَهْمٍ مِائَةَ سَهْمٍ، فَعَزَلَ نِصْفَهَا لِنَوَائِبِهِ وَمَا يَنْزِلُ بِهِ: الْوَطِيحَةَ وَالْكُتَيْبَةَ وَمَا أُحِيزَ مَعَهُمَا، وَعَزَلَ النِّصْفَ الْآخَرَ، فَقَسَمَهُ بَيْنَ الْمُسْلِمِينَ: الشَّقَّ وَالنَّطَاةَ وَمَا أُحِيزَ مَعَهُمَا، وَكَانَ سَهْمُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيمَا أُحِيزَ مَعَهُمَا.', 'മറ്റൊരു നിവേദനം: നിവേദകൻ പറഞ്ഞു: ഖൈബറിനെ അല്ലാഹു തന്റെ പ്രവാചകന് ഫൈഅ് (യുദ്ധംചെയ്യാതെ ലഭിക്കുന്ന ശത്രുമുതൽ) ആയി നൽകിയപ്പോൾ അതിനെ അവിടുന്ന് മുപ്പത്തിയാറ് ഓഹരികളായി വീതിച്ചു. മുഴുവൻ ഓഹരികളെയും അവിടുന്ന് നൂറ് ഓഹരികളാക്കി ഒരുമിച്ചുകൂട്ടി. ശേഷം അതിൽനിന്നുള്ള പകുതിയെ അഥവാ വത്വീഹത്, കുതൈബത് എന്നീ കോട്ടകളെയും അവയോടൊപ്പമുള്ള മറ്റു പ്രദേശങ്ങളെയും അവയ്ക്കുണ്ടാകുന്ന ചെലവുകൾക്കും വിപത്തുകൾക്കുംവേണ്ടി റസൂൽ(സ) മാറ്റിവെച്ചു. മറ്റൊരു പകുതിയെ, അഥവാ ശഖ്, നത്വാത് എന്നീ കോട്ടകളെയും അവയോടൊപ്പമുള്ള പ്രദേശങ്ങളെയും അവിടുന്ന് മാറ്റിവെക്കുകയും അവയെ മുസ്ലിംകൾക്കിടയിൽ വീതിക്കുകയും ചെയ്തു. റസൂൽ(സ)ക്കുള്ള വിഹിതം അവയോടൊപ്പമുള്ള പ്രദേശങ്ങളിലായിരുന്നു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=172), 3, 'وَفِي رِوَايَةٍ مُرْسَلَةٍ أَيْضًا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا أَفَاءَ اللَّهُ عَلَيْهِ خَيْبَرَ قَسَمَهَا سِتَّةً وَثَلَاثِينَ سَهْمًا، جَمَعَ: فَعَزَلَ لِلْمُسْلِمِينَ الشَّطْرَ ثَمَانِيَةَ عَشَرَ سَهْمًا، يَجْمَعُ كُلُّ سَهْمٍ مِائَةً، النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَعَهُمْ، لَهُ سَهْمٌ كَسَهْمِ أَحَدِهِمْ. وَعَزَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَمَانِيَةَ عَشَرَ سَهْمًا – وَهُوَ الشَّطْرُ – لِنَوَائِبِهِ وَمَا يَنْزِلُ بِهِ مِنْ أَمْرِ الْمُسْلِمِينَ، فَكَانَ ذَلِكَ: الْوَطِيحَ وَالْكُتَيْبَةَ وَالسَّلَالِمَ وَتَوَابِعَهَا، فَلَمَّا صَارَتِ الْأَمْوَالُ بِيَدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالْمُسْلِمِينَ لَمْ يَكُنْ لَهُمْ عُمَّالٌ يَكْفُونَهُمْ عَمَلَهَا، فَدَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْيَهُودَ فَعَامَلَهُمْ. (د)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ)ക്ക് അല്ലാഹു ഖൈബറിനെ ഫൈഅായി നൽകിയപ്പോൾ അതിനെ മൊത്തം മുപ്പത്തിയാറ് ഓഹരികളായി വീതിച്ചു. അങ്ങനെ മൊത്തം ഓഹരികളെ നൂറാക്കിയിട്ട് അതിൽനിന്നുള്ള പകുതിയെ, അഥവാ പതിനെട്ട് ഓഹരികളെ, അവിടുന്ന് മുസ്ലിംകൾക്കായി മാറ്റിവെച്ചു. നബി(സ)യും അവരോടൊപ്പം പങ്കുകാരനായിരുന്നു. എല്ലാവരെയും പോലെ അവിടുത്തേക്കും ഒരു വിഹിതം തന്നെയാണ് ഉണ്ടായിരുന്നത്. പതിനെട്ട് ഓഹരികളെ, അഥവാ പകുതിയെ, അതിലുണ്ടാകുന്ന വിപത്തുകൾക്കും മുസ്ലിംകൾ നേരിടുന്ന പ്രശ്നങ്ങൾക്കുംവേണ്ടി റസൂൽ(സ) മാറ്റിവെച്ചു. വത്വീഹ്, കുതൈബത്, സലാലിം എന്നീ കോട്ടകളും അവയോട് ചേർന്ന പ്രദേശങ്ങളുമായിരുന്നു അത്. സമ്പത്തെല്ലാം നബി(സ)യുടെയും മുസ്ലിംകളുടെയും നിയന്ത്രണത്തിൽ വന്നപ്പോൾ അതിനുവേണ്ട ജോലികളെല്ലാം ചെയ്യുന്ന ജോലിക്കാർ അവർക്ക് (മുസ്ലിംകൾക്ക്) ഉണ്ടായിരുന്നില്ല. അതിനാൽ റസൂൽ(സ) ജൂതരെ വിളിക്കുകയും അവരെ അതിന്റെ ജോലികൾ (കൂലിക്കു പകരമായി) ഏൽപിക്കുകയും ചെയ്തു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ مُجَمِّعِ بْنِ جَارِيَةَ الْأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ – وَكَانَ أَحَدَ الْقُرَّاءِ الَّذِينَ قَرَءُوا الْقُرْآنَ – قَالَ: قُسمَتْ خَيْبَرُ عَلَى أَهْلِ الْحُدَيْبِيَةِ، فَقَسَمَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى ثَمَانِيَةَ عَشَرَ سَهْمًا، وَكَانَ الْجَيْشُ أَلْفًا وَخَمْسَ مِائَةٍ فِيهِمْ ثَلَاثُ مِائَةِ فَارِسٍ، فَأَعْطَى الْفَارِسَ سَهْمَيْنِ، وَأَعْطَى الرَّاجِلَ سَهْمًا. (د)', 'മുജമ്മിളുബ്നുജാരിയതുൽ അൻസാരി(റ): - ഖുർആൻ പാരായണം ചെയ്തിരുന്ന ഖാരിഇഊങ്ങളിൽപെട്ട ആളായിരുന്നു അദ്ദേഹം -: ഖൈബർ ഭൂമി ഹുദൈബിയ്യയിൽ (സന്ധിയിൽ) പങ്കെടുത്തവർക്കായി വീതിക്കപ്പെട്ടു. പതിനെട്ട് ഓഹരികളായിട്ടാണ് റസൂൽ(സ) അതിനെ വീതിച്ചത്. ആയിരത്തഞ്ഞൂറ് ആളുകളായിരുന്നു സൈന്യത്തിലുണ്ടായിരുന്നത്. അവരിൽ മൂന്നൂറ് കുതിരപ്പടയാളികളുമുണ്ടായിരുന്നു. അവിടുന്ന് കുതിരപ്പടയാളികൾക്ക് രണ്ട് ഓഹരി വീതവും കാലാൾപടയാളികൾക്ക് ഓരോ വിഹിതവും നൽകി. (ദ)', 'مُجَمِّعِ بْنِ جَارِيَةَ الْأَنْصَارِيِّ', 'മുജമ്മിളുബ്നുജാരിയതുൽ അൻസാരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 108, 108, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنِ الزُّهْرِيِّ، وَعَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ، وَبَعْضِ وَلَدِ مُحَمَّدِ بْنِ مَسْلَمَةَ، قَالُوا: بَقِيَتْ بَقِيَّةٌ مِنْ أَهْلِ خَيْبَرَ تَحَصَّنُوا، فَسَأَلُوا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَحْقِنَ دِمَاءَهُمْ وَيُسَيِّرَهُمْ، فَفَعَلَ، فَسَمِعَ بِذَلِكَ أَهْلُ فَدَكٍ فَنَزَلُوا عَلَى مِثْلِ ذَلِكَ، فَكَانَتْ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاصَّةً، لِأَنَّهُ لَمْ يُوجَفْ عَلَيْهَا بِخَيْلٍ وَلَا رِكَابٍ. مرسل. (د)', 'സുഹ്രി(റ), അബ്ദുല്ലാഹിബ്നു അബീബക്ർ(റ), മുഹമ്മദുബ്നു മസ്ലമ(റ)വിന്റെ സന്താനങ്ങളിലൊരാൾ എന്നിവരിൽനിന്ന് നിവേദനം: അവർ പറഞ്ഞു: ഖൈബർ നിവാസികളിൽ കോട്ടയിൽ അഭയം പ്രാപിച്ചിരുന്ന ഒരു വിഭാഗം അവശേഷിച്ചിരുന്നു. തങ്ങളുടെ രക്തം സംരക്ഷിക്കണമെന്നും തങ്ങളെ പോകാൻ അനുവദിക്കണമെന്നും അവർ റസൂൽ(സ)യോടാവശ്യപ്പെട്ടു. അവിടുന്ന് അപ്രകാരം ചെയ്തു. ഈ വിവരം ഫദക് നിവാസികൾ കേൾക്കുകയും അതേ വ്യവസ്ഥയിൽ തന്നെ അവരും ഇറങ്ങുകയും ചെയ്തു. ആ പ്രദേശങ്ങളെല്ലാം റസൂൽ(സ)ക്ക് സ്വന്തമായുള്ളതായിരുന്നു. കാരണം, അതിനുവേണ്ടി ഒട്ടകങ്ങളോ കുതിരകളോ ഓടിക്കപ്പെട്ടിട്ടുണ്ടായിരുന്നില്ല (യുദ്ധം നടന്നിട്ടുണ്ടായിരുന്നില്ല). ഹദീസ് മുർസലാണ്. (ദ)', 'الزُّهْرِيِّ، وَعَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ، وَبَعْضِ وَلَدِ مُحَمَّدِ بْنِ مَسْلَمَةَ، قَالُوا', 'സുഹ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 108, 108, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ سَعِيدِ بْنِ الْمُسَيِّبِ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ افْتَتَحَ بَعْضَ خَيْبَرَ عَنْوَةً. (د)', 'സഈദുബ്നു മുസയ്യബ്(റ): ഖൈബറിലെ ചില ഭാഗങ്ങളെ റസൂൽ(സ) ബലപ്രയോഗത്തിലൂടെ ജയിച്ചടക്കി. (ദ)', 'سَعِيدِ بْنِ الْمُسَيِّبِ', 'സഈദുബ്നു മുസയ്യബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 108, 108, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنِ ابْنِ شِهَابٍ: أَنَّ خَيْبَرَ كَانَ بَعْضُهَا عَنْوَةً وَبَعْضُهَا صُلْحًا، وَالْكَتِيبَةَ أَكْثَرُهَا عَنْوَةً وَفِيهَا صُلْحٌ. قِيلَ لِمَالِكٍ: وَمَا الْكَتِيبَةُ؟ قَالَ: أَرْضُ خَيْبَرَ، وَهِيَ أَرْبَعُونَ أَلْفَ عَذْقٍ. وَفِي رِوَايَةٍ: قَالَ: بَلَغَنِي أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ افْتَتَحَ خَيْبَرَ عَنْوَةً بَعْدَ الْقِتَالِ، وَنَزَلَ مَنْ نَزَلَ مِنْ أَهْلِهَا عَلَى الْجَلَاءِ بَعْدَ الْقِتَالِ. (د)', 'ഇബ്നുഷിഹാബ്(റ): ഖൈബറിന്റെ ചില ഭാഗങ്ങൾ ബലമായും ചിലത് സന്ധിയിലൂടെയും പിടിച്ചടക്കിയതായിരുന്നു. കതീബയുടെ അതികഭാഗവും ബലമായി പിടിച്ചെടുത്തതായിരുന്നു. സന്ധിയിലൂടെ പിടിച്ചെടുത്ത ഭാഗവും അതിലുണ്ടായിരുന്നു. മാലിക്(റ)വിനോട് ചോദിക്കപ്പെട്ടു: എന്താണ് കതീബ? അദ്ദേഹം പറഞ്ഞു: ഖൈബറിലെ ഒരു സ്ഥലമാണത്. നാൽപതിനായിരം ഈത്തപ്പനകളടങ്ങുന്നതാണ് ആ സ്ഥലം. മറ്റൊരു നിവേദനം: നിവേദകൻ പറയുന്നു: യുദ്ധത്തിനുശേഷം ബലപ്രയോഗത്തിലൂടെയാണ് റസൂൽ(സ) ഖൈബർ ജയിച്ചടക്കിയത് എന്നാണ് എനിക്കു ലഭിച്ച വിവരം. നാടുവിടാം എന്ന വ്യവസ്ഥയിലാണ്, യുദ്ധത്തിനു ശേഷം അന്നാട്ടുകാരിൽനിന്ന് കീഴടങ്ങിയവരെല്ലാം, കീഴടങ്ങിയത്. (ദ)', 'ابْنِ شِهَابٍ', 'ഇബ്നുഷിഹാബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 108, 109, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=176), 1, 'وَفِي رِوَايَةٍ: قَالَ: بَلَغَنِي أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ افْتَتَحَ خَيْبَرَ عَنْوَةً بَعْدَ الْقِتَالِ، وَنَزَلَ مَنْ نَزَلَ مِنْ أَهْلِهَا عَلَى الْجَلَاءِ بَعْدَ الْقِتَالِ. (د)', 'മറ്റൊരു നിവേദനം: നിവേദകൻ പറയുന്നു: യുദ്ധത്തിനുശേഷം ബലപ്രയോഗത്തിലൂടെയാണ് റസൂൽ(സ) ഖൈബർ ജയിച്ചടക്കിയത് എന്നാണ് എനിക്കു ലഭിച്ച വിവരം. നാടുവിടാം എന്ന വ്യവസ്ഥയിലാണ്, യുദ്ധത്തിനു ശേഷം അന്നാട്ടുകാരിൽനിന്ന് കീഴടങ്ങിയവരെല്ലാം, കീഴടങ്ങിയത്. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنِ ابْنِ شِهَابٍ قَالَ: خَمَّسَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ، ثُمَّ قَسَمَ سَائِرَهَا عَلَى مَنْ شَهِدَهَا وَمَنْ غَابَ عَنْهَا مِنْ أَهْلِ الْحُدَيْبِيَةِ. (د)', 'ഇബ്നുശിഹാബ്(റ): റസൂൽ(സ) ഖൈബറിനെ അഞ്ചു ഒഹരികളായി വീതിച്ചു. ശേഷം ബാക്കി ഓഹരികളെ ആ യുദ്ധത്തിൽ പങ്കെടുത്തവർക്കും അതിൽ പങ്കെടുക്കാത്ത ഹുദൈബിയ സന്ധിയിലെ ആളുകൾക്കും വീതിച്ചു നൽകി. (ദ)', 'ابْنِ شِهَابٍ قَالَ', 'ഇബ്നുശിഹാബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 109, 109, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَوْلَا آخِرُ الْمُسْلِمِينَ مَا فُتِحَتْ قَرْيَةٌ إِلَّا قَسَمْتُهَا كَمَا قَسَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ. (خ,د)', 'ഉമർ(റ): ശേഷം വരുന്ന മുസ്ലിംകളില്ലായിരുന്നുവെങ്കിൽ ഞാൻ ജയിച്ചടക്കുന്ന എല്ലാ നാടുകളെയും, റസൂൽ(സ) ഖൈബറിനെ വീതിച്ചതു പോലെ, ഞാൻ വീതിക്കുമായിരുന്നു. (ബു,ദ)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 109, 109, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ عَنْ شَأْنِ ثَقِيفٍ إِذْ بَايَعَتْ، قَالَ: اشْتَرَطَتْ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنْ لَا صَدَقَةَ عَلَيْهَا وَلَا جِهَادَ، وَأَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدَ ذَلِكَ يَقُولُ: "سَيَتَصَدَّقُونَ وَيُجَاهِدُونَ إِذَا أَسْلَمُوا". (د)', 'ജാബിർ(റ): സഖീഫ് ഗോത്രം ഉടമ്പടി ചെയ്ത സന്ദർഭത്തെ സംബന്ധിച്ച് നിവേദകൻ പറയുന്നു: അവർ നബി(സ)യോട് ഇപ്രകാരം നിബന്ധനവെച്ചു: അവർക്ക് സകാതോ ധർമ്മസമരമോ നിർബന്ധമാകാൻ പാടില്ല. അതിനുശേഷം നബി(സ) ഇപ്രകാരം പറയുന്നത് അദ്ദേഹം കേട്ടു: "അവർ മുസ്ലിംകളായിക്കഴിഞ്ഞാൽ സകാത് നൽകുകയും ധർമ്മസമരം ചെയ്യുകയും ചെയ്യും." (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 109, 109, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ عُثْمَانَ بْنِ أَبِي الْعَاصِ رَضِيَ اللَّهُ عَنْهُ: أَنَّ وَفْدَ ثَقِيفٍ لَمَّا قَدِمُوا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْزَلَهُمُ الْمَسْجِدَ، لِيَكُونَ أَرَقَّ لِقُلُوبِهِمْ، فَاشْتَرَطُوا عَلَيْهِ: أَنْ لَا يُحْشَرُوا وَلَا يُعْشَرُوا وَلَا يُجَبُّوا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَكُمْ أَنْ لَا تُحْشَرُوا وَلَا تُعْشَرُوا وَلَا خَيْرَ فِي دِينٍ لَيْسَ فِيهِ رُكُوعٌ". (د)', 'ഉസ്മാനുബ്നു അബിൽആസ്(റ): സഖീഫ് ഗോത്രത്തിൽ നിന്നുള്ള സംഘം റസൂൽ(സ)യുടെ അടുത്ത് വന്നപ്പോൾ അവിടുന്ന് അവരെ പള്ളിയിൽ ഇറക്കി. അവരുടെ ഹൃദയങ്ങൾക്ക് (ഇസ്ലാമുമായുള്ള സമീപനത്തിൽ) മൃദുലത ലഭിക്കാനായിരുന്നു അത്. അങ്ങനെ റസൂൽ(സ)യോട് അവർ ഇപ്രകാരം നിബന്ധന വെച്ചു: അവർ യുദ്ധത്തിനുവേണ്ടി വിളിക്കപ്പെടാൻ പാടില്ല, അവരിൽനിന്ന് സകാത് പിടിക്കപ്പെടാൻ പാടില്ല, അവരോട് റുകൂഅ് ചെയ്യാൻ (നമസ്കരിക്കാൻ) കൽപിക്കപ്പെടരുത്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "യുദ്ധത്തിനു വിളിക്കപ്പെടാതിരിക്കുക, സകാത് പിടിക്കപ്പെടാതിരിക്കുക എന്നിവ നിങ്ങൾക്ക് അംഗീകരിച്ചു തരാം. റുകൂഅ് (നമസ്കാരം) ഇല്ലാത്ത ഒരു മതത്തിലും നന്മയില്ല." (ദ)', 'عُثْمَانَ بْنِ أَبِي الْعَاصِ', 'ഉസ്മാനുബ്നു അബിൽആസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 109, 109, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنْ عَامِرِ بْنِ شَهْرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ لِي هَمْدَانُ: هَلْ أَنْتَ آتٍ هَذَا الرَّجُلَ وَمُرْتَادٌ لَنَا: فَإِنْ رَضِيتَ لَنَا شَيْئًا قَبِلْنَاهُ، وَإِنْ كَرِهْتَ شَيْئًا كَرِهْنَاهُ؟ قُلْتُ: نَعَمْ، فَجِئْتُ حَتَّى قَدِمْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَرَضِيتُ أَمْرَهُ، وَأَسْلَمَ قَوْمِي، وَكَتَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَذَا الْكِتَابَ إِلَى عُمَيْرٍ ذِي مُرَّانَ، قَالَ: وَبَعَثَ مَالِكَ بْنَ مَرَارَةَ الرَّهَاوِيَّ إِلَى الْيَمَنِ جَمِيعًا، فَأَسْلَمَ عَكٌّ ذُو خَيْوَانَ، قَالَ: فَقِيلَ لِعَكٍّ: انْطَلِقْ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَخُذْ مِنْهُ الْأَمَانَ عَلَى قَرْيَتِكَ وَمَالِكَ. فَقَدِمَ وَكَتَبَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ مِنْ مُحَمَّدٍ رَسُولِ اللَّهِ لِعَكٍّ ذِي خَيْوَانَ: إِنْ كَانَ صَادِقًا فِي أَرْضِهِ وَمَالِهِ وَرَقِيقِهِ فَلَهُ الْأَمَانُ وَذِمَّةُ اللَّهِ وَذِمَّةُ مُحَمَّدٍ رَسُولِ اللَّهِ، وَكَتَبَ خَالِدُ بْنُ سَعِيدِ بْنِ الْعَاصِ". (د)', 'ആമിറുബ്നു ശഹ്ർ(റ): റസൂൽ(സ) (ഇസ്ലാമിന്റെ പ്രബോധനവുമായി) രംഗപ്രവേശം ചെയ്തപ്പോൾ ഹമദാൻ ഗോത്രക്കാർ എന്നോട് പറഞ്ഞു: താങ്കൾ ഈ വ്യക്തിയുടെ അടുത്ത് ചെന്ന് ഞങ്ങൾക്കുവേണ്ടി കാര്യങ്ങൾ അന്വേഷിക്കുമോ, താങ്കൾ വല്ല കാര്യവും ഞങ്ങൾക്കുവേണ്ടി തൃപ്തിപ്പെട്ടാൽ ഞങ്ങളത് സ്വീകരിക്കും, താങ്കൾ വല്ലതും വെറുക്കുന്നുവെങ്കിൽ ഞങ്ങളുമത് വെറുക്കും? ഞാൻ പറഞ്ഞു: അതെ. അങ്ങനെ ഞാൻ വന്ന് റസൂൽ(സ)യുടെ മുന്നിൽ ചെന്നു. അവിടുത്തെ കാര്യം എനിക്ക് തൃപ്തമാവുകയും എന്റെ സമൂഹം ഇസ്ലാം സ്വീകരിക്കുകയും ചെയ്തു. അങ്ങനെ റസൂൽ(സ) ഉമൈർ ദുമർറാനിലേക്ക് ഈ കത്ത് എഴുതി: നിവേദകൻ പറയുന്നു: യമനിലേക്ക് മൊത്തമായി മാലികുബ്നു മിറാറതുർറഹാവിയെ റസൂൽ(സ) നിയോഗിക്കുകയം ചെയ്തു. അങ്ങനെ അക്ക് ദൂഖയ്വാൻ ഇസ്ലാം സ്വീകരിച്ചു. അപ്പോൾ അക്കിനോട് ഇപ്രകാരം പറയപ്പെട്ടു: താങ്കൾ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് താങ്കളുടെ മുതലിനും ഗ്രാമത്തിനും മേൽ സംരക്ഷണം നേടുക. അങ്ങനെ അദ്ദേഹം വരികയും റസൂൽ(സ) അദ്ദേഹത്തിനു വേണ്ടി ഇപ്രകാരം എഴുതിക്കൊടുക്കുകയും ചെയ്തു: "കരുണാമയനും കരുണാനിധിയുമായ അല്ലാഹുവിന്റെ നാമത്തിൽ, മുഹമ്മദുർറസൂലുല്ലാഹി(സ) അക്കു ദീഖയ്വാനിനു വേണ്ടി രേഖപ്പെടുത്തുന്ന വ്യവസ്ഥ: അദ്ദേഹം തന്റെ ഭൂമിയിലും മുതലിലും അടിമകളിലും സത്യസന്ധതയുള്ളവനാണെങ്കിൽ അദ്ദേഹത്തിന് സംരക്ഷണവും, അല്ലാഹുവിന്റെയും മുഹമ്മദുർറസൂലുല്ലാഹി(സ)യുടെയും ഭാഗത്തു നിന്നുള്ള ഉത്തരവാദിത്തവുമുണ്ട്. ഖാലിദുബ്നു സഈദുബ്നുൽ ആസ് ആണ് ഇത് എഴുതിയത്." (ദ)', 'عَامِرِ بْنِ شَهْرٍ', 'ആമിറുബ്നു ശഹ്ർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 109, 110, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ أَبْيَضَ بْنِ حَمَّالٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ كَلَّمَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الصَّدَقَةِ، حِينَ وَفَدَ عَلَيْهِ، فَقَالَ: "يَا أَخَا سَبَأٍ، لَا بُدَّ مِنْ صَدَقَةٍ". فَقَالَ: إِنَّمَا زَرَعْنَا الْقُطْنَ يَا رَسُولَ اللَّهِ، وَقَدْ تَبَدَّدَتْ سَبَأٌ، وَلَمْ يَبْقَ مِنْهُمْ إِلَّا قَلِيلٌ بِمَأْرِبَ. فَصَالَحَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى سَبْعِينَ حُلَّةَ بَزٍّ – مِنْ قِيمَةِ وَفَاءِ بَزِّ الْمَعَافِرِ – كُلَّ سَنَةٍ، عَمَّنْ بَقِيَ مِنْ سَبَأٍ بِمَأْرِبَ، فَلَمْ يَزَالُوا يُؤَدُّونَهَا حَتَّى قُبِضَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَإِنَّ الْعُمَّالَ انْتَقَضُوا عَلَيْهِمْ بَعْدَ قَبْضِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيمَا صَالَحَ أَبْيَضُ بْنُ حَمَّالٍ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْحُلَلِ السَّبْعِينَ، فَرَدَّ ذَلِكَ أَبُو بَكْرٍ عَلَى مَا وَضَعَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، حَتَّى مَاتَ أَبُو بَكْرٍ، فَلَمَّا مَاتَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ انْتَقَضَ ذَلِكَ وَصَارَتْ عَلَى الصَّدَقَةِ. (د)', 'അബ്യളുബ്നു ഹമ്മാൽ(റ): അദ്ദേഹം റസൂൽ(സ)യുടെ അടുത്ത് ചെന്നപ്പോൾ സകാതിന്റെ വിഷയത്തിൽ അവിടത്തോട് ചർച്ച നടത്തി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "സബഉകാരുടെ സഹോദരാ, സകാത് കൂടാതെ കഴിയുകയില്ല." അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങൾ കൃഷി ചെയ്തിട്ടുള്ളത് പരുത്തി മാത്രമാണ്. സബഅ് ഗോത്രം ഛിന്നഭിന്നമായിപ്പോയിട്ടുണ്ട്. അവരിൽ കുറച്ചുപേർ മാത്രമേ മഅ്രിബിൽ ശേഷിച്ചിട്ടുള്ളൂ. അങ്ങനെ സബഅ് ഗോത്രക്കാരിൽനിന്ന് മഅ്രിബ് ദേശത്ത് അവശേഷിച്ചവർക്കു വേണ്ടി, മആഫിർ വസ്ത്രത്തിന്റെ തുല്ല്യ വിലയുള്ള എഴുപത് വസ്ത്രങ്ങൾ, വർഷം തോറും നൽകണമെന്ന് നബി(സ) (അദ്ദേഹവുമായി) സന്ധിചെയ്തു. റസൂൽ(സ) വഫാതാകുംവരെ അവർ ആ വിഹിതം കൊടുത്തു പോന്നു. അബ്യളുബ്നു ഹമ്മാൽ(റ) റസൂൽ(സ)യുമായി സന്ധിചെയ്ത എഴുപത് വസ്ത്രങ്ങളുടെ വ്യവസ്ഥ റസൂൽ(സ) വഫാതായതിനു ശേഷം ഉദ്യോഗസ്ഥർ അവരിൽനിന്നും എടുത്തു കളഞ്ഞു. എന്നാൽ അബൂബക്ർ(റ) റസൂൽ(സ) നിശ്ചയിച്ചിരുന്നതു പോലെ വീണ്ടുമതിനെ മാറ്റി. അബൂബക്ർ(റ) വഫാതാകുവോളം അതു തുടർന്നു. അബൂബക്ർ(റ) വഫാതായപ്പോൾ (മുമ്പുണ്ടായിരുന്ന) വ്യവസ്ഥ ഇല്ലാതാവുകയും അത് സാധാരണ സകാതുപോലെ ആയി മാറുകയും ചെയ്തു. (ദ)', 'أَبْيَضَ بْنِ حَمَّالٍ', 'അബ്യളുബ്നു ഹമ്മാൽ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 110, 111, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنَعَتِ الْعِرَاقُ قَفِيزَهَا وَدِرْهَمَهَا، وَمَنَعَتِ الشَّامُ مُدْيَهَا وَدِينَارَهَا، وَمَنَعَتْ مِصْرُ إِرْدَبَّهَا وَدِينَارَهَا، ثُمَّ عُدْتُمْ مِنْ حَيْثُ بَدَأْتُمْ". قَالَهَا ثَلَاثَ مَرَّاتٍ، شَهِدَ عَلَى ذَلِكَ لَحْمُ أَبِي هُرَيْرَةَ وَدَمُهُ. (م,د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഇറാഖ് അതിലെ ധാന്യങ്ങളെയും ദിർഹമിനെയും തടഞ്ഞുവെക്കും, സിരിയ അതിലെ ധാന്യങ്ങളെയും ദീനാറിനെയും തടഞ്ഞുവെക്കും, ഈജിപ്ത് അതിലെ ധാന്യങ്ങളെയും ദീനാറിനെയും തടഞ്ഞുവെക്കും. ശേഷം തുടങ്ങിയിടത്തേക്ക് നിങ്ങൾ മടങ്ങുന്ന അവസ്ഥ വരും." മൂന്നു പ്രാവശ്യം അവിടുന്ന് ഇപ്രകാരം പറഞ്ഞു. അബൂഹുറൈറയുടെ മാംസവും രക്തവും അതിന് സാക്ഷിയായിട്ടുണ്ട്. (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 111, 111, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَيُّمَا قَرْيَةٍ أَتَيْتُمُوهَا وَأَقَمْتُمْ فِيهَا فَسَهْمُكُمْ فِيهَا، وَأَيُّمَا قَرْيَةٍ عَصَتِ اللَّهَ وَرَسُولَهُ فَإِنَّ خُمُسَهَا لِلَّهِ وَلِلرَّسُولِ، ثُمَّ هِيَ لَكُمْ". (م,د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഏതെങ്കിലും ഗ്രാമത്തിൽ എത്തുകയും അവിടെ കഴിയുകയുമാണെങ്കിൽ നിങ്ങൾക്കുള്ള വിഹിതം (ആതിഥ്യം) അവിടെനിന്ന് ലഭിക്കേണ്ടതുണ്ട്. ഏതെങ്കിലും ഗ്രാമം അല്ലാഹുവിനെയും അവന്റെ റസൂലിനെയും ധിക്കരിക്കുന്നുവെങ്കിൽ നിശ്ചയം അതിന്റെ അഞ്ചിലൊന്ന് അല്ലാഹുവിനും റസൂലിനും അർഹതപ്പെട്ടതാണ്. ശേഷം അത് നിങ്ങൾക്കുള്ളതാണ്." (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 111, 111, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَقْطَعَهُ أَرْضًا بِحَضْرَمَوْتَ. (د,ت)', 'വാഇലുബ്നു ഹുജ്ർ(റ): നിശ്ചയം നബി(സ) അദ്ദേഹത്തിന് ഹളർമൗതിലെ ഒരു ഭൂമി പതിച്ചു നൽകി. (ദ,തു)', 'وَائِلِ بْنِ حُجْرٍ', 'വാഇലുബ്നു ഹുജ്ർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 111, 111, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ عَمْرِو بْنِ حُرَيْثٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَطَّ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَارًا بِالْمَدِينَةِ بِقَوْسٍ، وَقَالَ: "أَزِيدُكَ، أَزِيدُكَ". (د)', 'അംറുബ്നു ഹുറൈസ്(റ): റസൂൽ(സ) അമ്പുകൊണ്ട് മദീനയിൽ ഒരു വീട് (വീടിനുള്ള ഭൂമി) എനിക്ക് വരച്ചു തന്നു (അമ്പുകൊണ്ട് ഭൂമിയുടെ സ്ഥാനം നിർണ്ണയിച്ചു). എന്നിട്ട് ചോദിച്ചു: "ഞാൻ കൂടുതൽ നൽകേണ്ടതുണ്ടോ, ഞാൻ കൂടുതൽ നൽകേണ്ടതുണ്ടോ?" (ദ)', 'عَمْرِو بْنِ حُرَيْثٍ', 'അംറുബ്നു ഹുറൈസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 111, 111, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنْ رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ، عَنْ غَيْرِ وَاحِدٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَقْطَعَ بِلَالَ بْنَ الْحَارِثِ الْمُزَنِيَّ مَعَادِنَ الْقَبَلِيَّةِ، وَهِيَ مِنْ نَاحِيَةِ الْفُرْعِ، فَتِلْكَ الْمَعَادِنُ لَا يُؤْخَذُ مِنْهَا إِلَّا الزَّكَاةُ إِلَى الْيَوْمِ. مرسل. (د)', 'റബീഅതുബ്നു അബീ അബ്ദിർറഹ്മാൻ, ഒന്നിലധികം ആളുകളിൽനിന്ന് നിവേദനം: നിശ്ചയം റസൂൽ(സ) ബിലാലുബ്നു ഹാരിസുൽ മുസ്നി(റ)വിന് ഖബ്ലിയയിലെ ഖനികൾ പതിച്ചു നൽകി. അവ ''ഫുർഇ''ന്റെ ഭാഗത്താണ്. ഇന്നേവരെ ആ ഖനികളിൽനിന്ന് സകാത് മാത്രമാണ് (ദാനമായി) സ്വീകരിക്കപ്പെടുന്നത്. ഹദീസ് മുർസലാണ്. (ദ)', 'رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ، عَنْ غَيْرِ وَاحِدٍ', null, null, null, array['د']::text[], array['ദ']::text[], null, null, 111, 112, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ عَوْفٍ الْمُزَنِيِّ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَقْطَعَ بِلَالَ بْنَ الْحَارِثِ الْمُزَنِيَّ مَعَادِنَ الْقَبَلِيَّةِ: جَلْسِيَّهَا وَغَوْرِيَّهَا. وَفِي رِوَايَةٍ: جَلْسَهَا وَغَوْرَهَا، وَحَيْثُ يَصْلُحُ الزَّرْعُ مِنْ قُدْسٍ، وَفِي رِوَايَةٍ: وَجَرْسَهَا وَذَاتَ النُّصُبِ، وَلَمْ يُعْطِهِ حَقَّ مُسْلِمٍ، وَكَتَبَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ، هَذَا مَا أَعْطَى مُحَمَّدٌ رَسُولُ اللَّهِ بِلَالَ بْنَ الْحَارِثِ الْمُزَنِيَّ، أَعْطَاهُ مَعَادِنَ الْقَبَلِيَّةِ جَلْسِيَّهَا وَغَوْرِيَّهَا – وَفِي رِوَايَةٍ: جَلْسَهَا وَغَوْرَهَا – وَحَيْثُ يَصْلُحُ الزَّرْعُ مِنْ قُدْسٍ، وَلَمْ يُعْطِهِ حَقَّ مُسْلِمٍ". وَفِي رِوَايَةٍ: "وَكَتَبَ أُبَيُّ بْنُ كَعْبٍ". (د)', 'ഔഫുൽ മുസ്നി(റ): നിശ്ചയം നബി(സ) ബിലാലുബ്നു ഹാരിസുൽ മുസ്നിക്ക് ഖബ്ലിയ്യയിലെ ഖനികളിൽ ഉയർന്ന ഭാഗങ്ങളെയും താഴ്ന്ന ഭാഗങ്ങളെയും, ഖുദ്സ് പർവ്വതത്തിലെ കൃഷിയോഗ്യമായ ഭാഗങ്ങളെയും പതിച്ചു നൽകി. മറ്റൊരു നിവേദനം: ആ പർവ്വതത്തിന്റെ സമീപ പ്രദേശങ്ങളെയും ദാതുന്നുസ്വുബ് എന്ന പ്രദേശത്തെയും (പതിച്ചു നൽകി). ഒരു മുസ്ലിമിന്റെയും അവകാശമല്ല അവിടുന്ന് അദ്ദേഹത്തിന് നൽകിയത്. നബി(സ) അദ്ദേഹത്തിന് ഇപ്രകാരം എഴുതി നൽകി: "കാരുണ്യവാനും കരുണാനിധിയുമായ അല്ലാഹുവിന്റെ നാമത്തിൽ. അല്ലാഹുവിന്റെ പ്രവാചകനായ മുഹമ്മദ്(സ) ബിലാലുബ്നു ഹാരിസുൽ മുസ്നിക്ക് നൽകിയതാണിത് (ഈ രേഖ). അദ്ദേഹത്തിന് അവിടുന്ന് ഖബ്ലിയ്യയിലെ ഖനികളിൽ ഉയർന്ന ഭാഗങ്ങളെയും താഴ്ന്ന ഭാഗങ്ങളെയും, ഖുദ്സ് പർവ്വതത്തിലെ കൃഷിയോഗ്യമായ ഭാഗങ്ങളെയും പതിച്ചു നൽകിയിരിക്കുന്നു. ഒരു മുസ്ലിമിന്റെയും അവകാശമല്ല അവിടുന്ന് അദ്ദേഹത്തിന് നൽകിയിട്ടുള്ളത്." മറ്റൊരു നിവേദനത്തിൽ: "ഇത് എഴുതിയത് ഉബയ്യുബ്നു കഅ്ബാണ്." (ദ)', 'عَوْفٍ الْمُزَنِيِّ', 'ഔഫുൽ മുസ്നി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 112, 112, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=188), 1, 'وَفِي رِوَايَةٍ: جَلْسَهَا وَغَوْرَهَا، وَحَيْثُ يَصْلُحُ الزَّرْعُ مِنْ قُدْسٍ،', 'മറ്റൊരു നിവേദനം: ആ പർവ്വതത്തിന്റെ സമീപ പ്രദേശങ്ങളെയും ദാതുന്നുസ്വുബ് എന്ന പ്രദേശത്തെയും (പതിച്ചു നൽകി). ഒരു മുസ്ലിമിന്റെയും അവകാശമല്ല അവിടുന്ന് അദ്ദേഹത്തിന് നൽകിയത്. നബി(സ) അദ്ദേഹത്തിന് ഇപ്രകാരം എഴുതി നൽകി: "കാരുണ്യവാനും കരുണാനിധിയുമായ അല്ലാഹുവിന്റെ നാമത്തിൽ. അല്ലാഹുവിന്റെ പ്രവാചകനായ മുഹമ്മദ്(സ) ബിലാലുബ്നു ഹാരിസുൽ മുസ്നിക്ക് നൽകിയതാണിത് (ഈ രേഖ). അദ്ദേഹത്തിന് അവിടുന്ന് ഖബ്ലിയ്യയിലെ ഖനികളിൽ ഉയർന്ന ഭാഗങ്ങളെയും താഴ്ന്ന ഭാഗങ്ങളെയും, ഖുദ്സ് പർവ്വതത്തിലെ കൃഷിയോഗ്യമായ ഭാഗങ്ങളെയും പതിച്ചു നൽകിയിരിക്കുന്നു. ഒരു മുസ്ലിമിന്റെയും അവകാശമല്ല അവിടുന്ന് അദ്ദേഹത്തിന് നൽകിയിട്ടുള്ളത്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=188), 2, 'وَفِي رِوَايَةٍ: وَجَرْسَهَا وَذَاتَ النُّصُبِ، وَلَمْ يُعْطِهِ حَقَّ مُسْلِمٍ، وَكَتَبَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ، هَذَا مَا أَعْطَى مُحَمَّدٌ رَسُولُ اللَّهِ بِلَالَ بْنَ الْحَارِثِ الْمُزَنِيَّ، أَعْطَاهُ مَعَادِنَ الْقَبَلِيَّةِ جَلْسِيَّهَا وَغَوْرِيَّهَا –', 'മറ്റൊരു നിവേദനത്തിൽ: "ഇത് എഴുതിയത് ഉബയ്യുബ്നു കഅ്ബാണ്." (ദ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=188), 3, 'وَفِي رِوَايَةٍ: جَلْسَهَا وَغَوْرَهَا – وَحَيْثُ يَصْلُحُ الزَّرْعُ مِنْ قُدْسٍ، وَلَمْ يُعْطِهِ حَقَّ مُسْلِمٍ".', null);
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=188), 4, 'وَفِي رِوَايَةٍ: "وَكَتَبَ أُبَيُّ بْنُ كَعْبٍ". (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنْ أَبْيَضَ بْنِ حَمَّالٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ وَفَدَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاسْتَقْطَعَهُ الْمِلْحَ الَّذِي بِمَأْرِبَ، فَقَطَعَهُ لَهُ، فَلَمَّا أَنْ وَلَّى قَالَ رَجُلٌ مِنَ الْمَجْلِسِ: أَتَدْرِي مَا قَطَعْتَ لَهُ، إِنَّمَا قَطَعْتَ لَهُ الْمَاءَ الْعِدَّ. قَالَ: فَانْتَزَعَ مِنْهُ، قَالَ: وَسَأَلَهُ عَمَّا يُحْمَى مِنَ الْأَرَاكِ، قَالَ: "مَا لَمْ تَنَلْهُ خِفَافٌ – وَفِي رِوَايَةٍ: أَخْفَافُ – الْإِبِلِ". قَالَ مُحَمَّدُ بْنُ الْحَسَنِ: يَعْنِي أَنَّ الْإِبِلَ تَأْكُلُ مُنْتَهَى رُءُوسِهَا وَيُحْمَى مَا فَوْقَهُ.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=189), 1, 'وَفِي رِوَايَةٍ: أَخْفَافُ – الْإِبِلِ". قَالَ مُحَمَّدُ بْنُ الْحَسَنِ: يَعْنِي أَنَّ الْإِبِلَ تَأْكُلُ مُنْتَهَى رُءُوسِهَا وَيُحْمَى مَا فَوْقَهُ.', 'മറ്റൊരു നിവേദനം: കുളമ്പുകൾ - എത്താത്തിടമാണത്. മുഹമ്മദുബ്നു ഹസൻ പറയുന്നു: നിശ്ചയം ഒട്ടകങ്ങൾ അവയുടെ തലയെത്തുന്നിടം വരെ ഭക്ഷിക്കും. അതിനു മുകളിലുള്ളതാണ് സംരക്ഷിക്കപ്പെടുന്ന മേഘല."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=3 and h.hadith_no=189), 2, 'وَفِي رِوَايَةٍ: أَنَّهُ سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ حِمَى الْأَرَاكِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا حِمَى فِي الْأَرَاكِ". فَقَالَ: أَرَاكَةٌ فِي حِظَارِي؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا حِمَى فِي الْأَرَاكِ". قَالَ الرَّاوِي: يَعْنِي بِحِظَارِي: الْأَرْضَ الَّتِي فِيهَا الزَّرْعُ الْمُحَاطُ عَلَيْهَا. (د,ت,جه)', 'മറ്റൊരു നിവേദനം: അറാക് തോട്ടത്തിലെ സംരക്ഷിത മേഘലയെ സംബന്ധിച്ച് അവിടുന്ന് പറഞ്ഞു: "അറാക് തോട്ടത്തിൽ സംരക്ഷിത ഭാഗമില്ല." അദ്ദേഹം ചോദിച്ചു: ഞാൻ പരിപാലിക്കുന്ന തോട്ടത്തിലുള്ള അറാക് കൃഷിയിലോ? നബി(സ) പറഞ്ഞു: "അറാക് തോട്ടത്തിൽ സംരക്ഷിത മേഘലയില്ല." നിവേദകൻ പറഞ്ഞു: ''ഞാൻ പരിപാലിക്കുന്ന തോട്ടം'' എന്നതുകൊണ്ടുള്ള ഉദ്ദേശ്യം വേലികെട്ടി സംരക്ഷിച്ച കൃഷിയാണ്. (ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنْ صَخْرِ بْنِ الْعَيْلَةِ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَزَا ثَقِيفًا، فَلَمَّا أَنْ سَمِعَ ذَلِكَ صَخْرٌ رَكِبَ فِي خَيْلٍ يُمِدُّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَوَجَدَ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدِ انْصَرَفَ وَلَمْ يَفْتَحْ، فَجَعَلَ صَخْرٌ يَوْمَئِذٍ عَهْدَ اللَّهِ وَذِمَّتَهُ أَنْ لَا يُفَارِقَ هَذَا الْقَصْرَ حَتَّى يَنْزِلُوا عَلَى حُكْمِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمْ يُفَارِقْهُمْ حَتَّى نَزَلُوا عَلَى حُكْمِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَكَتَبَ إِلَيْهِ صَخْرٌ: أَمَّا بَعْدُ، فَإِنَّ ثَقِيفًا قَدْ نَزَلَتْ عَلَى حُكْمِكَ يَا رَسُولَ اللَّهِ، وَأَنَا مُقْبِلٌ إِلَيْهِمْ وَهُمْ فِي خَيْلٍ. فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالصَّلَاةِ جَامِعَةً، فَدَعَا لِأَحْمَسَ عَشْرَ دَعَوَاتٍ: "اللَّهُمَّ بَارِكْ لِأَحْمَسَ فِي خَيْلِهَا وَرِجَالِهَا". وَأَتَاهُ الْقَوْمُ، فَتَكَلَّمَ الْمُغِيرَةُ بْنُ شُعْبَةَ فَقَالَ: يَا نَبِيَّ اللَّهِ، إِنَّ صَخْرًا أَخَذَ عَمَّتِي وَدَخَلَتْ فِيمَا دَخَلَ فِيهِ الْمُسْلِمُونَ. فَدَعَاهُ فَقَالَ: "يَا صَخْرُ، إِنَّ الْقَوْمَ إِذَا أَسْلَمُوا أَحْرَزُوا دِمَاءَهُمْ وَأَمْوَالَهُمْ، فَادْفَعْ إِلَى الْمُغِيرَةِ عَمَّتَهُ". فَدَفَعَهَا إِلَيْهِ. وَسَأَلَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا لِبَنِي سُلَيْمٍ، قَدْ هَرَبُوا عَنِ الْإِسْلَامِ، وَتَرَكُوا ذَلِكَ الْمَاءَ". فَقَالَ: يَا نَبِيَّ اللَّهِ، أَنْزِلْنِيهِ أَنَا وَقَوْمِي. قَالَ: "نَعَمْ". فَأَنْزَلَهُ وَأَسْلَمَ – يَعْنِي السُّلَمِيِّينَ – فَأَتَوْا صَخْرًا، فَسَأَلُوهُ أَنْ يَدْفَعَ إِلَيْهِمُ الْمَاءَ، فَأَبَى، فَأَتَوُا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: يَا نَبِيَّ اللَّهِ، أَسْلَمْنَا وَأَتَيْنَا صَخْرًا لِيَدْفَعَ إِلَيْنَا مَاءَنَا فَأَبَى عَلَيْنَا. فَأَتَاهُ فَقَالَ: "يَا صَخْرُ، إِنَّ الْقَوْمَ إِذَا أَسْلَمُوا أَحْرَزُوا أَمْوَالَهُمْ وَدِمَاءَهُمْ، فَادْفَعْ إِلَى الْقَوْمِ مَاءَهُمْ". قَالَ: نَعَمْ يَا نَبِيَّ اللَّهِ. فَرَأَيْتُ وَجْهَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَغَيَّرُ عِنْدَ ذَلِكَ حُمْرَةً، حَيَاءً مِنْ أَخْذِهِ الْجَارِيَةَ وَأَخْذِهِ الْمَاءَ. (د)', 'സ്വഖ്റുബ്നുൽ ഈലഃ(റ): നിശ്ചയം റസൂൽ(സ) സഖീഫ് ഗോത്രത്തോട് യുദ്ധം ചെയ്തു. ഈ വിവരം സ്വഖ്ർ(റ) അറിഞ്ഞപ്പോൾ നബി(സ)യെ സഹായിക്കുന്നതിനു വേണ്ടി ഒരു കുതിരപ്പടയുമായി അദ്ദേഹം തിരിച്ചു. എന്നാൽ വിജയം വരിക്കാതെ നബി(സ) മടങ്ങിയതായിട്ട് അദ്ദേഹം കണ്ടു. അന്ന് സ്വഖ്ർ(റ) അല്ലാഹുവിനെ മുൻനിർത്തി ഇപ്രകാരം ദൃഢപ്രതിജ്ഞയെടുത്തു: അവർ (സഖീഫുകാർ) റസൂൽ(സ)യുടെ വിധി പ്രകാരം കീഴടങ്ങുംവരെ താൻ ഈ കോട്ട വിട്ടുപോവുകയില്ല. അങ്ങനെ റസൂൽ(സ)യുടെ വിധിപ്രകാരം അവർ കീഴടങ്ങുംവരെ സ്വഖർ(റ) അവിടെ നിലയുറപ്പിച്ചു. (അവർ കീഴടങ്ങിയപ്പോൾ) അദ്ദേഹം റസൂൽ(സ)ക്ക് ഇപ്രകാരം സന്ദേശമയച്ചു: മുഖവുരക്ക് ശേഷം, അല്ലാഹുവിന്റെ റസൂലേ, അവിടുത്തെ വിധി പ്രകാരം സഖീഫുകാർ കീഴടങ്ങിയിരിക്കുന്നു. കുതിരപ്പടയാളികളായ അവരിലേക്ക് ഞാൻ മുന്നേറാൻ നിൽക്കുകയാണ്. അപ്പോൾ റസൂൽ(സ) നമസ്കാരത്തിനുവേണ്ടി ജനങ്ങളെ ഒരുമിച്ചു കൂട്ടാൻ കൽപിക്കുകയും അഹ്മസ് ഗോത്രത്തിനുവേണ്ടി പത്തു പ്രാവശ്യം ഇപ്രകാരം പ്രാർത്ഥിക്കുകയും ചെയ്തു: "അല്ലാഹുവേ, അഹ്മസ് ഗോത്രത്തിന് അവരുടെ കുതിരപ്പടയിലും ജനങ്ങളിലും നീ അഭിവൃദ്ധി ചെയ്യണേ." ശേഷം ജനങ്ങൾ നബി(സ)യുടെ അടുത്ത് വന്നു. മുഗീറതുബ്നു ശുഅ്ബ(റ) റസൂൽ(സ)യോട് സംസാരിക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, നിശ്ചയം സ്വഖർ(റ) എന്റെ പിതൃസഹോദരിയെ പിടികൂടിയിരിക്കുന്നു. അവളാണെങ്കിൽ മുസ്ലിംകൾ പ്രവേശിച്ച കാര്യത്തിൽ (ഇസ്ലാമിൽ) പ്രവേശിച്ചിട്ടുണ്ട്. അപ്പോൾ റസൂൽ(സ) സ്വഖ്ർ(റ)വിനെ വിളിച്ച് ഇപ്രകാരം പറഞ്ഞു: "സ്വഖ്റേ, നിശ്ചയം ഒരു സമൂഹം ഇസ്ലാം സ്വീകരിച്ചാൽ അവർ തങ്ങളുടെ രക്തത്തെയും സമ്പത്തിനെയും സംരക്ഷിച്ചിരിക്കുന്നു. അതിനാൽ മുഗീറക്ക് അദ്ദേഹത്തിന്റെ പിതൃസഹോദരിയെ തിരിച്ചു നൽകുക." അങ്ങനെ അദ്ദേഹം അവളെ മുഗീറക്ക് തിരിച്ചു നൽകി. ശേഷം നബി(സ) ചോദിച്ചു: "ബനൂസുലൈം ഗോത്രത്തിനെന്തു പറ്റി, അവർ ഇസ്ലാമിൽനിന്ന് ഭയന്നോടുകയും ആ വെള്ളമുള്ള പ്രദേശം ഉപേക്ഷിക്കുകയും ചെയ്തിട്ടുണ്ടല്ലോ?" അപ്പോൾ മുഗീറ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, അവിടെ എന്നെയും എന്റെ സമൂഹത്തെയും താമസിപ്പിച്ചാലും. തിരുമേനി(സ) പറഞ്ഞു: "ശരി." അങ്ങനെ അദ്ദേഹത്തിനും അസ്ലം ഗോത്രത്തിനും തിരുമേനി(സ) അവിടെ താമസിക്കാൻ അനുവാദം നൽകി. അങ്ങനെ അവർ സ്വഖ്ർ(റ)വിന്റെ അടുത്ത് ചെന്ന് ആ വെള്ളമുള്ള പ്രദേശം തങ്ങൾക്ക് നൽകാൻ ആവശ്യപ്പെട്ടു. പക്ഷേ, അദ്ദേഹം സമ്മതിച്ചില്ല. അപ്പോൾ അവർ നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, ഞങ്ങൾ ഇസ്ലാം സ്വീകരിക്കുകയും ഞങ്ങളുടെ ആ വെള്ളമുള്ള പ്രദേശം ഞങ്ങൾക്കു തന്നെ നൽകണമെന്ന് ആവശ്യപ്പെട്ട് സ്വഖ്ർ(റ)വിനെ സമീപിക്കുകയും ചെയ്തു. പക്ഷേ, അദ്ദേഹമത് സമ്മതിച്ചില്ല. ഉടനെ നബി(സ) സ്വഖ്ർ(റ)വിന്റെ അടുത്ത് ചെന്ന് പറഞ്ഞു: "സ്വഖ്റേ, നിശ്ചയം ഒരു സമൂഹം ഇസ്ലാം സ്വീകരിച്ചാൽ അവർ തങ്ങളുടെ രക്തത്തെയും സമ്പത്തിനെയും സംരക്ഷിച്ചിരിക്കുന്നു. അതിനാൽ, ഇക്കൂട്ടർക്ക് അവരുടെ വെള്ളമുള്ള പ്രദേശം തിരിച്ചു നൽകുക." അദ്ദേഹം പറഞ്ഞു: അതെ, അല്ലാഹുവിന്റെ പ്രവാചകരേ. സ്വഖ്ർ(റ) ആ പെൺകുട്ടിയെയും വെള്ളത്തെയും കയ്യടക്കി വെച്ചതിൽ ലജ്ജ തോന്നിയതിനാൽ, അന്നേരം റസൂൽ(സ)യുടെ മുഖം ചുവന്ന് വിവർണ്ണമാകുന്നത് ഞാൻ കണ്ടു. (ദ)', 'صَخْرِ بْنِ الْعَيْلَةِ', 'സ്വഖ്റുബ്നുൽ ഈലഃ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 113, 114, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنْ سَبْرَةَ بْنِ مَعْبَدٍ الْجُهَنِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَزَلَ فِي مَوْضِعِ الْمَسْجِدِ تَحْتَ دَوْمَةٍ، فَأَقَامَ ثَلَاثًا، ثُمَّ خَرَجَ إِلَى تَبُوكَ، وَإِنَّ جُهَيْنَةَ لَحِقُوهُ بِالرَّحْبَةِ، فَقَالَ لَهُمْ: "مَنْ أَهْلُ ذِي الْمَرْوَةِ". فَقَالُوا: بَنُو رِفَاعَةَ مِنْ جُهَيْنَةَ، فَقَالَ: "قَدْ أَقْطَعْتُهَا لِبَنِي رِفَاعَةَ". فَاقْتَسَمُوهَا: فَمِنْهُمْ مَنْ بَاعَ، وَمِنْهُمْ مَنْ أَمْسَكَ فَعَمِلَ. (د)', 'സബ്റതുബ്നു മഅ്ബദിൽ ജുഹനി(റ): നിശ്ചയം നബി(സ) ദൗമ വൃക്ഷത്തിന്റെ ചുവട്ടിൽ പള്ളിയുടെ സ്ഥാനത്ത് വാഹനമിറങ്ങുകയും അവിടെ മൂന്ന് ദിവസം താമസിക്കുകയും ചെയ്തു. ശേഷം തബൂക്കിലേക്ക് പുറപ്പെട്ടു. അങ്ങനെ റഹ്ബയിൽവെച്ച് ജുഹൈന ഗോത്രം തിരുമേനി(സ)യോടൊപ്പം ചേർന്നു. അപ്പോൾ അവിടുന്ന് അവരോട് ചോദിച്ചു: "ദുൽമർവയിലെ താമസക്കാർ ആരാണ്?" അവർ പറഞ്ഞു: ജുഹൈന ഗോത്രത്തിലെ ബനൂരിഫാഅയാണ്. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "ഞാനത് ബനൂരിഫാഅക്ക് പതിച്ചു നൽകിയിരിക്കുന്നു." അങ്ങനെ അവർ ആ സ്ഥലം വീതിച്ചെടുത്തു. അവരിൽ ചിലർ അത് വിൽക്കുകയും മറ്റു ചിലർ കൈവശംവെച്ച് (അവയിൽ) ജോലികൾ ചെയ്യുകയും ചെയ്തു. (ദ)', 'سَبْرَةَ بْنِ مَعْبَدٍ الْجُهَنِيِّ', 'സബ്റതുബ്നു മഅ്ബദിൽ ജുഹനി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 114, 114, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَقْطَعَ الزُّبَيْرَ نَخْلًا. (د)', 'അസ്മാഉബിൻതു അബീബക്ർ(റ): നിശ്ചയം റസൂൽ(സ) സുബൈർ(റ)വിന് ഒരു ഈത്തപ്പനത്തോട്ടം പതിച്ചു നൽകി. (ദ)', 'أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ', 'അസ്മാഉബിൻതു അബീബക്ർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 114, 114, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنْ قَيْلَةَ بِنْتِ مَخْرَمَةَ رَضِيَ اللَّهُ عَنْهُمَا قَالَتْ: قَدِمْنَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَتْ: تَقَدَّمَ صَاحِبِي – تَعْنِي حُرَيْثَ بْنَ حَسَّانَ، وَافِدَ بَكْرِ بْنِ وَائِلٍ – فَبَايَعَهُ عَلَى الْإِسْلَامِ عَلَيْهِ وَعَلَى قَوْمِهِ، ثُمَّ قَالَ: يَا رَسُولَ اللَّهِ، اكْتُبْ بَيْنَنَا وَبَيْنَ بَنِي تَمِيمٍ بِالدَّهْنَاءِ: أَنْ لَا يُجَاوِزَهَا إِلَيْنَا مِنْهُمْ أَحَدٌ إِلَّا مُسَافِرٌ أَوْ مُجَاوِرٌ، فَقَالَ: "اكْتُبْ لَهُ يَا غُلَامُ بِالدَّهْنَاءِ". فَلَمَّا رَأَيْتُهُ قَدْ أُمِرَ لَهُ بِهَا شَخَصَ بِي، وَهِيَ وَطَنِي وَدَارِي، فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّهُ لَمْ يَسْأَلْكَ السَّوِيَّةَ مِنَ الْأَرْضِ إِذْ سَأَلَكَ، إِنَّمَا هِيَ هَذِهِ الدَّهْنَاءُ عِنْدَكَ مُقَيَّدُ الْجَمَلِ وَمَرْعَى الْغَنَمِ، وَنِسَاءُ بَنِي تَمِيمٍ وَأَبْنَاؤُهَا وَرَاءَ ذَلِكَ، فَقَالَ: "أَمْسِكْ يَا غُلَامُ، صَدَقَتِ الْمِسْكِينَةُ، الْمُسْلِمُ أَخُو الْمُسْلِمِ، يَسَعُهُمَا الْمَاءُ وَالشَّجَرُ، وَيَتَعَاوَنَانِ عَلَى الْفَتَّانِ". (د,ت)', 'ഖൈലതുബ്നു മഖ്റമ(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ സന്നിധിയിൽ ചെന്നു. മഹതി പറയുന്നു: അങ്ങനെ എന്റെയാൾ - ബക്റുബ്നു വാഇലിലെ ദൂതനായ ഹുറൈസുബ്നു ഹസ്സാൻ(റ)വാണ് ഉദ്ദേശ്യം - വരികയും തനിക്കും തന്റെ സമൂഹത്തിനും വേണ്ടി തിരുമേനി(സ)യോട് ഇസ്ലാമിന്റെ കാര്യത്തിൽ ഉടമ്പടി ചെയ്യുകയും ചെയ്തു. ശേഷം അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, യാത്രക്കാരോ, സമീപത്ത് കഴിയുന്നവരോ അല്ലാതെ ബനൂതമീമിൽ നിന്നുള്ള ഒരാളും ''ദഹ്നാഅ്'' പ്രദേശത്തുകൂടെ ഞങ്ങളിലേക്ക് കടന്നു വരരുതെന്ന്, ഞങ്ങൾക്കും അവർക്കുമിടയിൽ അങ്ങ് ഒരു രേഖയുണ്ടാക്കി നൽകിയാലും. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "കുട്ടീ, അദ്ദേഹത്തിന് ''ദഹ്നാഅ്'' പ്രദേശം എഴുതി നൽകുക." റസൂൽ(സ) അദ്ദേഹത്തിന് ആ പ്രദേശം നൽകാൻ കൽപിച്ചുവെന്ന് മനസ്സിലായപ്പോൾ എനിക്ക് അസ്വസ്ഥത തോന്നി. കാരണമത് എന്റെ സ്വദേശവും പുരയിടവുമായിരുന്നു. ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അദ്ദേഹം ഭൂമിയിലുള്ള തുല്ല്യ അവകാശമല്ല അങ്ങയോട് ചോദിച്ചിരിക്കുന്നത്. നിശ്ചയം അങ്ങയുടെ പക്കലുള്ള ഈ ''ദഹ്നാഅ്'' പ്രദേശം ഒട്ടകങ്ങളെ കെട്ടുകയും ആടുകളെ മേയ്ക്കുകയും ചെയ്യുന്ന സ്ഥലമാണ്. ബനൂതമീം ഗോത്രത്തിലെ സ്ത്രീകളും കുട്ടികളും കഴിയുന്നത് അതിനപ്പുറത്താണ്. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "കുട്ടീ, നീ (എഴുത്ത്) നിർത്ത്, ഈ ദരിദ്രയായ സത്രീ പറയുന്നത് സത്യമാണ്. ഒരു മുസ്ലിം മറ്റൊരു മുസ്ലിമിന്റെ സഹോദരനാണ്. വെള്ളവും വൃക്ഷവുമെല്ലാം അവർ രണ്ടുകൂട്ടർക്കും ഉപകാരപ്പെടുന്നതാവണം. മാത്രമല്ല, പിശാചിനെതിരെ അവർ പരസ്പരം സഹായിക്കുകയും ചെയ്യണം." (ദ,തു)', 'قَيْلَةَ بِنْتِ مَخْرَمَةَ', 'ഖൈലതുബ്നു മഖ്റമ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 114, 115, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنْ أَسْمَرَ بْنِ مُضَرِّسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَايَعْتُهُ، فَقَالَ: "مَنْ سَبَقَ إِلَى مَاءٍ لَمْ يَسْبِقْهُ إِلَيْهِ مُسْلِمٌ فَهُوَ لَهُ". قَالَ: فَخَرَجَ النَّاسُ يَتَعَادَوْنَ يَتَخَاطُّونَ. (د)', 'അസ്മറുബ്നു മുളർറസ്(റ): ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്ന് അവിടുത്തോട് ഉടമ്പടി ചെയ്തു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "ഏതെങ്കിലുമൊരാൾ, മറ്റെല്ലാ മുസ്ലിംകൾക്കും മുന്നിലായി, വെള്ളമുള്ള ഒരു പ്രദേശത്തേക്ക് ആദ്യം എത്തുന്നുവെങ്കിൽ അത് അവനുള്ളതാണ്." നിവേദകൻ പറയുന്നു: അപ്പോൾ ജനങ്ങളെല്ലാം ധൃതിയിൽ ചെന്ന് (തങ്ങളുടെ സ്ഥലങ്ങളുടെ) അതിരുകൾ രേഖപ്പെടുത്താൻ തുടങ്ങി. (ദ)', 'أَسْمَرَ بْنِ مُضَرِّسٍ', 'അസ്മറുബ്നു മുളർറസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 115, 115, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَقْطَعَ الزُّبَيْرَ حُضْرَ فَرَسِهِ، فَأَجْرَى فَرَسَهُ حَتَّى قَامَ، ثُمَّ رَمَى بِسَوْطِهِ، فَقَالَ: "أَعْطُوهُ مِنْ حَيْثُ بَلَغَ السَّوْطُ". (د)', 'ഇബ്നുഉമർ(റ): ഒട്ടകത്തിന്റെ ഒരു ഓട്ടത്തിന്റെ കണക്കനുസരിച്ചുള്ള സ്ഥലം നബി(സ) സുബൈർ(റ)വിന് പതിച്ചു നൽകി. അങ്ങനെ സുബൈർ(റ) തന്റെ കുതിരയെ ഓടിക്കുകയും പിന്നെ നിൽക്കുകയും ചെയ്തു. ശേഷം നബി(സ) തന്റെ ചാട്ടവാർ എറിഞ്ഞുകൊണ്ട് പറഞ്ഞു: "ചാട്ടവാർ വീണതുവരെയുള്ള സ്ഥലം നിങ്ങൾ അദ്ദേഹത്തിന് നൽകുക." (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 115, 115, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنْ سَعِيدِ بْنِ زَيْدٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَحْيَا أَرْضًا مَيِّتَةً فَهِيَ لَهُ، وَلَيْسَ لِعِرْقٍ ظَالِمٍ حَقٌّ". (د,ت,ن)', 'സഈദുബ്നു സൈദ്(റ): നബി(സ) പറഞ്ഞു: "ജനവാസമില്ലാത്ത ഭൂമിയെ ആരെങ്കിലും വാസയോഗ്യമാക്കിയാൽ അത് അവന് അവകാശപ്പെട്ടതാണ്. അനധികൃതമായി (മറ്റൊരാളുടെ ഭൂമിയിൽ) കൃഷി ചെയ്തവന്റെ കൃഷിക്ക് അവകാശമുണ്ടാകുന്നതല്ല." (ദ,തു,ന)', 'سَعِيدِ بْنِ زَيْدٍ', 'സഈദുബ്നു സൈദ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 115, 115, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنْ عُرْوَةَ قَالَ: أَشْهَدُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى: أَنَّ الْأَرْضَ أَرْضُ اللَّهِ، وَالْعِبَادَ عِبَادُ اللَّهِ، وَمَنْ أَحْيَا مَوَاتًا فَهُوَ أَحَقُّ بِهِ، جَاءَنَا بِهَذَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الَّذِينَ جَاءُوا بِالصَّلَوَاتِ عَنْهُ. (د)', 'ഉർവ്വ(റ): റസൂൽ(സ) ഇപ്രകാരം വിധിച്ചിട്ടുണ്ടെന്നതിന് ഞാൻ സാക്ഷിയാണ്: നിശ്ചയം ഭൂമി അല്ലാഹുവിന്റേതാണ്, ജനങ്ങൾ അല്ലാഹുവിന്റെ അടിമകളാണ്. ആരെങ്കിലും ജനവാസമില്ലാത്ത ഭൂമി വാസയോഗ്യമാക്കിയാൽ അവൻതന്നെയാണ് അതിന് ഏറ്റവും അവകാശപ്പെട്ടവൻ. നബി(സ)യിൽ നിന്നുള്ള ഈ വിവരം ഞങ്ങൾക്ക് എത്തിച്ചു തന്നത് തിരുമേനി(സ)യിൽ നിന്ന് നമസ്കാരത്തെ ഞങ്ങൾക്ക് എത്തിച്ചു തന്നവർ തന്നെയാണ്. (ദ)', 'عُرْوَةَ قَالَ', 'ഉർവ്വ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 115, 116, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنْ سَمُرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَحَاطَ حَائِطًا عَلَى أَرْضٍ فَهِيَ لَهُ". (د)', 'സമുറ(റ): നബി(സ) പറഞ്ഞു: "ഒരു ഭൂമിക്കു ചുറ്റും ഒരാൾ മതിൽ കെട്ടിയാൽ അത് അവന് അവകാശപ്പെട്ടതാണ്." (ദ)', 'سَمُرَةَ', 'സമുറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 116, 116, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: غَزَوْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَبُوكَ، فَلَمَّا أَتَى وَادِيَ الْقُرَى إِذَا امْرَأَةٌ فِي حَدِيقَةٍ لَهَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَصْحَابِهِ: "اخْرُصُوا". فَخَرَصَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَشْرَةَ أَوْسُقٍ، فَقَالَ لِلْمَرْأَةِ: "أَحْصِي مَا يَخْرُجُ مِنْهَا". فَأَتَيْنَا تَبُوكَ، فَأَهْدَى مَلِكُ أَيْلَةَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَغْلَةً بَيْضَاءَ، وَكَسَاهُ بُرْدَةً، وَكَتَبَ لَهُ، يَعْنِي بِبَحْرِهِ، قَالَ: فَلَمَّا أَتَيْنَا وَادِيَ الْقُرَى قَالَ لِلْمَرْأَةِ: "كَمْ كَانَ فِي حَدِيقَتِكِ". قَالَتْ: عَشْرَةَ أَوْسُقٍ، خَرْصَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي مُتَعَجِّلٌ إِلَى الْمَدِينَةِ، فَمَنْ أَرَادَ مِنْكُمْ أَنْ يَتَعَجَّلَ مَعِي فَلْيَتَعَجَّلْ". (ق,د)', 'അബു ഹുമൈദുസ്സാഇദീ(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം തബൂക് യുദ്ധത്തിനു പോയി. വാദിൽഖുറയിലെത്തിയപ്പോൾ ഒരു സ്ത്രീ തന്റെ തോട്ടത്തിൽ നിൽക്കുന്നുണ്ടായിരുന്നു. റസൂൽ(സ) അനുചരരോടരുളി: "നിങ്ങൾ (ഈ തോട്ടത്തിലെ വിളയുടെ) മതിപ്പു കണക്കാക്കുക." അവസാനം റസൂൽ(സ) തന്നെ പത്തു വസ്ഖുണ്ടാകുമെന്ന് മതിച്ചു. "ഈ തോട്ടത്തിൽനിന്നു കിട്ടുന്ന വിളകൾക്ക് കണക്കുവെക്കുക." എന്ന് അവളോടും അവിടുന്നരുളി. അങ്ങനെ ഞങ്ങൾ തബൂക്കിലെത്തി. അങ്ങനെ ''ഐല'' രാജ്യത്തെ രാജാവ് തിരുമേനി(സ)ക്ക് വെളുത്ത ഒരു കോവർകഴുതയെ സമ്മാനിക്കുകയും ഒരു ഷാൾ അണിയിക്കുകയും ചെയ്തു. തിരുമേനി(സ) ആ രാജാവിന് തന്റെ പ്രദേശത്തെ കടലിന്റെ അധികാരം നൽകി. അങ്ങനെ ഞങ്ങൾ (തിരിച്ച്) ''വാദിൽ ഖുറാ''യിലെത്തിയപ്പോൾ റസൂൽ(സ) തോട്ടക്കാരിയോടു ചോദിച്ചു: "നിന്റെ തോട്ടത്തിലെ ഉൽപന്നം എത്രയുണ്ടായിരുന്നു?" തിരുമേനി(സ) മതിച്ചതുപോലെ പത്തു വസ്ഖ് എന്ന് അവൾ പറഞ്ഞു: അവിടുന്ന് പറഞ്ഞു: "നിശ്ചയം ഞാൻ ധൃതിയിൽ മദീനയിലേക്ക് പോവുകയാണ്. എന്റെ കൂടെ ധൃതിയിൽ വരാൻ ആരെങ്കിലും ഒരുക്കമെങ്കിൽ അവർ വന്നുകൊള്ളട്ടെ.'' (ബു,മു,ദ)', 'أَبِي حُمَيْدٍ السَّاعِدِيِّ', 'അബു ഹുമൈദുസ്സാഇദീ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 116, 116, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنْ زَيْنَبَ رَضِيَ اللَّهُ عَنْهَا: أَنَّهَا كَانَتْ تَفْلِي رَأْسَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعِنْدَهُ امْرَأَةُ عُثْمَانَ بْنِ عَفَّانَ وَنِسَاءٌ مِنَ الْمُهَاجِرَاتِ، وَهُنَّ يَشْتَكِينَ مَنَازِلَهُنَّ أَنَّهَا تَضِيقُ عَلَيْهِنَّ وَيُخْرَجْنَ مِنْهَا، فَأَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تُوَرَّثَ دُورُ الْمُهَاجِرِينَ النِّسَاءَ. فَمَاتَ عَبْدُ اللَّهِ بْنُ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ فَوُرِّثَتْهُ امْرَأَتُهُ دَارًا بِالْمَدِينَةِ. (د)', 'സൈനബ്(റ): നിശ്ചയം മഹതി റസൂൽ(സ)യുടെ തലയിൽ പേൻ നോക്കുകയായിരുന്നു. ഉസ്മാനുബ്നു അഫാൻ(റ)വിന്റെ ഭാര്യയടക്കം മുഹാജിറുകളിൽപെട്ട കുറേ സ്ത്രീകളും തിരുമേനി(സ)യുടെ സന്നിധിയിലുണ്ട്. തങ്ങളുടെ വീടുകളിൽ സ്ഥലം കുറവാണെന്നും അതിനാൽ അവിടെ നിന്നും തങ്ങൾ പുറത്താക്കപ്പെടുകയാണെന്നും പരാതിപ്പെട്ടുകൊണ്ട് വന്നതായിരുന്നു അവർ. അപ്പോൾ, മുഹാജിറുകളുടെ വീടുകൾ അനന്തരസ്വത്തായി സ്ത്രീകൾക്ക് നൽകപ്പെടണമെന്ന് റസൂൽ(സ) കൽപിച്ചു. . അങ്ങനെ അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ) മരിച്ചപ്പോൾ അദ്ദേഹത്തിന്റെ ഭാര്യക്ക് മദീനയിലെ ഒരു വീട് അദ്ദേഹത്തിന്റെ അനന്തരവിഹിതമായി ലഭിച്ചു. (ദ)', 'زَيْنَبَ', 'സൈനബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 116, 116, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ مُعَاذٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَنْ عَقَدَ الْجِزْيَةَ فِي عُنُقِهِ فَقَدْ بَرِئَ مِمَّا عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (د)', 'മുആദ്(റ): ആരെങ്കിലും (മുസ്ലിംകൾ) തന്റെ പിരടിയിൽ ജിസ്യയെ സ്ഥാപിച്ചാൽ⁶ റസൂൽ(സ) നിലകൊള്ളുന്ന കാര്യത്തിൽ (ഇസ്ലാം) നിന്നും അവൻ ഒഴിഞ്ഞിരിക്കുന്നു. (ദ)', 'مُعَاذٍ', 'മുആദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 117, 117, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَخَذَ أَرْضًا بِجِزْيَتِهَا فَقَدِ اسْتَقَالَ هِجْرَتَهُ، وَمَنْ نَزَعَ صَغَارَ كَافِرٍ مِنْ عُنُقِهِ فَجَعَلَهُ فِي عُنُقِهِ فَقَدْ وَلَّى الْإِسْلَامَ ظَهْرَهُ". (د)', 'അബുദ്ദർദാഅ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ ഒരു ഭൂമിയെ, അതിന്റെ ജിസ്യ സഹിതം, ഏറ്റെടുത്താൽ അവൻ തന്റെ ഹിജ്റയെ ഒഴിവാക്കിയിരിക്കുന്നു. ആരെങ്കിലും സത്യനിഷേധിയുടെ നിന്ദ്യതയെ (ജിസ്യയെ) അവന്റെ പിരടിയിൽനിന്നും എടുത്ത് തന്റെ പിരടിയിലേക്ക് വെച്ചാൽ, അവൻ ഇസ്ലാമിൽനിന്നും പുറംതിരിഞ്ഞു നടന്നിരിക്കുന്നു." (ദ)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 117, 117, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "فِي الرِّكَازِ الْخُمُسُ". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നിശ്ചയം നബി(സ) പറഞ്ഞു: "നികുതികളിൽ അഞ്ചിലൊന്നുണ്ട്.⁷" (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 117, 117, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 204, 'عَنِ الْحَسَنِ قَالَ: الرِّكَازُ: الْكَنْزُ الْعَادِيُّ. (د)', 'ഹസൻ(റ): ''രികാസ്'' എന്നാൽ പുരാതനമായ നിധിയാണ്. (ദ)', 'الْحَسَنِ قَالَ', 'ഹസൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 117, 117, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 205, 'عَنْ ضُبَاعَةَ بِنْتِ الزُّبَيْرِ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: ذَهَبَ الْمِقْدَادُ لِحَاجَتِهِ بِبَقِيعِ الْخَبْخَبَةِ، فَإِذَا جُرَذٌ يُخْرِجُ مِنْ جُحْرٍ دِينَارًا، ثُمَّ لَمْ يَزَلْ يُخْرِجُ دِينَارًا دِينَارًا حَتَّى أَخْرَجَ سَبْعَةَ عَشَرَ دِينَارًا، ثُمَّ أَخْرَجَ خِرْقَةً حَمْرَاءَ – يَعْنِي فِيهَا دِينَارٌ – فَكَانَتْ ثَمَانِيَةَ عَشَرَ دِينَارًا، فَذَهَبَ بِهَا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ، وَقَالَ لَهُ: خُذْ صَدَقَتَهَا، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلْ هَوَيْتَ إِلَى الْجُحْرِ". قَالَ: لَا، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "بَارَكَ اللَّهُ لَكَ فِيهَا". (د,جه)', 'ളുബാഅതുബിൻതുസ്സുബൈർ(റ): മിഖ്ദാദ്(റ) തന്റെ ആവശ്യത്തിനു വേണ്ടി ''ബഖീഇൽ ഖബ്ഖബ''യിലേക്ക് പോയി. അവിടെ ഒരു ചുണ്ടെലി ഒരു മാളത്തിൽനിന്നും ഒരു ദീനാർ പുറത്തിടുന്നത് കണ്ടു. അങ്ങനെ അത് ഓരോരോ ദീനാറുകളായിട്ട് പതിനേഴ് ദീനാറുകൾ പുറത്തിട്ടു. ശേഷം ചുവന്ന ഒരു ശീലക്കഷ്ണവും പുറത്തിട്ടു - അതിലും ഒരു ദീനാറുണ്ടായിരുന്നുവെന്ന് ഉദ്ദേശ്യം - അങ്ങനെ പതിനെട്ട് ദീനാറുകളായി. അദ്ദേഹം അതുമായി നബി(സ)യുടെ അടുത്ത്ചെന്ന വിവരം പറഞ്ഞു. എന്നിട്ട് അവിടുത്തോട് പറഞ്ഞു: അതിന്റെ സകാത് അവിടുന്ന് സ്വീകരിച്ചാലും. അപ്പോൾ നബി(സ) ചോദിച്ചു: "താങ്കൾ ആ മാളത്തിലേക്ക് എത്തിനോക്കിയോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവയിൽ അല്ലാഹു താങ്കൾക്ക് അഭിവൃദ്ധി നൽകട്ടെ." (ദ,ജ)', 'ضُبَاعَةَ بِنْتِ الزُّبَيْرِ', 'ളുബാഅതുബിൻതുസ്സുബൈർ(റ)', '⁶. നികുതിയോ ജിസ്യയോ നൽകി കഴിയുന്ന സത്യനിഷേധിയിൽനിന്നും അവന്റെ ഭൂമി ഒരു മുസ്ലിം വാങ്ങുകയും അതിന്റെ ജിസ്യ താൻ നൽകാം എന്ന് അവൻ ഏറ്റെടുക്കകയും ചെയ്താൽ എന്നർത്ഥം
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 206, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ – حِينَ خَرَجْنَا مَعَهُ إِلَى الطَّائِفِ فَمَرَرْنَا بِقَبْرٍ – فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَذَا قَبْرُ أَبِي رِغَالٍ، وَكَانَ بِهَذَا الْحَرَمِ يُدْفَعُ عَنْهُ، فَلَمَّا خَرَجَ أَصَابَتْهُ النِّقْمَةُ الَّتِي أَصَابَتْ قَوْمَهُ بِهَذَا الْمَكَانِ، فَدُفِنَ فِيهِ، وَآيَةُ ذَلِكَ أَنَّهُ دُفِنَ مَعَهُ غُصْنٌ مِنْ ذَهَبٍ، إِنْ أَنْتُمْ نَبَشْتُمْ عَنْهُ أَصَبْتُمُوهُ مَعَهُ". فَابْتَدَرَهُ النَّاسُ، فَاسْتَخْرَجُوا الْغُصْنَ. (د)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം ത്വാഇഫിലേക്ക് പുറപ്പെട്ട്, ഒരു ഖബറിനു സമീപത്തുകൂടെ സഞ്ചരിക്കുമ്പോൾ, റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "ഇത് അബൂരിഗാലിന്റെ⁸ ഖബ്റാണ്. ഈ സുരക്ഷിത കേന്ദ്രത്തിൽ (തന്റെ ശത്രുക്കളെ) പ്രതിരോധിച്ച് കഴിയുകയായിരുന്നു അയാൾ. ശേഷം അയാൾ പുറത്തിറങ്ങിയപ്പോൾ തന്റെ സമുദായത്തിന് പിടിപെട്ട ആപത്ത് ഈ സ്ഥലത്തുവെച്ച് അയാൾക്കും പിടിപെടുകയും അവിടെത്തന്നെ അയാൾ മറവുചെയ്യപ്പെടുകയും ചെയ്തു. അതിനുള്ള തെളിവ്, അയാൾക്കൊപ്പം ഒരു സ്വർണ്ണ വടിയും മറവു ചെയ്യപ്പെട്ടിട്ടുണ്ടെന്നതാണ്. അയാളുടെ ഖബ്ർ നിങ്ങൾ തുറക്കുകയാണെങ്കിൽ അയാളോടൊപ്പം ആ വടിയും ലഭിക്കും." ഉടൻതന്നെ ജനങ്ങൾ ഖബ്ർ തുറക്കുകയും ആ വടി പുറത്തെടുക്കുകയും ചെയ്തു. (ദ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', '⁸. സഖീഫ് ഗോത്രത്തിന്റെ പ്രപിതാമഹനാണ് അബൂരിഗാൽ. അയാൾ സമൂദ് ഗോത്രത്തിൽ പെട്ടയാളായിരുന്നു.', null, array['د']::text[], array['ദ']::text[], null, null, 118, 118, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=4 and b.book_no=3 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
